-- artifact: check_constraint agent_run.agent_run_status_check
do $kernel$
declare
  existing_expression text;
  existing_validated boolean;
begin
  select pg_get_expr(constraint_row.conbin, constraint_row.conrelid, true),
         constraint_row.convalidated
    into existing_expression, existing_validated
  from pg_constraint as constraint_row
  where constraint_row.conrelid = to_regclass('agent_run')
    and constraint_row.conname = 'agent_run_status_check'
    and constraint_row.contype = 'c';

  if existing_expression = any (array['status = ANY (ARRAY[''recorded''::text, ''completed''::text, ''validation_exhausted''::text, ''runtime_error''::text])', 'status = ANY (ARRAY[''recorded''::text, ''completed''::text, ''validation_exhausted''::text, ''runtime_error''::text, ''cancelled''::text])']::text[]) then
    execute 'alter table "agent_run" drop constraint "agent_run_status_check"';
    existing_expression := null;
    existing_validated := false;
  elsif existing_expression is not null and existing_expression <> 'status = ANY (ARRAY[''recorded''::text, ''completed''::text, ''validation_exhausted''::text, ''budget_exhausted''::text, ''runtime_error''::text, ''cancelled''::text])' then
    raise exception using
      errcode = 'P0001',
      message = 'schema drift at agent_run.agent_run_status_check: existing check constraint is not a recognized catalog revision';
  end if;

  if existing_expression is null then
    execute 'alter table "agent_run" add constraint "agent_run_status_check" check (status in (''recorded'', ''completed'', ''validation_exhausted'', ''budget_exhausted'', ''runtime_error'', ''cancelled'')) not valid';
    existing_validated := false;
  end if;

  if not existing_validated then
    execute 'alter table "agent_run" validate constraint "agent_run_status_check"';
  end if;
end
$kernel$;

