-- artifact: check_constraint lookup_version.lookup_version_stage_check
do $kernel$
declare
  existing_expression text;
  existing_validated boolean;
begin
  select pg_get_expr(constraint_row.conbin, constraint_row.conrelid, true),
         constraint_row.convalidated
    into existing_expression, existing_validated
  from pg_constraint as constraint_row
  where constraint_row.conrelid = to_regclass('lookup_version')
    and constraint_row.conname = 'lookup_version_stage_check'
    and constraint_row.contype = 'c';

  if existing_expression = any (array['stage = ANY (ARRAY[''draft''::text, ''mainline''::text, ''discarded''::text])']::text[]) then
    execute 'alter table "lookup_version" drop constraint "lookup_version_stage_check"';
    existing_expression := null;
    existing_validated := false;
  elsif existing_expression is not null and existing_expression <> 'stage = ANY (ARRAY[''draft''::text, ''mainline''::text, ''discarded''::text, ''reverted''::text])' then
    raise exception using
      errcode = 'P0001',
      message = 'schema drift at lookup_version.lookup_version_stage_check: existing check constraint is not a recognized catalog revision';
  end if;

  if existing_expression is null then
    execute 'alter table "lookup_version" add constraint "lookup_version_stage_check" check (stage in (''draft'', ''mainline'', ''discarded'', ''reverted'')) not valid';
    existing_validated := false;
  end if;

  if not existing_validated then
    execute 'alter table "lookup_version" validate constraint "lookup_version_stage_check"';
  end if;
end
$kernel$;

