-- artifact: index position_version_change_set_idx
create index if not exists "position_version_change_set_idx" on "position_version" (change_set_id);

-- artifact: index position_version_change_set_value_once_idx
create unique index if not exists "position_version_change_set_value_once_idx" on "position_version" (record_id, effective_start, change_set_id) where not tombstones_record and not untombstones_record;

-- artifact: index position_version_lookup_idx
create index if not exists "position_version_lookup_idx" on "position_version" (record_id, stage, effective_start desc);

-- artifact: index position_version_mainline_lifecycle_once_idx
create unique index if not exists "position_version_mainline_lifecycle_once_idx" on "position_version" (record_id, effective_start, tombstones_record, untombstones_record) where stage = 'mainline' and (tombstones_record or untombstones_record);

-- artifact: index position_version_ref_live_unique_idx
create unique index if not exists "position_version_ref_live_unique_idx" on "position_version" (app_id, customer_id, "ref") where stage = 'mainline' and effective_end is null and "ref" is not null;

-- artifact: index schema_revision_active_idx
create unique index if not exists schema_revision_active_idx on schema_revision (app_id, customer_id) where activated_at is not null;

-- artifact: index schema_revision_tenant_id_idx
create unique index if not exists schema_revision_tenant_id_idx on schema_revision (id, app_id, customer_id);

