    and constraint_row.contype = 'f';

  differs := found and (actual_columns is distinct from array['schema_revision_id']::text[]
    or actual_referenced_table is distinct from 'schema_revision'
    or actual_referenced_columns is distinct from array['id']::text[]);
  if differs and (false) then
    execute 'alter table "schema_installation_revision" drop constraint "schema_installation_revision_schema_revision_fk"';
    actual_columns := null;
  elsif differs then
    raise exception using errcode = 'P0001', message = 'schema drift at schema_installation_revision.schema_installation_revision_schema_revision_fk: existing foreign key is not a recognized catalog revision';
  end if;
  if actual_columns is null then
    execute 'alter table "schema_installation_revision" add constraint "schema_installation_revision_schema_revision_fk" foreign key ("schema_revision_id") references "schema_revision" ("id") not valid';
    actual_validated := false;
  end if;
  if not actual_validated then
    execute 'alter table "schema_installation_revision" validate constraint "schema_installation_revision_schema_revision_fk"';
  end if;
end
