-- artifact: function kernel_installer_capability_role(text)
create or replace function kernel_installer_capability_role(capability text)
returns text
language plpgsql
stable
parallel safe
security invoker
set search_path from current
as $kernel$
declare
  raw_identifier text;
  normalized text;
begin
  raw_identifier := case capability
    when 'execution_owner' then current_database() || '__' || current_schema() || '__kernel_execution_owner'
    when 'runtime' then current_database() || '__' || current_schema() || '__kernel_runtime'
    when 'schema_admin' then current_database() || '__' || current_schema() || '__kernel_schema_admin'
    when 'query' then current_database() || '__' || current_schema() || '__kernel_query'
    else null
  end;
  if raw_identifier is null then
    return null;
  end if;
  normalized := trim(both '_' from regexp_replace(
    regexp_replace(lower(btrim(raw_identifier)), '[_\-[:space:]]+', '_', 'g'),
    '[^a-z0-9_]', '', 'g'
  ));
  if octet_length(normalized) <= 63 then
    return normalized;
  end if;
  return left(normalized, 46) || '_' || left(pg_catalog.md5(normalized), 16);
end;
$kernel$;

-- artifact: function kernel_principal_scope_authorized(text,text,text,text)
create or replace function kernel_principal_scope_authorized(
  requested_capability text,
  requested_app_id text,
  requested_customer_id text,
  requested_actor_id text default null
)
returns boolean
language plpgsql
volatile
parallel unsafe
security invoker
set search_path from current
as $kernel$
declare
  execution_role text := kernel_installer_capability_role('execution_owner');
begin
  if requested_capability not in ('runtime', 'schema_admin', 'any')
    or coalesce(btrim(requested_app_id), '') = ''
    or coalesce(btrim(requested_customer_id), '') = ''
  then
    return false;
  end if;

  -- The installer/verifier owns the generated artifacts and may operate before
  -- application principals have been bound. Request-time callers never receive
  -- membership in the execution-owner role.
  if session_user = execution_role
    or coalesce(
      pg_has_role(session_user, pg_catalog.to_regrole(execution_role), 'SET'),
      false
    )
  then
    return true;
  end if;

  return exists (
    select 1
    from kernel_principal_scope binding
    where binding.principal_name = session_user::name
      and binding.active
      and binding.app_id = requested_app_id
      and binding.customer_id = requested_customer_id
      and (
        requested_capability = 'any'
        or binding.capability = requested_capability
      )
      and (
        requested_actor_id is null
        or binding.actor_id = requested_actor_id
      )
      and (
        binding.capability <> 'runtime'
        or binding.actor_id is null
        or binding.actor_id = nullif(current_setting('kernel.actor_id',true),'')
      )
      and pg_has_role(
        session_user,
        pg_catalog.to_regrole(kernel_installer_capability_role(binding.capability)),
        'MEMBER'
      )
      and (
        binding.capability <> 'runtime'
        or not binding.actor_binding_required
        or exists (
          select 1 from kernel_actor_membership membership
          where membership.principal_name = session_user::name
            and membership.app_id = requested_app_id
            and membership.customer_id = requested_customer_id
            and membership.actor_id = coalesce(requested_actor_id, nullif(current_setting('kernel.actor_id',true),''))
            and membership.role = nullif(current_setting('kernel.actor_role',true),'')
            and membership.active
            and membership.fence_generation > 0
            and membership.fence_generation::text = nullif(current_setting('kernel.actor_fence_generation',true),'')
          for share of membership
        )
      )
  );
end;
$kernel$;

-- artifact: function kernel_read_active_schema_revision(jsonb)
create or replace function kernel_read_active_schema_revision(request jsonb)
returns jsonb
language plpgsql
volatile
security invoker
set search_path from current
as $kernel$
declare
  request_app_id text;
  request_customer_id text;
  active_revision_id bigint;
  active_schema jsonb;
  active_effective_hash text;
  authorization_result jsonb;
begin
  perform kernel_cleanup_generated_visible_query();
  if request is null or jsonb_typeof(request) <> 'object' then
    return jsonb_build_object(
      'ok', false,
      'error', jsonb_build_object(
        'code', 'contract_validation_failed',
        'message', 'Contract validation failed',
        'details', jsonb_build_array(jsonb_build_object(
          'path', 'request',
          'code', 'invalid_request',
          'message', 'request must be a JSON object'
        ))
      )
    );
  end if;

  request_app_id := request->>'app_id';
  request_customer_id := request->>'customer_id';
  if request_app_id is null or btrim(request_app_id) = '' then
    return jsonb_build_object(
      'ok', false,
      'error', jsonb_build_object(
        'code', 'contract_validation_failed',
        'message', 'Contract validation failed',
        'details', jsonb_build_array(jsonb_build_object(
          'path', 'app_id',
          'code', 'required',
          'message', 'app_id is required'
        ))
      )
    );
  end if;
  if request_customer_id is null or btrim(request_customer_id) = '' then
    return jsonb_build_object(
      'ok', false,
      'error', jsonb_build_object(
        'code', 'contract_validation_failed',
        'message', 'Contract validation failed',
        'details', jsonb_build_array(jsonb_build_object(
          'path', 'customer_id',
          'code', 'required',
          'message', 'customer_id is required'
        ))
      )
    );
  end if;

  authorization_result := kernel_authorize_scope(
    'runtime', request_app_id, request_customer_id, null
  );
  if authorization_result is not null then
    return authorization_result;
  end if;

  perform set_config('kernel.app_id', request_app_id, true);
  perform set_config('kernel.customer_id', request_customer_id, true);

  -- The effective hash is the exact expression the tenant schema revision
  -- commit compares `expected_effective_hash` against.
  select sr.id, sr.schema,
         coalesce(sir.effective_artifact_hash, sr.schema_hash, kernel_admin_sha256(kernel_canonical_json(sr.schema)))
  into active_revision_id, active_schema, active_effective_hash
  from schema_revision sr
  left join schema_installation_revision sir on sir.schema_revision_id = sr.id
  where sr.app_id = request_app_id
    and sr.customer_id = request_customer_id
    and sr.activated_at is not null;

  if not found then
    return jsonb_build_object(
      'ok', false,
      'error', jsonb_build_object(
        'code', 'active_schema_missing',
        'message', 'No active schema revision exists for this scope',
        'details', jsonb_build_array(jsonb_build_object(
          'path', 'scope',
          'code', 'active_schema_missing',
          'message', request_app_id || '/' || request_customer_id ||
            ': materialize a schema before applying or reading records'
        ))
      )
    );
  end if;

  return jsonb_build_object(
    'ok', true,
    'data', jsonb_build_object(
      'schema_revision_id', active_revision_id,
      'schema', active_schema,
      'effective_hash', active_effective_hash
    )
  );
exception
  when others then
    return jsonb_build_object(
      'ok', false,
      'error', jsonb_build_object(
        'code', 'database_error',
        'message', 'Database operation failed',
        'details', '[]'::jsonb
      )
    );
end;
$kernel$;

-- artifact: function kernel_preflight_schema_materialization(jsonb)
create or replace function kernel_preflight_schema_materialization(request jsonb)
returns jsonb
language plpgsql
volatile
parallel unsafe
security invoker
set search_path from current
as $kernel$
declare
  proposed_schema jsonb := case when request ? 'schema' then request->'schema' else request end;
  proposed_app_id text := proposed_schema->>'app_id';
  proposed_customer_id text := proposed_schema->>'customer_id';
  sibling record;
  proposed_model jsonb;
  sibling_model jsonb;
  proposed_field jsonb;
  sibling_field jsonb;
  proposed_required text[];
  sibling_required text[];
  proposed_unique text[];
  sibling_unique text[];
  mismatch text;
  previous_catalog_read text := current_setting('kernel.schema_catalog_read', true);
begin
  perform kernel_cleanup_generated_visible_query();
  if jsonb_typeof(proposed_schema) is distinct from 'object'
     or coalesce(proposed_app_id, '') = ''
     or coalesce(proposed_customer_id, '') = ''
     or jsonb_typeof(proposed_schema->'models') is distinct from 'array' then
    return jsonb_build_object(
      'ok', false,
      'error', jsonb_build_object(
        'code', 'contract_validation_failed',
        'message', 'Contract validation failed',
        'details', jsonb_build_array(jsonb_build_object(
          'path', 'schema',
          'code', 'invalid_materialization_preflight',
          'message', 'schema identity and models are required'
        ))
      )
    );
  end if;

  perform set_config('kernel.schema_catalog_read', 'on', true);
  for sibling in
    select app_id, customer_id, schema
    from schema_revision
    where activated_at is not null
      and not (app_id = proposed_app_id and customer_id = proposed_customer_id)
    order by app_id, customer_id
  loop
    for proposed_model in
      select value from jsonb_array_elements(proposed_schema->'models')
    loop
      select value
      into sibling_model
      from jsonb_array_elements(coalesce(sibling.schema->'models', '[]'::jsonb))
      where value->>'id' = proposed_model->>'id'
      limit 1;
      if not found then
        continue;
      end if;

      for proposed_field in
        select value from jsonb_array_elements(coalesce(proposed_model->'fields', '[]'::jsonb))
      loop
        select value
        into sibling_field
        from jsonb_array_elements(coalesce(sibling_model->'fields', '[]'::jsonb))
        where value->>'id' = proposed_field->>'id'
        limit 1;
        if found and (
          sibling_field->>'type' is distinct from proposed_field->>'type'
          or sibling_field->>'target_model' is distinct from proposed_field->>'target_model'
        ) then
          mismatch := format(
            'column %L has a different physical contract',
            proposed_field->>'id'
          );
          perform set_config(
            'kernel.schema_catalog_read',
            coalesce(previous_catalog_read, ''),
            true
          );
          return jsonb_build_object(
            'ok', false,
            'error', jsonb_build_object(
              'code', 'schema_drift',
              'message', 'Schema drift detected',
              'details', jsonb_build_array(jsonb_build_object(
                'path', 'object',
                'code', 'schema_drift',
                'message', proposed_model->>'id' || '_version: ' || mismatch || '; active sibling scope=' || sibling.app_id || '/' || sibling.customer_id || '; coordinated schema migration required because sequential materialization cannot change required, unique, or physical column contracts across active sibling tenants'
              ))
            )
          );
        end if;
      end loop;

      select coalesce(array_agg(value->>'id' order by value->>'id'), array[]::text[])
      into proposed_required
      from jsonb_array_elements(coalesce(proposed_model->'fields', '[]'::jsonb))
      where coalesce((value->>'required')::boolean, false);
      select coalesce(array_agg(value->>'id' order by value->>'id'), array[]::text[])
      into sibling_required
      from jsonb_array_elements(coalesce(sibling_model->'fields', '[]'::jsonb))
      where coalesce((value->>'required')::boolean, false);
      if proposed_required is distinct from sibling_required then
        mismatch := format(
          'required columns differ (proposed=%s, active=%s)',
          proposed_required,
          sibling_required
        );
        perform set_config(
          'kernel.schema_catalog_read',
          coalesce(previous_catalog_read, ''),
          true
        );
        return jsonb_build_object(
          'ok', false,
          'error', jsonb_build_object(
            'code', 'schema_drift',
            'message', 'Schema drift detected',
            'details', jsonb_build_array(jsonb_build_object(
              'path', 'object',
              'code', 'schema_drift',
              'message', proposed_model->>'id' || '_version: ' || mismatch || '; active sibling scope=' || sibling.app_id || '/' || sibling.customer_id || '; coordinated schema migration required because sequential materialization cannot change required, unique, or physical column contracts across active sibling tenants'
            ))
          )
        );
      end if;

      select coalesce(array_agg(value->>'id' order by value->>'id'), array[]::text[])
      into proposed_unique
      from jsonb_array_elements(coalesce(proposed_model->'fields', '[]'::jsonb))
      where coalesce((value->>'is_unique')::boolean, false);
      select coalesce(array_agg(value->>'id' order by value->>'id'), array[]::text[])
      into sibling_unique
      from jsonb_array_elements(coalesce(sibling_model->'fields', '[]'::jsonb))
      where coalesce((value->>'is_unique')::boolean, false);
      if proposed_unique is distinct from sibling_unique then
        mismatch := format(
          'unique columns differ (proposed=%s, active=%s)',
          proposed_unique,
          sibling_unique
        );
        perform set_config(
          'kernel.schema_catalog_read',
          coalesce(previous_catalog_read, ''),
          true
        );
        return jsonb_build_object(
          'ok', false,
          'error', jsonb_build_object(
            'code', 'schema_drift',
            'message', 'Schema drift detected',
            'details', jsonb_build_array(jsonb_build_object(
              'path', 'object',
              'code', 'schema_drift',
              'message', proposed_model->>'id' || '_version: ' || mismatch || '; active sibling scope=' || sibling.app_id || '/' || sibling.customer_id || '; coordinated schema migration required because sequential materialization cannot change required, unique, or physical column contracts across active sibling tenants'
            ))
          )
        );
      end if;
    end loop;
  end loop;

  perform set_config(
    'kernel.schema_catalog_read',
    coalesce(previous_catalog_read, ''),
    true
  );
  return jsonb_build_object('ok', true, 'data', jsonb_build_object('compatible', true));
end
$kernel$;

-- artifact: function kernel_lookup_has_typed_history(text,text,text)
create or replace function kernel_lookup_has_typed_history(
  requested_app_id text,
  requested_customer_id text,
  requested_model_id text
)
returns boolean
language plpgsql
stable
security invoker
set search_path from current
as $kernel$
declare
  legacy_table text;
  table_has_typed_history boolean;
begin
  foreach legacy_table in array array[
    kernel_physical_identifier(requested_model_id || '_record'),
    kernel_physical_identifier(requested_model_id || '_version')
  ] loop
    if to_regclass(format('%I.%I', current_schema(), legacy_table)) is not null then
      execute format(
        'select exists(select 1 from %I.%I where app_id=$1 and customer_id=$2)',
        current_schema(), legacy_table
      ) into table_has_typed_history using requested_app_id, requested_customer_id;
      if table_has_typed_history then
        return true;
      end if;
    end if;
  end loop;
  return false;
end;
$kernel$;

-- artifact: function kernel_canonical_json(jsonb)
create or replace function kernel_canonical_json(value jsonb)
returns text
language sql
immutable
strict
parallel safe
security invoker
set search_path from current
as $kernel$
  select case jsonb_typeof(value)
    when 'object' then
      '{' || coalesce((
        select string_agg(
          to_json(entry.key)::text || ':' || kernel_canonical_json(entry.value),
          ',' order by entry.key
        )
        from jsonb_each(value) as entry(key, value)
      ), '') || '}'
    when 'array' then
      '[' || coalesce((
        select string_agg(
          kernel_canonical_json(entry.value),
          ',' order by entry.ordinality
        )
        from jsonb_array_elements(value) with ordinality as entry(value, ordinality)
      ), '') || ']'
    else value::text
  end
$kernel$;

-- artifact: function kernel_physical_identifier(text)
create or replace function kernel_fnv1a64_hex(value text)
returns text
language plpgsql
immutable
strict
parallel safe
security invoker
set search_path from current
as $kernel$
declare
  bytes bytea := convert_to(value, 'UTF8');
  hash bigint := -3750763034362895579;
  unsigned_hash numeric;
  position integer;
begin
  if octet_length(bytes) > 0 then
    for position in 0..octet_length(bytes) - 1 loop
      hash := hash # get_byte(bytes, position)::bigint;
      unsigned_hash := case
        when hash < 0 then hash::numeric + 18446744073709551616
        else hash::numeric
      end;
      unsigned_hash := mod(unsigned_hash * 1099511628211, 18446744073709551616);
      hash := case
        when unsigned_hash >= 9223372036854775808
          then (unsigned_hash - 18446744073709551616)::bigint
        else unsigned_hash::bigint
      end;
    end loop;
  end if;
  return lpad(to_hex(hash), 16, '0');
end
$kernel$;

create or replace function kernel_physical_identifier(value text)
returns text
language plpgsql
immutable
strict
parallel safe
security invoker
set search_path from current
as $kernel$
declare
  normalized text;
begin
  normalized := trim(both '_' from regexp_replace(
    regexp_replace(lower(btrim(value)), '[_\-[:space:]]+', '_', 'g'),
    '[^a-z0-9_]', '', 'g'
  ));
  if octet_length(normalized) <= 63 then
    return normalized;
  end if;
  return left(normalized, 46) || '_' || kernel_fnv1a64_hex(normalized);
end
$kernel$;

