-- artifact: function kernel_prepare_visible_query(jsonb)
do $kernel$
declare
  schema_name text := current_schema();
  query_role text := kernel_installer_capability_role('query');
begin
  if to_regrole(query_role) is not null then
    if exists (
      select 1
      from pg_roles
      where rolname = query_role
        and (rolcanlogin or rolbypassrls)
    ) then
      raise exception 'generated query role must be NOLOGIN NOBYPASSRLS';
    end if;
    execute format('grant usage on schema %I to %I', schema_name, query_role);
    execute format(
      'revoke all privileges on all tables in schema %I from %I',
      schema_name, query_role
    );
    execute format(
      'revoke all privileges on all sequences in schema %I from %I',
      schema_name, query_role
    );
  end if;
end
$kernel$;

create or replace function kernel_prepare_visible_query(request jsonb)
returns jsonb
language plpgsql
volatile
security invoker
set search_path from current
as $kernel$
declare
  request_app_id text;
  request_customer_id text;
  request_as_of date;
  policy_snapshot jsonb;
  active_schema jsonb;
  source_schema text := current_schema();
  query_role text := kernel_installer_capability_role('query');
  model_json jsonb;
  model_id text;
  model_kind text;
  field_json jsonb;
  field_id text;
  field_type text;
  field_identifier text;
  projection_sql text;
  record_table text;
  version_table text;
begin
  perform kernel_cleanup_generated_visible_query();
  if request is null or jsonb_typeof(request) <> 'object' then
    return jsonb_build_object(
      'ok', false,
      'error', jsonb_build_object(
        'code', 'contract_validation_failed',
        'message', 'request must be a JSON object'
      )
    );
  end if;
  request_app_id := request->>'app_id';
  request_customer_id := request->>'customer_id';
  if request_app_id is null or btrim(request_app_id) = ''
     or request_customer_id is null or btrim(request_customer_id) = '' then
    return jsonb_build_object(
      'ok', false,
      'error', jsonb_build_object(
        'code', 'contract_validation_failed',
        'message', 'app_id and customer_id are required'
      )
    );
  end if;
  if request ? 'as_of' and request->>'as_of' is not null then
    request_as_of := (request->>'as_of')::date;
  end if;

  perform set_config('kernel.app_id', request_app_id, true);
  perform set_config('kernel.customer_id', request_customer_id, true);

  select schema_revision.schema
  into active_schema
  from schema_revision
  where app_id = request_app_id
    and customer_id = request_customer_id
    and activated_at is not null;
  if active_schema is null then
    return jsonb_build_object(
      'ok', false,
      'error', jsonb_build_object(
        'code', 'active_schema_missing',
        'message', 'No active schema revision exists for this scope'
      )
    );
  end if;

  policy_snapshot := kernel_policy_active_snapshot(request_app_id, request_customer_id);
  if coalesce((policy_snapshot->>'declared')::boolean, false) then
    perform kernel_policy_request_actor(request_app_id, request_customer_id);
    return jsonb_build_object(
      'ok', false,
      'error', jsonb_build_object(
        'code', 'unsupported_capability',
        'message', 'The legacy prepared visible-query protocol is unavailable for policy-enabled revisions'
      )
    );
  end if;

  begin
    execute 'deallocate kernel_visible_query_validation';
  exception when invalid_sql_statement_name then
    null;
  end;

  execute format(
    'create temp view change_set as select * from %I.change_set where app_id = %L and customer_id = %L',
    source_schema,
    request_app_id,
    request_customer_id
  );
  if to_regrole(query_role) is not null then
    execute format('grant select on pg_temp.change_set to %I', query_role);
  end if;

  for model_json in
    select model.value
    from jsonb_array_elements(active_schema->'models') with ordinality model(value, ordinal)
    order by model.ordinal
  loop
    model_id := model_json->>'id';
    model_kind := coalesce(model_json->>'kind', 'entity');
    record_table := kernel_physical_identifier(model_id || '_record');
    version_table := kernel_physical_identifier(model_id || '_version');
    if model_kind = 'lookup' then
      projection_sql := 'v.*';
      for field_json in
        select field.value
        from jsonb_array_elements(coalesce(model_json->'fields', '[]'::jsonb))
          with ordinality as field(value, ordinal)
        where coalesce(field.value->>'lifecycle', 'active') = 'active'
        order by field.ordinal
      loop
        field_id := field_json->>'id';
        field_type := field_json->>'type';
        field_identifier := kernel_physical_identifier(field_id);
        case
          when field_type in ('text', 'enum', 'iso_country', 'iso_currency') then
            projection_sql := projection_sql || format(
              ', v.values->%L->>''value'' as %I', field_id, field_identifier
            );
          when field_type = 'number' then
            projection_sql := projection_sql || format(
              ', (v.values->%L->>''value'')::numeric as %I', field_id, field_identifier
            );
          when field_type = 'bool' then
            projection_sql := projection_sql || format(
              ', (v.values->%L->>''value'')::boolean as %I', field_id, field_identifier
            );
          when field_type = 'date' then
            projection_sql := projection_sql || format(
              ', (v.values->%L->>''value'')::date as %I', field_id, field_identifier
            );
          when field_type = 'datetime' then
            projection_sql := projection_sql || format(
              ', (v.values->%L->>''value'')::timestamptz as %I', field_id, field_identifier
            );
          when field_type = 'relation' then
            projection_sql := projection_sql || format(
              ', (v.values #>> array[%L,''value'',''value''])::uuid as %I',
              field_id, field_identifier
            );
          when field_type in ('text_list', 'known_aliases') then
            projection_sql := projection_sql || format(
              ', array(select jsonb_array_elements_text(coalesce(v.values->%L->''value'',''[]''::jsonb))) as %I',
              field_id, field_identifier
            );
          when field_type = 'json' then
            projection_sql := projection_sql || format(
              ', v.values->%L->''value'' as %I', field_id, field_identifier
            );
          when field_type = 'money_rate' then
            projection_sql := projection_sql || format(
              ', (v.values #>> array[%L,''value'',''amount''])::numeric as %I',
              field_id, kernel_physical_identifier(field_id || '_amount')
            );
            projection_sql := projection_sql || format(
              ', v.values #>> array[%L,''value'',''currency''] as %I',
              field_id, kernel_physical_identifier(field_id || '_currency')
            );
            projection_sql := projection_sql || format(
              ', v.values #>> array[%L,''value'',''period''] as %I',
              field_id, kernel_physical_identifier(field_id || '_period')
            );
          else
            return jsonb_build_object(
              'ok', false,
              'error', jsonb_build_object(
                'code', 'schema_drift',
                'message', format('lookup field `%s.%s` has unsupported type `%s`', model_id, field_id, field_type)
              )
            );
        end case;
      end loop;

      execute format(
        $query$
        create temp view %I as
        with visible_version as (
          select distinct on (v.record_id) v.*
          from %I.lookup_version v
          join %I.change_set changes
            on changes.id = v.change_set_id
           and changes.app_id = v.app_id
           and changes.customer_id = v.customer_id
          where v.app_id = %L
            and v.customer_id = %L
            and v.model_id = %L
            and v.stage = 'mainline'
            and changes.status = 'mainline'
            and changes.applied_order is not null
            and v.effective_start <= coalesce(%L::date, current_date)
            and (v.effective_end is null or v.effective_end >= coalesce(%L::date, current_date))
          order by v.record_id, v.effective_start desc,
            v.tombstones_record desc, v.untombstones_record desc,
            changes.applied_order desc, v.id desc
        )
        select r.*
        from %I.lookup_record r
        join visible_version v
          on v.app_id = r.app_id
         and v.customer_id = r.customer_id
         and v.model_id = r.model_id
         and v.record_id = r.id
        where r.app_id = %L
          and r.customer_id = %L
          and r.model_id = %L
          and not v.tombstones_record
          and not v.untombstones_record
          and v.availability = 'active'
        $query$,
        record_table,
        source_schema,
        source_schema,
        request_app_id,
        request_customer_id,
        model_id,
        request_as_of,
        request_as_of,
        source_schema,
        request_app_id,
        request_customer_id,
        model_id
      );
      execute format(
        $query$
        create temp view %I as
        select %s
        from (
          select distinct on (lookup_version.record_id) lookup_version.*
          from %I.lookup_version
          join %I.change_set changes
            on changes.id = lookup_version.change_set_id
           and changes.app_id = lookup_version.app_id
           and changes.customer_id = lookup_version.customer_id
          where lookup_version.app_id = %L
            and lookup_version.customer_id = %L
            and lookup_version.model_id = %L
            and lookup_version.stage = 'mainline'
            and changes.status = 'mainline'
            and changes.applied_order is not null
            and lookup_version.effective_start <= coalesce(%L::date, current_date)
            and (lookup_version.effective_end is null or lookup_version.effective_end >= coalesce(%L::date, current_date))
          order by lookup_version.record_id, lookup_version.effective_start desc,
            lookup_version.tombstones_record desc, lookup_version.untombstones_record desc,
            changes.applied_order desc, lookup_version.id desc
        ) v
        where not v.tombstones_record
          and not v.untombstones_record
          and v.availability = 'active'
        $query$,
        version_table,
        projection_sql,
        source_schema,
        source_schema,
        request_app_id,
        request_customer_id,
        model_id,
        request_as_of,
        request_as_of
      );
      if to_regrole(query_role) is not null then
        execute format('grant select on pg_temp.%I to %I', record_table, query_role);
        execute format('grant select on pg_temp.%I to %I', version_table, query_role);
      end if;
      continue;
    end if;
    if request_as_of is null then
      execute format(
        'create temp view %I as select * from %I.%I where app_id = %L and customer_id = %L',
        record_table,
        source_schema,
        record_table,
        request_app_id,
        request_customer_id
      );
      execute format(
        'create temp view %I as select * from %I.%I where app_id = %L and customer_id = %L',
        version_table,
        source_schema,
        version_table,
        request_app_id,
        request_customer_id
      );
    else
      execute format(
        $query$
        create temp view %I as
        with visible_version as (
          select distinct on (version.record_id) version.*
          from %I.%I version
          join %I.change_set changes
            on changes.id = version.change_set_id
           and changes.app_id = version.app_id
           and changes.customer_id = version.customer_id
          where version.app_id = %L
            and version.customer_id = %L
            and version.stage = 'mainline'
            and changes.status = 'mainline'
            and changes.applied_order is not null
            and version.effective_start <= %L::date
            and (version.effective_end is null or version.effective_end >= %L::date)
          order by version.record_id, version.effective_start desc, changes.applied_order desc, version.id desc
        )
        select record.*
        from %I.%I record
        join visible_version version on version.record_id = record.id
        where record.app_id = %L
          and record.customer_id = %L
          and not version.tombstones_record
          and not version.untombstones_record
        $query$,
        record_table,
        source_schema,
        version_table,
        source_schema,
        request_app_id,
        request_customer_id,
        request_as_of,
        request_as_of,
        source_schema,
        record_table,
        request_app_id,
        request_customer_id
      );
      execute format(
        $query$
        create temp view %I as
        select *
        from (
          select distinct on (version.record_id) version.*
          from %I.%I version
          join %I.change_set changes
            on changes.id = version.change_set_id
           and changes.app_id = version.app_id
           and changes.customer_id = version.customer_id
          where version.app_id = %L
            and version.customer_id = %L
            and version.stage = 'mainline'
            and changes.status = 'mainline'
            and changes.applied_order is not null
            and version.effective_start <= %L::date
            and (version.effective_end is null or version.effective_end >= %L::date)
          order by version.record_id, version.effective_start desc, changes.applied_order desc, version.id desc
        ) visible_version
        where not tombstones_record and not untombstones_record
        $query$,
        version_table,
        source_schema,
        version_table,
        source_schema,
        request_app_id,
        request_customer_id,
        request_as_of,
        request_as_of
      );
    end if;
    if to_regrole(query_role) is not null then
      execute format('grant select on pg_temp.%I to %I', record_table, query_role);
      execute format('grant select on pg_temp.%I to %I', version_table, query_role);
    end if;
  end loop;
  return jsonb_build_object('ok', true, 'data', jsonb_build_object(
    'schema', source_schema,
    'query_role', query_role
  ));
exception when others then
  return jsonb_build_object(
    'ok', false,
    'error', jsonb_build_object('code', 'query_rejected', 'message', sqlerrm)
  );
end;
$kernel$;

-- artifact: function kernel_validate_visible_query(jsonb)
create or replace function kernel_validate_visible_query(request jsonb)
returns jsonb
language plpgsql
volatile
security invoker
set search_path from current
as $kernel$
declare
  statement text;
  params jsonb;
  param jsonb;
  param_type text;
  param_value text;
  prepared_types text := '';
  prepared_values text := '';
  prepare_sql text;
  explain_sql text;
  plan jsonb;
  operation text;
  scoped_app_id text := nullif(current_setting('kernel.app_id', true), '');
  scoped_customer_id text := nullif(current_setting('kernel.customer_id', true), '');
begin
  if scoped_app_id is not null and scoped_customer_id is not null
    and not kernel_policy_raw_table_access_allowed(
      current_user::name, scoped_app_id, scoped_customer_id
    )
  then
    return jsonb_build_object(
      'ok', false,
      'error', jsonb_build_object(
        'code', 'unsupported_capability',
        'message', 'The legacy prepared visible-query protocol is unavailable for policy-enabled revisions'
      )
    );
  end if;
  if request is null or jsonb_typeof(request) <> 'object' then
    return jsonb_build_object(
      'ok', false,
      'error', jsonb_build_object('code', 'query_rejected', 'message', 'query validation request must be an object')
    );
  end if;
  statement := request->>'sql';
  params := coalesce(request->'params', '[]'::jsonb);
  if jsonb_typeof(params) <> 'array' then
    return jsonb_build_object(
      'ok', false,
      'error', jsonb_build_object('code', 'query_rejected', 'message', 'query params must be an array')
    );
  end if;
  if statement is null or btrim(statement) = '' then
    return jsonb_build_object(
      'ok', false,
      'error', jsonb_build_object('code', 'query_rejected', 'message', 'SQL must not be empty')
    );
  end if;
  if statement ~* '(^|[^a-z0-9_])set_config[[:space:]]*\(' then
    return jsonb_build_object(
      'ok', false,
      'error', jsonb_build_object('code', 'query_rejected', 'message', 'SQL must not call set_config')
    );
  end if;

  for param in select value from jsonb_array_elements(params) with ordinality entry(value, ordinal) order by ordinal
  loop
    if jsonb_typeof(param) <> 'object' or not (param ? 'type') or not (param ? 'value') then
      return jsonb_build_object(
        'ok', false,
        'error', jsonb_build_object('code', 'query_rejected', 'message', 'each query parameter requires type and value')
      );
    end if;
    param_type := param->>'type';
    param_value := param #>> '{value}';
    if param_value is null then
      return jsonb_build_object(
        'ok', false,
        'error', jsonb_build_object('code', 'query_rejected', 'message', 'query parameters cannot be null')
      );
    end if;
    prepared_types := prepared_types || case when prepared_types = '' then '' else ', ' end;
    prepared_values := prepared_values || case when prepared_values = '' then '' else ', ' end;
    case param_type
      when 'text' then
        prepared_types := prepared_types || 'text';
        prepared_values := prepared_values || format('%L::text', param_value);
      when 'int' then
        perform param_value::bigint;
        prepared_types := prepared_types || 'bigint';
        prepared_values := prepared_values || format('%L::bigint', param_value);
      when 'number' then
        perform param_value::numeric;
        prepared_types := prepared_types || 'numeric';
        prepared_values := prepared_values || format('%L::numeric', param_value);
      when 'bool' then
        perform param_value::boolean;
        prepared_types := prepared_types || 'boolean';
        prepared_values := prepared_values || format('%L::boolean', param_value);
      when 'date' then
        perform param_value::date;
        prepared_types := prepared_types || 'date';
        prepared_values := prepared_values || format('%L::date', param_value);
      when 'json' then
        prepared_types := prepared_types || 'jsonb';
        prepared_values := prepared_values || format('%L::jsonb', (param->'value')::text);
      else
        return jsonb_build_object(
          'ok', false,
          'error', jsonb_build_object('code', 'query_rejected', 'message', 'unsupported query parameter type `' || param_type || '`')
        );
    end case;
  end loop;

  begin
    begin
      execute 'deallocate kernel_visible_query_validation';
    exception when invalid_sql_statement_name then
      null;
    end;
    prepare_sql := 'prepare kernel_visible_query_validation';
    if prepared_types <> '' then
      prepare_sql := prepare_sql || ' (' || prepared_types || ')';
    end if;
    execute prepare_sql || ' as ' || statement;
    explain_sql := 'explain (format json, verbose true) execute kernel_visible_query_validation';
    if prepared_values <> '' then
      explain_sql := explain_sql || '(' || prepared_values || ')';
    end if;
    execute explain_sql into plan;
    execute 'deallocate kernel_visible_query_validation';
  exception when others then
    begin
      execute 'deallocate kernel_visible_query_validation';
    exception when invalid_sql_statement_name then
      null;
    end;
    return jsonb_build_object(
      'ok', false,
      'error', jsonb_build_object(
        'code', case when sqlstate = '57014' then 'query_timeout' else 'query_rejected' end,
        'message', sqlerrm
      )
    );
  end;
  operation := plan #>> '{0,Plan,Operation}';
  if operation is not null and operation <> 'Select' then
    return jsonb_build_object(
      'ok', false,
      'error', jsonb_build_object('code', 'query_rejected', 'message', 'SQL must be one SELECT statement')
    );
  end if;
  if plan::text ~ '"Schema"[[:space:]]*:[[:space:]]*"(pg_catalog|information_schema)"' then
    return jsonb_build_object(
      'ok', false,
      'error', jsonb_build_object(
        'code', 'query_rejected',
        'message', 'SQL must not reference Postgres catalog objects'
      )
    );
  end if;
  return jsonb_build_object('ok', true, 'data', jsonb_build_object());
exception when others then
  begin
    execute 'deallocate kernel_visible_query_validation';
  exception when invalid_sql_statement_name then
    null;
  end;
  return jsonb_build_object(
    'ok', false,
    'error', jsonb_build_object(
      'code', case when sqlstate = '57014' then 'query_timeout' else 'query_rejected' end,
      'message', sqlerrm
    )
  );
end;
$kernel$;

-- artifact: function kernel_validate_visible_query(text)
create or replace function kernel_validate_visible_query(statement text)
returns jsonb
language sql
volatile
security invoker
set search_path from current
as $kernel$
  select kernel_validate_visible_query(
    jsonb_build_object('sql', statement, 'params', '[]'::jsonb)
  )
$kernel$;

-- artifact: function kernel_policy_reject_unsupported_capability(text,text,text)
create or replace function kernel_policy_reject_unsupported_capability(
  app_id text,
  customer_id text,
  capability text
)
returns void
language plpgsql
volatile
security invoker
set search_path from current
as $kernel$
declare
  snapshot jsonb;
begin
  if app_id is null or btrim(app_id) = ''
     or customer_id is null or btrim(customer_id) = '' then
    return;
  end if;
  perform set_config('kernel.app_id', app_id, true);
  perform set_config('kernel.customer_id', customer_id, true);
  if not exists (
    select 1
    from schema_revision revision
    where revision.app_id = $1
      and revision.customer_id = $2
      and revision.activated_at is not null
  ) then
    return;
  end if;
  snapshot := kernel_policy_active_snapshot(app_id, customer_id);
  if coalesce((snapshot->>'declared')::boolean, false) then
    perform kernel_policy_request_actor(app_id, customer_id);
    raise exception 'unsupported_capability: %', capability;
  end if;
end;
$kernel$;

-- artifact: function kernel_derived_divide(numeric,numeric)
create or replace function kernel_derived_divide(dividend numeric, divisor numeric)
returns numeric
language plpgsql
immutable
strict
parallel safe
security invoker
set search_path from current
as $kernel$
declare
  numerator numeric;
  denominator numeric;
  common numeric;
  residual numeric;
  twos integer := 0;
  fives integer := 0;
  exponent integer;
  result_scale integer;
  quotient numeric;
  twice_remainder numeric;
begin
  if divisor = 0 then return null; end if;
  if dividend = 0 then return 0; end if;
  numerator := trunc(abs(dividend) * ('1e' || (scale(dividend) + scale(divisor)))::numeric);
  denominator := trunc(abs(divisor) * ('1e' || (scale(dividend) + scale(divisor)))::numeric);
  common := gcd(numerator, denominator);
  numerator := div(numerator, common);
  denominator := div(denominator, common);
  residual := denominator;
  while mod(residual, 2) = 0 loop residual := div(residual, 2); twos := twos + 1; end loop;
  while mod(residual, 5) = 0 loop residual := div(residual, 5); fives := fives + 1; end loop;
  if residual = 1 then
    result_scale := greatest(twos, fives);
    quotient := numerator * power(2::numeric, result_scale - twos) * power(5::numeric, result_scale - fives);
  else
    exponent := length(numerator::text) - length(denominator::text);
    if (exponent >= 0 and numerator < denominator * ('1e' || exponent)::numeric)
      or (exponent < 0 and numerator * ('1e' || (-exponent))::numeric < denominator) then
      exponent := exponent - 1;
    end if;
    result_scale := 27 - exponent;
    if result_scale >= 0 then
      numerator := numerator * ('1e' || result_scale)::numeric;
    else
      denominator := denominator * ('1e' || (-result_scale))::numeric;
    end if;
    quotient := div(numerator, denominator);
    twice_remainder := 2 * mod(numerator, denominator);
    if twice_remainder > denominator or (twice_remainder = denominator and mod(quotient, 2) <> 0) then
      quotient := quotient + 1;
    end if;
  end if;
  quotient := (trunc(quotient)::text || 'e' || (-result_scale))::numeric;
  return case when (dividend < 0) <> (divisor < 0) then -quotient else quotient end;
end;
$kernel$;

-- artifact: function kernel_derived_money(numeric,text,text)
create or replace function kernel_derived_money(amount numeric, currency text, period text)
returns jsonb
language sql
immutable
parallel safe
security invoker
set search_path from current
as $kernel$
  select case when amount is null then null else jsonb_build_object(
    'amount', trim_scale(amount)::text, 'currency', currency, 'period', period
  ) end
$kernel$;

-- artifact: function kernel_derived_money_combine(jsonb,jsonb,integer)
create or replace function kernel_derived_money_combine(left_value jsonb, right_value jsonb, sign integer)
returns jsonb
language sql
immutable
parallel safe
security invoker
set search_path from current
as $kernel$
  select case
    when left_value is null or right_value is null
      or left_value->>'currency' is distinct from right_value->>'currency'
      or left_value->>'period' is distinct from right_value->>'period'
      then null
    else kernel_derived_money(
      (left_value->>'amount')::numeric + sign * (right_value->>'amount')::numeric,
      left_value->>'currency', left_value->>'period'
    )
  end
$kernel$;

-- artifact: function kernel_derived_money_scale(jsonb,numeric,boolean)
create or replace function kernel_derived_money_scale(money_value jsonb, factor numeric, divide boolean)
returns jsonb
language sql
immutable
parallel safe
security invoker
set search_path from current
as $kernel$
  select case when money_value is null or factor is null then null else kernel_derived_money(
    case when divide then kernel_derived_divide((money_value->>'amount')::numeric, factor)
      else (money_value->>'amount')::numeric * factor end,
    money_value->>'currency', money_value->>'period'
  ) end
$kernel$;

-- artifact: function kernel_derived_money_normalize(jsonb,text)
create or replace function kernel_derived_money_normalize(money_value jsonb, target_period text)
returns jsonb
language sql
immutable
parallel safe
security invoker
set search_path from current
as $kernel$
  with factor(period, per_year) as (
    values ('hourly', 2080::numeric), ('daily', 260), ('weekly', 52), ('monthly', 12), ('annual', 1)
  )
  select case when money_value is null then null else kernel_derived_money(
    kernel_derived_divide(
      (money_value->>'amount')::numeric * (select per_year from factor where period = money_value->>'period'),
      (select per_year from factor where period = target_period)
    ),
    money_value->>'currency', target_period
  ) end
$kernel$;

-- artifact: function kernel_derived_environment(jsonb,text)
create or replace function kernel_derived_environment(schema_json jsonb, model_id text)
returns jsonb
language sql
immutable
parallel safe
security invoker
set search_path from current
as $kernel$
  select coalesce((
    select jsonb_object_agg(field.value->>'id', jsonb_build_object('type', field.value->>'type', 'source', 'base'))
    from jsonb_array_elements(coalesce(schema_json->'models', '[]'::jsonb)) model(value)
    cross join jsonb_array_elements(coalesce(model.value->'fields', '[]'::jsonb)) field(value)
    where model.value->>'id' = model_id and coalesce(field.value->>'lifecycle', 'active') = 'active'
  ), '{}'::jsonb) || coalesce((
    select jsonb_object_agg(custom.value->>'field_id', jsonb_strip_nulls(jsonb_build_object(
      'type', custom.value->>'type', 'source', 'custom',
      'expression', nullif(custom.value->'expression', 'null'::jsonb)
    )))
    from jsonb_array_elements(coalesce(schema_json->'custom_fields', '[]'::jsonb)) custom(value)
    where custom.value->>'model_id' = model_id
      and coalesce(custom.value->>'lifecycle', 'active') = 'active'
      and coalesce(custom.value->'archived_at', 'null'::jsonb) = 'null'::jsonb
  ), '{}'::jsonb)
$kernel$;

-- artifact: function kernel_derived_infer(jsonb,jsonb,jsonb,integer,integer)
create or replace function kernel_derived_infer(
  expression jsonb,
  environment jsonb,
  visiting jsonb,
  depth integer,
  nodes integer
)
returns jsonb
language plpgsql
immutable
parallel safe
security invoker
set search_path from current
as $kernel$
declare
  node_type text;
  target jsonb;
  item jsonb;
  result jsonb;
  left_type text;
  right_type text;
  expected text;
  literal jsonb;
  invalid constant jsonb := jsonb_build_object('code', 'invalid_derived_expression', 'message', 'derived expression node is malformed');
begin
  nodes := nodes + 1;
  if nodes > 256 or depth > 32 then
    return jsonb_build_object('code', 'derived_expression_too_large', 'message',
      'derived expressions are limited to 256 nodes and depth 32 after expanding referenced derived fields');
  end if;
  if jsonb_typeof(expression) is distinct from 'object' or jsonb_typeof(expression->'type') is distinct from 'string' then
    return invalid;
  end if;
  node_type := expression->>'type';
  if node_type = 'field' then
    if expression - array['type', 'field'] <> '{}'::jsonb or jsonb_typeof(expression->'field') is distinct from 'string' then
      return invalid;
    end if;
    target := environment->(expression->>'field');
    if target is null then
      return jsonb_build_object('code', 'unknown_field', 'message', format('field `%s` is not an active field on the model', expression->>'field'));
    end if;
    if not target ? 'expression' then
      return jsonb_build_object('type', target->>'type', 'nodes', nodes);
    end if;
    if visiting ? (expression->>'field') then
      return jsonb_build_object('code', 'derived_cycle', 'message', format('derived field `%s` references itself', expression->>'field'));
    end if;
    return kernel_derived_infer(target->'expression', environment, visiting || jsonb_build_array(expression->>'field'), depth + 1, nodes);
  elsif node_type = 'literal' then
    literal := expression->'value';
    if expression - array['type', 'value'] <> '{}'::jsonb or jsonb_typeof(literal) is distinct from 'object'
      or jsonb_typeof(literal->'type') is distinct from 'string' or not literal ? 'value' or literal - array['type', 'value'] <> '{}'::jsonb then
      return invalid;
    end if;
    if literal->>'type' in ('enum', 'iso_country', 'iso_currency') then
      return jsonb_build_object('code', 'unsupported_derived_type', 'message', 'derived literals are text, number, bool, date, or datetime');
    end if;
    if literal->>'type' not in ('text', 'number', 'bool', 'date', 'datetime') then
      return invalid;
    end if;
    if not kernel_apply_typed_value_valid(literal, literal->>'type')
      or (literal->>'type' = 'number' and (literal->>'value' !~ '^-?[0-9]+([.][0-9]+)?$'
        or ltrim(replace(literal->>'value', '.', ''), '-')::numeric > 79228162514264337593543950335)) then
      return jsonb_build_object('code', 'type_mismatch', 'message', 'derived literal value is invalid');
    end if;
    return jsonb_build_object('type', literal->>'type', 'nodes', nodes);
  elsif node_type in ('coalesce', 'concat') then
    if expression - array['type', 'expressions'] <> '{}'::jsonb or jsonb_typeof(expression->'expressions') is distinct from 'array' then
      return invalid;
    end if;
    if jsonb_array_length(expression->'expressions') = 0 then
      return jsonb_build_object('code', 'empty_derived_expression', 'message', format('%s must contain at least one expression', node_type));
    end if;
    expected := case when node_type = 'concat' then 'text' end;
    for item in select value from jsonb_array_elements(expression->'expressions') loop
      result := kernel_derived_infer(item, environment, visiting, depth + 1, nodes);
      if result ? 'code' then return result; end if;
      nodes := (result->>'nodes')::integer;
      if expected is null then
        expected := result->>'type';
      elsif result->>'type' <> expected then
        return jsonb_build_object('code', 'type_mismatch', 'message',
          case when node_type = 'concat' then 'concat expressions must be text' else 'coalesce expressions must have one type' end);
      end if;
    end loop;
    return jsonb_build_object('type', expected, 'nodes', nodes);
  elsif node_type in ('add', 'subtract', 'multiply', 'divide') then
    if expression - array['type', 'left', 'right'] <> '{}'::jsonb or not expression ?& array['left', 'right'] then
      return invalid;
    end if;
    result := kernel_derived_infer(expression->'left', environment, visiting, depth + 1, nodes);
    if result ? 'code' then return result; end if;
    left_type := result->>'type';
    result := kernel_derived_infer(expression->'right', environment, visiting, depth + 1, (result->>'nodes')::integer);
    if result ? 'code' then return result; end if;
    right_type := result->>'type';
    nodes := (result->>'nodes')::integer;
    if node_type in ('add', 'subtract') then
      if left_type = right_type and left_type in ('number', 'money_rate') then
        return jsonb_build_object('type', left_type, 'nodes', nodes);
      end if;
      return jsonb_build_object('code', 'type_mismatch', 'message', 'add/subtract requires matching number or money_rate operands');
    end if;
    if left_type = 'number' and right_type = 'number' then
      return jsonb_build_object('type', 'number', 'nodes', nodes);
    end if;
    if (node_type = 'multiply' and ((left_type = 'money_rate' and right_type = 'number') or (left_type = 'number' and right_type = 'money_rate')))
      or (node_type = 'divide' and left_type = 'money_rate' and right_type = 'number') then
      return jsonb_build_object('type', 'money_rate', 'nodes', nodes);
    end if;
    return jsonb_build_object('code', 'type_mismatch', 'message', 'multiply/divide operands are not a supported number or money_rate combination');
  elsif node_type = 'normalize_money_rate' then
    if expression - array['type', 'expression', 'period'] <> '{}'::jsonb or not expression ? 'expression'
      or expression->>'period' is null or expression->>'period' not in ('hourly', 'daily', 'weekly', 'monthly', 'annual') then
      return invalid;
    end if;
    result := kernel_derived_infer(expression->'expression', environment, visiting, depth + 1, nodes);
    if result ? 'code' then return result; end if;
    if result->>'type' <> 'money_rate' then
      return jsonb_build_object('code', 'type_mismatch', 'message', 'normalize_money_rate requires money_rate input');
    end if;
    return result;
  elsif node_type in ('relation_field', 'inverse_aggregate') then
    return jsonb_build_object('code', 'unsupported_derived_expression', 'message',
      'relation_field and inverse_aggregate are not evaluated by the SQL runtime');
  end if;
  return jsonb_build_object('code', 'unsupported_derived_expression', 'message', format('derived expression type `%s` is not supported', node_type));
end;
$kernel$;

-- artifact: function kernel_derived_issues(jsonb,text,jsonb,text,text)
create or replace function kernel_derived_issues(
  environment jsonb,
  field_id text,
  expression jsonb,
  declared_type text,
  path text
)
returns jsonb
language plpgsql
immutable
parallel safe
security invoker
set search_path from current
as $kernel$
declare
  result jsonb;
begin
  if declared_type is null or declared_type not in ('text', 'number', 'bool', 'date', 'datetime', 'money_rate') then
    return jsonb_build_array(jsonb_build_object('path', path || '.type', 'code', 'unsupported_derived_type',
      'message', 'derived fields evaluate to text, number, bool, date, datetime, or money_rate'));
  end if;
  result := kernel_derived_infer(expression, environment, jsonb_build_array(field_id), 1, 0);
  if result ? 'code' then
    return jsonb_build_array(jsonb_build_object('path', path || '.expression', 'code', result->>'code', 'message', result->>'message'));
  end if;
  if result->>'type' not in ('text', 'number', 'bool', 'date', 'datetime', 'money_rate') then
    return jsonb_build_array(jsonb_build_object('path', path || '.type', 'code', 'unsupported_derived_type',
      'message', 'derived fields evaluate to text, number, bool, date, datetime, or money_rate'));
  end if;
  if result->>'type' <> declared_type then
    return jsonb_build_array(jsonb_build_object('path', path || '.type', 'code', 'type_mismatch',
      'message', format('declared type `%s` does not match expression type `%s`', declared_type, result->>'type')));
  end if;
  return '[]'::jsonb;
end;
$kernel$;

-- artifact: function kernel_derived_typed_sql(jsonb,jsonb,text,text)
create or replace function kernel_derived_typed_sql(
  expression jsonb,
  environment jsonb,
  base_accessor text,
  custom_accessor text
)
returns jsonb
language plpgsql
immutable
parallel safe
security invoker
set search_path from current
as $kernel$
declare
  node_type text := expression->>'type';
  target jsonb;
  accessor text;
  left_sql jsonb;
  right_sql jsonb;
  parts text[] := array[]::text[];
  result_type text;
  item jsonb;
  lowered jsonb;
begin
  if node_type = 'field' then
    target := environment->(expression->>'field');
    if target is null then
      raise exception 'schema_drift: derived field references an inactive field';
    end if;
    if target ? 'expression' then
      return kernel_derived_typed_sql(target->'expression', environment, base_accessor, custom_accessor);
    end if;
    accessor := format('nullif(%s,''null''::jsonb)',
      format(case when target->>'source' = 'base' then base_accessor else custom_accessor end, expression->>'field'));
    return jsonb_build_object('type', target->>'type', 'sql',
      case when target->>'type' = 'number' then format('(%s#>>''{}'')::numeric', accessor) else accessor end);
  elsif node_type = 'literal' then
    return jsonb_build_object('type', expression#>>'{value,type}', 'sql',
      case when expression#>>'{value,type}' = 'number' then format('%L::numeric', expression#>>'{value,value}')
        else format('%L::jsonb', expression#>'{value,value}') end);
  elsif node_type in ('coalesce', 'concat') then
    for item in select value from jsonb_array_elements(expression->'expressions') loop
      lowered := kernel_derived_typed_sql(item, environment, base_accessor, custom_accessor);
      result_type := lowered->>'type';
      parts := parts || case when node_type = 'concat' then format('(%s#>>''{}'')', lowered->>'sql') else lowered->>'sql' end;
    end loop;
    if node_type = 'concat' then
      return jsonb_build_object('type', 'text', 'sql', format('to_jsonb(%s)', array_to_string(parts, '||')));
    end if;
    return jsonb_build_object('type', result_type, 'sql', format('coalesce(%s)', array_to_string(parts, ',')));
  elsif node_type in ('add', 'subtract', 'multiply', 'divide') then
    left_sql := kernel_derived_typed_sql(expression->'left', environment, base_accessor, custom_accessor);
    right_sql := kernel_derived_typed_sql(expression->'right', environment, base_accessor, custom_accessor);
    if left_sql->>'type' = 'number' and right_sql->>'type' = 'number' then
      return jsonb_build_object('type', 'number', 'sql', case node_type
        when 'add' then format('(%s+%s)', left_sql->>'sql', right_sql->>'sql')
        when 'subtract' then format('(%s-%s)', left_sql->>'sql', right_sql->>'sql')
        when 'multiply' then format('(%s*%s)', left_sql->>'sql', right_sql->>'sql')
        else format('kernel_derived_divide(%s,%s)', left_sql->>'sql', right_sql->>'sql') end);
    end if;
    return jsonb_build_object('type', 'money_rate', 'sql', case
      when node_type in ('add', 'subtract') then format('kernel_derived_money_combine(%s,%s,%s)', left_sql->>'sql', right_sql->>'sql', case when node_type = 'add' then 1 else -1 end)
      when left_sql->>'type' = 'money_rate' then format('kernel_derived_money_scale(%s,%s,%L)', left_sql->>'sql', right_sql->>'sql', node_type = 'divide')
      else format('kernel_derived_money_scale(%s,%s,false)', right_sql->>'sql', left_sql->>'sql') end);
  elsif node_type = 'normalize_money_rate' then
    lowered := kernel_derived_typed_sql(expression->'expression', environment, base_accessor, custom_accessor);
    return jsonb_build_object('type', 'money_rate', 'sql',
      format('kernel_derived_money_normalize(%s,%L)', lowered->>'sql', expression->>'period'));
  end if;
  raise exception 'contract_validation_failed: unsupported derived expression';
end;
$kernel$;

-- artifact: function kernel_derived_value_sql(jsonb,jsonb,text,text)
create or replace function kernel_derived_value_sql(
  expression jsonb,
  environment jsonb,
  base_accessor text,
  custom_accessor text
)
returns text
language plpgsql
immutable
parallel safe
security invoker
set search_path from current
