begin
  return case when lowered->>'type' = 'number'
    then format('to_jsonb(trim_scale(%s)::text)', lowered->>'sql')
    else lowered->>'sql' end;
end;
$kernel$;

-- artifact: function kernel_derived_references(jsonb,jsonb)
create or replace function kernel_derived_references(expression jsonb, environment jsonb)
returns jsonb
language plpgsql
immutable
parallel safe
security invoker
set search_path from current
as $kernel$
declare
  result jsonb := '[]'::jsonb;
  child jsonb;
  target jsonb;
begin
  if expression->>'type' = 'field' then
    target := environment->(expression->>'field');
    if target ? 'expression' then
      return kernel_derived_references(target->'expression', environment);
    end if;
    return jsonb_build_array(expression->>'field');
  end if;
  for child in
    select value from jsonb_array_elements(coalesce(expression->'expressions', '[]'::jsonb))
    union all select expression->'left' where expression ? 'left'
    union all select expression->'right' where expression ? 'right'
    union all select expression->'expression' where jsonb_typeof(expression->'expression') = 'object'
  loop
    result := result || kernel_derived_references(child, environment);
  end loop;
  return result;
end;
$kernel$;

