    {"table":"agent_run","name":"schema_revision_id","type":"bigint","not_null":true},
    {"table":"agent_run","name":"actor_id","type":"text","not_null":false},
    {"table":"agent_run","name":"agent_identity_id","type":"text","not_null":true},
    {"table":"agent_run","name":"execution_profile_id","type":"text","not_null":true},
    {"table":"agent_run","name":"source_artifacts","type":"jsonb","not_null":true},
    {"table":"agent_run","name":"alignment_decisions","type":"jsonb","not_null":true},
    {"table":"agent_run","name":"model_calls","type":"jsonb","not_null":true},
    {"table":"agent_run","name":"tool_calls","type":"jsonb","not_null":true},
    {"table":"agent_run","name":"token_usage","type":"jsonb","not_null":true},
    {"table":"agent_run","name":"validation_failures","type":"jsonb","not_null":true},
    {"table":"agent_run","name":"final_outputs","type":"jsonb","not_null":true},
    {"table":"agent_run","name":"approval_boundaries","type":"jsonb","not_null":true},
    {"table":"agent_run","name":"compiled_preview_ids","type":"jsonb","not_null":true},
    {"table":"agent_run","name":"created_at","type":"timestamp with time zone","not_null":true}
  ]'::jsonb;
  expected_constraints jsonb := '[
    {"table":"schema_revision","name":"schema_revision_pkey","type":"p","columns":["id"]},
    {"table":"schema_revision","name":"schema_revision_scope_version_key","type":"u","columns":["app_id","customer_id","version"]},
    {"table":"schema_activation_head","name":"schema_activation_head_pkey","type":"p","columns":["app_id","customer_id"]},
    {"table":"change_set","name":"change_set_pkey","type":"p","columns":["id"]},
    {"table":"change_set","name":"change_set_created_with_mode_check","type":"c","expression":"created_with_mode = ANY (ARRAY[''mainline''::text, ''draft''::text])"},
    {"table":"change_set","name":"change_set_status_check","type":"c","expression":"status = ANY (ARRAY[''draft''::text, ''mainline''::text, ''discarded''::text])"},
    {"table":"change_set","name":"change_set_applied_at_status_check","type":"c","expression":"(status = ''mainline''::text) = (applied_at IS NOT NULL)"},
    {"table":"change_set","name":"change_set_applied_order_status_check","type":"c","expression":"(status = ''mainline''::text) = (applied_order IS NOT NULL)"},
    {"table":"change_set","name":"change_set_schema_revision_tenant_fk","type":"f","columns":["schema_revision_id","app_id","customer_id"],"ref_table":"schema_revision","ref_columns":["id","app_id","customer_id"]},
    {"table":"agent_run","name":"agent_run_pkey","type":"p","columns":["id"]},
    {"table":"agent_run","name":"agent_run_scope_run_key","type":"u","columns":["app_id","customer_id","run_id"]},
    {"table":"agent_run","name":"agent_run_status_check","type":"c","expression":"status = ANY (ARRAY[''recorded''::text, ''completed''::text, ''validation_exhausted''::text, ''budget_exhausted''::text, ''runtime_error''::text, ''cancelled''::text])"},
    {"table":"agent_run","name":"agent_run_schema_revision_tenant_fk","type":"f","columns":["schema_revision_id","app_id","customer_id"],"ref_table":"schema_revision","ref_columns":["id","app_id","customer_id"]}
  ]'::jsonb;
  expected_indexes jsonb := '[
    {"table":"schema_revision","name":"schema_revision_tenant_id_idx","unique":true,"columns":["id","app_id","customer_id"]},
    {"table":"schema_revision","name":"schema_revision_active_idx","unique":true,"columns":["app_id","customer_id"],"predicate":"activated_at IS NOT NULL"},
    {"table":"change_set","name":"change_set_tenant_id_idx","unique":true,"columns":["id","app_id","customer_id"]},
    {"table":"change_set","name":"change_set_idempotency_idx","unique":true,"columns":["app_id","customer_id","idempotency_key"],"predicate":"idempotency_key IS NOT NULL"},
    {"table":"agent_run","name":"agent_run_tenant_id_idx","unique":true,"columns":["id","app_id","customer_id"]}
  ]'::jsonb;
  policy_tables text[] := array['schema_revision', 'schema_activation_head', 'change_set', 'agent_run'];
  requested_table_name text;
  record_table_name text;
  version_table_name text;
  field_name text;
  field_type text;
  column_type text;
  target_table_name text;
  extra_table jsonb;
  assertion jsonb;
  assertion_kind text;
  object_name text;
  expected_definition text;
  actual_definition text;
  assertion_exists boolean;
  actual_type text;
  actual_not_null boolean;
  unexpected_table text;
  unexpected_column text;
  constraint_row record;
  index_row record;
  policy_row record;
  normalized_expected text;
  normalized_actual text;
begin
  foreach requested_table_name in array array['schema_revision', 'schema_activation_head', 'change_set', 'agent_run']
  loop
    if to_regclass(format('%I.%I', current_schema(), requested_table_name)) is null then
      return kernel_admin_error('schema_drift', 'Schema drift detected', jsonb_build_array(jsonb_build_object(
        'path', 'object', 'code', 'schema_drift', 'message', requested_table_name || ': required materialized table is missing'
      )));
    end if;
  end loop;
  for model_value in select value from jsonb_array_elements(coalesce(expected_schema->'models', '[]'::jsonb))
  loop
    requested_table_name := kernel_admin_normalize_identifier(model_value->>'id');
    if requested_table_name is null then
      return kernel_admin_validation_error(jsonb_build_array(jsonb_build_object(
        'path', 'models.id', 'code', 'invalid_identifier', 'message', 'model id cannot be materialized'
      )));
    end if;
    record_table_name := kernel_admin_bounded_identifier(requested_table_name || '_record');
    version_table_name := kernel_admin_bounded_identifier(requested_table_name || '_version');
    policy_tables := policy_tables || array[record_table_name, version_table_name];
    expected_columns := expected_columns || jsonb_build_array(
      jsonb_build_object('table', record_table_name, 'name', 'id', 'type', 'uuid', 'not_null', true),
      jsonb_build_object('table', record_table_name, 'name', 'app_id', 'type', 'text', 'not_null', true),
      jsonb_build_object('table', record_table_name, 'name', 'customer_id', 'type', 'text', 'not_null', true),
      jsonb_build_object('table', record_table_name, 'name', 'external_key', 'type', 'text', 'not_null', false),
      jsonb_build_object('table', record_table_name, 'name', 'created_at', 'type', 'timestamp with time zone', 'not_null', true),
      jsonb_build_object('table', version_table_name, 'name', 'id', 'type', 'uuid', 'not_null', true),
      jsonb_build_object('table', version_table_name, 'name', 'record_id', 'type', 'uuid', 'not_null', true),
      jsonb_build_object('table', version_table_name, 'name', 'app_id', 'type', 'text', 'not_null', true),
      jsonb_build_object('table', version_table_name, 'name', 'customer_id', 'type', 'text', 'not_null', true),
      jsonb_build_object('table', version_table_name, 'name', 'stage', 'type', 'text', 'not_null', true),
      jsonb_build_object('table', version_table_name, 'name', 'effective_start', 'type', 'date', 'not_null', true),
      jsonb_build_object('table', version_table_name, 'name', 'effective_end', 'type', 'date', 'not_null', false),
      jsonb_build_object('table', version_table_name, 'name', 'change_set_id', 'type', 'bigint', 'not_null', true),
      jsonb_build_object('table', version_table_name, 'name', 'created_at', 'type', 'timestamp with time zone', 'not_null', true),
      jsonb_build_object('table', version_table_name, 'name', 'applied_at', 'type', 'timestamp with time zone', 'not_null', false),
      jsonb_build_object('table', version_table_name, 'name', 'tombstones_record', 'type', 'boolean', 'not_null', true),
      jsonb_build_object('table', version_table_name, 'name', 'untombstones_record', 'type', 'boolean', 'not_null', true),
      jsonb_build_object('table', version_table_name, 'name', 'provenance', 'type', 'jsonb', 'not_null', false),
      jsonb_build_object('table', version_table_name, 'name', 'custom_fields', 'type', 'jsonb', 'not_null', true)
    );
    expected_constraints := expected_constraints || jsonb_build_array(
      jsonb_build_object('table', record_table_name, 'name', kernel_admin_bounded_identifier(record_table_name || '_pkey'), 'type', 'p', 'columns', jsonb_build_array('id')),
      jsonb_build_object('table', record_table_name, 'name', kernel_admin_bounded_identifier(record_table_name || '_tenant_id_key'), 'type', 'u', 'columns', jsonb_build_array('id','app_id','customer_id')),
      jsonb_build_object(
        'table', version_table_name,
        'name', case when octet_length(version_table_name || '_pkey') <= 63
          then version_table_name || '_pkey' else left(version_table_name, 58) || '_pkey' end,
        'type', 'p', 'columns', jsonb_build_array('id')
      ),
      jsonb_build_object('table', version_table_name, 'name', kernel_admin_bounded_identifier(version_table_name || '_stage_check'), 'type', 'c', 'expression', 'stage = ANY (ARRAY[''draft''::text, ''mainline''::text, ''discarded''::text, ''reverted''::text])'),
      jsonb_build_object('table', version_table_name, 'name', kernel_admin_bounded_identifier(version_table_name || '_effective_range_check'), 'type', 'c', 'expression', 'effective_end IS NULL OR effective_end >= effective_start'),
      jsonb_build_object('table', version_table_name, 'name', kernel_admin_bounded_identifier(version_table_name || '_applied_at_stage_check'), 'type', 'c', 'expression', '(stage = ''mainline''::text) = (applied_at IS NOT NULL)'),
      jsonb_build_object('table', version_table_name, 'name', kernel_admin_bounded_identifier(version_table_name || '_record_event_exclusion_check'), 'type', 'c', 'expression', 'NOT (tombstones_record AND untombstones_record)'),
      jsonb_build_object('table', version_table_name, 'name', kernel_admin_bounded_identifier(version_table_name || '_record_tenant_fk'), 'type', 'f', 'columns', jsonb_build_array('record_id','app_id','customer_id'), 'ref_table', record_table_name, 'ref_columns', jsonb_build_array('id','app_id','customer_id')),
      jsonb_build_object('table', version_table_name, 'name', kernel_admin_bounded_identifier(version_table_name || '_change_set_tenant_fk'), 'type', 'f', 'columns', jsonb_build_array('change_set_id','app_id','customer_id'), 'ref_table', 'change_set', 'ref_columns', jsonb_build_array('id','app_id','customer_id'))
    );
    expected_indexes := expected_indexes || jsonb_build_array(
      jsonb_build_object('table', record_table_name, 'name', kernel_admin_bounded_identifier(record_table_name || '_external_key_idx'), 'unique', true, 'columns', jsonb_build_array('app_id','customer_id','external_key'), 'predicate', 'external_key IS NOT NULL'),
      jsonb_build_object('table', version_table_name, 'name', kernel_admin_bounded_identifier(version_table_name || '_lookup_idx'), 'unique', false, 'columns', jsonb_build_array('record_id','stage','effective_start')),
      jsonb_build_object('table', version_table_name, 'name', kernel_admin_bounded_identifier(version_table_name || '_change_set_idx'), 'unique', false, 'columns', jsonb_build_array('change_set_id')),
      jsonb_build_object('table', version_table_name, 'name', kernel_admin_bounded_identifier(version_table_name || '_change_set_value_once_idx'), 'unique', true, 'columns', jsonb_build_array('record_id','effective_start','change_set_id'), 'predicate', 'NOT tombstones_record AND NOT untombstones_record'),
      jsonb_build_object('table', version_table_name, 'name', kernel_admin_bounded_identifier(version_table_name || '_mainline_lifecycle_once_idx'), 'unique', true, 'columns', jsonb_build_array('record_id','effective_start','tombstones_record','untombstones_record'), 'predicate', 'stage = ''mainline''::text AND (tombstones_record OR untombstones_record)')
    );

    for field_value in select value from jsonb_array_elements(coalesce(model_value->'fields', '[]'::jsonb))
    loop
      field_name := kernel_admin_normalize_identifier(field_value->>'id');
      field_type := field_value->>'type';
      if field_name is null then
        return kernel_admin_validation_error(jsonb_build_array(jsonb_build_object(
          'path', 'models.fields.id', 'code', 'invalid_identifier', 'message', 'field id cannot be materialized'
        )));
      end if;
      if field_type = 'money_rate' then
        foreach expected in array array[
          jsonb_build_object('name', kernel_admin_bounded_identifier(field_name || '_amount'), 'type', 'numeric'),
          jsonb_build_object('name', kernel_admin_bounded_identifier(field_name || '_currency'), 'type', 'text'),
          jsonb_build_object('name', kernel_admin_bounded_identifier(field_name || '_period'), 'type', 'text')
        ] loop
          expected_columns := expected_columns || jsonb_build_array(jsonb_build_object(
            'table', version_table_name, 'name', expected->>'name', 'type', expected->>'type', 'not_null', false
          ));
          expected_constraints := expected_constraints || jsonb_build_array(jsonb_build_object(
            'table', version_table_name,
            'name', kernel_admin_bounded_identifier(version_table_name || '_' || (expected->>'name') || '_record_event_null_check'),
            'type', 'c', 'expression', 'NOT tombstones_record AND NOT untombstones_record OR ' || (expected->>'name') || ' IS NULL'
          ));
          if coalesce((field_value->>'required')::boolean, false) then
            expected_constraints := expected_constraints || jsonb_build_array(jsonb_build_object(
              'table', version_table_name,
              'name', kernel_admin_bounded_identifier(version_table_name || '_' || (expected->>'name') || '_required_check'),
              'type', 'c', 'expression', 'tombstones_record OR untombstones_record OR ' || (expected->>'name') || ' IS NOT NULL'
            ));
          end if;
        end loop;
        expected_constraints := expected_constraints || jsonb_build_array(
          jsonb_build_object(
            'table', version_table_name, 'name', kernel_admin_bounded_identifier(version_table_name || '_' || kernel_admin_bounded_identifier(field_name || '_amount') || '_all_or_none_check'), 'type', 'c',
            'expression', '(' || kernel_admin_bounded_identifier(field_name || '_amount') || ' IS NULL AND ' || kernel_admin_bounded_identifier(field_name || '_currency') || ' IS NULL AND ' || kernel_admin_bounded_identifier(field_name || '_period') || ' IS NULL) OR (' || kernel_admin_bounded_identifier(field_name || '_amount') || ' IS NOT NULL AND ' || kernel_admin_bounded_identifier(field_name || '_currency') || ' IS NOT NULL AND ' || kernel_admin_bounded_identifier(field_name || '_period') || ' IS NOT NULL)'
          ),
          jsonb_build_object(
            'table', version_table_name, 'name', kernel_admin_bounded_identifier(version_table_name || '_' || kernel_admin_bounded_identifier(field_name || '_period') || '_period_check'), 'type', 'c',
            'expression', kernel_admin_bounded_identifier(field_name || '_period') || ' IS NULL OR ' || kernel_admin_bounded_identifier(field_name || '_period') || ' = ANY (ARRAY[''hourly''::text, ''daily''::text, ''weekly''::text, ''monthly''::text, ''annual''::text])'
          )
        );
      else
        column_type := case field_type
          when 'text' then 'text' when 'iso_country' then 'text' when 'iso_currency' then 'text'
          when 'enum' then 'text' when 'number' then 'numeric' when 'bool' then 'boolean'
          when 'date' then 'date' when 'datetime' then 'timestamp with time zone'
          when 'relation' then 'uuid' when 'text_list' then 'text[]' when 'known_aliases' then 'text[]'
          when 'json' then 'jsonb' else null end;
        if column_type is null then
          return kernel_admin_validation_error(jsonb_build_array(jsonb_build_object(
            'path', 'models.fields.type', 'code', 'unsupported_field_type', 'message', 'field type cannot be validated against the materialized catalog'
          )));
        end if;
        field_name := kernel_admin_bounded_identifier(field_name);
        expected_columns := expected_columns || jsonb_build_array(jsonb_build_object(
          'table', version_table_name, 'name', field_name, 'type', column_type, 'not_null', false
        ));
        expected_constraints := expected_constraints || jsonb_build_array(jsonb_build_object(
          'table', version_table_name,
          'name', kernel_admin_bounded_identifier(version_table_name || '_' || field_name || '_record_event_null_check'),
          'type', 'c', 'expression', 'NOT tombstones_record AND NOT untombstones_record OR ' || field_name || ' IS NULL'
        ));
        if coalesce((field_value->>'required')::boolean, false) then
          expected_constraints := expected_constraints || jsonb_build_array(jsonb_build_object(
            'table', version_table_name,
            'name', kernel_admin_bounded_identifier(version_table_name || '_' || field_name || '_required_check'),
            'type', 'c', 'expression', 'tombstones_record OR untombstones_record OR ' || field_name || ' IS NOT NULL'
          ));
        end if;
        if field_type = 'relation' then
          select kernel_admin_bounded_identifier(kernel_admin_normalize_identifier(target->>'id') || '_record')
          into target_table_name
          from jsonb_array_elements(expected_schema->'models') as targets(target)
          where target->>'id' = field_value->>'target_model';
          if not found then
            return kernel_admin_validation_error(jsonb_build_array(jsonb_build_object(
              'path', 'models.fields.target_model', 'code', 'unknown_relation_target', 'message', 'relation target cannot be validated against the materialized catalog'
            )));
          end if;
          expected_constraints := expected_constraints || jsonb_build_array(jsonb_build_object(
            'table', version_table_name,
            'name', kernel_admin_bounded_identifier(version_table_name || '_' || field_name || '_tenant_fk'),
            'type', 'f', 'columns', jsonb_build_array(field_name,'app_id','customer_id'),
            'ref_table', target_table_name, 'ref_columns', jsonb_build_array('id','app_id','customer_id')
          ));
        end if;
        if coalesce((field_value->>'is_unique')::boolean, false) then
          expected_indexes := expected_indexes || jsonb_build_array(jsonb_build_object(
            'table', version_table_name,
            'name', kernel_admin_bounded_identifier(version_table_name || '_' || field_name || '_live_unique_idx'),
            'unique', true, 'columns', jsonb_build_array('app_id','customer_id',field_name),
            'predicate', 'stage = ''mainline''::text AND effective_end IS NULL AND ' || field_name || ' IS NOT NULL'
          ));
        end if;
      end if;
    end loop;
  end loop;

  for expected in select value from jsonb_array_elements(expected_columns)
  loop
    select format_type(attribute.atttypid, attribute.atttypmod), attribute.attnotnull
    into actual_type, actual_not_null
    from pg_attribute as attribute
    join pg_class as relation on relation.oid = attribute.attrelid
    join pg_namespace as namespace on namespace.oid = relation.relnamespace
    where namespace.nspname = current_schema() and relation.relname = expected->>'table'
      and attribute.attname = expected->>'name' and attribute.attnum > 0 and not attribute.attisdropped;
    if not found then
      return kernel_admin_error('schema_drift', 'Schema drift detected', jsonb_build_array(jsonb_build_object(
        'path', 'object', 'code', 'schema_drift', 'message', (expected->>'table') || '.' || (expected->>'name') || ': required materialized column is missing'
      )));
    end if;
    if actual_type <> expected->>'type' or actual_not_null <> (expected->>'not_null')::boolean then
      return kernel_admin_error('schema_drift', 'Schema drift detected', jsonb_build_array(jsonb_build_object(
        'path', 'object', 'code', 'schema_drift', 'message', (expected->>'table') || '.' || (expected->>'name') || ': materialized column definition differs from the compiled catalog'
      )));
    end if;
  end loop;

  select relation.relname, attribute.attname
  into unexpected_table, unexpected_column
  from pg_attribute as attribute
  join pg_class as relation on relation.oid = attribute.attrelid
  join pg_namespace as namespace on namespace.oid = relation.relnamespace
  where namespace.nspname = current_schema()
    and attribute.attnum > 0
    and not attribute.attisdropped
    and exists (
      select 1
      from jsonb_array_elements(expected_columns) as expected_table(value)
      where expected_table.value->>'table' = relation.relname
    )
    and not exists (
      select 1
      from jsonb_array_elements(expected_columns) as expected_column(value)
      where expected_column.value->>'table' = relation.relname
        and expected_column.value->>'name' = attribute.attname
    )
  order by relation.relname, attribute.attnum
  limit 1;
  if found then
    return kernel_admin_error('schema_drift', 'Schema drift detected', jsonb_build_array(jsonb_build_object(
      'path', 'object', 'code', 'schema_drift',
      'message', unexpected_table || '.' || unexpected_column || ': unexpected materialized column is present'
    )));
  end if;

  for expected in select value from jsonb_array_elements(expected_constraints)
  loop
    select constraint_value.contype::text as constraint_type, constraint_value.convalidated,
      pg_get_expr(constraint_value.conbin, constraint_value.conrelid, true) as expression,
      referenced_relation.relname as referenced_table,
      (select jsonb_agg(attribute.attname order by key_column.ordinality)
       from unnest(constraint_value.conkey) with ordinality as key_column(attnum, ordinality)
       join pg_attribute as attribute on attribute.attrelid = constraint_value.conrelid and attribute.attnum = key_column.attnum) as columns,
      (select jsonb_agg(attribute.attname order by key_column.ordinality)
       from unnest(constraint_value.confkey) with ordinality as key_column(attnum, ordinality)
       join pg_attribute as attribute on attribute.attrelid = constraint_value.confrelid and attribute.attnum = key_column.attnum) as referenced_columns
    into constraint_row
    from pg_constraint as constraint_value
    join pg_class as relation on relation.oid = constraint_value.conrelid
    join pg_namespace as namespace on namespace.oid = relation.relnamespace
    left join pg_class as referenced_relation on referenced_relation.oid = constraint_value.confrelid
    where namespace.nspname = current_schema() and relation.relname = expected->>'table'
      and constraint_value.conname = expected->>'name';
    if not found then
      return kernel_admin_error('schema_drift', 'Schema drift detected', jsonb_build_array(jsonb_build_object(
        'path', 'object', 'code', 'schema_drift', 'message', (expected->>'table') || '.' || (expected->>'name') || ': required materialized constraint is missing'
      )));
    end if;
    normalized_expected := regexp_replace(lower(coalesce(expected->>'expression', '')), '[[:space:]()"]', '', 'g');
    normalized_actual := regexp_replace(lower(coalesce(constraint_row.expression, '')), '[[:space:]()"]', '', 'g');
    if constraint_row.constraint_type <> expected->>'type'
      or not constraint_row.convalidated
      or (expected ? 'columns' and constraint_row.columns is distinct from expected->'columns')
      or (expected ? 'ref_table' and constraint_row.referenced_table is distinct from expected->>'ref_table')
      or (expected ? 'ref_columns' and constraint_row.referenced_columns is distinct from expected->'ref_columns')
      or (expected ? 'expression' and normalized_actual <> normalized_expected)
    then
      return kernel_admin_error('schema_drift', 'Schema drift detected', jsonb_build_array(jsonb_build_object(
        'path', 'object', 'code', 'schema_drift', 'message', (expected->>'table') || '.' || (expected->>'name') || ': materialized constraint definition or validation state differs from the compiled catalog'
      )));
    end if;
  end loop;

  for expected in select value from jsonb_array_elements(expected_indexes)
  loop
    select index_value.indisunique, index_value.indisvalid, index_value.indisready,
      pg_get_expr(index_value.indpred, index_value.indrelid, true) as predicate,
      (select jsonb_agg(attribute.attname order by key_column.ordinality)
       from unnest(index_value.indkey::smallint[]) with ordinality as key_column(attnum, ordinality)
       join pg_attribute as attribute on attribute.attrelid = index_value.indrelid and attribute.attnum = key_column.attnum
       where key_column.ordinality <= index_value.indnkeyatts) as columns
    into index_row
    from pg_index as index_value
    join pg_class as index_relation on index_relation.oid = index_value.indexrelid
    join pg_class as table_relation on table_relation.oid = index_value.indrelid
    join pg_namespace as namespace on namespace.oid = table_relation.relnamespace
    where namespace.nspname = current_schema() and table_relation.relname = expected->>'table'
      and index_relation.relname = expected->>'name';
    if not found then
      return kernel_admin_error('schema_drift', 'Schema drift detected', jsonb_build_array(jsonb_build_object(
        'path', 'object', 'code', 'schema_drift', 'message', (expected->>'table') || '.' || (expected->>'name') || ': required materialized index is missing'
      )));
    end if;
    normalized_expected := regexp_replace(lower(coalesce(expected->>'predicate', '')), '[[:space:]()"]', '', 'g');
    normalized_actual := regexp_replace(lower(coalesce(index_row.predicate, '')), '[[:space:]()"]', '', 'g');
    if index_row.indisunique <> (expected->>'unique')::boolean
      or not index_row.indisvalid or not index_row.indisready
      or index_row.columns is distinct from expected->'columns'
      or normalized_actual <> normalized_expected
    then
      return kernel_admin_error('schema_drift', 'Schema drift detected', jsonb_build_array(jsonb_build_object(
        'path', 'object', 'code', 'schema_drift', 'message', (expected->>'table') || '.' || (expected->>'name') || ': materialized index definition or readiness differs from the compiled catalog'
      )));
    end if;
  end loop;

  foreach requested_table_name in array policy_tables
  loop
    select relation.relrowsecurity, relation.relforcerowsecurity, policy.permissive, policy.cmd,
      policy.roles, policy.qual, policy.with_check
    into policy_row
    from pg_class as relation
    join pg_namespace as namespace on namespace.oid = relation.relnamespace
    left join pg_policies as policy on policy.schemaname = namespace.nspname
      and policy.tablename = relation.relname and policy.policyname = 'kernel_tenant_isolation'
    where namespace.nspname = current_schema() and relation.relname = requested_table_name;
    normalized_expected := regexp_replace(lower(
      'app_id = current_setting(''kernel.app_id''::text, true) AND customer_id = current_setting(''kernel.customer_id''::text, true) AND kernel_principal_scope_authorized(''any''::text, app_id, customer_id, NULL::text)'
    ), '[[:space:]()"]', '', 'g');
    normalized_actual := regexp_replace(lower(coalesce(policy_row.qual, '')), '[[:space:]()"]', '', 'g');
    if not found or not policy_row.relrowsecurity or not policy_row.relforcerowsecurity
      or policy_row.permissive <> 'PERMISSIVE' or policy_row.cmd <> 'ALL'
      or policy_row.roles <> '{public}'::name[]
      or normalized_actual <> normalized_expected
      or regexp_replace(lower(coalesce(policy_row.with_check, '')), '[[:space:]()"]', '', 'g') <> normalized_expected
    then
      return kernel_admin_error('schema_drift', 'Schema drift detected', jsonb_build_array(jsonb_build_object(
        'path', 'object', 'code', 'schema_drift', 'message', requested_table_name || '.kernel_tenant_isolation: RLS or tenant policy differs from the compiled catalog'
      )));
    end if;
  end loop;
  if active_row ? 'materialized_tables' then
    if jsonb_typeof(active_row->'materialized_tables') <> 'array' then
      return kernel_admin_validation_error(jsonb_build_array(jsonb_build_object(
        'path', 'materialized_tables', 'code', 'invalid_materialized_tables', 'message', 'materialized_tables must be a JSON array'
      )));
    end if;
    for extra_table in select value from jsonb_array_elements(active_row->'materialized_tables')
    loop
      if jsonb_typeof(extra_table) <> 'string' or (extra_table #>> '{}') !~ '^[A-Za-z][A-Za-z0-9_]*$' then
        return kernel_admin_validation_error(jsonb_build_array(jsonb_build_object(
          'path', 'materialized_tables', 'code', 'invalid_materialized_table', 'message', 'materialized table names must be identifiers'
        )));
      end if;
      requested_table_name := extra_table #>> '{}';
      if to_regclass(format('%I.%I', current_schema(), requested_table_name)) is null then
        return kernel_admin_error('schema_drift', 'Schema drift detected', jsonb_build_array(jsonb_build_object(
          'path', 'object', 'code', 'schema_drift', 'message', requested_table_name || ': required materialized table is missing'
        )));
      end if;
    end loop;
  end if;
  if active_row ? 'materialized_assertions' then
    if jsonb_typeof(active_row->'materialized_assertions') <> 'array' then
      return kernel_admin_validation_error(jsonb_build_array(jsonb_build_object(
        'path', 'materialized_assertions', 'code', 'invalid_materialized_assertions',
        'message', 'materialized_assertions must be a JSON array'
      )));
    end if;
    for assertion in select value from jsonb_array_elements(active_row->'materialized_assertions')
    loop
      assertion_kind := assertion->>'kind';
      requested_table_name := assertion->>'table';
      object_name := assertion->>'name';
      expected_definition := assertion->>'definition';
      if jsonb_typeof(assertion) <> 'object'
        or assertion_kind not in ('table', 'column', 'constraint', 'index', 'policy')
        or (assertion_kind <> 'index' and coalesce(requested_table_name, '') !~ '^[A-Za-z][A-Za-z0-9_]*$')
        or (assertion_kind <> 'table' and coalesce(object_name, '') !~ '^[A-Za-z][A-Za-z0-9_]*$')
      then
        return kernel_admin_validation_error(jsonb_build_array(jsonb_build_object(
          'path', 'materialized_assertions', 'code', 'invalid_materialized_assertion',
          'message', 'materialized assertions require a supported kind and identifier names'
        )));
      end if;
      actual_definition := null;
      case assertion_kind
        when 'table' then
          assertion_exists := to_regclass(format('%I.%I', current_schema(), requested_table_name)) is not null;
        when 'column' then
          select exists (
            select 1 from information_schema.columns
            where table_schema = current_schema() and table_name = requested_table_name
              and column_name = object_name
          ) into assertion_exists;
          if assertion_exists and expected_definition is not null then
            select format('%s%s', data_type, case when is_nullable = 'YES' then ' nullable' else ' not null' end)
            into actual_definition
            from information_schema.columns
            where table_schema = current_schema() and table_name = requested_table_name
              and column_name = object_name;
          end if;
        when 'constraint' then
          select pg_get_constraintdef(catalog_constraint.oid, true)
          into actual_definition
          from pg_constraint as catalog_constraint
          join pg_class as relation on relation.oid = catalog_constraint.conrelid
          join pg_namespace as namespace on namespace.oid = relation.relnamespace
          where namespace.nspname = current_schema() and relation.relname = requested_table_name
            and catalog_constraint.conname = object_name and catalog_constraint.convalidated;
          assertion_exists := found;
        when 'index' then
          select indexes.indexdef into actual_definition
          from pg_indexes as indexes
          join pg_class as index_relation on index_relation.relname = indexes.indexname
          join pg_namespace as index_namespace on index_namespace.oid = index_relation.relnamespace and index_namespace.nspname = indexes.schemaname
          join pg_index as index_value on index_value.indexrelid = index_relation.oid
          where indexes.schemaname = current_schema() and indexes.indexname = object_name
            and (requested_table_name is null or indexes.tablename = requested_table_name)
            and index_value.indisvalid and index_value.indisready;
          assertion_exists := found;
        when 'policy' then
          select coalesce(qual, '') || '|' || coalesce(with_check, '')
          into actual_definition
          from pg_policies
          where schemaname = current_schema() and tablename = requested_table_name and policyname = object_name;
          assertion_exists := found;
      end case;
      if not assertion_exists then
        return kernel_admin_error('schema_drift', 'Schema drift detected', jsonb_build_array(jsonb_build_object(
          'path', 'object', 'code', 'schema_drift',
          'message', coalesce(requested_table_name || '.', '') || coalesce(object_name, requested_table_name) || ': required materialized object is missing'
        )));
      end if;
      if expected_definition is not null and actual_definition is distinct from expected_definition then
        return kernel_admin_error('schema_drift', 'Schema drift detected', jsonb_build_array(jsonb_build_object(
          'path', 'object', 'code', 'schema_drift',
          'message', coalesce(requested_table_name || '.', '') || coalesce(object_name, requested_table_name) || ': materialized definition differs from the compiled assertion'
        )));
      end if;
    end loop;
  end if;
  return null;
end;
$kernel$;

-- artifact: function kernel_schema_revision_is_active_with_materialized_tables(jsonb)
create or replace function kernel_schema_revision_is_active_with_materialized_tables(request jsonb)
returns jsonb
language plpgsql
volatile
security invoker
set search_path from current
as $kernel$
declare
  expected_schema jsonb;
  request_app_id text;
  request_customer_id text;
  expected_revision_id bigint;
  expected_schema_hash text;
  active_id bigint;
  active_base_schema jsonb;
  active_schema jsonb;
  active_overlay jsonb;
  active_hash text;
  composed_schema jsonb;
  assertion_error jsonb;
begin
  perform kernel_cleanup_generated_visible_query();
  if request is null or jsonb_typeof(request) <> 'object' then
    return kernel_admin_validation_error(jsonb_build_array(jsonb_build_object(
      'path', 'request', 'code', 'invalid_request', 'message', 'request must be a JSON object'
    )));
  end if;
  expected_schema := case when request ? 'schema' then request->'schema' else request end;
  if expected_schema is null or jsonb_typeof(expected_schema) <> 'object' then
    return kernel_admin_validation_error(jsonb_build_array(jsonb_build_object(
      'path', 'schema', 'code', 'invalid_schema', 'message', 'schema must be a JSON object'
    )));
  end if;
  request_app_id := expected_schema->>'app_id';
  request_customer_id := expected_schema->>'customer_id';
  if coalesce(btrim(request_app_id), '') = '' or coalesce(btrim(request_customer_id), '') = '' then
    return kernel_admin_validation_error(jsonb_build_array(jsonb_build_object(
      'path', case when coalesce(btrim(request_app_id), '') = '' then 'app_id' else 'customer_id' end,
      'code', 'empty_scope_id', 'message', 'scope id must not be empty'
    )));
  end if;
  if not kernel_principal_scope_authorized(
    'runtime', request_app_id, request_customer_id, null
  ) then
    return kernel_authorize_scope(
      'runtime', request_app_id, request_customer_id, null
    );
  end if;
  if coalesce(btrim(expected_schema->>'version'), '') = '' then
    return kernel_admin_validation_error(jsonb_build_array(jsonb_build_object(
      'path', 'version', 'code', 'empty_value', 'message', 'value must not be empty'
    )));
  end if;
  if jsonb_typeof(coalesce(expected_schema->'models', 'null'::jsonb)) <> 'array' then
    return kernel_admin_validation_error(jsonb_build_array(jsonb_build_object(
      'path', 'models', 'code', 'invalid_models', 'message', 'models must be a JSON array'
    )));
  end if;
  if request ? 'expected_active_revision_id' then
    if jsonb_typeof(request->'expected_active_revision_id') <> 'number'
      or (request->>'expected_active_revision_id')::numeric <> trunc((request->>'expected_active_revision_id')::numeric)
      or (request->>'expected_active_revision_id')::numeric <= 0
    then
      return kernel_admin_validation_error(jsonb_build_array(jsonb_build_object(
        'path', 'expected_active_revision_id', 'code', 'invalid_schema_revision_id', 'message', 'expected_active_revision_id must be a positive integer'
      )));
    end if;
    expected_revision_id := (request->>'expected_active_revision_id')::bigint;
  end if;
  expected_schema_hash := nullif(request->>'expected_schema_hash', '');

  perform set_config('kernel.app_id', request_app_id, true);
  perform set_config('kernel.customer_id', request_customer_id, true);

  select id, base_schema, schema, customer_overlay, schema_hash
  into active_id, active_base_schema, active_schema, active_overlay, active_hash
  from schema_revision
  where app_id = request_app_id and customer_id = request_customer_id and activated_at is not null
  for share;
  if not found then
    return jsonb_build_object('ok', true, 'data', false);
  end if;
  if expected_revision_id is not null and active_id <> expected_revision_id then
    return kernel_admin_error('stale_schema_revision', 'The supplied schema revision is not active', jsonb_build_array(jsonb_build_object(
      'path', 'schema_revision_id', 'code', 'stale_schema_revision',
      'message', format('Supplied schema_revision_id is %s; active schema_revision_id is %s', expected_revision_id, active_id)
    )));
  end if;
  if expected_schema_hash is not null and active_hash is distinct from expected_schema_hash then
    return kernel_admin_error('schema_revision_conflict', 'Schema revision already exists with different schema JSON', jsonb_build_array(
      jsonb_build_object('path', 'schema_revision.existing_schema_hash', 'code', 'schema_hash', 'message', coalesce(active_hash, '')),
      jsonb_build_object('path', 'schema_revision.current_schema_hash', 'code', 'schema_hash', 'message', expected_schema_hash)
    ));
  end if;
  if active_base_schema->>'version' <> expected_schema->>'version' then
    return jsonb_build_object('ok', true, 'data', false);
  end if;
  if active_base_schema <> expected_schema then
    return kernel_admin_error('schema_revision_conflict', 'Schema revision already exists with different schema JSON', jsonb_build_array(
      jsonb_build_object('path', 'schema_revision.existing_schema_hash', 'code', 'schema_hash', 'message', coalesce(active_hash, kernel_admin_sha256(kernel_canonical_json(active_base_schema)))),
      jsonb_build_object('path', 'schema_revision.current_schema_hash', 'code', 'schema_hash', 'message', coalesce(expected_schema_hash, kernel_admin_sha256(kernel_canonical_json(expected_schema))))
    ));
  end if;
  composed_schema := kernel_admin_apply_overlay(expected_schema, active_overlay);
  composed_schema := jsonb_set(composed_schema, '{version}', to_jsonb(active_schema->>'version'));
  if composed_schema <> active_schema then
    return kernel_admin_error('schema_revision_conflict', 'Schema revision already exists with different schema JSON', jsonb_build_array(
      jsonb_build_object('path', 'schema_revision.existing_schema_hash', 'code', 'schema_hash', 'message', coalesce(active_hash, kernel_admin_sha256(kernel_canonical_json(active_schema)))),
      jsonb_build_object('path', 'schema_revision.current_schema_hash', 'code', 'schema_hash', 'message', kernel_admin_sha256(kernel_canonical_json(composed_schema)))
    ));
  end if;
  assertion_error := kernel_admin_materialization_error(expected_schema, request);
  if assertion_error is not null then
    return assertion_error;
  end if;
  return jsonb_build_object('ok', true, 'data', true);
exception
  when others then
    return kernel_admin_error('database_error', 'Database operation failed', '[]'::jsonb);
end;
$kernel$;

-- artifact: function kernel_http_body_record_agent_run(jsonb)
create or replace function kernel_http_body_record_agent_run(request jsonb)
returns jsonb
language plpgsql
volatile
security invoker
set search_path from current
as $kernel$
declare
  app_id_value text;
  customer_id_value text;
  run_id_value text;
  status_value text;
  supplied_revision_id bigint;
  active_revision_id bigint;
  existing agent_run%rowtype;
  inserted_id bigint;
  field_name text;
  expected_value jsonb;
  actual_value jsonb;
  array_field text;
  object_field text;
  policy_snapshot jsonb;
  validation_issues jsonb := '[]'::jsonb;
begin
  if request is null or jsonb_typeof(request) <> 'object' then
    return kernel_admin_validation_error(jsonb_build_array(jsonb_build_object(
      'path', 'request', 'code', 'invalid_request', 'message', 'request must be a JSON object'
    )));
  end if;
  app_id_value := request->>'app_id';
  customer_id_value := request->>'customer_id';
  run_id_value := request->>'run_id';
  foreach field_name in array array['app_id', 'customer_id', 'run_id', 'agent_identity_id', 'execution_profile_id']
  loop
    if coalesce(btrim(request->>field_name), '') = '' then
      validation_issues := validation_issues || jsonb_build_array(jsonb_build_object(
        'path', field_name,
        'code', case when field_name in ('app_id', 'customer_id') then 'empty_scope_id' else 'empty_value' end,
        'message', case when field_name in ('app_id', 'customer_id') then 'scope id must not be empty' else 'value must not be empty' end
      ));
    end if;
  end loop;
  status_value := coalesce(request->>'status', 'recorded');
  if status_value not in ('recorded', 'completed', 'validation_exhausted', 'budget_exhausted', 'runtime_error', 'cancelled') then
    validation_issues := validation_issues || jsonb_build_array(jsonb_build_object(
      'path', 'status', 'code', 'invalid_agent_run_status', 'message', 'agent run status is not recognized'
    ));
  end if;
  if request ? 'schema_revision_id' and request->'schema_revision_id' <> 'null'::jsonb then
    if jsonb_typeof(request->'schema_revision_id') not in ('number', 'string')
      or (request->>'schema_revision_id') !~ '^[0-9]+$'
      or (request->>'schema_revision_id')::numeric <= 0
      or (request->>'schema_revision_id')::numeric > 9223372036854775807
    then
      validation_issues := validation_issues || jsonb_build_array(jsonb_build_object(
        'path', 'schema_revision_id', 'code', 'invalid_schema_revision_id', 'message', 'schema_revision_id must be positive when supplied'
      ));
    else
      supplied_revision_id := (request->>'schema_revision_id')::bigint;
    end if;
  end if;
  foreach array_field in array array['source_artifacts', 'alignment_decisions', 'model_calls', 'tool_calls', 'validation_failures', 'approval_boundaries', 'compiled_preview_ids']
  loop
    if request ? array_field and jsonb_typeof(request->array_field) is distinct from 'array' then
      validation_issues := validation_issues || jsonb_build_array(jsonb_build_object(
        'path', array_field, 'code', 'invalid_json_evidence',
        'message', 'agent run evidence field must be omitted for defaults or supplied as a JSON array'
      ));
    end if;
  end loop;
  foreach object_field in array array['token_usage', 'final_outputs']
  loop
    if request ? object_field and jsonb_typeof(request->object_field) is distinct from 'object' then
      validation_issues := validation_issues || jsonb_build_array(jsonb_build_object(
        'path', object_field, 'code', 'invalid_json_evidence',
        'message', 'agent run evidence field must be omitted for defaults or supplied as a JSON object'
      ));
    end if;
  end loop;
  if jsonb_array_length(validation_issues) > 0 then
    return kernel_admin_validation_error(validation_issues);
  end if;

  if not kernel_principal_scope_authorized(
    'runtime', app_id_value, customer_id_value, null
  ) then
    return kernel_authorize_scope(
      'runtime', app_id_value, customer_id_value, null
    );
  end if;

  perform set_config('kernel.app_id', app_id_value, true);
  perform set_config('kernel.customer_id', customer_id_value, true);
  perform pg_advisory_xact_lock_shared(hashtext(
    'postgres-schema:' || current_schema() || ':materialize-tenant:' || app_id_value || ':' || customer_id_value || ':schema-activation'
  )::bigint);
  select id into active_revision_id from schema_revision
  where app_id = app_id_value and customer_id = customer_id_value and activated_at is not null
  for share;
  if not found then
    select * into existing from agent_run
    where app_id = app_id_value and customer_id = customer_id_value and run_id = run_id_value;
    if not found then
      return kernel_admin_error('active_schema_missing', 'No active schema revision exists for this scope', jsonb_build_array(jsonb_build_object(
        'path', 'scope', 'code', 'active_schema_missing',
        'message', app_id_value || '/' || customer_id_value || ': materialize a schema before applying or reading records'
      )));
    end if;
  else
    policy_snapshot := kernel_policy_active_snapshot(app_id_value, customer_id_value);
    if coalesce((policy_snapshot->>'declared')::boolean, false) then
      perform kernel_policy_request_actor(app_id_value, customer_id_value);
      return kernel_admin_error(
        'unsupported_capability',
        'Agent-run record envelopes are unavailable for policy-enabled revisions',
        jsonb_build_array(jsonb_build_object(
          'path', 'capability', 'code', 'unsupported_capability',
          'message', 'use an application-owned policy-aware workflow record'
        ))
      );
    end if;
  end if;
  select * into existing from agent_run
  where app_id = app_id_value and customer_id = customer_id_value and run_id = run_id_value;
  if found then
    if supplied_revision_id is not null and supplied_revision_id <> existing.schema_revision_id then
      return kernel_admin_error('agent_run_schema_mismatch', format(
        'agent run `%s` was recorded against schema_revision_id `%s` not supplied schema_revision_id `%s`',
        run_id_value, existing.schema_revision_id, supplied_revision_id
      ), '[]'::jsonb);
    end if;
    foreach field_name in array array[
      'actor_id', 'agent_identity_id', 'execution_profile_id', 'source_artifacts',
      'alignment_decisions', 'model_calls', 'tool_calls', 'token_usage',
      'validation_failures', 'final_outputs', 'approval_boundaries', 'compiled_preview_ids'
    ]
    loop
      expected_value := case field_name
        when 'actor_id' then coalesce(request->'actor_id', 'null'::jsonb)
        when 'agent_identity_id' then to_jsonb(request->>'agent_identity_id')
        when 'execution_profile_id' then to_jsonb(request->>'execution_profile_id')
        when 'token_usage' then coalesce(request->field_name, '{}'::jsonb)
        when 'final_outputs' then coalesce(request->field_name, '{}'::jsonb)
        else coalesce(request->field_name, '[]'::jsonb)
      end;
      actual_value := case field_name
        when 'actor_id' then coalesce(to_jsonb(existing.actor_id), 'null'::jsonb)
        when 'agent_identity_id' then to_jsonb(existing.agent_identity_id)
        when 'execution_profile_id' then to_jsonb(existing.execution_profile_id)
        when 'source_artifacts' then existing.source_artifacts
        when 'alignment_decisions' then existing.alignment_decisions
        when 'model_calls' then existing.model_calls
        when 'tool_calls' then existing.tool_calls
        when 'token_usage' then existing.token_usage
        when 'validation_failures' then existing.validation_failures
        when 'final_outputs' then existing.final_outputs
        when 'approval_boundaries' then existing.approval_boundaries
        else existing.compiled_preview_ids
      end;
      if actual_value is distinct from expected_value then
        return kernel_admin_error('agent_run_conflict', format(
          'agent run `%s` is already recorded with different `%s`', run_id_value, field_name
        ), '[]'::jsonb);
      end if;
    end loop;
    return jsonb_build_object('ok', true, 'data', jsonb_build_object(
      'id', existing.id, 'run_id', run_id_value, 'schema_revision_id', existing.schema_revision_id
    ));
  end if;

  if supplied_revision_id is not null and supplied_revision_id <> active_revision_id then
    return kernel_admin_error('stale_schema_revision', 'The supplied schema revision is not active', jsonb_build_array(jsonb_build_object(
      'path', 'schema_revision_id', 'code', 'stale_schema_revision',
      'message', format('Supplied schema_revision_id is %s; active schema_revision_id is %s', supplied_revision_id, active_revision_id)
    )));
  end if;
  insert into agent_run (
    app_id, customer_id, run_id, status, schema_revision_id, actor_id,
    agent_identity_id, execution_profile_id, source_artifacts, alignment_decisions,
    model_calls, tool_calls, token_usage, validation_failures, final_outputs,
    approval_boundaries, compiled_preview_ids
  ) values (
    app_id_value, customer_id_value, run_id_value, status_value, active_revision_id,
    request->>'actor_id', request->>'agent_identity_id', request->>'execution_profile_id',
    coalesce(request->'source_artifacts', '[]'::jsonb), coalesce(request->'alignment_decisions', '[]'::jsonb),
    coalesce(request->'model_calls', '[]'::jsonb), coalesce(request->'tool_calls', '[]'::jsonb),
    coalesce(request->'token_usage', '{}'::jsonb), coalesce(request->'validation_failures', '[]'::jsonb),
    coalesce(request->'final_outputs', '{}'::jsonb), coalesce(request->'approval_boundaries', '[]'::jsonb),
    coalesce(request->'compiled_preview_ids', '[]'::jsonb)
  ) on conflict (app_id, customer_id, run_id) do nothing returning id into inserted_id;
  if inserted_id is null then
    return kernel_http_body_record_agent_run(request);
  end if;
  return jsonb_build_object('ok', true, 'data', jsonb_build_object(
    'id', inserted_id, 'run_id', run_id_value, 'schema_revision_id', active_revision_id
  ));
exception
  when others then
    return kernel_admin_error('database_error', 'Database operation failed', '[]'::jsonb);
end;
$kernel$;

-- artifact: function kernel_record_agent_run(jsonb)
create or replace function kernel_record_agent_run(request jsonb)
returns jsonb language plpgsql volatile parallel unsafe security invoker set search_path from current
as $kernel$
declare guard jsonb; result jsonb;
begin
  perform kernel_cleanup_generated_visible_query();
  guard := kernel_http_mutation_guard(request,'kernel_record_agent_run');
  if guard->'ok'='false'::jsonb then return guard; end if;
  result := kernel_http_body_record_agent_run(request);
  if coalesce((guard->>'required')::boolean,false) then
    perform kernel_http_mutation_record(request,guard,result);
  end if;
  return result;
end;
$kernel$;

-- artifact: function kernel_http_body_update_agent_run_status(jsonb)
create or replace function kernel_http_body_update_agent_run_status(request jsonb)
returns jsonb
language plpgsql
volatile
security invoker
set search_path from current
as $kernel$
declare
  app_id_value text;
  customer_id_value text;
  run_id_value text;
  status_value text;
  existing agent_run%rowtype;
  active_revision_id bigint;
  array_field text;
  object_field text;
  merged_model_calls jsonb;
  merged_tool_calls jsonb;
  merged_token_usage jsonb;
  merged_validation_failures jsonb;
  merged_final_outputs jsonb;
  policy_snapshot jsonb;
  validation_issues jsonb := '[]'::jsonb;
begin
  if request is null or jsonb_typeof(request) <> 'object' then
    return kernel_admin_validation_error(jsonb_build_array(jsonb_build_object(
      'path', 'request', 'code', 'invalid_request', 'message', 'request must be a JSON object'
    )));
  end if;
  app_id_value := request->>'app_id';
  customer_id_value := request->>'customer_id';
  run_id_value := request->>'run_id';
  status_value := request->>'status';
  foreach array_field in array array['app_id', 'customer_id', 'run_id']
  loop
    if coalesce(btrim(request->>array_field), '') = '' then
      validation_issues := validation_issues || jsonb_build_array(jsonb_build_object(
        'path', array_field,
        'code', case when array_field in ('app_id', 'customer_id') then 'empty_scope_id' else 'empty_value' end,
        'message', case when array_field in ('app_id', 'customer_id') then 'scope id must not be empty' else 'value must not be empty' end
      ));
    end if;
  end loop;
  if status_value not in ('completed', 'validation_exhausted', 'budget_exhausted', 'runtime_error', 'cancelled') then
    validation_issues := validation_issues || jsonb_build_array(jsonb_build_object(
      'path', 'status', 'code', 'invalid_agent_run_status',
      'message', 'agent run status updates must move a recorded run to a terminal status'
    ));
  end if;
  foreach array_field in array array['model_calls', 'tool_calls', 'validation_failures']
  loop
    if request ? array_field and request->array_field <> 'null'::jsonb and jsonb_typeof(request->array_field) <> 'array' then
      validation_issues := validation_issues || jsonb_build_array(jsonb_build_object(
        'path', array_field, 'code', 'invalid_json_evidence',
        'message', 'agent run evidence field must be omitted or supplied as a JSON array'
      ));
    end if;
  end loop;
  foreach object_field in array array['token_usage', 'final_outputs']
  loop
    if request ? object_field and request->object_field <> 'null'::jsonb and jsonb_typeof(request->object_field) <> 'object' then
      validation_issues := validation_issues || jsonb_build_array(jsonb_build_object(
        'path', object_field, 'code', 'invalid_json_evidence',
        'message', 'agent run evidence field must be omitted or supplied as a JSON object'
      ));
    end if;
  end loop;
  if jsonb_array_length(validation_issues) > 0 then
    return kernel_admin_validation_error(validation_issues);
  end if;

  if not kernel_principal_scope_authorized(
    'runtime', app_id_value, customer_id_value, null
  ) then
    return kernel_authorize_scope(
      'runtime', app_id_value, customer_id_value, null
    );
  end if;

  perform set_config('kernel.app_id', app_id_value, true);
  perform set_config('kernel.customer_id', customer_id_value, true);
  perform pg_advisory_xact_lock_shared(hashtext(
    'postgres-schema:' || current_schema() || ':materialize-tenant:' || app_id_value || ':' || customer_id_value || ':schema-activation'
  )::bigint);
  select id into active_revision_id from schema_revision
  where app_id = app_id_value and customer_id = customer_id_value and activated_at is not null
  for share;
  select * into existing from agent_run
  where app_id = app_id_value and customer_id = customer_id_value and run_id = run_id_value
  for update;
  if active_revision_id is null then
    if existing.id is not null and existing.status = status_value then
      return jsonb_build_object('ok', true, 'data', jsonb_build_object(
        'id', existing.id, 'run_id', run_id_value, 'schema_revision_id', existing.schema_revision_id
      ));
    end if;
    return kernel_admin_error('active_schema_missing', 'No active schema revision exists for this scope', jsonb_build_array(jsonb_build_object(
      'path', 'scope', 'code', 'active_schema_missing',
      'message', app_id_value || '/' || customer_id_value || ': materialize a schema before applying or reading records'
    )));
  end if;
  policy_snapshot := kernel_policy_active_snapshot(app_id_value, customer_id_value);
  if coalesce((policy_snapshot->>'declared')::boolean, false) then
    perform kernel_policy_request_actor(app_id_value, customer_id_value);
    return kernel_admin_error(
      'unsupported_capability',
      'Agent-run status envelopes are unavailable for policy-enabled revisions',
      jsonb_build_array(jsonb_build_object(
        'path', 'capability', 'code', 'unsupported_capability',
        'message', 'use an application-owned policy-aware workflow record'
      ))
    );
  end if;
  if existing.id is null then
    return kernel_admin_error('agent_run_missing', format('agent run `%s` has not been recorded', run_id_value), '[]'::jsonb);
  end if;
  if existing.status = status_value then
    return jsonb_build_object('ok', true, 'data', jsonb_build_object(
      'id', existing.id, 'run_id', run_id_value, 'schema_revision_id', existing.schema_revision_id
    ));
  end if;
  if existing.status <> 'recorded' then
    return kernel_admin_error('agent_run_conflict', format(
      'agent run `%s` is already terminal with status `%s`', run_id_value, existing.status
    ), '[]'::jsonb);
  end if;
  merged_model_calls := existing.model_calls || coalesce(nullif(request->'model_calls', 'null'::jsonb), '[]'::jsonb);
  merged_tool_calls := existing.tool_calls || coalesce(nullif(request->'tool_calls', 'null'::jsonb), '[]'::jsonb);
  merged_validation_failures := existing.validation_failures || coalesce(nullif(request->'validation_failures', 'null'::jsonb), '[]'::jsonb);
  merged_token_usage := coalesce(nullif(request->'token_usage', 'null'::jsonb), '{}'::jsonb) || existing.token_usage;
  merged_final_outputs := coalesce(nullif(request->'final_outputs', 'null'::jsonb), '{}'::jsonb) || existing.final_outputs;
  update agent_run set
    status = status_value,
    model_calls = merged_model_calls,
    tool_calls = merged_tool_calls,
    token_usage = merged_token_usage,
    validation_failures = merged_validation_failures,
    final_outputs = merged_final_outputs
  where id = existing.id;
  return jsonb_build_object('ok', true, 'data', jsonb_build_object(
    'id', existing.id, 'run_id', run_id_value, 'schema_revision_id', existing.schema_revision_id
  ));
exception
  when others then
    return kernel_admin_error('database_error', 'Database operation failed', '[]'::jsonb);
end;
$kernel$;

-- artifact: function kernel_update_agent_run_status(jsonb)
create or replace function kernel_update_agent_run_status(request jsonb)
returns jsonb language plpgsql volatile parallel unsafe security invoker set search_path from current
as $kernel$
declare guard jsonb; result jsonb;
begin
  perform kernel_cleanup_generated_visible_query();
  guard := kernel_http_mutation_guard(request,'kernel_update_agent_run_status');
  if guard->'ok'='false'::jsonb then return guard; end if;
  result := kernel_http_body_update_agent_run_status(request);
  if coalesce((guard->>'required')::boolean,false) then
    perform kernel_http_mutation_record(request,guard,result);
  end if;
  return result;
end;
$kernel$;

-- artifact: function kernel_read_actor_binding(jsonb)
create or replace function kernel_read_actor_binding(request jsonb)
returns jsonb language plpgsql stable parallel safe security invoker set search_path from current
as $kernel$
declare app text:=request->>'app_id'; customer text:=request->>'customer_id'; actor text:=request->>'actor_id'; role_name text:=request->>'role'; binding jsonb;
begin
  if request is null or jsonb_typeof(request)<>'object' or request-array['app_id','customer_id','actor_id','role']::text[]<>'{}'::jsonb or jsonb_typeof(request->'app_id')<>'string' or jsonb_typeof(request->'customer_id')<>'string' or jsonb_typeof(request->'actor_id')<>'string' or jsonb_typeof(request->'role')<>'string' or coalesce(btrim(app),'')='' or coalesce(btrim(customer),'')='' or coalesce(btrim(actor),'')='' or coalesce(btrim(role_name),'')='' then
    return kernel_installer_error('contract_validation_failed','Contract validation failed','request','invalid_actor_binding','app_id, customer_id, actor_id and role are required');
  end if;
  if not exists(select 1 from kernel_principal_scope s where s.principal_name=session_user::name and s.active and s.capability='runtime' and s.app_id=app and s.customer_id=customer and (s.actor_id is null or s.actor_id=actor) and pg_has_role(session_user,pg_catalog.to_regrole(kernel_installer_capability_role('runtime')),'MEMBER')) then return kernel_installer_error('authorization_denied','Runtime scope is not authorized','request','scope_mismatch','the current runtime principal is not bound to this app and organization'); end if;
  select jsonb_build_object('appId',m.app_id,'actorId',m.actor_id,'organizationId',m.customer_id,'role',m.role,'active',m.active,'fenceGeneration',m.fence_generation)
  into binding from kernel_actor_membership m
  where m.principal_name=session_user::name and m.app_id=app and m.customer_id=customer and m.actor_id=actor and m.role=role_name;
  return jsonb_build_object('ok',true,'data',binding);
end;
$kernel$;

-- artifact: function kernel_bind_actor_membership(jsonb)
create or replace function kernel_bind_actor_membership(request jsonb)
returns jsonb language plpgsql volatile parallel unsafe security invoker set search_path from current
as $kernel$
declare principal text:=request->>'principal_name'; app text:=request->>'app_id'; customer text:=request->>'customer_id'; actor text:=request->>'actor_id'; role_name text:=request->>'role'; active_value boolean:=true; fence_generation_value bigint:=0; requested_generation numeric; applied record; runtime_role text:=kernel_installer_capability_role('runtime');
begin
  if request is null or jsonb_typeof(request)<>'object' or request-array['principal_name','app_id','customer_id','actor_id','role','active','fence_generation','actor_kind']::text[]<>'{}'::jsonb or coalesce(btrim(principal),'')='' or coalesce(btrim(app),'')='' or coalesce(btrim(customer),'')='' or coalesce(btrim(actor),'')='' or coalesce(btrim(role_name),'')='' or coalesce(request->>'actor_kind','agent') not in ('human','agent') or (request?'active' and jsonb_typeof(request->'active')<>'boolean') then
    return kernel_installer_error('contract_validation_failed','Contract validation failed','request','invalid_actor_membership','principal_name, app_id, customer_id, actor_id, role, and optional boolean active and nonnegative integer fence_generation are required');
  end if;
  if request?'active' then active_value := (request->>'active')::boolean; end if;
  if request?'fence_generation' then
    if jsonb_typeof(request->'fence_generation')<>'number' or (request->>'fence_generation') !~ '^(0|[1-9][0-9]*)$' then
      return kernel_installer_error('contract_validation_failed','Contract validation failed','fence_generation','invalid_fence_generation','fence_generation must be a nonnegative safe integer');
    end if;
    requested_generation := (request->>'fence_generation')::numeric;
    if requested_generation > 9007199254740991 then
      return kernel_installer_error('contract_validation_failed','Contract validation failed','fence_generation','invalid_fence_generation','fence_generation must be a nonnegative safe integer');
    end if;
    fence_generation_value := requested_generation::bigint;
  end if;
  if not kernel_principal_scope_authorized('schema_admin',app,customer,null) then return kernel_authorize_scope('schema_admin',app,customer,null); end if;
  if to_regrole(principal) is null then return kernel_installer_error('contract_validation_failed','Contract validation failed','principal_name','unknown_principal','database principal does not exist'); end if;
  if not pg_has_role(principal,pg_catalog.to_regrole(runtime_role),'MEMBER') then return kernel_installer_error('authorization_denied','Principal lacks runtime capability role','principal_name','runtime_capability_role_missing','bind the generated runtime capability role before binding actor membership'); end if;
  insert into kernel_actor_membership(principal_name,app_id,customer_id,actor_id,role,actor_kind,active,fence_generation,bound_at) values(principal::name,app,customer,actor,role_name,coalesce(request->>'actor_kind','agent'),active_value,fence_generation_value,now())
  on conflict on constraint kernel_actor_membership_pkey do update
    set active=excluded.active, actor_kind=excluded.actor_kind,
        fence_generation=excluded.fence_generation,
        bound_at=case when excluded.fence_generation=0 or kernel_actor_membership.fence_generation<excluded.fence_generation then now() else kernel_actor_membership.bound_at end
    where (excluded.fence_generation=0 and kernel_actor_membership.fence_generation=0)
       or kernel_actor_membership.fence_generation<excluded.fence_generation
       or (kernel_actor_membership.fence_generation=excluded.fence_generation and kernel_actor_membership.active=excluded.active and kernel_actor_membership.actor_kind=excluded.actor_kind)
  returning active,fence_generation into applied;
  if not found then
    return kernel_installer_error('authorization_denied','Actor membership fence rejected the write','fence_generation','stale_or_conflicting_generation','a newer operation or conflicting intent already owns this membership');
  end if;
  return jsonb_build_object('ok',true,'data',jsonb_build_object('principal_name',principal,'app_id',app,'customer_id',customer,'actor_id',actor,'role',role_name,'active',applied.active,'fence_generation',applied.fence_generation));
end;
$kernel$;

-- artifact: function kernel_sync_schema_authorization_policy(bigint)
create or replace function kernel_sync_schema_authorization_policy(requested_revision_id bigint)
returns void
language plpgsql
volatile
parallel unsafe
security invoker
set search_path from current
as $kernel$
declare
  revision_row record;
  expected_row record;
  source_row record;
  snapshot_row record;
  expectation_found boolean := false;
  expected_policy_declared boolean := false;
  revision_marker_present boolean := false;
  revision_policy_declared boolean := null;
begin
  select *, base_schema->>'version' as base_version
  into strict revision_row
  from schema_revision
  where id = requested_revision_id
  for update;

  revision_marker_present := to_jsonb(revision_row) ? 'authorization_policy_declared';
  if revision_marker_present then
    revision_policy_declared := (to_jsonb(revision_row)->>'authorization_policy_declared')::boolean;
  end if;

  select policy_declared, policy_hash
  into expected_row
  from schema_authorization_policy_expectation
  where app_id = revision_row.app_id
    and schema_version = revision_row.base_version;
  expectation_found := found;
  if expectation_found then
    expected_policy_declared := expected_row.policy_declared;
    if not revision_marker_present then
      raise exception 'schema_drift: authorization policy expectation requires a revision policy marker';
    end if;
    if revision_policy_declared is not null
      and revision_policy_declared is distinct from expected_policy_declared
    then
      raise exception 'schema_drift: authorization policy marker differs from release expectation';
    end if;
    update schema_revision
    set authorization_policy_declared = expected_policy_declared
    where id = revision_row.id;
  end if;

  if not expectation_found then
    if revision_policy_declared then
      raise exception 'schema_drift: active declared policy marker exists without a release expectation';
    end if;
    -- A historical issued release predates all policy artifacts. Do not add a
    -- snapshot during a later installer upgrade: absence is its legacy proof.
    if exists (
      select 1
      from schema_authorization_policy_source
      where app_id = revision_row.app_id
        and schema_version = revision_row.base_version
    ) or exists (
      select 1
      from schema_authorization_policy_snapshot
      where schema_revision_id = revision_row.id
        and app_id = revision_row.app_id
        and customer_id = revision_row.customer_id
    ) then
      raise exception 'schema_drift: authorization policy artifacts exist without a release expectation';
    end if;
    return;
  elsif not expected_policy_declared then
    if expected_row.policy_hash is not null then
      raise exception 'schema_drift: authorization policy expectation has a hash while policy is undeclared';
    end if;
    insert into schema_authorization_policy_snapshot(
      schema_revision_id, app_id, customer_id, policy, policy_hash
    ) values (
      revision_row.id, revision_row.app_id, revision_row.customer_id, null, null
    ) on conflict do nothing;
  else
    if expected_row.policy_hash is null
      or expected_row.policy_hash !~ '^[0-9a-f]{64}$'
    then
      raise exception 'schema_drift: declared authorization policy expectation is malformed';
    end if;
    select policy, policy_hash
    into source_row
    from schema_authorization_policy_source
    where app_id = revision_row.app_id
      and schema_version = revision_row.base_version;
    if not found
      or source_row.policy_hash is distinct from expected_row.policy_hash
      or source_row.policy_hash !~ '^[0-9a-f]{64}$'
      or kernel_admin_sha256(kernel_canonical_json(source_row.policy))
        is distinct from source_row.policy_hash
    then
      raise exception 'schema_drift: declared authorization policy source is missing or altered';
    end if;
    insert into schema_authorization_policy_snapshot(
      schema_revision_id, app_id, customer_id, policy, policy_hash
    ) values (
      revision_row.id, revision_row.app_id, revision_row.customer_id,
      source_row.policy, source_row.policy_hash
    ) on conflict do nothing;
  end if;

  select policy, policy_hash
  into snapshot_row
  from schema_authorization_policy_snapshot
  where schema_revision_id = revision_row.id
    and app_id = revision_row.app_id
    and customer_id = revision_row.customer_id;
  if not found
    or (
      expected_policy_declared
      and (
        snapshot_row.policy is null
        or snapshot_row.policy_hash is distinct from expected_row.policy_hash
        or kernel_admin_sha256(kernel_canonical_json(snapshot_row.policy))
          is distinct from snapshot_row.policy_hash
      )
    )
    or (
      not expected_policy_declared
      and (snapshot_row.policy is not null or snapshot_row.policy_hash is not null)
    )
  then
    raise exception 'schema_drift: authorization policy snapshot differs from release expectation';
  end if;
end;
$kernel$;

-- artifact: function kernel_policy_active_snapshot(text,text)
create or replace function kernel_policy_active_snapshot(app text, customer text)
returns jsonb
language plpgsql
stable
parallel safe
security invoker
set search_path from current
as $kernel$
declare
  active_row record;
  expected_row record;
  source_row record;
  snapshot_row record;
  expectation_found boolean := false;
  source_found boolean := false;
  snapshot_found boolean := false;
  active_marker_present boolean := false;
  active_policy_declared boolean := null;
begin
  select *, base_schema->>'version' as base_version
  into active_row
  from schema_revision
  where app_id = app
    and customer_id = customer
    and activated_at is not null;
  if not found then
    raise exception 'active_schema_missing: %/%', app, customer;
  end if;
  active_marker_present := to_jsonb(active_row) ? 'authorization_policy_declared';
  if active_marker_present then
    active_policy_declared := (to_jsonb(active_row)->>'authorization_policy_declared')::boolean;
  end if;

  select policy_declared, policy_hash
  into expected_row
  from schema_authorization_policy_expectation
  where app_id = app and schema_version = active_row.base_version;
  expectation_found := found;
  select policy, policy_hash
  into source_row
  from schema_authorization_policy_source
  where app_id = app and schema_version = active_row.base_version;
  source_found := found;
  select policy, policy_hash
  into snapshot_row
  from schema_authorization_policy_snapshot
  where schema_revision_id = active_row.id
    and app_id = app and customer_id = customer;
  snapshot_found := found;

  -- Pre-substrate issued revisions have none of the three policy artifacts.
  if not expectation_found and not source_found and not snapshot_found then
    if active_policy_declared then
      raise exception 'schema_drift: active declared policy marker exists without authorization policy artifacts';
    end if;
    return jsonb_build_object('declared', false, 'policy', null);
  end if;
  if not expectation_found then
    raise exception 'schema_drift: authorization policy source or snapshot exists without a release expectation';
  end if;
  if active_marker_present
    and active_policy_declared is not null
    and active_policy_declared is distinct from expected_row.policy_declared
  then
    raise exception 'schema_drift: authorization policy marker differs from release expectation';
  end if;
  if expected_row.policy_declared then
    if not source_found
      or not snapshot_found
      or expected_row.policy_hash is null
      or source_row.policy_hash is distinct from expected_row.policy_hash
      or snapshot_row.policy is null
      or snapshot_row.policy_hash is distinct from expected_row.policy_hash
      or kernel_admin_sha256(kernel_canonical_json(source_row.policy))
        is distinct from source_row.policy_hash
      or kernel_admin_sha256(kernel_canonical_json(snapshot_row.policy))
        is distinct from snapshot_row.policy_hash
    then
      raise exception 'schema_drift: active authorization policy source or snapshot is altered';
    end if;
    return jsonb_build_object('declared', true, 'policy', snapshot_row.policy);
  end if;
  if expected_row.policy_hash is not null
    or source_found
    or (
      snapshot_found
      and (snapshot_row.policy is not null or snapshot_row.policy_hash is not null)
    )
  then
    raise exception 'schema_drift: legacy authorization policy artifacts are altered';
  end if;
  return jsonb_build_object('declared', false, 'policy', null);
end;
$kernel$;

-- artifact: function kernel_policy_request_actor(text,text)
create or replace function kernel_policy_request_actor(app text, customer text)
returns text language plpgsql volatile parallel unsafe security invoker set search_path from current
as $kernel$
declare actor text:=nullif(current_setting('kernel.actor_id',true),''); runtime_role text:=kernel_installer_capability_role('runtime'); requested_role text:=nullif(current_setting('kernel.actor_role',true),''); requested_fence text:=nullif(current_setting('kernel.actor_fence_generation',true),'');
begin
  if actor is null then raise exception 'authorization_denied: a trusted actor binding is required'; end if;
  if not exists(select 1 from kernel_principal_scope scope where scope.principal_name=session_user::name and scope.capability='runtime' and scope.active and scope.app_id=app and scope.customer_id=customer and (scope.actor_id is null or scope.actor_id=actor) and pg_has_role(session_user,pg_catalog.to_regrole(runtime_role),'MEMBER')) then raise exception 'authorization_denied: runtime principal scope is not authorized'; end if;
  if not exists(select 1 from kernel_actor_membership membership where membership.principal_name=session_user::name and membership.active and membership.app_id=app and membership.customer_id=customer and membership.actor_id=actor) then raise exception 'authorization_denied: actor membership is not authorized'; end if;
  if requested_role is not null or requested_fence is not null or exists(select 1 from kernel_principal_scope s where s.principal_name=session_user::name and s.capability='runtime' and s.app_id=app and s.customer_id=customer and s.actor_binding_required) then
    if requested_role is null or requested_fence is null or requested_fence !~ '^[1-9][0-9]*$' or not exists(select 1 from kernel_actor_membership m where m.principal_name=session_user::name and m.active and m.app_id=app and m.customer_id=customer and m.actor_id=actor and m.role=requested_role and m.fence_generation::text=requested_fence for share of m) then
      raise exception 'authorization_denied: actor binding fence is no longer current';
    end if;
  end if;
  return actor;
end;
$kernel$;

-- artifact: function kernel_policy_capture_grants(jsonb,text,text)
create or replace function kernel_policy_capture_grants(policy jsonb, model_id text, operation text)
returns jsonb language sql stable parallel safe security invoker set search_path from current
as $kernel$
 select jsonb_build_object('actor_id',nullif(current_setting('kernel.actor_id',true),''),'operation',operation,
  'grants',coalesce(jsonb_agg(grant_value.value),'[]'::jsonb))
 from kernel_actor_membership membership
 join jsonb_array_elements(coalesce(policy->'grants','[]'::jsonb)) grant_value(value)
  on grant_value.value->>'role'=membership.role
 where membership.principal_name=session_user::name and membership.active
  and membership.app_id=current_setting('kernel.app_id',true)
  and membership.customer_id=current_setting('kernel.customer_id',true)
  and membership.actor_id=nullif(current_setting('kernel.actor_id',true),'')
  and grant_value.value->>'model'=model_id
  and grant_value.value->'operations' ? operation
$kernel$;

-- artifact: function kernel_policy_grants_fields_allowed(jsonb,jsonb)
create or replace function kernel_policy_grants_fields_allowed(captured jsonb, required_fields jsonb)
returns boolean language plpgsql immutable parallel safe security invoker set search_path from current
as $kernel$
declare grants jsonb:=coalesce(captured->'grants','[]'::jsonb); grant_count integer:=jsonb_array_length(grants);
 operation text:=captured->>'operation'; allowed_fields jsonb:='[]'::jsonb; i integer;
 required_count integer:=jsonb_array_length(coalesce(required_fields,'[]'::jsonb));
begin
 if grant_count=0 then return false; end if;
 if operation='delete' or required_count=0 then return true; end if;
 for i in 0..grant_count-1 loop
  if operation in ('read','history') then allowed_fields:=allowed_fields||coalesce(grants->i->'read_fields','[]'::jsonb);
  elsif operation in ('create','update') then allowed_fields:=allowed_fields||coalesce(grants->i->'write_fields','[]'::jsonb); end if;
 end loop;
 return coalesce(required_fields,'[]'::jsonb)<@allowed_fields;
end $kernel$;

-- artifact: function kernel_policy_grants_record_allowed(jsonb,jsonb,jsonb)
create or replace function kernel_policy_grants_record_allowed(captured jsonb, required_fields jsonb, record_values jsonb)
returns boolean language plpgsql immutable parallel safe security invoker set search_path from current
as $kernel$
declare grants jsonb:=coalesce(captured->'grants','[]'::jsonb); grant_count integer:=jsonb_array_length(grants);
 matched jsonb:='[]'::jsonb; grant_value jsonb; i integer;
begin
 for i in 0..grant_count-1 loop
  grant_value:=grants->i;
  if grant_value->'record'->>'kind'='all' or (
   grant_value->'record'->>'kind'='actor_equals_field'
   and record_values->(grant_value->'record'->>'field')->>'value'=captured->>'actor_id'
  ) then matched:=matched||jsonb_build_array(grant_value); end if;
 end loop;
 return kernel_policy_grants_fields_allowed(captured||jsonb_build_object('grants',matched),required_fields);
end $kernel$;

-- artifact: function kernel_policy_required_fields_allowed(jsonb,text,text,jsonb)
create or replace function kernel_policy_required_fields_allowed(policy jsonb, model_id text, operation text, required_fields jsonb)
returns boolean language sql stable parallel safe security invoker set search_path from current
as $kernel$
 select kernel_policy_grants_fields_allowed(kernel_policy_capture_grants(policy,model_id,operation),required_fields)
$kernel$;

-- artifact: function kernel_policy_record_allowed(jsonb,text,text,jsonb,jsonb)
create or replace function kernel_policy_record_allowed(policy jsonb, model_id text, operation text, required_fields jsonb, record_values jsonb)
returns boolean language sql stable parallel safe security invoker set search_path from current
as $kernel$
 select kernel_policy_grants_record_allowed(kernel_policy_capture_grants(policy,model_id,operation),required_fields,record_values)
$kernel$;

-- artifact: function kernel_policy_authorize_query(text,text,text,jsonb)
create or replace function kernel_policy_authorize_query(
  app text,
  customer text,
  model_id text,
  required_fields jsonb
)
returns jsonb
language plpgsql
stable
parallel safe
security invoker
set search_path from current
as $kernel$
declare
  snapshot jsonb;
begin
  if jsonb_typeof(required_fields) is distinct from 'array'
    or exists (
      select 1
      from jsonb_array_elements(required_fields) item(value)
      where jsonb_typeof(item.value) <> 'string'
    )
  then
    raise exception 'contract_validation_failed: authorization field set must be an array of strings';
  end if;
  snapshot := kernel_policy_active_snapshot(app, customer);
  if not coalesce((snapshot->>'declared')::boolean, false) then
    return null;
  end if;
  perform kernel_policy_request_actor(app, customer);
  if not kernel_policy_required_fields_allowed(
    snapshot->'policy',
    model_id,
    'read',
    required_fields
  ) then
    raise exception 'authorization_denied: no applicable authorization grant permits the requested fields';
  end if;
  return snapshot->'policy';
end;
$kernel$;

-- artifact: function kernel_policy_raw_table_access_allowed(name,text,text)
create or replace function kernel_policy_raw_table_access_allowed(
  access_role name,
  app text,
  customer text
)
returns boolean
language plpgsql
stable
parallel safe
security invoker
set search_path from current
as $kernel$
declare
  snapshot jsonb;
begin
  if access_role::text = kernel_installer_capability_role('execution_owner') then
    return true;
  end if;
  if not exists (
    select 1
    from schema_revision revision
    where revision.app_id = $2
      and revision.customer_id = $3
      and revision.activated_at is not null
  ) then
    return false;
  end if;
  snapshot := kernel_policy_active_snapshot(app, customer);
  if not coalesce((snapshot->>'declared')::boolean, false) then
    return true;
  end if;
  return false;
end;
$kernel$;

-- artifact: function kernel_apply_identifier(text)
create or replace function kernel_apply_identifier(logical_id text)
returns text
language plpgsql
immutable
security invoker
set search_path from current
as $kernel_apply$
declare
  normalized text;
  candidate text;
begin
  normalized := regexp_replace(lower(btrim(logical_id)), '[[:space:]_-]+', '_', 'g');
  normalized := btrim(normalized, '_');
  if normalized is null or normalized = '' or normalized !~ '^[a-z][a-z0-9_]*$' then
    perform kernel_apply_fail(
      'schema_drift', 'Schema drift detected', 'object', 'schema_drift',
      coalesce(logical_id, '<null>') || ': invalid logical identifier'
    );
  end if;
  candidate := kernel_physical_identifier(normalized);
  return candidate;
end;
$kernel_apply$;

-- artifact: function kernel_apply_normalize_lookup_label(text)
create or replace function kernel_apply_normalize_lookup_label(label text)
returns text
language sql
immutable
strict
parallel safe
security invoker
set search_path from current
as $kernel_lookup$
  select nullif(lower(regexp_replace(btrim(label), '[[:space:]_-]+', '_', 'g')), '')
$kernel_lookup$;

-- artifact: function kernel_apply_prepare_lookup_or_create(jsonb,jsonb)
create or replace function kernel_apply_prepare_lookup_or_create(request jsonb, active_schema jsonb)
returns jsonb
language plpgsql
volatile
security invoker
set search_path from current
as $kernel_lookup$
<<kernel_apply_prepare_lookup_or_create>>
declare
  app_id text := request->>'app_id';
  customer_id text := request->>'customer_id';
  writes jsonb := request->'writes';
  intents jsonb := '[]'::jsonb;
  intent_map jsonb := '{}'::jsonb;
  lock_map jsonb := '{}'::jsonb;
  resolved_map jsonb := '{}'::jsonb;
  created_map jsonb := '{}'::jsonb;
  generated_writes jsonb := '[]'::jsonb;
  write jsonb;
  write_index bigint;
  source_model jsonb;
  field_entry record;
  relation_definition jsonb;
  custom_entry jsonb;
  custom_index bigint;
  relation_key jsonb;
  target_index bigint;
  target_model_id text;
  intent jsonb;
  payload jsonb;
  target_model jsonb;
  display_field_id text;
  normalized_label text;
  label_key text;
  intent_key text;
  intent_effective_start date;
  existing_intent jsonb;
  intent_contract jsonb;
  candidate_ids uuid[];
  candidate_count integer;
  resolved_record_id uuid;
  reserved_record_id uuid;
  create_values jsonb;
  generated_write jsonb;
  patch_path text[];
begin
  if jsonb_typeof(coalesce(writes,'null'::jsonb))<>'array' then return request; end if;

  select value,ordinal-1 into write,write_index
  from jsonb_array_elements(writes) with ordinality item(value,ordinal)
  where exists(
    select 1 from jsonb_object_keys(case when jsonb_typeof(value)='object' then value else '{}'::jsonb end) key
    where key like '\_\_kernel\_%' escape '\'
  )
  order by ordinal
  limit 1;
  if write is not null then
    perform kernel_apply_fail(
      'contract_validation_failed','Contract validation failed','writes[' || write_index || ']',
      'reserved_internal_apply_field','caller-supplied __kernel_ fields are forbidden'
    );
  end if;

  for write,write_index in
    select value,ordinal-1 from jsonb_array_elements(writes) with ordinality item(value,ordinal)
  loop
    select value into source_model from jsonb_array_elements(coalesce(active_schema->'models','[]'::jsonb)) item(value)
    where value->>'id'=write->>'model_id';
    if source_model is null then continue; end if;

    for field_entry in
      select key,value from jsonb_each(case when jsonb_typeof(write->'values')='object' then write->'values' else '{}'::jsonb end)
    loop
      relation_key:=field_entry.value->'value';
      if field_entry.value->>'type'='relation' and relation_key->>'type'='lookup_or_create' then
        select value into relation_definition from jsonb_array_elements(coalesce(source_model->'fields','[]'::jsonb)) item(value)
        where value->>'id'=field_entry.key and value->>'type'='relation';
        if relation_definition is null then continue; end if;
        intents:=intents || jsonb_build_array(jsonb_build_object(
          'target_model_id',relation_definition->>'target_model','payload',relation_key->'value',
          'effective_start',write->>'effective_start','provenance',write->'provenance',
          'path',jsonb_build_array(write_index::text,'values',field_entry.key,'value'),
          'path_label','writes[' || write_index || '].values.' || field_entry.key
        ));
      elsif field_entry.value->>'type'='relation_list' and jsonb_typeof(field_entry.value->'value')='array' then
        select value into relation_definition from jsonb_array_elements(coalesce(source_model->'many_relations','[]'::jsonb)) item(value)
        where value->>'id'=field_entry.key;
        if relation_definition is null then continue; end if;
        for relation_key,target_index in
          select value,ordinal-1 from jsonb_array_elements(field_entry.value->'value') with ordinality target(value,ordinal)
        loop
          if relation_key->>'type'<>'lookup_or_create' then continue; end if;
          intents:=intents || jsonb_build_array(jsonb_build_object(
            'target_model_id',relation_definition->>'target_model','payload',relation_key->'value',
            'effective_start',write->>'effective_start','provenance',write->'provenance',
            'path',jsonb_build_array(write_index::text,'values',field_entry.key,'value',target_index::text),
            'path_label','writes[' || write_index || '].values.' || field_entry.key || '[' || target_index || ']'
          ));
        end loop;
      end if;
    end loop;

    for custom_entry,custom_index in
      select value,ordinal-1 from jsonb_array_elements(case when jsonb_typeof(write->'custom_fields')='array' then write->'custom_fields' else '[]'::jsonb end)
        with ordinality item(value,ordinal)
    loop
      relation_key:=custom_entry->'value';
      if custom_entry->>'type'<>'relation' or relation_key->>'type'<>'lookup_or_create' then continue; end if;
      select value into relation_definition from jsonb_array_elements(coalesce(active_schema->'custom_fields','[]'::jsonb)) item(value)
      where value->>'model_id'=write->>'model_id' and value->>'field_id'=custom_entry->>'field_id'
        and value->>'type'='relation';
      if relation_definition is null then continue; end if;
      intents:=intents || jsonb_build_array(jsonb_build_object(
        'target_model_id',relation_definition->>'target_model_id','payload',relation_key->'value',
        'effective_start',write->>'effective_start','provenance',write->'provenance',
        'path',jsonb_build_array(write_index::text,'custom_fields',custom_index::text,'value'),
        'path_label','writes[' || write_index || '].custom_fields[' || custom_index || '].value'
      ));
    end loop;
  end loop;

  if jsonb_array_length(intents)=0 then return request; end if;

  for intent in select value from jsonb_array_elements(intents) item(value) loop
    payload:=intent->'payload';
    if jsonb_typeof(payload)<>'object'
      or not (payload ? 'label')
      or payload-array['label','values']<>'{}'::jsonb
      or jsonb_typeof(payload->'label')<>'string'
      or (payload ? 'values' and jsonb_typeof(payload->'values')<>'object')
    then
      perform kernel_apply_fail(
        'contract_validation_failed','Contract validation failed',intent->>'path_label',
        'invalid_lookup_or_create','lookup_or_create requires a nonblank label and optional typed values object'
      );
    end if;
    normalized_label:=kernel_apply_normalize_lookup_label(payload->>'label');
    if normalized_label is null then
      perform kernel_apply_fail(
        'contract_validation_failed','Contract validation failed',intent->>'path_label',
        'empty_lookup_match_label','lookup_or_create label must not be blank'
      );
    end if;
    target_model_id:=intent->>'target_model_id';
    select value into target_model from jsonb_array_elements(coalesce(active_schema->'models','[]'::jsonb)) item(value)
    where value->>'id'=target_model_id;
    if target_model is null or target_model->>'kind'<>'lookup' then
      perform kernel_apply_fail(
        'contract_validation_failed','Contract validation failed',intent->>'path_label',
        'lookup_or_create_target_not_lookup','lookup_or_create is valid only for relations targeting lookup models'
      );
    end if;
    if coalesce(target_model->>'lifecycle','active')<>'active' then
      perform kernel_apply_fail(
        'contract_validation_failed','Contract validation failed',intent->>'path_label',
        'retired_relation_target_model','lookup_or_create cannot target a retired lookup model'
      );
    end if;
    perform kernel_apply_assert_lookup_storage_authority(app_id,customer_id,target_model_id);
    display_field_id:=target_model->>'display_field_id';
    if display_field_id is null then
      perform kernel_apply_fail('schema_drift','Schema drift detected',intent->>'path_label','lookup_display_field_missing','lookup model has no display_field_id');
    end if;
    if coalesce(payload->'values','{}'::jsonb) ? display_field_id then
      perform kernel_apply_fail(
        'contract_validation_failed','Contract validation failed',intent->>'path_label' || '.values.' || display_field_id,
        'lookup_display_value_conflict','lookup_or_create derives the display field from label; values must not also supply it'
      );
    end if;
    label_key:=target_model_id || ':' || normalized_label;
    intent_key:=label_key || ':' || (intent->>'effective_start');
    intent_contract:=jsonb_build_object(
      'label',payload->>'label','values',coalesce(payload->'values','{}'::jsonb),
      'effective_start',intent->>'effective_start'
    );
    existing_intent:=intent_map->intent_key;
    if existing_intent is not null and existing_intent->'contract' is distinct from intent_contract then
      perform kernel_apply_fail(
        'contract_validation_failed','Contract validation failed',intent->>'path_label',
        'lookup_create_intent_conflict','one change set cannot supply different create payloads for the same normalized lookup label'
      );
    elsif existing_intent is null then
      intent_map:=intent_map || jsonb_build_object(intent_key,jsonb_build_object(
        'target_model_id',target_model_id,'normalized_label',normalized_label,
        'display_field_id',display_field_id,'contract',intent_contract,
        'provenance',intent->'provenance','path_label',intent->>'path_label',
        'label_key',label_key
      ));
      lock_map:=lock_map || jsonb_build_object(label_key,true);
    end if;
  end loop;

  for label_key,intent in select key,value from jsonb_each(lock_map) order by key loop
    perform pg_advisory_xact_lock(hashtextextended(
      'lookup-normalized:' || current_schema() || ':' || app_id || ':' || customer_id || ':' || label_key,0
    ));
  end loop;

  for intent_key,intent in
    select key,value from jsonb_each(intent_map)
    order by value->>'target_model_id',value->>'normalized_label',value#>>'{contract,effective_start}',key
  loop
    target_model_id:=intent->>'target_model_id';
    normalized_label:=intent->>'normalized_label';
    label_key:=intent->>'label_key';
    intent_effective_start:=(intent#>>'{contract,effective_start}')::date;
    candidate_ids:=null;
    with visible_versions as (
      select distinct on (version.record_id)
        version.id,version.record_id,version.availability,
        version.tombstones_record,version.untombstones_record
      from lookup_version version
      join change_set changes
        on changes.id=version.change_set_id and changes.app_id=version.app_id
       and changes.customer_id=version.customer_id
      where version.app_id=kernel_apply_prepare_lookup_or_create.app_id
        and version.customer_id=kernel_apply_prepare_lookup_or_create.customer_id
        and version.model_id=target_model_id and version.stage='mainline'
        and changes.status='mainline' and changes.applied_order is not null
        and version.effective_start<=intent_effective_start
        and (version.effective_end is null or version.effective_end>=intent_effective_start)
      order by version.record_id,version.effective_start desc,version.tombstones_record desc,
        version.untombstones_record desc,changes.applied_order desc,version.id desc
    )
    select array_agg(candidate.record_id order by candidate.record_id) into candidate_ids
    from (
      select distinct projection.record_id
      from visible_versions visible
      join lookup_alias_projection projection
        on projection.app_id=kernel_apply_prepare_lookup_or_create.app_id
       and projection.customer_id=kernel_apply_prepare_lookup_or_create.customer_id
       and projection.model_id=target_model_id and projection.version_id=visible.id
      where projection.normalized_alias=normalized_label
        and visible.availability='active'
        and not visible.tombstones_record and not visible.untombstones_record
    ) candidate;
    candidate_count:=coalesce(cardinality(candidate_ids),0);
    if candidate_count>1 then
      perform kernel_apply_fail(
        'lookup_match_ambiguous','Normalized lookup match is ambiguous',intent->>'path_label',
        'lookup_match_ambiguous','more than one active lookup record owns normalized label `' || normalized_label || '`'
      );
    end if;
    resolved_record_id:=case when candidate_count=1 then candidate_ids[1] else null end;
    if resolved_record_id is null then
      reserved_record_id:=null;
      select projection.record_id into reserved_record_id
      from lookup_alias_projection projection
      join lookup_version version
        on version.app_id=projection.app_id and version.customer_id=projection.customer_id
       and version.model_id=projection.model_id and version.id=projection.version_id
      join change_set changes
        on changes.id=version.change_set_id and changes.app_id=version.app_id
       and changes.customer_id=version.customer_id
      where projection.app_id=kernel_apply_prepare_lookup_or_create.app_id
        and projection.customer_id=kernel_apply_prepare_lookup_or_create.customer_id
        and projection.model_id=target_model_id and projection.normalized_alias=normalized_label
        and version.stage<>'discarded' and changes.status in ('mainline','draft')
      order by projection.record_id
      limit 1;
      if reserved_record_id is not null then
        perform kernel_apply_fail(
          'lookup_label_reserved','Lookup label is reserved',intent->>'path_label',
          'lookup_label_reserved','normalized label `' || normalized_label || '` belongs to a retired, tombstoned, renamed, or pending-draft lookup record'
        );
      end if;

      existing_intent:=created_map->label_key;
      if existing_intent is not null then
        if existing_intent->'contract' is distinct from ((intent->'contract')-'effective_start'::text) then
          perform kernel_apply_fail(
            'contract_validation_failed','Contract validation failed',intent->>'path_label',
            'lookup_create_intent_conflict','temporal lookup create intents for one normalized label must use the same create payload'
          );
        end if;
        resolved_record_id:=(existing_intent->>'record_id')::uuid;
      else
        resolved_record_id:=gen_random_uuid();
        create_values:=coalesce(intent#>'{contract,values}','{}'::jsonb) || jsonb_build_object(
          intent->>'display_field_id',jsonb_build_object('type','text','value',intent#>>'{contract,label}')
        );
        generated_write:=jsonb_build_object(
          'model_id',target_model_id,'new_record_id',resolved_record_id,
          'effective_start',intent#>>'{contract,effective_start}','values',create_values,
          '__kernel_lookup_or_create',true
        );
        if intent ? 'provenance' and intent->'provenance'<>'null'::jsonb then
          generated_write:=generated_write || jsonb_build_object('provenance',intent->'provenance');
        end if;
        generated_writes:=generated_writes || jsonb_build_array(generated_write);
        created_map:=created_map || jsonb_build_object(label_key,jsonb_build_object(
          'record_id',resolved_record_id,'contract',(intent->'contract')-'effective_start'::text
        ));
      end if;
    end if;
    resolved_map:=resolved_map || jsonb_build_object(intent_key,resolved_record_id::text);
  end loop;

  for intent in select value from jsonb_array_elements(intents) item(value) loop
    normalized_label:=kernel_apply_normalize_lookup_label(intent#>>'{payload,label}');
    intent_key:=(intent->>'target_model_id') || ':' || normalized_label || ':' || (intent->>'effective_start');
    resolved_record_id:=(resolved_map->>intent_key)::uuid;
    select array_agg(value order by ordinal) into patch_path
    from jsonb_array_elements_text(intent->'path') with ordinality part(value,ordinal);
    writes:=jsonb_set(
      writes,patch_path,
      jsonb_build_object('type','record_id','value',resolved_record_id),false
    );
  end loop;

  return jsonb_set(request,'{writes}',generated_writes || writes,false);
end;
$kernel_lookup$;

-- artifact: function kernel_apply_error_envelope(text,text)
create or replace function kernel_apply_error_envelope(error_sqlstate text, error_message text)
returns jsonb
language plpgsql
stable
security invoker
set search_path from current
as $kernel_apply$
declare
  payload text;
begin
  if error_message like 'kernel_apply:%' then
    payload := substring(error_message from length('kernel_apply:') + 1);
    return payload::jsonb;
  end if;
  -- Shared policy helpers raise a stable prefix instead of an apply envelope.
  -- Keep authorization failure safe and distinguish it from an unexpected fault.
  if error_sqlstate = 'P0001' and error_message like 'authorization_denied:%' then
    return jsonb_build_object(
      'code', 'authorization_denied',
      'message', 'This operation is not authorized',
      'details', '[]'::jsonb
    );
  end if;
  if error_sqlstate = 'P0001' and error_message like 'unsupported_capability:%' then
    return jsonb_build_object(
      'code', 'unsupported_capability',
      'message', 'This capability is not supported',
      'details', '[]'::jsonb
    );
  end if;
  if error_sqlstate = 'P0001' and error_message like 'active_schema_missing:%' then
    return jsonb_build_object(
      'code', 'active_schema_missing',
      'message', 'No active schema revision exists for this scope',
      'details', jsonb_build_array(jsonb_build_object(
        'path', 'scope', 'code', 'active_schema_missing',
        'message', 'materialize a schema before applying or reading records'
      ))
    );
  end if;
  if error_sqlstate = '23505' then
    return jsonb_build_object(
      'code', 'record_key_conflict',
      'message', 'Record key conflict',
      'details', '[]'::jsonb
    );
  end if;
  return jsonb_build_object(
    'code', 'database_error',
    'message', 'Database operation failed',
    'details', '[]'::jsonb
  );
end;
$kernel_apply$;

-- artifact: function kernel_apply_error_envelope(text,text,text,jsonb)
create or replace function kernel_apply_error_envelope(
  error_sqlstate text,
  error_message text,
  error_constraint text,
  request jsonb
)
returns jsonb
language plpgsql
stable
security invoker
set search_path from current
as $kernel_apply$
declare
  active_schema jsonb;
  model jsonb;
  field jsonb;
  write jsonb;
  typed_value jsonb;
  model_id text;
  field_id text;
  field_type text;
  version_name text;
  column_name text;
  expected_constraint text;
  display_value text;
begin
  if error_sqlstate <> '23505' or error_constraint is null then
    return kernel_apply_error_envelope(error_sqlstate, error_message);
  end if;

  select schema into active_schema
  from schema_revision
  where app_id = request->>'app_id'
    and customer_id = request->>'customer_id'
    and activated_at is not null;

  for model in
    select value from jsonb_array_elements(coalesce(active_schema->'models','[]'::jsonb)) item(value)
  loop
    model_id := model->>'id';
    version_name := kernel_apply_identifier(kernel_apply_identifier(model_id) || '_version');
    for field in
      select value from jsonb_array_elements(coalesce(model->'fields','[]'::jsonb)) item(value)
      where coalesce((value->>'is_unique')::boolean,false)
    loop
      field_id := field->>'id';
      field_type := field->>'type';
      column_name := kernel_apply_identifier(field_id);
      if field_type = 'money_rate' then
        column_name := kernel_apply_identifier(column_name || '_amount');
      end if;
      expected_constraint := kernel_apply_identifier(
        version_name || '_' || column_name || '_live_unique_idx'
      );
      if error_constraint <> expected_constraint then
        continue;
      end if;

      select value into write
      from jsonb_array_elements(coalesce(request->'writes','[]'::jsonb)) item(value)
      where value->>'model_id' = model_id
        and jsonb_typeof(value->'values') = 'object'
        and value->'values' ? field_id
      limit 1;
      typed_value := write->'values'->field_id;
      display_value := case field_type
        when 'relation' then kernel_apply_record_key_debug(typed_value->'value')
        when 'text_list' then (
          select string_agg(value, ', ' order by ordinal)
          from jsonb_array_elements_text(typed_value->'value') with ordinality item(value,ordinal)
        )
        when 'known_aliases' then (
          select string_agg(value, ', ' order by ordinal)
          from jsonb_array_elements_text(typed_value->'value') with ordinality item(value,ordinal)
        )
        when 'json' then kernel_canonical_json(typed_value->'value')
        when 'money_rate' then
          (typed_value#>>'{value,amount}') || ' ' ||
          (typed_value#>>'{value,currency}') || ' ' ||
          initcap(typed_value#>>'{value,period}')
        else typed_value->>'value'
      end;
      return jsonb_build_object(
        'code','unique_field_conflict',
        'message','Unique field value already exists',
        'details',jsonb_build_array(
          jsonb_build_object('path','model','code','unique_field_conflict','message',model_id),
          jsonb_build_object('path','field','code','unique_field_conflict','message',field_id),
          jsonb_build_object('path','value','code','unique_field_conflict','message',coalesce(display_value,'<unknown>'))
        )
      );
    end loop;
  end loop;

  return kernel_apply_error_envelope(error_sqlstate, error_message);
end;
$kernel_apply$;

-- artifact: function kernel_apply_error_envelope_v2(text,text,text,text,jsonb)
create or replace function kernel_apply_error_envelope_v2(
  error_sqlstate text,
  error_message text,
  error_constraint text,
  error_table text,
  request jsonb
)
returns jsonb
language plpgsql
volatile
security invoker
set search_path from current
as $kernel_apply$
declare
  identity_row record;
  details jsonb;
begin
  if error_sqlstate = '23514'
    and error_constraint is not null
    and error_table is not null
  then
    -- The failed executor subtransaction rolls back its tenant settings.
    -- Restore scope before reading the RLS-protected diagnostic catalog.
    perform set_config('kernel.app_id', request->>'app_id', true);
    perform set_config('kernel.customer_id', request->>'customer_id', true);
    select identity_value->>'model_id' as model_id,
           identity_value->>'constraint_id' as constraint_id,
           identity_value->'field_ids' as field_ids
    into identity_row
    from schema_revision as revision
    join schema_constraint_identity as snapshot on snapshot.schema_revision_id = revision.id
      and snapshot.app_id = revision.app_id and snapshot.customer_id = revision.customer_id
    cross join lateral jsonb_array_elements(snapshot.catalog) as identity_item(identity_value)
    where revision.app_id = request->>'app_id'
      and revision.customer_id = request->>'customer_id'
      and revision.activated_at is not null
      and identity_value->>'table_name' = error_table
      and identity_value->>'constraint_name' = error_constraint;
    if found then
      details := jsonb_build_array(
        jsonb_build_object(
          'path', 'model',
          'code', 'constraint_violation',
          'message', identity_row.model_id
        ),
        jsonb_build_object(
          'path', 'constraint',
          'code', 'constraint_violation',
          'message', identity_row.constraint_id
        )
      ) || coalesce((
        select jsonb_agg(jsonb_build_object(
          'path', 'field',
          'code', 'constraint_violation',
          'message', value
        ))
        from jsonb_array_elements_text(identity_row.field_ids) as item(value)
      ), '[]'::jsonb);
      return jsonb_build_object(
        'code', 'constraint_violation',
        'message', 'A required rule was not satisfied',
        'details', details
      );
    end if;
  end if;
  return kernel_apply_error_envelope(error_sqlstate, error_message, error_constraint, request);
end;
$kernel_apply$;

-- artifact: function kernel_apply_fail(text,text,text,text,text)
create or replace function kernel_apply_fail(
  error_code text,
  error_message text,
  detail_path text default null,
  detail_code text default null,
  detail_message text default null
)
returns void
language plpgsql
volatile
security invoker
set search_path from current
as $kernel_apply$
declare
  envelope jsonb;
begin
  envelope := jsonb_build_object(
    'code', error_code,
    'message', error_message,
    'details', case when detail_path is null then '[]'::jsonb else jsonb_build_array(
      jsonb_build_object(
        'path', detail_path,
        'code', coalesce(detail_code, error_code),
        'message', coalesce(detail_message, error_message)
      )
    ) end
  );
  raise exception using errcode = 'P0001', message = 'kernel_apply:' || envelope::text;
end;
$kernel_apply$;

