-- artifact: function kernel_http_body_approve_draft_change_set(jsonb)
create or replace function kernel_http_body_approve_draft_change_set(request jsonb)
returns jsonb language plpgsql volatile security invoker set search_path from current
as $kernel$
<<kernel_draft_api>>
declare
  app_id text; customer_id text; change_set_id bigint; revision_id bigint; current_status text; created_mode text;
  draft_created_order bigint; applied_order bigint; schema_json jsonb; model jsonb; row_data jsonb;
  version_table text; record_table text; version_filter text; record_filter text; lock_model jsonb;
  draft_rows jsonb := '[]'::jsonb; item jsonb; other jsonb; field jsonb; conflict_id bigint;
  predecessor record; next_start date; other_next_start date; new_end date; stale_details text[] := '{}';
  lock_set jsonb := '[]'::jsonb; relation_target jsonb; column_name text; value_text text; affected bigint;
  interval_scope jsonb; interval_violation jsonb; request_actor text;
begin
  if request is null or jsonb_typeof(request) <> 'object' then return kernel_draft_contract_error('request', 'invalid_request', 'request must be a JSON object'); end if;
  app_id := request->>'app_id'; customer_id := request->>'customer_id';
  if app_id is null or btrim(app_id) = '' then return kernel_draft_contract_error('app_id', 'required', 'app_id is required'); end if;
  if customer_id is null or btrim(customer_id) = '' then return kernel_draft_contract_error('customer_id', 'required', 'customer_id is required'); end if;
  begin change_set_id := (request->>'change_set_id')::bigint; exception when others then return kernel_draft_contract_error('change_set_id', 'invalid', 'change_set_id must be an integer'); end;
  perform kernel_draft_require_scope(app_id, customer_id);
  begin
    request_actor := kernel_policy_request_actor(app_id, customer_id);
  exception when raise_exception then
    if sqlerrm like 'authorization_denied:%' then
      perform kernel_draft_fail('authorization_denied', 'A trusted actor binding is required');
    end if;
    raise;
  end;
  if nullif(request->>'actor_id', '') is distinct from request_actor or not coalesce((
    select bool_and(m.actor_kind='human') from kernel_actor_membership m
    where m.principal_name=session_user::name and m.app_id=kernel_draft_api.app_id
      and m.customer_id=kernel_draft_api.customer_id and m.actor_id=request_actor and m.active
  ), false) then
    perform kernel_draft_fail('authorization_denied', 'Draft approval requires human authority');
  end if;
  perform set_config('kernel.app_id', app_id, true); perform set_config('kernel.customer_id', customer_id, true);
  select schema_revision_id, status, created_with_mode, created_order into revision_id, current_status, created_mode, draft_created_order
  from change_set where id=change_set_id and change_set.app_id=kernel_draft_api.app_id and change_set.customer_id=kernel_draft_api.customer_id for update;
  if not found then perform kernel_draft_fail('record_target_missing', format('change_set `%s` did not resolve', change_set_id)); end if;
  if current_status='mainline' and created_mode='draft' then return kernel_draft_ok(jsonb_build_object('id', change_set_id, 'schema_revision_id', revision_id)); end if;
  if current_status <> 'draft' then perform kernel_draft_fail('draft_status_conflict', format('cannot approve change_set `%s` with status `%s`', change_set_id, current_status)); end if;
  schema_json := kernel_draft_active_schema(app_id, customer_id, revision_id);
  perform kernel_draft_assert_schema_lookup_authority(schema_json,app_id,customer_id);

  for model in select value from jsonb_array_elements(schema_json->'models') loop
    version_table := kernel_draft_version_table(model);
    version_filter := kernel_draft_model_filter(model,'v');
    for row_data in execute format('select to_jsonb(v) from %I v where app_id=$1 and customer_id=$2 and change_set_id=$3 and stage=''draft''%s order by effective_start, tombstones_record, untombstones_record, id for update', version_table, version_filter) using app_id, customer_id, change_set_id loop
      draft_rows := draft_rows || jsonb_build_array(jsonb_build_object('model', model, 'row', row_data, 'version_table', version_table));
      lock_set := lock_set || jsonb_build_array(jsonb_build_object('model_id',model->>'id','record_id',row_data->>'record_id'));
      for relation_target in select value from jsonb_array_elements(kernel_draft_relation_targets(schema_json,model,row_data)) loop
        lock_set := lock_set || jsonb_build_array(relation_target);
      end loop;
    end loop;
  end loop;
  if jsonb_array_length(draft_rows)=0 then perform kernel_draft_fail('draft_status_conflict', format('change_set `%s` has no draft version rows', change_set_id)); end if;
  select jsonb_object_agg(scoped.model_id, scoped.record_ids) into interval_scope
  from (
    select value->'model'->>'id' as model_id, jsonb_agg(distinct value->'row'->>'record_id') as record_ids
    from jsonb_array_elements(draft_rows) group by value->'model'->>'id'
  ) scoped;
  -- Interval-rule model locks precede the canonical subject locks.
  interval_violation := kernel_constraint_interval_isolation_error(app_id, customer_id, null, array(select jsonb_object_keys(interval_scope)));
  if interval_violation is not null then perform kernel_draft_fail(interval_violation->>'code', interval_violation->>'message', interval_violation->'details'); end if;
  perform kernel_constraint_interval_lock(app_id, customer_id, null, array(select jsonb_object_keys(interval_scope)));

  -- Canonical subject locks precede validation and causal-order allocation.
  for item in select value from (select distinct value from jsonb_array_elements(lock_set)) locks order by value->>'model_id', value->>'record_id' loop
    select value into lock_model from jsonb_array_elements(schema_json->'models') candidate(value)
    where value->>'id'=item->>'model_id';
    if lock_model is null then perform kernel_draft_fail('schema_drift','Schema drift detected'); end if;
    record_table := kernel_draft_record_table(lock_model); record_filter:=kernel_draft_model_filter(lock_model,'');
    execute format('select 1 from %I where id=$1 and app_id=$2 and customer_id=$3%s for update', record_table,record_filter)
      using (item->>'record_id')::uuid, app_id, customer_id;
  end loop;

  for item in select value from jsonb_array_elements(draft_rows) order by value->'model'->>'id', value->'row'->>'record_id', (value->'row'->>'effective_start')::date, value->'row'->>'id' loop
    model := item->'model'; row_data := item->'row'; version_table := item->>'version_table';
    version_filter:=kernel_draft_model_filter(model,'v');
    conflict_id := null;
    execute format('select cs.id from %I v join change_set cs on cs.id=v.change_set_id and cs.app_id=v.app_id and cs.customer_id=v.customer_id where v.record_id=$1 and v.app_id=$2 and v.customer_id=$3%s and v.stage=''mainline'' and v.change_set_id<>$4 and cs.applied_order>$5 order by cs.applied_order, cs.id limit 1', version_table,version_filter)
      into conflict_id using (row_data->>'record_id')::uuid, app_id, customer_id, change_set_id, draft_created_order;
    if conflict_id is not null then stale_details := array_append(stale_details, format('%s:%s updated by change_set `%s`', model->>'id', row_data->>'record_id', conflict_id)); end if;
    conflict_id := null;
    execute format('select rcs.id from %I v join change_set rcs on rcs.app_id=v.app_id and rcs.customer_id=v.customer_id and rcs.source_kind=''revert'' and rcs.source_ref=v.change_set_id::text where v.record_id=$1 and v.app_id=$2 and v.customer_id=$3%s and v.stage=''reverted'' and v.change_set_id<>$4 and rcs.status=''mainline'' and rcs.applied_order>$5 order by rcs.applied_order, rcs.id limit 1', version_table,version_filter)
      into conflict_id using (row_data->>'record_id')::uuid, app_id, customer_id, change_set_id, draft_created_order;
    if conflict_id is not null then stale_details := array_append(stale_details, format('%s:%s reverted by change_set `%s`', model->>'id', row_data->>'record_id', conflict_id)); end if;
    if (row_data->>'tombstones_record')::boolean and exists(
      select 1 from jsonb_array_elements(draft_rows) later where later->'model'->>'id'=model->>'id' and later->'row'->>'record_id'=row_data->>'record_id' and (later->'row'->>'effective_start')::date>(row_data->>'effective_start')::date
    ) then perform kernel_draft_fail('timeline_conflict', format('draft tombstone for `%s:%s` at %s would precede a later draft version', model->>'id', row_data->>'record_id', row_data->>'effective_start')); end if;
    if (row_data->>'tombstones_record')::boolean or (row_data->>'untombstones_record')::boolean then
      conflict_id := null;
      execute format('select change_set_id from %I v where record_id=$1 and app_id=$2 and customer_id=$3%s and stage=''mainline'' and effective_start=$4 and tombstones_record=$5 and untombstones_record=$6 limit 1', version_table,version_filter)
        into conflict_id using (row_data->>'record_id')::uuid, app_id, customer_id, (row_data->>'effective_start')::date, (row_data->>'tombstones_record')::boolean, (row_data->>'untombstones_record')::boolean;
      if conflict_id is not null then perform kernel_draft_fail('timeline_conflict', format('record `%s` already has a mainline version at %s', row_data->>'record_id', row_data->>'effective_start')); end if;
    end if;
    execute format('select effective_start from %I v where record_id=$1 and app_id=$2 and customer_id=$3%s and stage=''mainline'' and effective_start>$4 order by effective_start limit 1', version_table,version_filter)
      into next_start using (row_data->>'record_id')::uuid, app_id, customer_id, (row_data->>'effective_start')::date;
    if (row_data->>'tombstones_record')::boolean and next_start is not null then perform kernel_draft_fail('timeline_conflict', format('tombstone for record `%s` at %s would precede a later mainline version', row_data->>'record_id', row_data->>'effective_start')); end if;
    perform kernel_draft_validate_relations(schema_json, model, row_data, app_id, customer_id, (row_data->>'effective_start')::date, change_set_id);
    if next_start is null and not (row_data->>'tombstones_record')::boolean then
      perform kernel_draft_validate_unique(model, row_data, version_table, app_id, customer_id, (row_data->>'record_id')::uuid);
      if not exists(select 1 from jsonb_array_elements(draft_rows) later where later->'model'->>'id'=model->>'id' and later->'row'->>'record_id'=row_data->>'record_id' and (later->'row'->>'effective_start')::date>(row_data->>'effective_start')::date) then
        for other in select value from jsonb_array_elements(draft_rows)
          where value->'model'->>'id'=model->>'id'
            and value->'row'->>'record_id'<>row_data->>'record_id'
            and not (value->'row'->>'tombstones_record')::boolean
            and not exists(select 1 from jsonb_array_elements(draft_rows) later where later->'model'->>'id'=model->>'id' and later->'row'->>'record_id'=value->'row'->>'record_id' and (later->'row'->>'effective_start')::date>(value->'row'->>'effective_start')::date)
        loop
          execute format('select effective_start from %I v where record_id=$1 and app_id=$2 and customer_id=$3%s and stage=''mainline'' and effective_start>$4 order by effective_start limit 1',version_table,version_filter)
            into other_next_start using (other->'row'->>'record_id')::uuid,app_id,customer_id,(other->'row'->>'effective_start')::date;
          if other_next_start is not null then continue; end if;
          for field in select value from jsonb_array_elements(coalesce(model->'fields','[]'::jsonb)) where coalesce((value->>'is_unique')::boolean,false) loop
            column_name:=kernel_physical_identifier(field->>'id');
            if (case when model->>'kind'='lookup' then row_data->'values'->(field->>'id') else row_data->column_name end) is not null
              and (case when model->>'kind'='lookup' then row_data->'values'->(field->>'id') else row_data->column_name end)
                =(case when model->>'kind'='lookup' then other->'row'->'values'->(field->>'id') else other->'row'->column_name end) then
              value_text:=case when model->>'kind'='lookup' then row_data#>>array['values',field->>'id','value'] else row_data->>column_name end;
              perform kernel_draft_fail('unique_field_conflict','Unique field value already exists',jsonb_build_array(
                jsonb_build_object('path','model','code','unique_field_conflict','message',model->>'id'),
                jsonb_build_object('path','field','code','unique_field_conflict','message',field->>'id'),
                jsonb_build_object('path','value','code','unique_field_conflict','message',value_text)
              ));
            end if;
          end loop;
        end loop;
      end if;
    end if;
  end loop;
  if cardinality(stale_details)>0 then select array_agg(distinct value order by value) into stale_details from unnest(stale_details) value; perform kernel_draft_fail('stale_draft', array_to_string(stale_details, '; ')); end if;

  applied_order := nextval('change_set_lifecycle_order_seq');
  update change_set set status='mainline', applied_order=kernel_draft_api.applied_order, applied_at=now()
  where id=change_set_id and change_set.app_id=kernel_draft_api.app_id and change_set.customer_id=kernel_draft_api.customer_id and status='draft';
  if not found then perform kernel_draft_fail('draft_status_conflict', format('draft change_set `%s` changed during approval', change_set_id)); end if;

  for item in select value from jsonb_array_elements(draft_rows) order by value->'model'->>'id', value->'row'->>'record_id', (value->'row'->>'effective_start')::date, value->'row'->>'id' loop
    model:=item->'model'; row_data:=item->'row'; version_table:=item->>'version_table'; version_filter:=kernel_draft_model_filter(model,'v');
    execute format('select v.id, v.effective_start, v.effective_end, v.tombstones_record, v.untombstones_record from %I v join change_set cs on cs.id=v.change_set_id and cs.app_id=v.app_id and cs.customer_id=v.customer_id where v.record_id=$1 and v.app_id=$2 and v.customer_id=$3%s and v.stage=''mainline'' and v.id<>$4 and v.effective_start<=$5 order by v.effective_start desc, case when v.tombstones_record then 2 when v.untombstones_record then 1 else 0 end desc, cs.applied_order desc, v.id desc limit 1', version_table,version_filter)
      into predecessor using (row_data->>'record_id')::uuid, app_id, customer_id, (row_data->>'id')::uuid, (row_data->>'effective_start')::date;
    execute format('select effective_start from %I v where record_id=$1 and app_id=$2 and customer_id=$3%s and stage=''mainline'' and id<>$4 and effective_start>$5 order by effective_start limit 1', version_table,version_filter)
      into next_start using (row_data->>'record_id')::uuid, app_id, customer_id, (row_data->>'id')::uuid, (row_data->>'effective_start')::date;
    if predecessor.id is not null and predecessor.effective_start=(row_data->>'effective_start')::date and not predecessor.tombstones_record and not predecessor.untombstones_record then new_end:=predecessor.effective_end; else new_end:=case when next_start is null then null else next_start-1 end; end if;
    if predecessor.id is not null then
      execute format('update %I set effective_end=case when effective_start=$2 then $2 else $2-1 end where id=$1 and app_id=$3 and customer_id=$4 and stage=''mainline''%s', version_table, kernel_draft_model_filter(model,''))
        using predecessor.id, (row_data->>'effective_start')::date, app_id, customer_id;
    end if;
    execute format('update %I set stage=''mainline'', effective_end=$2, applied_at=now() where id=$1 and app_id=$3 and customer_id=$4 and stage=''draft''%s', version_table, kernel_draft_model_filter(model,''))
      using (row_data->>'id')::uuid, new_end, app_id, customer_id;
    get diagnostics affected = row_count;
    if affected<>1 then perform kernel_draft_fail('schema_drift', 'Schema drift detected', jsonb_build_array(jsonb_build_object('path','object','code','schema_drift','message',version_table || ': draft version changed during approval'))); end if;
    if model->>'kind'='lookup' then
      if new_end is null and not (row_data->>'tombstones_record')::boolean and coalesce(row_data->>'availability','active')='active' then
        update lookup_alias_projection projection set is_current=false
        where projection.app_id=kernel_draft_api.app_id and projection.customer_id=kernel_draft_api.customer_id
          and projection.model_id=model->>'id' and projection.record_id=(row_data->>'record_id')::uuid and projection.is_current;
      end if;
      perform kernel_apply_project_lookup_version(
        (row_data->>'id')::uuid,app_id,customer_id,model->>'id',(row_data->>'record_id')::uuid,
        schema_json,model,coalesce(row_data->'values','{}'::jsonb),coalesce(row_data->'many_relations','{}'::jsonb),
        new_end is null and not (row_data->>'tombstones_record')::boolean and coalesce(row_data->>'availability','active')='active'
      );
    end if;
  end loop;
  interval_violation := kernel_constraint_interval_violation(app_id, customer_id, null, interval_scope);
  if interval_violation is not null then perform kernel_draft_fail(interval_violation->>'code', interval_violation->>'message', interval_violation->'details'); end if;
  return kernel_draft_ok(jsonb_build_object('id', change_set_id, 'schema_revision_id', revision_id));
exception when unique_violation then return kernel_draft_unique_error(model,row_data);
when serialization_failure then raise;
when others then
  if sqlstate='AR001' then return sqlerrm::jsonb; end if;
  return kernel_draft_error('database_error', 'Database operation failed');
end
$kernel$;

-- artifact: function kernel_approve_draft_change_set(jsonb)
create or replace function kernel_approve_draft_change_set(request jsonb)
returns jsonb language plpgsql volatile parallel unsafe security invoker set search_path from current
as $kernel$
declare guard jsonb; result jsonb;
begin
  perform kernel_cleanup_generated_visible_query();
  guard := kernel_http_mutation_guard(request,'kernel_approve_draft_change_set');
  if guard->'ok'='false'::jsonb then return guard; end if;
  result := kernel_http_body_approve_draft_change_set(request);
  if coalesce((guard->>'required')::boolean,false) then
    perform kernel_http_mutation_record(request,guard,result);
  end if;
  return result;
end;
$kernel$;

-- artifact: function kernel_http_body_revert_change_set(jsonb)
create or replace function kernel_http_body_revert_change_set(request jsonb)
returns jsonb language plpgsql volatile security invoker set search_path from current
as $kernel$
<<kernel_draft_api>>
declare
  app_id text; customer_id text; target_id bigint; revision_id bigint; target_status text; target_source text; target_order bigint;
  schema_json jsonb; model jsonb; lock_model jsonb; version_table text; record_table text;
  version_filter text; record_filter text; row_data jsonb; item jsonb;
  target_rows jsonb := '[]'::jsonb; target_subjects jsonb := '{}'::jsonb; timeline_row record;
  lock_set jsonb := '[]'::jsonb; relation_target jsonb; rechecked_rows jsonb := '[]'::jsonb;
  conflict_start date; conflict_change_set_id bigint;
  idempotency_key_value text; existing record; fingerprint text; revert_id bigint; lifecycle integer; created_order bigint; affected bigint;
  interval_scope jsonb; interval_violation jsonb; request_actor text;
begin
  if request is null or jsonb_typeof(request) <> 'object' then return kernel_draft_contract_error('request', 'invalid_request', 'request must be a JSON object'); end if;
  app_id:=request->>'app_id'; customer_id:=request->>'customer_id'; idempotency_key_value:=request->>'idempotency_key';
  if app_id is null or btrim(app_id)='' then return kernel_draft_contract_error('app_id','required','app_id is required'); end if;
  if customer_id is null or btrim(customer_id)='' then return kernel_draft_contract_error('customer_id','required','customer_id is required'); end if;
  begin target_id:=(request->>'change_set_id')::bigint; exception when others then return kernel_draft_contract_error('change_set_id','invalid','change_set_id must be an integer'); end;
  perform kernel_draft_require_scope(app_id, customer_id);
  begin
    request_actor := kernel_policy_request_actor(app_id, customer_id);
  exception when raise_exception then
    if sqlerrm like 'authorization_denied:%' then
      perform kernel_draft_fail('authorization_denied', 'A trusted actor binding is required');
    end if;
    raise;
  end;
  if nullif(request->>'actor_id', '') is distinct from request_actor or not coalesce((
    select bool_and(m.actor_kind='human') from kernel_actor_membership m
    where m.principal_name=session_user::name and m.app_id=kernel_draft_api.app_id
      and m.customer_id=kernel_draft_api.customer_id and m.actor_id=request_actor and m.active
  ), false) then
    perform kernel_draft_fail('authorization_denied', 'Revert requires human authority');
  end if;

  perform set_config('kernel.app_id', app_id, true); perform set_config('kernel.customer_id', customer_id, true);
  if idempotency_key_value is not null then
    perform pg_advisory_xact_lock(hashtextextended(app_id || E'\x1f' || customer_id || E'\x1f' || idempotency_key_value, 0));
    select id, schema_revision_id, request_fingerprint into existing from change_set where change_set.app_id=kernel_draft_api.app_id and change_set.customer_id=kernel_draft_api.customer_id and idempotency_key=idempotency_key_value;
    if found then
      fingerprint:=kernel_draft_revert_fingerprint(request, existing.schema_revision_id);
      if existing.request_fingerprint is distinct from fingerprint then
        perform kernel_draft_fail('idempotency_conflict','Idempotency key was reused for a different request',jsonb_build_array(jsonb_build_object('path','idempotency_key','code','idempotency_conflict','message',format('Key `%s` was reused; use a new idempotency key or replay the exact equivalent request',idempotency_key_value))));
      end if;
      return kernel_draft_ok(jsonb_build_object('id',existing.id,'schema_revision_id',existing.schema_revision_id));
    end if;
  end if;
  select schema_revision_id,status,source_kind,applied_order into revision_id,target_status,target_source,target_order from change_set
  where id=target_id and change_set.app_id=kernel_draft_api.app_id and change_set.customer_id=kernel_draft_api.customer_id for update;
  if not found then perform kernel_draft_fail('record_target_missing',format('change_set `%s` did not resolve',target_id)); end if;
  if target_status<>'mainline' then perform kernel_draft_fail('revert_conflict',format('change_set `%s` has status `%s`, not `mainline`',target_id,target_status)); end if;
  if target_source='revert' then perform kernel_draft_fail('revert_conflict',format('change_set `%s` is itself a revert',target_id)); end if;
  if target_order is null then perform kernel_draft_fail('schema_drift','Schema drift detected',jsonb_build_array(jsonb_build_object('path','object','code','schema_drift','message',format('change_set.applied_order: mainline change_set `%s` has no applied_order',target_id)))); end if;
  schema_json:=kernel_draft_active_schema(app_id,customer_id,revision_id);
  perform kernel_draft_assert_schema_lookup_authority(schema_json,app_id,customer_id);
  for model in select value from jsonb_array_elements(schema_json->'models') loop
    version_table:=kernel_draft_version_table(model); version_filter:=kernel_draft_model_filter(model,'v');
    for row_data in execute format('select to_jsonb(v) from %I v where app_id=$1 and customer_id=$2 and change_set_id=$3 and stage=''mainline''%s order by effective_start,tombstones_record,untombstones_record,id',version_table,version_filter) using app_id,customer_id,target_id loop
      target_rows:=target_rows || jsonb_build_array(jsonb_build_object('model',model,'row',row_data,'version_table',version_table));
      target_subjects:=target_subjects || jsonb_build_object((model->>'id') || ':' || (row_data->>'record_id'), jsonb_build_object('model',model,'record_id',row_data->'record_id','version_table',version_table));
      lock_set:=lock_set || jsonb_build_array(jsonb_build_object('model_id',model->>'id','record_id',row_data->>'record_id'));
    end loop;
  end loop;
  if jsonb_array_length(target_rows)=0 then perform kernel_draft_fail('already_reverted',format('change_set `%s` has no mainline version rows to revert',target_id)); end if;
  select jsonb_object_agg(scoped.model_id, scoped.record_ids) into interval_scope
  from (
    select value->'model'->>'id' as model_id, jsonb_agg(distinct value->>'record_id') as record_ids
    from jsonb_each(target_subjects) subject(key, value) group by value->'model'->>'id'
  ) scoped;
  -- Interval-rule model locks precede the canonical subject locks.
  interval_violation := kernel_constraint_interval_isolation_error(app_id, customer_id, null, array(select jsonb_object_keys(interval_scope)));
  if interval_violation is not null then perform kernel_draft_fail(interval_violation->>'code', interval_violation->>'message', interval_violation->'details'); end if;
  perform kernel_constraint_interval_lock(app_id, customer_id, null, array(select jsonb_object_keys(interval_scope)));

  for item in select value from jsonb_each(target_subjects) order by key loop
    model:=item->'model'; version_table:=item->>'version_table'; version_filter:=kernel_draft_model_filter(model,'v');
    for row_data in execute format('select row_data from (select to_jsonb(v) row_data,v.effective_start,lead(v.effective_start) over(order by v.effective_start,case when v.tombstones_record then 2 when v.untombstones_record then 1 else 0 end,cs.applied_order,v.id) next_start from %I v join change_set cs on cs.id=v.change_set_id and cs.app_id=v.app_id and cs.customer_id=v.customer_id where v.record_id=$1 and v.app_id=$2 and v.customer_id=$3%s and v.stage=''mainline'' and v.change_set_id<>$4 and cs.status=''mainline'' and cs.applied_order is not null) timeline where next_start is null or next_start<>effective_start order by effective_start',version_table,version_filter) using (item->>'record_id')::uuid,app_id,customer_id,target_id loop
      for relation_target in select value from jsonb_array_elements(kernel_draft_relation_targets(schema_json,model,row_data)) loop
        lock_set:=lock_set || jsonb_build_array(relation_target);
      end loop;
    end loop;
  end loop;
  for item in select value from (select distinct value from jsonb_array_elements(lock_set)) locks order by value->>'model_id',value->>'record_id' loop
    select value into lock_model from jsonb_array_elements(schema_json->'models') candidate(value)
    where value->>'id'=item->>'model_id';
    if lock_model is null then perform kernel_draft_fail('schema_drift','Schema drift detected'); end if;
    record_table:=kernel_draft_record_table(lock_model); record_filter:=kernel_draft_model_filter(lock_model,'');
    execute format('select 1 from %I where id=$1 and app_id=$2 and customer_id=$3%s for update',record_table,record_filter) using (item->>'record_id')::uuid,app_id,customer_id;
  end loop;
  for model in select value from jsonb_array_elements(schema_json->'models') loop
    version_table:=kernel_draft_version_table(model); version_filter:=kernel_draft_model_filter(model,'v');
    for row_data in execute format('select to_jsonb(v) from %I v where app_id=$1 and customer_id=$2 and change_set_id=$3 and stage=''mainline''%s order by effective_start,tombstones_record,untombstones_record,id',version_table,version_filter) using app_id,customer_id,target_id loop
      rechecked_rows:=rechecked_rows || jsonb_build_array(jsonb_build_object('model',model,'row',row_data,'version_table',version_table));
    end loop;
  end loop;
  if rechecked_rows<>target_rows then
    perform kernel_draft_fail('database_error','Database operation failed');
  end if;
  for item in select value from jsonb_array_elements(target_rows) loop
    model:=item->'model'; row_data:=item->'row'; version_table:=item->>'version_table'; version_filter:=kernel_draft_model_filter(model,'v'); lifecycle:=case when (row_data->>'tombstones_record')::boolean then 2 when (row_data->>'untombstones_record')::boolean then 1 else 0 end;
    conflict_start := null; conflict_change_set_id := null;
    execute format('select v.effective_start,v.change_set_id from %I v join change_set cs on cs.id=v.change_set_id and cs.app_id=v.app_id and cs.customer_id=v.customer_id and cs.status=''mainline'' and cs.applied_order is not null where v.record_id=$1 and v.app_id=$2 and v.customer_id=$3%s and v.stage=''mainline'' and v.change_set_id<>$4 and (v.effective_start>$5 or (v.effective_start=$5 and (case when v.tombstones_record then 2 when v.untombstones_record then 1 else 0 end>$6 or (case when v.tombstones_record then 2 when v.untombstones_record then 1 else 0 end=$6 and cs.applied_order>$7)))) order by v.effective_start, v.tombstones_record desc, v.untombstones_record desc, cs.applied_order, v.id limit 1',version_table,version_filter)
      into conflict_start, conflict_change_set_id using (row_data->>'record_id')::uuid,app_id,customer_id,target_id,(row_data->>'effective_start')::date,lifecycle,target_order;
    if conflict_change_set_id is not null then perform kernel_draft_fail('revert_conflict',format('record `%s` has a later mainline version at %s from change_set `%s`',row_data->>'record_id',conflict_start,conflict_change_set_id)); end if;
  end loop;

  fingerprint:=kernel_draft_revert_fingerprint(request,revision_id); created_order:=nextval('change_set_lifecycle_order_seq');
  insert into change_set(app_id,customer_id,schema_revision_id,created_with_mode,status,actor_id,source_kind,source_ref,idempotency_key,request_fingerprint,change_type_id,notes,created_order,applied_order,applied_at)
  values(app_id,customer_id,revision_id,'mainline','mainline',request->>'actor_id','revert',target_id::text,idempotency_key_value,fingerprint,null,request->>'notes',created_order,created_order,now()) returning id into revert_id;
  for item in select value from jsonb_array_elements(target_rows) loop
    model:=item->'model'; row_data:=item->'row'; version_table:=item->>'version_table';
    execute format('update %I set stage=''reverted'',applied_at=null where id=$1 and app_id=$2 and customer_id=$3 and stage=''mainline''%s',version_table,kernel_draft_model_filter(model,'')) using (row_data->>'id')::uuid,app_id,customer_id;
    get diagnostics affected = row_count;
    if affected<>1 then perform kernel_draft_fail('schema_drift','Schema drift detected',jsonb_build_array(jsonb_build_object('path','object','code','schema_drift','message',format('%s: revert target version `%s` was not a live mainline row',version_table,row_data->>'id')))); end if;
    if model->>'kind'='lookup' then
      update lookup_alias_projection projection set is_current=false
      where projection.app_id=kernel_draft_api.app_id and projection.customer_id=kernel_draft_api.customer_id
        and projection.model_id=model->>'id' and projection.version_id=(row_data->>'id')::uuid;
    end if;
  end loop;
  for item in select value from jsonb_each(target_subjects) order by key loop
    model:=item->'model'; version_table:=item->>'version_table'; version_filter:=kernel_draft_model_filter(model,'v');
    for timeline_row in execute format('select v.id,to_jsonb(v) row_data,v.effective_start,lead(v.effective_start) over(order by v.effective_start,case when v.tombstones_record then 2 when v.untombstones_record then 1 else 0 end,cs.applied_order,v.id) next_start from %I v join change_set cs on cs.id=v.change_set_id and cs.app_id=v.app_id and cs.customer_id=v.customer_id where v.record_id=$1 and v.app_id=$2 and v.customer_id=$3%s and v.stage=''mainline'' and cs.status=''mainline'' and cs.applied_order is not null order by v.effective_start,case when v.tombstones_record then 2 when v.untombstones_record then 1 else 0 end,cs.applied_order,v.id',version_table,version_filter) using (item->>'record_id')::uuid,app_id,customer_id loop
      row_data:=timeline_row.row_data;
      execute format('update %I set effective_end=$2 where id=$1 and app_id=$3 and customer_id=$4 and stage=''mainline''%s',version_table,kernel_draft_model_filter(model,''))
        using timeline_row.id,case when timeline_row.next_start is null then null when timeline_row.next_start=timeline_row.effective_start then timeline_row.effective_start else timeline_row.next_start-1 end,app_id,customer_id;
    end loop;
    for row_data in execute format('select row_data from (select to_jsonb(v) row_data, v.effective_start, lead(v.effective_start) over(order by v.effective_start,case when v.tombstones_record then 2 when v.untombstones_record then 1 else 0 end,cs.applied_order,v.id) next_start from %I v join change_set cs on cs.id=v.change_set_id and cs.app_id=v.app_id and cs.customer_id=v.customer_id where v.record_id=$1 and v.app_id=$2 and v.customer_id=$3%s and v.stage=''mainline'' and cs.status=''mainline'' and cs.applied_order is not null) timeline where next_start is null or next_start<>effective_start order by effective_start',version_table,version_filter) using (item->>'record_id')::uuid,app_id,customer_id loop
      perform kernel_draft_validate_relations(schema_json,model,row_data,app_id,customer_id,(row_data->>'effective_start')::date,null);
    end loop;
    execute format('select to_jsonb(v) from %I v join change_set cs on cs.id=v.change_set_id and cs.app_id=v.app_id and cs.customer_id=v.customer_id where v.record_id=$1 and v.app_id=$2 and v.customer_id=$3%s and v.stage=''mainline'' and cs.status=''mainline'' and cs.applied_order is not null order by v.effective_start desc,case when v.tombstones_record then 2 when v.untombstones_record then 1 else 0 end desc,cs.applied_order desc,v.id desc limit 1',version_table,version_filter) into row_data using (item->>'record_id')::uuid,app_id,customer_id;
    if row_data is not null and not (row_data->>'tombstones_record')::boolean then
      perform kernel_draft_validate_unique(model,row_data,version_table,app_id,customer_id,(item->>'record_id')::uuid);
    end if;
    if model->>'kind'='lookup' and row_data is not null then
      update lookup_alias_projection projection set is_current=false
      where projection.app_id=kernel_draft_api.app_id and projection.customer_id=kernel_draft_api.customer_id
        and projection.model_id=model->>'id' and projection.record_id=(item->>'record_id')::uuid and projection.is_current;
      perform kernel_apply_project_lookup_version(
        (row_data->>'id')::uuid,app_id,customer_id,model->>'id',(item->>'record_id')::uuid,
        schema_json,model,coalesce(row_data->'values','{}'::jsonb),coalesce(row_data->'many_relations','{}'::jsonb),
        not (row_data->>'tombstones_record')::boolean and coalesce(row_data->>'availability','active')='active'
      );
    end if;
    record_table:=kernel_draft_record_table(model); record_filter:=kernel_draft_model_filter(model,'r');
    execute format('update %I r set external_key=null where r.id=$1 and r.app_id=$2 and r.customer_id=$3%s and r.external_key is not null and not exists(select 1 from %I v where v.record_id=r.id and v.app_id=r.app_id and v.customer_id=r.customer_id%s and v.stage in (''draft'',''mainline''))',record_table,record_filter,version_table,kernel_draft_model_filter(model,'v')) using (item->>'record_id')::uuid,app_id,customer_id;
  end loop;
  interval_violation := kernel_constraint_interval_violation(app_id, customer_id, null, interval_scope);
  if interval_violation is not null then perform kernel_draft_fail(interval_violation->>'code', interval_violation->>'message', interval_violation->'details'); end if;
  return kernel_draft_ok(jsonb_build_object('id',revert_id,'schema_revision_id',revision_id));
exception when unique_violation then return kernel_draft_unique_error(model,row_data);
when others then
  if sqlstate='AR001' then return sqlerrm::jsonb; end if;
  return kernel_draft_error('database_error','Database operation failed');
end
$kernel$;

-- artifact: function kernel_revert_change_set(jsonb)
create or replace function kernel_revert_change_set(request jsonb)
returns jsonb language plpgsql volatile parallel unsafe security invoker set search_path from current
as $kernel$
declare guard jsonb; result jsonb;
begin
  perform kernel_cleanup_generated_visible_query();
  guard := kernel_http_mutation_guard(request,'kernel_revert_change_set');
  if guard->'ok'='false'::jsonb then return guard; end if;
  result := kernel_http_body_revert_change_set(request);
  if coalesce((guard->>'required')::boolean,false) then
    perform kernel_http_mutation_record(request,guard,result);
  end if;
  return result;
end;
$kernel$;

-- artifact: function kernel_search_normalize(text)
create or replace function kernel_search_normalize(value text)
returns text
language sql
immutable
strict
parallel safe
security invoker
set search_path from current
as $kernel_search$
  select nullif(btrim(regexp_replace(
    lower(regexp_replace(normalize(value, NFD), '[̀-ͯ]', '', 'g') collate "und-x-icu"),
    '[\t\n\v\f\r \u00a0\u1680\u2000-\u200a\u2028\u2029\u202f\u205f\u3000\ufeff]+', ' ', 'g'
  )), '')
$kernel_search$;

-- artifact: function kernel_search_distance(text,text,integer)
create or replace function kernel_search_distance(a text, b text, max_distance integer)
returns integer
language plpgsql
immutable
strict
parallel safe
security invoker
set search_path from current
as $kernel_search$
declare
  a_length integer := char_length(a);
  b_length integer := char_length(b);
  before_previous integer[];
  previous integer[];
  current_row integer[];
  row_minimum integer;
  best integer;
  a_char text;
  b_char text;
begin
  if abs(a_length - b_length) > max_distance then return max_distance + 1; end if;
  if a_length = 0 or b_length = 0 then return greatest(a_length, b_length); end if;
  previous := array(select generate_series(0, b_length));
  for i in 1..a_length loop
    current_row := array_fill(0, array[b_length + 1]);
    current_row[1] := i;
    row_minimum := i;
    a_char := substr(a, i, 1);
    for j in 1..b_length loop
      b_char := substr(b, j, 1);
      best := least(
        previous[j + 1] + 1,
        current_row[j] + 1,
        previous[j] + case when a_char = b_char then 0 else 1 end
      );
      if i > 1 and j > 1 and a_char = substr(b, j - 1, 1) and substr(a, i - 1, 1) = b_char then
        best := least(best, before_previous[j - 1] + 1);
      end if;
      current_row[j + 1] := best;
      row_minimum := least(row_minimum, best);
    end loop;
    if row_minimum > max_distance then return max_distance + 1; end if;
    before_previous := previous;
    previous := current_row;
  end loop;
  return least(previous[b_length + 1], max_distance + 1);
end;
$kernel_search$;

-- artifact: function kernel_search_grade(text,text)
create or replace function kernel_search_grade(candidate text, query text)
returns integer
language plpgsql
immutable
strict
parallel safe
security invoker
set search_path from current
as $kernel_search$
declare
  found_at integer;
  searched integer := 0;
  term text;
  word text;
  allowed integer;
  matched boolean;
begin
  if candidate = query then return 0; end if;
  if starts_with(candidate, query) then return 1; end if;
  found_at := strpos(candidate, query);
  if found_at > 0 then
    loop
      found_at := strpos(substr(candidate, searched + 1), query);
      exit when found_at = 0;
      found_at := found_at + searched;
      if substr(candidate, found_at - 1, 1) collate "und-x-icu" !~ '[[:alnum:]]' then return 2; end if;
      searched := found_at;
    end loop;
    return 3;
  end if;
  foreach term in array string_to_array(query, ' ') loop
    allowed := case
      when char_length(term) < 4 then 0
      when char_length(term) < 8 then 1
      else 2
    end;
    matched := false;
    foreach word in array regexp_split_to_array(candidate collate "und-x-icu", '[^[:alnum:]]+') loop
      continue when word = '';
      -- Cheap filters first: a word too short, or missing more of the
      -- term's characters than edits allow, cannot match.
      matched := starts_with(word, term) or (
        allowed > 0
        and char_length(word) >= char_length(term) - allowed
        and char_length(translate(term, word, '')) <= allowed
        and (
          kernel_search_distance(term, word, allowed) <= allowed
          or kernel_search_distance(term, left(word, char_length(term)), allowed) <= allowed
        )
      );
      exit when matched;
    end loop;
    if not matched then return null; end if;
  end loop;
  return 4;
end;
$kernel_search$;

-- artifact: function kernel_search_record_grade(text,jsonb,jsonb)
create or replace function kernel_search_record_grade(query text, record_values jsonb, field_ids jsonb)
returns integer
language sql
immutable
strict
parallel safe
security invoker
set search_path from current
as $kernel_search$
  select min(kernel_search_grade(normalized.value, query))
  from jsonb_array_elements_text(field_ids) field(id)
  cross join lateral (
    select record_values->field.id->>'value' as value
    where jsonb_typeof(record_values->field.id->'value') = 'string'
    union all
    select item.value
    from jsonb_array_elements_text(
      case when jsonb_typeof(record_values->field.id->'value') = 'array'
        then record_values->field.id->'value' else '[]'::jsonb end
    ) item(value)
  ) candidate
  cross join lateral (select kernel_search_normalize(candidate.value) as value) normalized
  where normalized.value is not null
$kernel_search$;

-- artifact: function kernel_read_physical_identifier(text)
create or replace function kernel_read_physical_identifier(logical_id text)
returns text
language plpgsql
immutable
security invoker
set search_path from current
as $kernel$
declare
  normalized text;
begin
  if logical_id is null
     or btrim(logical_id) = ''
     or logical_id ~ '[^A-Za-z0-9_[:space:]-]' then
    raise exception 'contract_validation_failed: invalid identifier `%`', logical_id;
  end if;
  normalized := regexp_replace(lower(btrim(logical_id)), '[[:space:]_-]+', '_', 'g');
  normalized := btrim(normalized, '_');
  if normalized = '' or normalized !~ '^[a-z][a-z0-9_]*$' then
    raise exception 'contract_validation_failed: invalid identifier `%`', logical_id;
  end if;
  return kernel_physical_identifier(logical_id);
end;
$kernel$;

-- artifact: function kernel_read_error_envelope(text,text)
create or replace function kernel_read_error_envelope(error_sqlstate text, error_message text)
returns jsonb
language plpgsql
stable
security invoker
set search_path from current
as $kernel$
declare
  error_code text;
  details text;
  drift_object text;
  drift_details text;
begin
  if error_message is not null and position(': ' in error_message) > 0 then
    error_code := split_part(error_message, ': ', 1);
    details := substring(error_message from length(error_code) + 3);
  end if;

  if error_code = 'active_schema_missing' then
    return jsonb_build_object(
      'code', 'active_schema_missing',
      'message', 'No active schema revision exists for this scope',
      'details', jsonb_build_array(jsonb_build_object(
        'path', 'scope',
        'code', 'active_schema_missing',
        'message', details || ': materialize a schema before applying or reading records'
      ))
    );
  elsif error_code = 'record_target_missing' then
    return jsonb_build_object(
      'code', 'record_target_missing', 'message', details, 'details', '[]'::jsonb
    );
  elsif error_code = 'schema_drift' then
    drift_object := split_part(details, '|', 1);
    drift_details := substring(details from length(drift_object) + 2);
    return jsonb_build_object(
      'code', 'schema_drift',
      'message', 'Schema drift detected',
      'details', jsonb_build_array(jsonb_build_object(
        'path', 'object',
        'code', 'schema_drift',
        'message', drift_object || ': ' || drift_details
      ))
    );
  elsif error_code = 'query_rejected' then
    return jsonb_build_object(
      'code', 'query_rejected', 'message', details, 'details', '[]'::jsonb
    );
  elsif error_code = 'query_timeout' then
    return jsonb_build_object(
      'code', 'query_timeout', 'message', details, 'details', '[]'::jsonb
    );
  elsif error_code = 'unsupported_capability' then
    return jsonb_build_object(
      'code', 'unsupported_capability', 'message', details, 'details', '[]'::jsonb
    );
  elsif error_code = 'authorization_denied' then
    return jsonb_build_object(
      'code', 'authorization_denied',
      'message', 'Tenant scope is not authorized',
      'details', jsonb_build_array(jsonb_build_object(
        'path', 'scope',
        'code', 'tenant_scope_not_bound',
        'message', coalesce(details, 'the authenticated database principal is not bound to the requested tenant')
      ))
    );
  elsif error_code = 'lookup_storage_authority_mismatch' then
    return jsonb_build_object(
      'code', 'lookup_storage_authority_mismatch',
      'message', 'Lookup storage authority mismatch',
      'details', jsonb_build_array(jsonb_build_object(
        'path', 'model_id',
        'code', 'lookup_storage_authority_mismatch',
        'message', details
      ))
    );
  elsif error_code = 'contract_validation_failed'
        or error_sqlstate in ('22007', '22P02', '22023') then
    return jsonb_build_object(
      'code', 'contract_validation_failed',
      'message', 'Contract validation failed',
      'details', jsonb_build_array(jsonb_build_object(
        'path', 'request',
        'code', 'sql_contract_validation_failed',
        'message', coalesce(details, error_message, 'invalid generated SQL request')
      ))
    );
  end if;

  return jsonb_build_object(
    'code', 'database_error',
    'message', 'Database operation failed',
    'details', '[]'::jsonb
  );
end;
$kernel$;

-- artifact: function kernel_read_scope_schema(text,text)
create or replace function kernel_read_scope_schema(request_app_id text, request_customer_id text)
returns jsonb
language plpgsql
stable
security invoker
set search_path from current
as $kernel$
declare
  active_schema jsonb;
begin
  if request_app_id is null or btrim(request_app_id) = ''
     or request_customer_id is null or btrim(request_customer_id) = '' then
    raise exception 'contract_validation_failed: app_id and customer_id are required';
  end if;
  if not kernel_principal_scope_authorized(
    'runtime', request_app_id, request_customer_id, null
  ) then
    raise exception 'authorization_denied: the authenticated database principal is not bound to the requested tenant and runtime capability';
  end if;
  perform set_config('kernel.app_id', request_app_id, true);
  perform set_config('kernel.customer_id', request_customer_id, true);
  select schema
  into active_schema
  from schema_revision
  where app_id = request_app_id
    and customer_id = request_customer_id
    and activated_at is not null;
  if active_schema is null then
    raise exception 'active_schema_missing: %/%', request_app_id, request_customer_id;
  end if;
  return active_schema;
end;
$kernel$;

-- artifact: function kernel_read_custom_fields(jsonb,text,jsonb)
create or replace function kernel_read_custom_fields(
  request_schema jsonb,
  request_model_id text,
  stored_entries jsonb
)
returns jsonb
language sql
stable
security invoker
set search_path from current
as $kernel$
  select coalesce(jsonb_agg(entry.value order by entry.ordinal), '[]'::jsonb)
  from jsonb_array_elements(coalesce(stored_entries, '[]'::jsonb))
       with ordinality as entry(value, ordinal)
  where case
    when coalesce(entry.value->>'type', '') <> 'enum' then true
    else not exists (
      select 1
      from jsonb_array_elements(coalesce(request_schema->'custom_fields', '[]'::jsonb)) definition(value)
      where definition.value->>'model_id' = request_model_id
        and definition.value->>'field_id' = entry.value->>'field_id'
        and coalesce(definition.value->'archived_at', 'null'::jsonb) = 'null'::jsonb
        and definition.value->>'type' = 'enum'
        and not exists (
          select 1
          from jsonb_array_elements(coalesce(definition.value->'option_set', '[]'::jsonb)) option(value)
          where option.value->>'id' = entry.value->>'value'
        )
    )
  end;
$kernel$;

-- artifact: function kernel_read_custom_field_map(jsonb,text,jsonb)
create or replace function kernel_read_custom_field_map(
  schema_json jsonb,
  model_id text,
  entries jsonb
)
returns jsonb
language plpgsql
stable
security invoker
set search_path from current
as $kernel$
declare
  result jsonb;
begin
  select coalesce(jsonb_object_agg(entry.value->>'field_id', entry.value - 'field_id'), '{}'::jsonb)
  into result
  from jsonb_array_elements(kernel_read_custom_fields(schema_json, model_id, entries)) entry(value);
  return result;
end;
$kernel$;

-- artifact: function kernel_read_field_values_expression(text,jsonb,jsonb)
create or replace function kernel_read_field_values_expression(
  row_alias text,
  model jsonb,
  projection jsonb default '[]'::jsonb
)
returns text
language plpgsql
immutable
security invoker
set search_path from current
as $kernel$
declare
  field jsonb;
  field_id text;
  field_type text;
  field_identifier text;
  amount_identifier text;
  currency_identifier text;
  period_identifier text;
  expression text := '''{}''::jsonb';
begin
  if row_alias is null or row_alias !~ '^[a-z][a-z0-9_]*$' then
    raise exception 'contract_validation_failed: invalid SQL row alias `%`', row_alias;
  end if;
  for field in
    select field_value.value
    from jsonb_array_elements(model->'fields') with ordinality field_value(value, ordinal)
    where jsonb_array_length(coalesce(projection, '[]'::jsonb)) = 0
       or field_value.value->>'id' in (
         select jsonb_array_elements_text(projection)
       )
    order by field_value.ordinal
  loop
    field_id := field->>'id';
    field_type := field->>'type';
    field_identifier := kernel_read_physical_identifier(field_id);
    if field_type in ('text', 'iso_country', 'iso_currency') then
      expression := expression || format(
        ' || case when %1$s.%2$I is null then ''{}''::jsonb else jsonb_build_object(%3$L, jsonb_build_object(''type'', ''text'', ''value'', %1$s.%2$I)) end',
        row_alias, field_identifier, field_id
      );
    elsif field_type = 'number' then
      expression := expression || format(
        ' || case when %1$s.%2$I is null then ''{}''::jsonb else jsonb_build_object(%3$L, jsonb_build_object(''type'', ''number'', ''value'', %1$s.%2$I::text)) end',
        row_alias, field_identifier, field_id
      );
    elsif field_type = 'bool' then
      expression := expression || format(
        ' || case when %1$s.%2$I is null then ''{}''::jsonb else jsonb_build_object(%3$L, jsonb_build_object(''type'', ''bool'', ''value'', %1$s.%2$I)) end',
        row_alias, field_identifier, field_id
      );
    elsif field_type = 'date' then
      expression := expression || format(
        ' || case when %1$s.%2$I is null then ''{}''::jsonb else jsonb_build_object(%3$L, jsonb_build_object(''type'', ''date'', ''value'', to_char(%1$s.%2$I, ''YYYY-MM-DD''))) end',
        row_alias, field_identifier, field_id
      );
    elsif field_type = 'datetime' then
      expression := expression || format(
        ' || case when %1$s.%2$I is null then ''{}''::jsonb else jsonb_build_object(%3$L, jsonb_build_object(''type'', ''datetime'', ''value'', regexp_replace(to_char(%1$s.%2$I at time zone ''UTC'', ''YYYY-MM-DD"T"HH24:MI:SS.US"Z"''), ''\.000000Z$'', ''Z''))) end',
        row_alias, field_identifier, field_id
      );
    elsif field_type = 'relation' then
      expression := expression || format(
        ' || case when %1$s.%2$I is null then ''{}''::jsonb else jsonb_build_object(%3$L, jsonb_build_object(''type'', ''relation'', ''value'', jsonb_build_object(''type'', ''record_id'', ''value'', %1$s.%2$I))) end',
        row_alias, field_identifier, field_id
      );
    elsif field_type in ('text_list', 'known_aliases') then
      expression := expression || format(
        ' || case when %1$s.%2$I is null then ''{}''::jsonb else jsonb_build_object(%3$L, jsonb_build_object(''type'', ''text_list'', ''value'', %1$s.%2$I)) end',
        row_alias, field_identifier, field_id
      );
    elsif field_type = 'json' then
      expression := expression || format(
        ' || case when %1$s.%2$I is null then ''{}''::jsonb else jsonb_build_object(%3$L, jsonb_build_object(''type'', ''json'', ''value'', %1$s.%2$I)) end',
        row_alias, field_identifier, field_id
      );
    elsif field_type = 'enum' then
      expression := expression || format(
        ' || case when %1$s.%2$I is null or not exists (select 1 from jsonb_array_elements(%4$L::jsonb) option(value) where option.value->>''id'' = %1$s.%2$I) then ''{}''::jsonb else jsonb_build_object(%3$L, jsonb_build_object(''type'', ''enum'', ''value'', %1$s.%2$I)) end',
        row_alias, field_identifier, field_id, coalesce(field->'option_set', '[]'::jsonb)::text
      );
    elsif field_type = 'money_rate' then
      amount_identifier := kernel_read_physical_identifier(field_id || '_amount');
      currency_identifier := kernel_read_physical_identifier(field_id || '_currency');
      period_identifier := kernel_read_physical_identifier(field_id || '_period');
      expression := expression || format(
        ' || case when %1$s.%2$I is null or %1$s.%3$I is null or %1$s.%4$I is null then ''{}''::jsonb else jsonb_build_object(%5$L, jsonb_build_object(''type'', ''money_rate'', ''value'', jsonb_build_object(''amount'', %1$s.%2$I::text, ''currency'', %1$s.%3$I, ''period'', %1$s.%4$I))) end',
        row_alias, amount_identifier, currency_identifier, period_identifier, field_id
      );
    else
      raise exception 'schema_drift: %|unsupported field type `%`', field_id, field_type;
    end if;
  end loop;
  return expression;
end;
$kernel$;

-- artifact: function kernel_read_lookup_values(jsonb,jsonb,jsonb)
create or replace function kernel_read_lookup_values(model jsonb, stored_values jsonb, projection jsonb)
returns jsonb
language plpgsql
stable
security invoker
set search_path from current
as $kernel$
declare
  field jsonb;
  field_id text;
  typed_value jsonb;
  result jsonb := '{}'::jsonb;
begin
  for field in select value from jsonb_array_elements(coalesce(model->'fields','[]'::jsonb)) item(value) loop
    field_id := field->>'id';
    if jsonb_array_length(coalesce(projection,'[]'::jsonb))>0 and not (projection ? field_id) then continue; end if;
    typed_value := stored_values->field_id;
    if typed_value is null then continue; end if;
    if field->>'type'='enum' and not exists(
      select 1 from jsonb_array_elements(coalesce(field->'option_set','[]'::jsonb)) option(value)
      where value->>'id'=typed_value->>'value'
    ) then continue; end if;
    result := result || jsonb_build_object(field_id,typed_value);
  end loop;
  return result;
end;
$kernel$;

-- artifact: function kernel_read_assert_lookup_storage_authority(text,text,text)
create or replace function kernel_read_assert_lookup_storage_authority(
  requested_app_id text,
  requested_customer_id text,
  requested_model_id text
)
returns void
language plpgsql
volatile
security invoker
set search_path from current
as $kernel$
declare
  authority_error jsonb;
  authority_exists boolean;
  generic_rows_exist boolean;
begin
  authority_error := kernel_lookup_storage_authority_error(
    requested_app_id, requested_customer_id, requested_model_id
  );
  if authority_error is not null then
    raise exception 'lookup_storage_authority_mismatch: %',
      authority_error#>>'{details,0,message}';
  end if;

  select exists(
    select 1
    from lookup_storage_authority authority
    where authority.app_id = requested_app_id
      and authority.customer_id = requested_customer_id
      and authority.model_id = requested_model_id
  ) into authority_exists;
  if authority_exists then
    return;
  end if;

  select exists(
    select 1
    from lookup_record record
    where record.app_id = requested_app_id
      and record.customer_id = requested_customer_id
      and record.model_id = requested_model_id
    union all
    select 1
    from lookup_version version
    where version.app_id = requested_app_id
      and version.customer_id = requested_customer_id
      and version.model_id = requested_model_id
  ) into generic_rows_exist;
  if generic_rows_exist then
    raise exception 'lookup_storage_authority_mismatch: generic lookup storage has rows but no authority is declared for `%/%/%`',
      requested_app_id, requested_customer_id, requested_model_id;
  end if;
end;
$kernel$;

-- artifact: function kernel_read_assert_mainline_order(text,text,text)
create or replace function kernel_read_assert_mainline_order(
  version_table text,
  request_app_id text,
  request_customer_id text
)
returns void
language plpgsql
stable
security invoker
set search_path from current
as $kernel$
declare
  drift record;
  query_sql text;
  status_display text;
  order_display text;
begin
  query_sql := format(
    'select v.id, v.change_set_id, cs.status, cs.applied_order from %I v left join change_set cs on cs.id = v.change_set_id and cs.app_id = v.app_id and cs.customer_id = v.customer_id where v.app_id = $1 and v.customer_id = $2 and v.stage in (''mainline'', ''reverted'') and (cs.id is null or cs.status <> ''mainline'' or cs.applied_order is null) limit 1',
    version_table
  );
  execute query_sql using request_app_id, request_customer_id into drift;
  if drift.id is null then return; end if;
  status_display := case when drift.status is null then 'None' else 'Some("' || drift.status || '")' end;
  order_display := case when drift.applied_order is null then 'None' else 'Some(' || drift.applied_order::text || ')' end;
  raise exception 'schema_drift: %|version `%` is mainline history but owning change_set `%` has status % and applied_order %',
    version_table, drift.id, drift.change_set_id, status_display, order_display;
end;
$kernel$;

-- artifact: function kernel_read_enum_audit_value(jsonb,jsonb,text,text,jsonb,bigint)
create or replace function kernel_read_enum_audit_value(
  request_current_schema jsonb,
  request_event_schema jsonb,
  requested_model_id text,
  requested_field_id text,
  typed_value jsonb,
  event_schema_revision_id bigint
)
returns jsonb
language plpgsql
stable
security invoker
set search_path from current
as $kernel$
declare
  option_id text;
  event_fields jsonb;
  current_fields jsonb;
  event_field jsonb;
  current_field jsonb;
  event_option jsonb;
  current_option jsonb;
begin
  if typed_value is null or typed_value->>'type' <> 'enum' then
    return null;
  end if;
  option_id := typed_value->>'value';
  if option_id is null or btrim(option_id) = '' then
    raise exception 'schema_drift: enum|stored enum value for `%`.`%` has no option identity', requested_model_id, requested_field_id;
  end if;

  select coalesce(jsonb_agg(candidate.definition order by candidate.kind), '[]'::jsonb)
  into event_fields
  from (
    select 'declared' kind, field.value definition
    from jsonb_array_elements(coalesce(request_event_schema->'models', '[]'::jsonb)) model(value)
    cross join lateral jsonb_array_elements(coalesce(model.value->'fields', '[]'::jsonb)) field(value)
    where model.value->>'id' = requested_model_id and field.value->>'id' = requested_field_id
    union all
    select 'custom' kind, definition.value
    from jsonb_array_elements(coalesce(request_event_schema->'custom_fields', '[]'::jsonb)) definition(value)
    where definition.value->>'model_id' = requested_model_id
      and definition.value->>'field_id' = requested_field_id
  ) candidate;
  if jsonb_array_length(event_fields) <> 1 or event_fields->0->>'type' <> 'enum' then
    raise exception 'schema_drift: enum|enum field `%`.`%` is not declared in pinned schema revision `%`', requested_model_id, requested_field_id, event_schema_revision_id;
  end if;
  event_field := event_fields->0;
  select option.value into event_option
  from jsonb_array_elements(coalesce(event_field->'option_set', '[]'::jsonb)) option(value)
  where option.value->>'id' = option_id;
  if event_option is null then
    raise exception 'schema_drift: enum|enum option `%` is not declared for `%`.`%` in pinned schema revision `%`', option_id, requested_model_id, requested_field_id, event_schema_revision_id;
  end if;

  select coalesce(jsonb_agg(candidate.definition order by candidate.kind), '[]'::jsonb)
  into current_fields
  from (
    select 'declared' kind, field.value definition
    from jsonb_array_elements(coalesce(request_current_schema->'models', '[]'::jsonb)) model(value)
    cross join lateral jsonb_array_elements(coalesce(model.value->'fields', '[]'::jsonb)) field(value)
    where model.value->>'id' = requested_model_id and field.value->>'id' = requested_field_id
    union all
    select 'custom' kind, definition.value
    from jsonb_array_elements(coalesce(request_current_schema->'custom_fields', '[]'::jsonb)) definition(value)
    where definition.value->>'model_id' = requested_model_id
      and definition.value->>'field_id' = requested_field_id
  ) candidate;
  if jsonb_array_length(current_fields) > 1 then
    raise exception 'schema_drift: enum|active schema declares `%`.`%` more than once', requested_model_id, requested_field_id;
  end if;
  current_field := case when jsonb_array_length(current_fields) = 1
    and current_fields->0->>'type' = 'enum' then current_fields->0 else null end;
  if current_field is not null then
    select option.value into current_option
    from jsonb_array_elements(coalesce(current_field->'option_set', '[]'::jsonb)) option(value)
    where option.value->>'id' = option_id;
  end if;

  return jsonb_build_object(
    'option_id', option_id,
    'event_schema_revision_id', event_schema_revision_id,
    'current_label', current_option->>'label',
    'event_label', event_option->>'label'
  );
end;
$kernel$;

-- artifact: function kernel_read_visible_records_core(jsonb,boolean)
create or replace function kernel_read_visible_records_core(request jsonb, lock_record boolean)
returns jsonb
language plpgsql
volatile
security invoker
set search_path from current
as $kernel$
declare
  request_app_id text;
  request_customer_id text;
  request_model_id text;
  request_as_of date;
  request_projection jsonb := coalesce(request->'fields', '[]'::jsonb);
  request_record_ids jsonb := coalesce(request->'record_ids', '[]'::jsonb);
  request_text_filters jsonb := coalesce(request->'field_filters', '{}'::jsonb);
  request_limit bigint;
  schema_json jsonb;
  model_json jsonb;
  model_identifier text;
  record_table text;
  version_table text;
  values_expression text;
  record_filter_sql text := '';
  text_filter_sql text := '';
  field_filter record;
  field_json jsonb;
  field_identifier text;
  query_sql text;
  result_json jsonb;
begin
  if request is null or jsonb_typeof(request) <> 'object' then
    raise exception 'contract_validation_failed: request must be a JSON object';
  end if;
  request_app_id := request->>'app_id';
  request_customer_id := request->>'customer_id';
  request_model_id := request->>'model_id';
  if request_model_id is null or btrim(request_model_id) = '' or request->>'as_of' is null then
    raise exception 'contract_validation_failed: model_id and as_of are required';
  end if;
  request_as_of := (request->>'as_of')::date;
  if request ? 'limit' and request->'limit' <> 'null'::jsonb then
    if jsonb_typeof(request->'limit') <> 'number'
       or request->>'limit' !~ '^[0-9]+$'
       or (request->>'limit')::numeric > 9223372036854775807
       or (request->>'limit')::numeric < 1 then
      raise exception 'contract_validation_failed: limit must be a positive integer';
    end if;
    request_limit := (request->>'limit')::bigint;
  end if;
  if jsonb_typeof(request_projection) <> 'array'
     or jsonb_typeof(request_record_ids) <> 'array'
     or jsonb_typeof(request_text_filters) <> 'object' then
    raise exception 'contract_validation_failed: fields and record_ids must be arrays and field_filters must be an object';
  end if;
  schema_json := kernel_read_scope_schema(request_app_id, request_customer_id);
  select model.value
  into model_json
  from jsonb_array_elements(schema_json->'models') model(value)
  where model.value->>'id' = request_model_id;
  if model_json is null then
    raise exception 'record_target_missing: model `%` is not declared in active schema', request_model_id;
  end if;
  if exists (
    select 1 from jsonb_array_elements_text(request_projection) projected(field_id)
    where not exists (
      select 1 from jsonb_array_elements(model_json->'fields') field(value)
      where field.value->>'id' = projected.field_id
    )
  ) then
    select projected.field_id into field_identifier
    from jsonb_array_elements_text(request_projection) projected(field_id)
    where not exists (
      select 1 from jsonb_array_elements(model_json->'fields') field(value)
      where field.value->>'id' = projected.field_id
    ) limit 1;
    raise exception 'record_target_missing: field `%` is not declared on model `%`', field_identifier, request_model_id;
  end if;
  if model_json->>'kind'='lookup' then
    perform kernel_read_assert_lookup_storage_authority(
      request_app_id, request_customer_id, request_model_id
    );
    record_table := 'lookup_record';
    version_table := 'lookup_version';
  else
    model_identifier := kernel_read_physical_identifier(request_model_id);
    record_table := kernel_read_physical_identifier(request_model_id || '_record');
    version_table := kernel_read_physical_identifier(request_model_id || '_version');
  end if;
  perform kernel_read_assert_mainline_order(version_table, request_app_id, request_customer_id);
  if jsonb_array_length(request_record_ids) > 0 then
    record_filter_sql := ' and r.id in (select value::uuid from jsonb_array_elements_text($4))';
  end if;
  for field_filter in select key, value #>> '{}' as value from jsonb_each(request_text_filters) loop
    select field.value into field_json
    from jsonb_array_elements(model_json->'fields') field(value)
    where field.value->>'id' = field_filter.key;
    if field_json is null then
      raise exception 'record_target_missing: field `%` is not declared on model `%`', field_filter.key, request_model_id;
    end if;
    if field_json->>'type' not in ('text', 'iso_country', 'iso_currency') then
      raise exception 'record_target_missing: field `%` on model `%` is not a text field', field_filter.key, request_model_id;
    end if;
    if model_json->>'kind'='lookup' then
      text_filter_sql := text_filter_sql || format(
        ' and v.values->%L->>''value'' = %L', field_filter.key, field_filter.value
      );
    else
      field_identifier := kernel_read_physical_identifier(field_filter.key);
      text_filter_sql := text_filter_sql || format(
        ' and v.%I = %L', field_identifier, field_filter.value
      );
    end if;
  end loop;
  if model_json->>'kind'='lookup' then
    query_sql := format(
      $query$
      select coalesce(jsonb_agg(visible.row_json order by visible.external_key nulls last,visible.record_id),'[]'::jsonb)
      from (
        select r.external_key,r.id record_id,jsonb_build_object(
          'record_id',r.id,'version_id',v.id,'external_key',r.external_key,
          'effective_start',to_char(v.effective_start,'YYYY-MM-DD'),
          'effective_end',case when v.effective_end is null then null else to_char(v.effective_end,'YYYY-MM-DD') end,
          'values',kernel_read_lookup_values($5,v.values,$7),
          'custom_fields',kernel_read_custom_fields($8,$3,v.custom_fields),
          'metadata',v.metadata,
          'many_relations',v.many_relations,
          'availability',v.availability
        ) row_json
        from lookup_record r
        join lateral (
          select v.* from lookup_version v join change_set cs
            on cs.id=v.change_set_id and cs.app_id=v.app_id and cs.customer_id=v.customer_id
           and cs.status='mainline' and cs.applied_order is not null
          where v.app_id=r.app_id and v.customer_id=r.customer_id and v.model_id=r.model_id
            and v.record_id=r.id and v.stage='mainline' and v.effective_start<=$6
            and (v.effective_end is null or v.effective_end>=$6)
          order by v.effective_start desc,v.tombstones_record desc,v.untombstones_record desc,
            cs.applied_order desc,v.id desc limit 1
        ) v on true
        where r.app_id=$1 and r.customer_id=$2 and r.model_id=$3%s%s
          and not v.tombstones_record and not v.untombstones_record
        order by r.external_key nulls last,r.id limit $9 %s
      ) visible
      $query$,
      record_filter_sql,text_filter_sql,case when lock_record then 'for update of r' else '' end
    );
    execute query_sql using request_app_id,request_customer_id,request_model_id,request_record_ids,
      model_json,request_as_of,request_projection,schema_json,request_limit into result_json;
    return coalesce(result_json,'[]'::jsonb);
  end if;
  values_expression := kernel_read_field_values_expression('v', model_json, request_projection);
  query_sql := format(
    $query$
    select coalesce(jsonb_agg(visible.row_json order by visible.external_key nulls last, visible.record_id), '[]'::jsonb)
    from (
      select r.external_key, r.id as record_id,
        jsonb_build_object(
          'record_id', r.id,
          'version_id', v.id,
          'external_key', r.external_key,
          'effective_start', to_char(v.effective_start, 'YYYY-MM-DD'),
          'effective_end', case when v.effective_end is null then null else to_char(v.effective_end, 'YYYY-MM-DD') end,
          'values', (%s),
          'custom_fields', kernel_read_custom_fields($5, $3, v.custom_fields),
          'metadata', coalesce(v.metadata, '{}'::jsonb)
        ) as row_json
      from %I r
      join lateral (
        select v.*
        from %I v
        join change_set cs
          on cs.id = v.change_set_id
         and cs.app_id = v.app_id
         and cs.customer_id = v.customer_id
         and cs.status = 'mainline'
         and cs.applied_order is not null
        where v.record_id = r.id
          and v.app_id = r.app_id
          and v.customer_id = r.customer_id
          and v.stage = 'mainline'
          and v.effective_start <= $6
          and (v.effective_end is null or v.effective_end >= $6)
        order by
          v.effective_start desc,
          v.tombstones_record desc,
          v.untombstones_record desc,
          cs.applied_order desc,
          v.id desc
        limit 1
      ) v on true
      where r.app_id = $1
        and r.customer_id = $2
        %s
        %s
        and not v.tombstones_record
        and not v.untombstones_record
      order by r.external_key nulls last, r.id
      limit $7
      %s
    ) visible
    $query$,
    values_expression,
    record_table,
    version_table,
    record_filter_sql,
    text_filter_sql,
    case when lock_record then 'for update of r' else '' end
  );
  execute query_sql
    using request_app_id, request_customer_id, request_model_id, request_record_ids, schema_json, request_as_of, request_limit
    into result_json;
  return coalesce(result_json, '[]'::jsonb);
end;
$kernel$;

-- artifact: function kernel_read_aggregate_bin(numeric,jsonb)
-- Edges are validated once by kernel_data_query. Keep exact numeric arithmetic;
-- the final interval is closed, and overflow values are represented explicitly.
create or replace function kernel_read_aggregate_bin(amount numeric, edges jsonb)
returns jsonb language plpgsql immutable security invoker set search_path from current
as $kernel$
declare
  i integer;
  last_edge integer := jsonb_array_length(edges)-1;
begin
  if amount is null then return null; end if;
  if amount < (edges->>0)::numeric then return '"below"'::jsonb; end if;
  if amount > (edges->>last_edge)::numeric then return '"above"'::jsonb; end if;
  for i in 0..last_edge-1 loop
    if amount < (edges->>(i+1))::numeric or i=last_edge-1 then
      return jsonb_build_object('from',edges->i,'to',edges->(i+1));
    end if;
  end loop;
  return null;
end;
$kernel$;

-- artifact: function kernel_read_aggregate_percentile(numeric[],numeric)
-- Continuous percentile with numeric interpolation, without converting decimal
-- amounts to float8. Input is sorted and null-free by the calling aggregate.
create or replace function kernel_read_aggregate_percentile(amounts numeric[], p numeric)
returns numeric language plpgsql immutable security invoker set search_path from current
as $kernel$
declare
  rank_position numeric;
  lower_index integer;
begin
  if coalesce(cardinality(amounts),0)=0 then return null; end if;
  rank_position := 1 + (cardinality(amounts)-1)*p;
  lower_index := floor(rank_position)::integer;
  if lower_index=cardinality(amounts) then return amounts[lower_index]; end if;
  return amounts[lower_index] + (amounts[lower_index+1]-amounts[lower_index])*(rank_position-lower_index);
end;
$kernel$;

-- artifact: function kernel_data_query_core(jsonb,jsonb,boolean)
create or replace function kernel_data_query_core(request jsonb, work_state jsonb, work_rule_scan boolean)
returns jsonb
language plpgsql
volatile
security invoker
set search_path from current
as $kernel$
declare
  schema_json jsonb;
  work_fork jsonb;
  model_json jsonb;
  query_fields jsonb;
  select_fields jsonb;
  source_sql text;
  record_table text;
  version_table text;
  values_expression text;
  lookup_filter text := '';
  request_date date;
  filter jsonb;
  filter_index integer := -1;
  ordering jsonb;
  field_json jsonb;
  field_id text;
  expression text;
  predicate text := 'true';
  ordering_sql text := '';
  group_expression text := 'jsonb_build_array()';
  grouping jsonb;
  metric jsonb;
  aggregate_groups jsonb;
  aggregate_metrics jsonb;
  money_fields jsonb := '[]'::jsonb;
  metric_sql text := '';
  units_sql text := '';
  header_unit_sql text;
  group_order_sql text := '';
  total_metric_sql text := '';
  metric_expression text;
  total_metric_expression text;
  value_expression text;
  unit_expression text;
  eligible_predicate text := 'true';
  edge jsonb;
  previous_edge numeric;
  money_bins boolean := false;
  grouping_index integer := -1;
  metric_index integer := -1;
  query_sql text;
  result jsonb;
  select_ids jsonb;
  authorization_policy jsonb;
  authorization_grants jsonb;
  authorization_fields jsonb;
  response_expression text := 'r';
  page_size integer;
  page_offset integer;
  op text;
  field_type text;
  relation_source jsonb;
  relation_json jsonb;
  source_model_json jsonb;
  source_record_id uuid;
  source_record_table text;
  source_version_table text;
  source_values_expression text;
  source_lookup_filter text := '';
  source_navigation_sql text;
  source_navigation_allowed boolean;
  relation_through text;
  relation_predicate text := 'true';
  search_query text;
  search_fields jsonb;
  search_grade text;
  retired_filter text := '';
  record_filter text := '';
  derived_environment jsonb;
  derived_entries_sql text := '';
  requested_fields jsonb;
begin
  if request is null or jsonb_typeof(request) <> 'object'
    or octet_length(request::text)>1048576
    or jsonb_typeof(coalesce(request->'where','[]'::jsonb)) <> 'array'
    or jsonb_array_length(coalesce(request->'where','[]'::jsonb)) > 20
    or jsonb_typeof(coalesce(request->'order_by','[]'::jsonb)) <> 'array'
    or jsonb_array_length(coalesce(request->'order_by','[]'::jsonb)) > 5
    or coalesce(request->>'kind','list') not in ('list','aggregate')
    or (request ? 'exclude_retired' and jsonb_typeof(request->'exclude_retired') <> 'boolean') then
    raise exception 'contract_validation_failed: invalid bounded data query';
  end if;
  if (request ? 'limit' and request->'limit' <> 'null'::jsonb and (jsonb_typeof(request->'limit') <> 'number' or request->>'limit' !~ '^[0-9]+$'))
    or (request ? 'offset' and request->'offset' <> 'null'::jsonb and (jsonb_typeof(request->'offset') <> 'number' or request->>'offset' !~ '^[0-9]+$'))
    or (request ? 'limit' and request->'limit' <> 'null'::jsonb and (request->>'limit')::numeric not between 1 and 100)
    or (request ? 'offset' and request->'offset' <> 'null'::jsonb and (request->>'offset')::numeric not between 0 and 10000) then
    raise exception 'contract_validation_failed: invalid bounded data query';
  end if;
  page_size := coalesce((request->>'limit')::integer, 50);
  page_offset := coalesce((request->>'offset')::integer, 0);
  if request->>'as_of' is null then raise exception 'contract_validation_failed: as_of is required'; end if;
  request_date := (request->>'as_of')::date;
  schema_json := kernel_read_scope_schema(request->>'app_id',request->>'customer_id');
  if request->>'schema_version' is distinct from schema_json->>'version' then raise exception 'schema_drift: generated operation schema version is stale'; end if;
  select value into model_json from jsonb_array_elements(schema_json->'models') where value->>'id'=request->>'model_id';
  if model_json is null then raise exception 'record_target_missing: unknown model'; end if;
  if request ? 'relation_source' then
    relation_source := request->'relation_source';
    if jsonb_typeof(relation_source) <> 'object'
      or relation_source - array['model_id','relation_id','record_id'] <> '{}'::jsonb
      or not (relation_source ?& array['model_id','relation_id','record_id'])
      or exists (
        select 1 from jsonb_each(relation_source) item(key,value)
        where jsonb_typeof(item.value) <> 'string' or item.value = '""'::jsonb
      ) then
      raise exception 'contract_validation_failed: invalid relation source';
    end if;
    begin
      source_record_id := (relation_source->>'record_id')::uuid;
    exception when invalid_text_representation then
      raise exception 'contract_validation_failed: relation source record id must be a canonical UUID';
    end;
    if source_record_id::text is distinct from relation_source->>'record_id' then
      raise exception 'contract_validation_failed: relation source record id must be a canonical UUID';
    end if;
  end if;
  if request ? 'work' then
    if jsonb_typeof(request->'work') is distinct from 'object'
      or (request->'work') - array['session_id','fork_id'] <> '{}'::jsonb
      or not ((request->'work') ?& array['session_id','fork_id']) then
      raise exception 'contract_validation_failed: invalid work reference';
    end if;
    if work_state is null then
      work_state := kernel_work_state(request || jsonb_build_object('session_id',request#>>'{work,session_id}'));
    end if;
    if work_state->>'as_of' is distinct from request->>'as_of' then
      raise exception 'contract_validation_failed: work query must use the fixed session as_of';
    end if;
    work_fork := work_state->'forks'->(request#>>'{work,fork_id}');
    if work_fork is null then raise exception 'record_target_missing: unknown work fork'; end if;
  elsif work_rule_scan then
    raise exception 'contract_validation_failed: rule evaluation requires work';
  end if;
  -- Derived custom fields are read-only custom fields whose values are
  -- evaluated from their expression over each authorized read image.
  derived_environment := kernel_derived_environment(schema_json,request->>'model_id');
  query_fields := (model_json->'fields') || coalesce((select jsonb_agg(value || jsonb_build_object('id',value->>'field_id','custom',true)) from jsonb_array_elements(coalesce(schema_json->'custom_fields','[]'::jsonb)) where value->>'model_id'=request->>'model_id' and coalesce(value->'archived_at','null'::jsonb)='null'::jsonb and coalesce(value->>'lifecycle','active')='active'),'[]'::jsonb);
  select_fields := query_fields || coalesce(model_json->'many_relations','[]'::jsonb);
  if request ? 'select' then
    if request->>'kind' = 'aggregate' then
      raise exception 'contract_validation_failed: select is not supported for aggregate';
    end if;
    if jsonb_typeof(request->'select') <> 'array' or jsonb_array_length(request->'select') = 0
      or exists (select 1 from jsonb_array_elements(request->'select') value where jsonb_typeof(value) <> 'string')
      or exists (select 1 from jsonb_array_elements_text(request->'select') value group by value having count(*) > 1) then
      raise exception 'contract_validation_failed: invalid select';
    end if;
    select_ids := request->'select';
    for field_id in select value from jsonb_array_elements_text(select_ids) loop
      if field_id not in ('$id','$externalKey','$version')
        and not exists (select 1 from jsonb_array_elements(select_fields) value where value->>'id'=field_id) then
        raise exception 'contract_validation_failed: unsupported select field';
      end if;
    end loop;
    response_expression := format(
      '(case when %1$L::jsonb ? ''$id'' then jsonb_build_object(''record_id'',r->''record_id'') else ''{}''::jsonb end || case when %1$L::jsonb ? ''$version'' then jsonb_build_object(''version_id'',r->''version_id'') else ''{}''::jsonb end || case when %1$L::jsonb ? ''$externalKey'' then jsonb_build_object(''external_key'',r->''external_key'') else ''{}''::jsonb end || case when exists (select 1 from jsonb_each(r->''values'') where %1$L::jsonb ? key) then jsonb_build_object(''values'',(select jsonb_object_agg(key,value) from jsonb_each(r->''values'') where %1$L::jsonb ? key)) else ''{}''::jsonb end || case when exists (select 1 from jsonb_array_elements(r->''custom_fields'') where %1$L::jsonb ? (value->>''field_id'')) then jsonb_build_object(''custom_fields'',(select jsonb_agg(value) from jsonb_array_elements(r->''custom_fields'') where %1$L::jsonb ? (value->>''field_id''))) else ''{}''::jsonb end || case when exists (select 1 from jsonb_each(r->''many_relations'') where %1$L::jsonb ? key) then jsonb_build_object(''many_relations'',(select jsonb_object_agg(key,value) from jsonb_each(r->''many_relations'') where %1$L::jsonb ? key)) else ''{}''::jsonb end)',
      select_ids::text
    );
  end if;
  if request->>'kind' = 'aggregate' then
    aggregate_groups := coalesce(request->'group_by','[]'::jsonb);
    aggregate_metrics := request->'metrics';
    if jsonb_typeof(aggregate_groups) is distinct from 'array'
      or jsonb_array_length(aggregate_groups)>2
      or jsonb_typeof(aggregate_metrics) is distinct from 'array'
      or jsonb_array_length(aggregate_metrics) not between 1 and 8
      or request ?| array['limit','offset','order_by'] then
      raise exception 'contract_validation_failed: invalid aggregate query';
    end if;
    for grouping in select value from jsonb_array_elements(aggregate_groups) loop
      grouping_index := grouping_index + 1;
      field_id := case when jsonb_typeof(grouping)='string' then grouping #>> '{}' else grouping->>'field' end;
      select value into field_json from jsonb_array_elements(query_fields) where value->>'id'=field_id;
      field_type := field_json->>'type';
      if field_json is null then raise exception 'contract_validation_failed: unsupported group field'; end if;
      value_expression := case when field_json->>'custom'='true'
        then format('(kernel_read_custom_field_map($4,$3,r->''custom_fields'')->%L->''value'')',field_id)
        else format('(r->''values''->%L->''value'')',field_id) end;
      if jsonb_typeof(grouping)='object' then
        if grouping - array['field','bins','unit'] <> '{}'::jsonb
          or not (grouping ?& array['field','bins'])
          or jsonb_typeof(grouping->'field') is distinct from 'string'
          or field_type not in ('number','money_rate')
          or jsonb_typeof(grouping->'bins') is distinct from 'object'
          or (grouping->'bins') - array['edges'] <> '{}'::jsonb
          or jsonb_typeof(grouping#>'{bins,edges}') is distinct from 'array'
          or jsonb_array_length(grouping#>'{bins,edges}') not between 2 and 51 then
          raise exception 'contract_validation_failed: invalid aggregate bins';
        end if;
        previous_edge := null;
        for edge in select value from jsonb_array_elements(grouping#>'{bins,edges}') loop
          if jsonb_typeof(edge)<>'string' or (edge #>> '{}') !~ '^-?[0-9]+([.][0-9]+)?$' then
            raise exception 'contract_validation_failed: bin edges must be decimal strings';
          end if;
          if previous_edge is not null and (edge #>> '{}')::numeric <= previous_edge then
            raise exception 'contract_validation_failed: bin edges must ascend';
          end if;
          previous_edge := (edge #>> '{}')::numeric;
        end loop;
        if field_type='money_rate' then
          if jsonb_typeof(grouping->'unit') is distinct from 'object'
            or (grouping->'unit') - array['currency','period'] <> '{}'::jsonb
            or not (grouping->'unit' ?& array['currency','period'])
            or jsonb_typeof(grouping#>'{unit,currency}') is distinct from 'string'
            or jsonb_typeof(grouping#>'{unit,period}') is distinct from 'string'
            or grouping#>>'{unit,currency}' !~ '^[A-Z]{3}$'
            or grouping#>>'{unit,period}' not in ('hourly','daily','weekly','monthly','annual') then
            raise exception 'contract_validation_failed: money bins require a unit';
          end if;
          money_bins := true;
          unit_expression := format('case when %1$s is null then null else %1$s - ''amount'' end',value_expression);
          eligible_predicate := eligible_predicate || format(' and (%s is null or %s = $11->''group_by''->%s->''unit'')',value_expression,unit_expression,grouping_index);
          value_expression := format('(%s->>''amount'')::numeric',value_expression);
        else
          if grouping ? 'unit' then raise exception 'contract_validation_failed: number bins do not take a unit'; end if;
          value_expression := format('(%s#>>''{}'')::numeric',value_expression);
        end if;
        expression := format('kernel_read_aggregate_bin(%s,$11->''group_by''->%s->''bins''->''edges'')',value_expression,grouping_index);
      elsif jsonb_typeof(grouping)='string' and field_type in ('text','enum','bool','date','iso_country','iso_currency','relation','number') then
        expression := case
          when field_type='relation' then format('%s->''value''',value_expression)
          when field_type='number' then format('to_jsonb(trim_scale((%s#>>''{}'')::numeric)::text)',value_expression)
          else value_expression end;
      else
        raise exception 'contract_validation_failed: unsupported group field';
      end if;
      if group_order_sql <> '' then group_order_sql := group_order_sql || ','; end if;
      if jsonb_typeof(grouping)='object' then
        group_order_sql := group_order_sql || format('case when key->%1$s = ''"below"''::jsonb then 0 when jsonb_typeof(key->%1$s)=''object'' then 1 when key->%1$s = ''"above"''::jsonb then 2 else 3 end,(key->%1$s->>''from'')::numeric',grouping_index);
      elsif field_type='enum' then
        group_order_sql := group_order_sql || format('(select ordinal from jsonb_array_elements(%L::jsonb) with ordinality as options(option,ordinal) where option->>''id''=key->>%s) nulls last',field_json->'option_set',grouping_index);
      else
        group_order_sql := group_order_sql || format('(key->>%s)%s nulls last',grouping_index,case field_type when 'number' then '::numeric' when 'date' then '::date' when 'bool' then '::boolean' else '' end);
      end if;
      group_expression := group_expression || format(' || jsonb_build_array(%s)',expression);
    end loop;
    for metric in select value from jsonb_array_elements(aggregate_metrics) loop
      metric_index := metric_index + 1;
      op := metric->>'fn';
      header_unit_sql := 'null::jsonb';
      if jsonb_typeof(metric) is distinct from 'object'
        or metric - array['fn','field','p'] <> '{}'::jsonb
        or op is null or op not in ('count','count_distinct','sum','avg','min','max','median','percentile') then
        raise exception 'contract_validation_failed: unsupported aggregate metric';
      end if;
      if op='count' then
        if metric ?| array['field','p'] then raise exception 'contract_validation_failed: count takes no field'; end if;
        metric_expression := 'count(*)::text'; total_metric_expression := metric_expression;
      else
        field_id := metric->>'field';
        select value into field_json from jsonb_array_elements(query_fields) where value->>'id'=field_id;
        field_type := field_json->>'type';
        if jsonb_typeof(metric->'field') is distinct from 'string' or field_json is null or field_type not in ('number','money_rate') then
          raise exception 'contract_validation_failed: metric requires a number or money-rate field';
        end if;
        if op='percentile' then
          if jsonb_typeof(metric->'p') is distinct from 'number' or (metric->>'p')::numeric not between 0 and 1 then
            raise exception 'contract_validation_failed: percentile requires p between zero and one';
          end if;
        elsif metric ? 'p' then raise exception 'contract_validation_failed: only percentile takes p'; end if;
        value_expression := case when field_json->>'custom'='true'
          then format('(kernel_read_custom_field_map($4,$3,r->''custom_fields'')->%L->''value'')',field_id)
          else format('(r->''values''->%L->''value'')',field_id) end;
        if field_type='money_rate' then
          unit_expression := format('case when %1$s is null then null else %1$s - ''amount'' end',value_expression);
          if not money_fields ? field_id then
            money_fields := money_fields || jsonb_build_array(field_id);
            group_expression := group_expression || format(' || jsonb_build_array(jsonb_build_object(''unit'',%s))',unit_expression);
          end if;
          value_expression := format('(%s->>''amount'')::numeric',value_expression);
        else value_expression := format('(%s#>>''{}'')::numeric',value_expression); end if;
        metric_expression := case
          when op='count_distinct' then format('count(distinct %s)::text',value_expression)
          when op in ('median','percentile') then format('kernel_read_aggregate_percentile(array_agg(%1$s order by %1$s) filter (where %1$s is not null),%2$s)::text',value_expression,case when op='median' then '0.5::numeric' else format('($11->''metrics''->%s->>''p'')::numeric',metric_index) end)
          else format('%s(%s)::text',op,value_expression) end;
        total_metric_expression := metric_expression;
        if field_type='money_rate' then
          header_unit_sql := format('case when count(distinct %1$s)=1 then min((%1$s)::text)::jsonb else null end',unit_expression);
          total_metric_expression := format('case when count(distinct %s) <= 1 then %s else null end',unit_expression,metric_expression);
        end if;
      end if;
      units_sql := units_sql || case when units_sql='' then '' else ',' end || header_unit_sql;
      metric_sql := metric_sql || case when metric_sql='' then '' else ',' end || metric_expression;
      total_metric_sql := total_metric_sql || case when total_metric_sql='' then '' else ',' end || total_metric_expression;
    end loop;
  elsif request ?| array['group_by','metrics'] then
    raise exception 'contract_validation_failed: grouping and metrics require aggregate';
  end if;
  for filter in select value from jsonb_array_elements(coalesce(request->'where','[]'::jsonb)) loop
    filter_index := filter_index + 1;
    field_id := filter->>'field';
    op := filter->>'op';
    select value into field_json from jsonb_array_elements(query_fields) where value->>'id'=field_id;
    if field_id in ('$id','$externalKey') then
      expression := format('r->>%L',case when field_id='$id' then 'record_id' else 'external_key' end);
      field_type := 'text';
    elsif field_json is not null and field_json->>'type' in ('text','number','bool','date','datetime','enum','iso_country','iso_currency','relation') then
      field_type := field_json->>'type';
      expression := case when field_json->>'custom'='true' then format('(kernel_read_custom_field_map($4,$3,r->''custom_fields'')->%L%s)',field_id,case when field_type='relation' then '->''value''->>''value''' else '->>''value''' end) when field_type='relation' then format('r->''values''->%L->''value''->>''value''',field_id)
        else format('r->''values''->%L->>''value''',field_id) end;
    else raise exception 'contract_validation_failed: unsupported query field'; end if;
    if op='isNull' then
      predicate := predicate || format(' and (%s) is null',expression);
    elsif op='contains' and field_type='text' and jsonb_typeof(filter->'value')='string' then
      predicate := predicate || format(' and strpos((%s),($11->''where''->%s->>''value''))>0',expression,filter_index);
    elsif op in ('eq','ne','lt','lte','gt','gte') and jsonb_typeof(filter->'value') in ('string','boolean') then
      if field_type='bool' and op not in ('eq','ne') then raise exception 'contract_validation_failed: bool supports equality only'; end if;
      predicate := predicate || format(' and (%s)::%s %s ($11->''where''->%s->>''value'')::%s',expression,
        case field_type when 'number' then 'numeric' when 'date' then 'date' when 'datetime' then 'timestamptz' when 'bool' then 'boolean' else 'text' end,
        case op when 'eq' then '=' when 'ne' then '<>' when 'lt' then '<' when 'lte' then '<=' when 'gt' then '>' else '>=' end,
        filter_index,case field_type when 'number' then 'numeric' when 'date' then 'date' when 'datetime' then 'timestamptz' when 'bool' then 'boolean' else 'text' end);
    else raise exception 'contract_validation_failed: unsupported query operator or value'; end if;
    -- Immutable IDs can be restricted before temporal selection and overlay.
    -- Keep the public text predicate too: noncanonical UUID spellings still do not match.
    if field_id='$id' and op='eq' and jsonb_typeof(filter->'value')='string' then
      if filter->>'value' ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
        record_filter:=record_filter||format(' and r.id=($11->''where''->%s->>''value'')::uuid',filter_index);
      else record_filter:=record_filter||' and false'; end if;
    end if;
  end loop;
  -- Search: records whose declared text, list-of-text or alias fields match
  -- the query (see kernel_search_grade), best grade first.
  if request ? 'search' then
    -- A query must be a JSON string of at most 200 characters; anything else
    -- leaves search_query null and is rejected below.
    if jsonb_typeof(request->'search'->'query') = 'string'
      and char_length(request->'search'->>'query') <= 200
    then
      search_query := kernel_search_normalize(request->'search'->>'query');
    end if;
    search_fields := request->'search'->'fields';
    if jsonb_typeof(request->'search') <> 'object'
      or (request->'search') - array['query','fields'] <> '{}'::jsonb
      or search_query is null
      or jsonb_typeof(search_fields) is distinct from 'array'
      or jsonb_array_length(search_fields) not between 1 and 10
      or exists (
        select 1 from jsonb_array_elements(search_fields) item(value)
        where jsonb_typeof(item.value) <> 'string'
          or not exists (
            select 1 from jsonb_array_elements(model_json->'fields') field(value)
            where field.value->>'id' = item.value #>> '{}'
              and field.value->>'type' in ('text','text_list','known_aliases')
          )
      ) then
      raise exception 'contract_validation_failed: invalid search';
    end if;
    search_grade := 'kernel_search_record_grade($12,r->''values'',$11->''search''->''fields'')';
    predicate := predicate || format(' and %s is not null',search_grade);
    ordering_sql := search_grade || ' asc,';
  end if;
  if coalesce((request->>'exclude_retired')::boolean,false) and model_json->>'kind'='lookup' then
    retired_filter := ' and v.availability=''active''';
  end if;
  for ordering in select value from jsonb_array_elements(coalesce(request->'order_by','[]'::jsonb)) loop
    field_id := ordering->>'field';
    select value into field_json from jsonb_array_elements(query_fields) where value->>'id'=field_id;
    if field_id in ('$id','$externalKey') then
      expression := format('r->>%L',case when field_id='$id' then 'record_id' else 'external_key' end);
    elsif field_json->>'type' in ('text','number','bool','date','datetime','enum','iso_country','iso_currency') then
      expression := case when field_json->>'custom'='true' then format('(kernel_read_custom_field_map($4,$3,r->''custom_fields'')->%L->>''value'')',field_id) else format('(r->''values''->%L->>''value'')',field_id) end;
      expression := format('(%s)::%s',expression,
        case field_json->>'type' when 'number' then 'numeric' when 'datetime' then 'timestamptz' else 'text' end);
    else raise exception 'contract_validation_failed: unsupported order field'; end if;
    if ordering->>'direction' not in ('asc','desc') then raise exception 'contract_validation_failed: unsupported direction'; end if;
    ordering_sql := ordering_sql || expression || ' ' || (ordering->>'direction') || ' nulls last,';
  end loop;
  ordering_sql := ordering_sql || 'r->>''record_id'' asc';
  -- Query canonical row versions directly. Filtering, aggregates and pagination
  -- execute before JSON aggregation; no full collection crosses the transport.
  if model_json->>'kind'='lookup' then
    perform kernel_read_assert_lookup_storage_authority(request->>'app_id',request->>'customer_id',request->>'model_id');
    record_table := 'lookup_record'; version_table := 'lookup_version';
    lookup_filter := ' and r.model_id=$3 and v.model_id=r.model_id';
    values_expression := format('kernel_read_lookup_values(%L::jsonb,v.values,''[]''::jsonb)',model_json::text);
  else
    record_table := kernel_read_physical_identifier((request->>'model_id') || '_record');
    version_table := kernel_read_physical_identifier((request->>'model_id') || '_version');
    values_expression := kernel_read_field_values_expression('v',model_json,'[]'::jsonb);
  end if;
  perform kernel_read_assert_mainline_order(version_table,request->>'app_id',request->>'customer_id');
  if request->>'kind' = 'aggregate' then
    authorization_fields := '[]'::jsonb;
  elsif request ? 'select' then
    authorization_fields := select_ids;
  else
    authorization_fields := coalesce((
      select jsonb_agg(value->>'id' order by value->>'id')
      from jsonb_array_elements(select_fields) item(value)
    ),'[]'::jsonb) || jsonb_build_array('$id','$externalKey','$version','$effectiveStart','$effectiveEnd','$metadata');
  end if;
  for filter in select value from jsonb_array_elements(coalesce(request->'where','[]'::jsonb)) loop
    authorization_fields := authorization_fields || jsonb_build_array(filter->>'field');
  end loop;
  for ordering in select value from jsonb_array_elements(coalesce(request->'order_by','[]'::jsonb)) loop
    authorization_fields := authorization_fields || jsonb_build_array(ordering->>'field');
  end loop;
  for grouping in select value from jsonb_array_elements(coalesce(aggregate_groups,'[]'::jsonb)) loop
    authorization_fields := authorization_fields || jsonb_build_array(case when jsonb_typeof(grouping)='string' then grouping #>> '{}' else grouping->>'field' end);
  end loop;
  for metric in select value from jsonb_array_elements(coalesce(aggregate_metrics,'[]'::jsonb)) loop
    if metric ? 'field' then authorization_fields := authorization_fields || jsonb_build_array(metric->>'field'); end if;
  end loop;
  if search_fields is not null then authorization_fields := authorization_fields || search_fields; end if;
  -- Every field the request reads; only these derived fields are evaluated.
  requested_fields := authorization_fields;
  -- A derived value is readable exactly when every stored field its
  -- expression reads is readable, so it is authorized through those fields.
  select coalesce(jsonb_agg(item.value),'[]'::jsonb) into authorization_fields
  from (
    select to_jsonb(requested.field_id) as value
    from jsonb_array_elements_text(authorization_fields) requested(field_id)
    where not coalesce(derived_environment->requested.field_id ? 'expression',false)
    union all
    select reference.value
    from jsonb_array_elements_text(authorization_fields) requested(field_id)
    cross join lateral jsonb_array_elements(kernel_derived_references(jsonb_build_object('type','field','field',requested.field_id),derived_environment)) reference(value)
    where derived_environment->requested.field_id ? 'expression'
  ) item;
  authorization_policy := kernel_policy_authorize_query(request->>'app_id',request->>'customer_id',request->>'model_id',authorization_fields);
  if authorization_policy is not null then authorization_grants:=kernel_policy_capture_grants(authorization_policy,request->>'model_id','read'); end if;
  if relation_source is not null then
    if authorization_policy is null then
      raise exception 'contract_validation_failed: relation source requires a policy-enabled schema';
    end if;
    select value into relation_json
    from jsonb_array_elements(coalesce(authorization_policy->'relations','[]'::jsonb))
    where value->>'model' = relation_source->>'model_id'
      and value->>'id' = relation_source->>'relation_id'
      and value->>'target_model' = request->>'model_id';
    if relation_json is null or coalesce(relation_json->>'through','') = '' then
      raise exception 'authorization_denied: relation navigation is not declared for this target model';
    end if;
    relation_through := relation_json->>'through';
    select value into source_model_json
    from jsonb_array_elements(schema_json->'models')
    where value->>'id' = relation_source->>'model_id';
    if source_model_json is null then
      raise exception 'authorization_denied: relation source model is not present in the active schema';
    end if;
    if source_model_json->>'kind' = 'lookup' then
      perform kernel_read_assert_lookup_storage_authority(request->>'app_id',request->>'customer_id',relation_source->>'model_id');
      source_record_table := 'lookup_record'; source_version_table := 'lookup_version';
      source_lookup_filter := ' and r.model_id=$3 and v.model_id=r.model_id';
      source_values_expression := format('kernel_read_lookup_values(%L::jsonb,v.values,''[]''::jsonb)',source_model_json::text);
    else
      source_record_table := kernel_read_physical_identifier((relation_source->>'model_id') || '_record');
      source_version_table := kernel_read_physical_identifier((relation_source->>'model_id') || '_version');
      source_values_expression := kernel_read_field_values_expression('v',source_model_json,'[]'::jsonb);
    end if;
    perform kernel_read_assert_mainline_order(source_version_table,request->>'app_id',request->>'customer_id');
    source_navigation_sql := format($navigation$
      with source_image as materialized (
        select (%1$s) as canonical_values,
          case when $13::jsonb is null then jsonb_build_object('values',(%1$s))
            else kernel_work_overlay_row($12 || jsonb_build_object('model_id',$3),$13,
              jsonb_build_object('record_id',r.id,'values',(%1$s),'custom_fields',kernel_read_custom_fields($4,$3,v.custom_fields)),$4) end as values
        from %2$I r join lateral (
          select v.* from %3$I v join change_set cs on cs.id=v.change_set_id
            and cs.app_id=v.app_id and cs.customer_id=v.customer_id
            and cs.status='mainline' and cs.applied_order is not null
          where v.record_id=r.id and v.app_id=r.app_id and v.customer_id=r.customer_id
            and v.stage='mainline' and v.effective_start<=$5 and (v.effective_end is null or v.effective_end>=$5)%4$s
          order by v.effective_start desc,v.tombstones_record desc,v.untombstones_record desc,cs.applied_order desc,v.id desc limit 1
        ) v on true
        where r.app_id=$1 and r.customer_id=$2 and r.id=$10::uuid
          and not v.tombstones_record and not v.untombstones_record
      )
      select exists (
        select 1 from source_image
        where exists (
          select 1
          from kernel_actor_membership membership
          join jsonb_array_elements(coalesce($8->'grants','[]'::jsonb)) grant_value(value)
            on grant_value.value->>'role'=membership.role
          where membership.principal_name=session_user::name and membership.active
            and membership.app_id=$1 and membership.customer_id=$2
            and membership.actor_id=nullif(current_setting('kernel.actor_id',true),'')
            and grant_value.value->>'model'=$3 and grant_value.value->'operations' ? 'read'
            and coalesce(grant_value.value->'read_relations','[]'::jsonb) ? $11
            and (grant_value.value->'record'->>'kind'='all' or (
              grant_value.value->'record'->>'kind'='actor_equals_field'
              and source_image.values->'values'->(grant_value.value->'record'->>'field')->>'value'
                = nullif(current_setting('kernel.actor_id',true),'')
              and source_image.canonical_values->(grant_value.value->'record'->>'field')->>'value'
                = nullif(current_setting('kernel.actor_id',true),'')
            ))
        )
      )
    $navigation$,source_values_expression,source_record_table,source_version_table,source_lookup_filter);
    execute source_navigation_sql
      using request->>'app_id',request->>'customer_id',relation_source->>'model_id',schema_json,request_date,
        null::integer,null::integer,authorization_policy,authorization_fields,source_record_id::text,relation_source->>'relation_id',request,work_fork
      into source_navigation_allowed;
    if not coalesce(source_navigation_allowed,false) then
      raise exception 'authorization_denied: source record or relation navigation is not authorized';
    end if;
    select value into field_json from jsonb_array_elements(query_fields) where value->>'id'=relation_through;
    if field_json is null or field_json->>'type' <> 'relation'
      or field_json->>'target_model' is distinct from relation_source->>'model_id' then
      raise exception 'schema_drift: relation navigation through field is not a supported target relation';
    end if;
    relation_predicate := case when field_json->>'custom'='true'
      then format('(kernel_read_custom_field_map($4,$3,policy_source.r->''custom_fields'')->%L->''value''->>''value'')=$10',relation_through)
      else format('policy_source.r->''values''->%L->''value''->>''value''=$10',relation_through)
    end;
  end if;
  for field_id, field_json in
    select definition.value->>'field_id', derived_environment->(definition.value->>'field_id')
    from jsonb_array_elements(coalesce(schema_json->'custom_fields','[]'::jsonb)) with ordinality definition(value,ordinal)
    where definition.value->>'model_id'=request->>'model_id'
      and derived_environment->(definition.value->>'field_id') ? 'expression'
      and requested_fields ? (definition.value->>'field_id')
    order by definition.ordinal
  loop
    derived_entries_sql := derived_entries_sql || format(' || kernel_derived_entry(%L,%L,%s)',field_id,field_json->>'type',
      kernel_derived_value_sql(field_json->'expression',derived_environment,
        'authorized_source.r->''values''->%L->''value''','derived_source.custom_map->%L->''value'''));
  end loop;
  source_sql := format($query$
    with overlay_records as materialized (
      select entry->>'record_id' record_id,jsonb_agg(entry) entries
      from jsonb_array_elements(coalesce($13->'overlay','[]'::jsonb)) entry
      where entry->>'model_id'=$3 group by entry->>'record_id'
    ), canonical_source as materialized (
    select jsonb_build_object('record_id',r.id,'version_id',v.id,'external_key',r.external_key,
      'effective_start',to_char(v.effective_start,'YYYY-MM-DD'),
      'effective_end',case when v.effective_end is null then null else to_char(v.effective_end,'YYYY-MM-DD') end,
      'values',(%s),'custom_fields',kernel_read_custom_fields($4,$3,v.custom_fields),
      'metadata',coalesce(v.metadata,'{}'::jsonb),'many_relations',coalesce(to_jsonb(v)->'many_relations','{}'::jsonb)) as r
    from %I r join lateral (
      select v.* from %I v join change_set cs on cs.id=v.change_set_id
        and cs.app_id=v.app_id and cs.customer_id=v.customer_id
        and cs.status='mainline' and cs.applied_order is not null
      where v.record_id=r.id and v.app_id=r.app_id and v.customer_id=r.customer_id
        and v.stage='mainline' and v.effective_start<=$5 and (v.effective_end is null or v.effective_end>=$5)%s
      order by v.effective_start desc,v.tombstones_record desc,v.untombstones_record desc,cs.applied_order desc,v.id desc limit 1
    ) v on true
    where r.app_id=$1 and r.customer_id=$2 and not v.tombstones_record and not v.untombstones_record%s
    ),
    policy_source as materialized (
      select case when $13::jsonb is null then r
        else kernel_work_overlay_row($11,jsonb_build_object('overlay',coalesce(overlay_records.entries,'[]'::jsonb)),r,$4) end as r
      from canonical_source left join overlay_records on overlay_records.record_id=canonical_source.r->>'record_id'
      where $8 is null or kernel_policy_grants_record_allowed($14,$9,canonical_source.r->'values')
    ),
    authorized_source as materialized (
      select r from policy_source
      where ($8 is null or kernel_policy_grants_record_allowed($14,$9,policy_source.r->'values')) and (%s)
    )
    select %s from authorized_source%s
  $query$,values_expression,record_table,version_table,lookup_filter,retired_filter||record_filter,relation_predicate,
    case when derived_entries_sql='' then 'r'
      else format('authorized_source.r || jsonb_build_object(''custom_fields'',(authorized_source.r->''custom_fields'')%s) as r',derived_entries_sql) end,
    case when derived_entries_sql='' then ''
      else ' cross join lateral (select kernel_read_custom_field_map($4,$3,authorized_source.r->''custom_fields'') as custom_map) derived_source' end);
  if request->>'kind'='aggregate' then
    group_order_sql := group_order_sql || case when group_order_sql='' then '' else ',' end || 'key';
    query_sql := format($aggregate$
      with visible as materialized (select r from (%s) source where %s),
      eligible as materialized (select r from visible where %s),
      -- CASE below evaluates metrics only after this bounded key count succeeds.
      group_limit as (select count(*) as n from (select distinct %s as key from eligible limit 101) keys),
      grouped as (
        select %s as key,jsonb_build_array(%s) as metrics
        from eligible group by 1 order by 1 limit 101
      )
      select case when (select n from group_limit)>100 then null else jsonb_build_object(
        'as_of',$5,'units',(select jsonb_build_array(%s) from eligible group by ()),
        'groups',coalesce((select jsonb_agg(to_jsonb(grouped) order by %s) from grouped),'[]'::jsonb),
        'total',(select jsonb_build_object('metrics',jsonb_build_array(%s)) from eligible)
      ) %s end
    $aggregate$,source_sql,predicate,eligible_predicate,group_expression,group_expression,metric_sql,units_sql,group_order_sql,total_metric_sql,
      case when money_bins then ' || jsonb_build_object(''other_units'',(select count(*)::text from visible where not (' || eligible_predicate || ')))' else '' end);
    execute query_sql using request->>'app_id',request->>'customer_id',request->>'model_id',schema_json,request_date,null::integer,null::integer,authorization_policy,authorization_fields,source_record_id::text,request,search_query,work_fork,authorization_grants into result;
    if result is null then raise exception 'query_rejected: group limit exceeded'; end if;
  else
    query_sql := format('select coalesce(jsonb_agg(%s),''[]''::jsonb) from (select r from (%s) visible where %s order by %s %s) p',case when work_rule_scan then 'r' else replace(response_expression,'r->','p.r->') end,source_sql,predicate,ordering_sql,case when work_rule_scan then '' else 'limit $6 offset $7' end);
    execute query_sql using request->>'app_id',request->>'customer_id',request->>'model_id',schema_json,request_date,page_size,page_offset,authorization_policy,authorization_fields,source_record_id::text,request,search_query,work_fork,authorization_grants into result;
  end if;
  return jsonb_build_object('ok',true,'data',result);
exception when others then
  return jsonb_build_object('ok',false,'error',kernel_read_error_envelope(sqlstate,sqlerrm));
end;
$kernel$;

