-- artifact: function kernel_change_set_diff(jsonb)
create or replace function kernel_change_set_diff(request jsonb)
returns jsonb
language plpgsql
volatile
security invoker
set search_path from current
as $kernel$
<<read_diff>>
declare
  app_id text;
  customer_id text;
  requested_change_set_id bigint;
  source_change_set_id bigint;
  source_schema_revision_id bigint;
  source_kind text;
  source_ref text;
  source_is_revert boolean;
  schema_json jsonb;
  active_schema_json jsonb;
  model_json jsonb;
  model_id text;
  model_identifier text;
  record_table text;
  version_table text;
  values_expression text;
  previous_values_expression text;
  version_many_expression text;
  previous_many_expression text;
  version_availability_expression text;
  previous_availability_expression text;
  version_filter text;
  candidate_filter text;
  record_filter text;
  record_join_filter text;
  query_sql text;
  version_row record;
  field_json jsonb;
  field_id text;
  before_values jsonb;
  after_values jsonb;
  before_custom jsonb;
  after_custom jsonb;
  before_metadata jsonb;
  after_metadata jsonb;
  before_many jsonb;
  after_many jsonb;
  before_availability text;
  after_availability text;
  before_value jsonb;
  after_value jsonb;
  before_enum jsonb;
  after_enum jsonb;
  fields_json jsonb;
  custom_json jsonb;
  custom_id text;
  relation_json jsonb;
  relation_id text;
  records_json jsonb := '[]'::jsonb;
  sorted_json jsonb;
begin
  perform kernel_cleanup_generated_visible_query();
  if request is null or jsonb_typeof(request) <> 'object' then
    raise exception 'contract_validation_failed: request must be a JSON object';
  end if;
  app_id := request->>'app_id';
  customer_id := request->>'customer_id';
  requested_change_set_id := (request->>'change_set_id')::bigint;
  if app_id is null or btrim(app_id) = '' or customer_id is null or btrim(customer_id) = '' then
    raise exception 'contract_validation_failed: app_id and customer_id are required';
  end if;
  perform set_config('kernel.app_id', app_id, true);
  perform set_config('kernel.customer_id', customer_id, true);
  perform kernel_policy_reject_unsupported_capability(
    app_id, customer_id, 'change-set diff'
  );
  select schema_revision_id, change_set.source_kind, change_set.source_ref
  into source_schema_revision_id, source_kind, source_ref
  from change_set
  where id = requested_change_set_id
    and change_set.app_id = read_diff.app_id
    and change_set.customer_id = read_diff.customer_id;
  if source_schema_revision_id is null then
    raise exception 'record_target_missing: change_set `%` did not resolve', requested_change_set_id;
  end if;
  if source_kind = 'revert' then
    if source_ref is null or source_ref !~ '^-?[0-9]+$' then
      raise exception 'schema_drift: change_set.source_ref|revert change_set `%` source_ref is not a change_set id', requested_change_set_id;
    end if;
    source_change_set_id := source_ref::bigint;
  else
    source_change_set_id := requested_change_set_id;
  end if;
  source_is_revert := source_change_set_id <> requested_change_set_id;
  select schema into schema_json
  from schema_revision
  where id = source_schema_revision_id
    and schema_revision.app_id = read_diff.app_id
    and schema_revision.customer_id = read_diff.customer_id;
  if schema_json is null then
    raise exception 'schema_drift: change_set|change_set `%` pins missing schema revision `%`', requested_change_set_id, source_schema_revision_id;
  end if;
  active_schema_json := kernel_read_scope_schema(app_id, customer_id);

  for model_json in
    select model.value from jsonb_array_elements(schema_json->'models') with ordinality model(value, ordinal)
    order by model.ordinal
  loop
    model_id := model_json->>'id';
    if model_json->>'kind'='lookup' then
      perform kernel_read_assert_lookup_storage_authority(app_id, customer_id, model_id);
      record_table:='lookup_record'; version_table:='lookup_version';
      version_filter:=format(' and v.model_id=%L',model_id);
      candidate_filter:=format(' and candidate.model_id=%L',model_id);
      record_filter:=format(' and r.model_id=%L',model_id);
      record_join_filter:=' and r.model_id=v.model_id';
      values_expression:='kernel_read_lookup_values($6,v.values,''[]''::jsonb)';
      previous_values_expression:='kernel_read_lookup_values($6,p.values,''[]''::jsonb)';
      version_many_expression := 'coalesce(v.many_relations, ''{}''::jsonb)';
      previous_many_expression := 'coalesce(p.many_relations, ''{}''::jsonb)';
      version_availability_expression := 'case when v.id is null then null else coalesce(v.availability, ''active'') end';
      previous_availability_expression := 'case when p.id is null then null else coalesce(p.availability, ''active'') end';
    else
      model_identifier := kernel_read_physical_identifier(model_id);
      record_table := kernel_read_physical_identifier(model_id || '_record');
      version_table := kernel_read_physical_identifier(model_id || '_version');
      version_filter:=''; candidate_filter:=''; record_filter:=''; record_join_filter:='';
      values_expression := kernel_read_field_values_expression('v', model_json, '[]'::jsonb);
      previous_values_expression := kernel_read_field_values_expression('p', model_json, '[]'::jsonb);
      version_many_expression := '''{}''::jsonb';
      previous_many_expression := '''{}''::jsonb';
      version_availability_expression := 'null::text';
      previous_availability_expression := 'null::text';
    end if;
    perform kernel_read_assert_mainline_order(version_table, app_id, customer_id);
    query_sql := format(
      $query$
      select
        v.id version_id, v.change_set_id, v.record_id, r.external_key, v.stage,
        v.effective_start, v.effective_end, v.tombstones_record, v.untombstones_record,
        p.id is not null previous_exists,
        coalesce(p.tombstones_record, false) previous_tombstones_record,
        (%s) version_values, (%s) previous_values,
        kernel_read_custom_field_map($4, $5, v.custom_fields) version_custom,
        kernel_read_custom_field_map($4, $5, p.custom_fields) previous_custom,
        coalesce(v.metadata, '{}'::jsonb) version_metadata,
        coalesce(p.metadata, '{}'::jsonb) previous_metadata,
        (%s) version_many,
        (%s) previous_many,
        (%s) version_availability,
        (%s) previous_availability
      from %I v
      join %I r on r.id = v.record_id and r.app_id = v.app_id and r.customer_id = v.customer_id%s
      join change_set vcs on vcs.id = v.change_set_id and vcs.app_id = v.app_id and vcs.customer_id = v.customer_id
      left join lateral (
        select candidate.*
        from %I candidate
        join change_set pcs on pcs.id = candidate.change_set_id and pcs.app_id = candidate.app_id and pcs.customer_id = candidate.customer_id
        where candidate.record_id = v.record_id
          and candidate.app_id = v.app_id
          and candidate.customer_id = v.customer_id
          and candidate.id <> v.id
          %s
          and (
            (candidate.stage = 'mainline' and pcs.status = 'mainline' and pcs.applied_order is not null)
            or (v.stage = 'draft' and candidate.change_set_id = v.change_set_id and candidate.stage = 'draft' and pcs.status = 'draft' and pcs.applied_order is null)
          )
          and (
            candidate.effective_start,
            case when candidate.tombstones_record then 2 when candidate.untombstones_record then 1 else 0 end,
            case when candidate.stage = 'draft' then 1 else 0 end,
            case when candidate.stage = 'mainline' then pcs.applied_order else pcs.created_order end
          ) < (
            v.effective_start,
            case when v.tombstones_record then 2 when v.untombstones_record then 1 else 0 end,
            case when v.stage = 'draft' then 1 else 0 end,
            case when v.stage in ('mainline', 'reverted') then vcs.applied_order else vcs.created_order end
          )
        order by candidate.effective_start desc,
          candidate.tombstones_record desc,
          candidate.untombstones_record desc,
          case when candidate.stage = 'draft' then 1 else 0 end desc,
          case when candidate.stage = 'mainline' then pcs.applied_order else pcs.created_order end desc,
          candidate.id desc
        limit 1
      ) p on true
      where v.app_id = $1 and v.customer_id = $2 and v.change_set_id = $3
        %s
        %s
        and (
          (v.stage in ('mainline', 'reverted') and vcs.status = 'mainline' and vcs.applied_order is not null)
          or (v.stage = 'draft' and vcs.status = 'draft' and vcs.applied_order is null)
          or (v.stage = 'discarded' and vcs.status = 'discarded' and vcs.applied_order is null)
        )
      order by v.effective_start,
        v.tombstones_record,
        v.untombstones_record,
        case when v.stage = 'draft' then 1 else 0 end,
        case when v.stage in ('mainline', 'reverted') then vcs.applied_order else vcs.created_order end,
        v.id
      $query$,
      values_expression,previous_values_expression,
      version_many_expression,previous_many_expression,
      version_availability_expression,previous_availability_expression,
      version_table,record_table,record_join_filter,version_table,candidate_filter,version_filter,record_filter
    );
    for version_row in execute query_sql using app_id, customer_id, source_change_set_id, schema_json, model_id,model_json loop
      if source_is_revert then
        before_values := coalesce(version_row.version_values, '{}'::jsonb);
        after_values := coalesce(version_row.previous_values, '{}'::jsonb);
        before_custom := coalesce(version_row.version_custom, '{}'::jsonb);
        after_custom := coalesce(version_row.previous_custom, '{}'::jsonb);
        before_metadata := coalesce(version_row.version_metadata, '{}'::jsonb);
        after_metadata := coalesce(version_row.previous_metadata, '{}'::jsonb);
        before_many := coalesce(version_row.version_many, '{}'::jsonb);
        after_many := coalesce(version_row.previous_many, '{}'::jsonb);
        before_availability := version_row.version_availability;
        after_availability := version_row.previous_availability;
      else
        before_values := coalesce(version_row.previous_values, '{}'::jsonb);
        after_values := coalesce(version_row.version_values, '{}'::jsonb);
        before_custom := coalesce(version_row.previous_custom, '{}'::jsonb);
        after_custom := coalesce(version_row.version_custom, '{}'::jsonb);
        before_metadata := coalesce(version_row.previous_metadata, '{}'::jsonb);
        after_metadata := coalesce(version_row.version_metadata, '{}'::jsonb);
        before_many := coalesce(version_row.previous_many, '{}'::jsonb);
        after_many := coalesce(version_row.version_many, '{}'::jsonb);
        before_availability := version_row.previous_availability;
        after_availability := version_row.version_availability;
      end if;
      fields_json := '[]'::jsonb;
      for field_json in select field.value from jsonb_array_elements(model_json->'fields') with ordinality field(value, ordinal) order by field.ordinal loop
        field_id := field_json->>'id';
        if jsonb_array_length(coalesce(request->'project', '[]'::jsonb)) > 0
           and not (coalesce(request->'project', '[]'::jsonb) ? field_id) then
          continue;
        end if;
        before_value := before_values->field_id;
        after_value := after_values->field_id;
        if before_value is distinct from after_value then
          before_enum := kernel_read_enum_audit_value(
            active_schema_json, schema_json, model_id, field_id, before_value, source_schema_revision_id
          );
          after_enum := kernel_read_enum_audit_value(
            active_schema_json, schema_json, model_id, field_id, after_value, source_schema_revision_id
          );
          fields_json := fields_json || jsonb_build_array(
            jsonb_build_object('field_id', field_id, 'before', before_value, 'after', after_value)
            || case when before_enum is null then '{}'::jsonb else jsonb_build_object('before_enum', before_enum) end
            || case when after_enum is null then '{}'::jsonb else jsonb_build_object('after_enum', after_enum) end
          );
        end if;
      end loop;
      for relation_json in
        select relation.value
        from jsonb_array_elements(coalesce(model_json->'many_relations', '[]'::jsonb))
          with ordinality relation(value, ordinal)
        order by relation.ordinal
      loop
        relation_id := relation_json->>'id';
        if jsonb_array_length(coalesce(request->'project', '[]'::jsonb)) > 0
           and not (coalesce(request->'project', '[]'::jsonb) ? relation_id) then
          continue;
        end if;
        before_value := case
          when not version_row.previous_exists and not source_is_revert then null
          else jsonb_build_object(
            'type', 'relation_list',
            'value', coalesce((
              select jsonb_agg(jsonb_build_object('type', 'record_id', 'value', target.value) order by target.ordinal)
              from jsonb_array_elements_text(coalesce(before_many->relation_id, '[]'::jsonb))
                with ordinality target(value, ordinal)
            ), '[]'::jsonb)
          )
        end;
        after_value := case
          when source_is_revert and not version_row.previous_exists then null
          else jsonb_build_object(
            'type', 'relation_list',
            'value', coalesce((
              select jsonb_agg(jsonb_build_object('type', 'record_id', 'value', target.value) order by target.ordinal)
              from jsonb_array_elements_text(coalesce(after_many->relation_id, '[]'::jsonb))
                with ordinality target(value, ordinal)
            ), '[]'::jsonb)
          )
        end;
        if before_value is distinct from after_value then
          fields_json := fields_json || jsonb_build_array(jsonb_build_object(
            'field_id', relation_id, 'before', before_value, 'after', after_value
          ));
        end if;
      end loop;
      if model_json#>'{extensions,record_metadata}' is not null
         and model_json#>'{extensions,record_metadata}' <> 'null'::jsonb
         and (jsonb_array_length(coalesce(request->'project', '[]'::jsonb)) = 0
           or coalesce(request->'project', '[]'::jsonb) ? '__record_metadata')
         and before_metadata is distinct from after_metadata then
        fields_json := fields_json || jsonb_build_array(jsonb_build_object(
          'field_id', '__record_metadata',
          'before', jsonb_build_object('type', 'json', 'value', before_metadata),
          'after', jsonb_build_object('type', 'json', 'value', after_metadata)
        ));
      end if;
      if model_json->>'kind' = 'lookup'
         and (jsonb_array_length(coalesce(request->'project', '[]'::jsonb)) = 0
           or coalesce(request->'project', '[]'::jsonb) ? '__lookup_lifecycle')
         and before_availability is distinct from after_availability then
        fields_json := fields_json || jsonb_build_array(jsonb_build_object(
          'field_id', '__lookup_lifecycle',
          'before', case when before_availability is null then null else jsonb_build_object(
            'type', 'schema_lifecycle', 'value', before_availability
          ) end,
          'after', case when after_availability is null then null else jsonb_build_object(
            'type', 'schema_lifecycle', 'value', after_availability
          ) end
        ));
      end if;
      custom_json := '[]'::jsonb;
      for custom_id in
        select key from (
          select jsonb_object_keys(before_custom) key union select jsonb_object_keys(after_custom) key
        ) ids order by key
      loop
        if jsonb_array_length(coalesce(request->'project', '[]'::jsonb)) > 0
           and not (coalesce(request->'project', '[]'::jsonb) ? custom_id) then
          continue;
        end if;
        before_value := before_custom->custom_id;
        after_value := after_custom->custom_id;
        if before_value is distinct from after_value then
          before_enum := kernel_read_enum_audit_value(
            active_schema_json, schema_json, model_id, custom_id, before_value, source_schema_revision_id
          );
          after_enum := kernel_read_enum_audit_value(
            active_schema_json, schema_json, model_id, custom_id, after_value, source_schema_revision_id
          );
          custom_json := custom_json || jsonb_build_array(
            jsonb_build_object('field_id', custom_id, 'before', before_value, 'after', after_value)
            || case when before_enum is null then '{}'::jsonb else jsonb_build_object('before_enum', before_enum) end
            || case when after_enum is null then '{}'::jsonb else jsonb_build_object('after_enum', after_enum) end
          );
        end if;
      end loop;
      records_json := records_json || jsonb_build_array(jsonb_build_object(
        'model_id', model_id,
        'record_id', version_row.record_id,
        'external_key', version_row.external_key,
        'version_id', version_row.version_id,
        'change_set_id', version_row.change_set_id,
        'stage', version_row.stage,
        'effective_start', to_char(version_row.effective_start, 'YYYY-MM-DD'),
        'effective_end', case when version_row.effective_end is null then null else to_char(version_row.effective_end, 'YYYY-MM-DD') end,
        'before_tombstones_record', case when source_is_revert then version_row.tombstones_record else version_row.previous_tombstones_record end,
        'after_tombstones_record', case when source_is_revert then version_row.previous_tombstones_record or (not version_row.previous_exists and not version_row.tombstones_record) else version_row.tombstones_record end,
        'before_untombstones_record', case when source_is_revert then version_row.untombstones_record else false end,
        'after_untombstones_record', case when source_is_revert then false else version_row.untombstones_record end,
        'fields', fields_json,
        'custom_fields', custom_json
      ));
    end loop;
  end loop;
  select coalesce(jsonb_agg(record.value order by
    record.value->>'model_id',
    record.value->>'effective_start',
    record.value->>'record_id',
    (record.value->>'before_tombstones_record')::boolean or (record.value->>'after_tombstones_record')::boolean,
    (record.value->>'before_untombstones_record')::boolean or (record.value->>'after_untombstones_record')::boolean,
    record.value->>'version_id'
  ), '[]'::jsonb) into sorted_json from jsonb_array_elements(records_json) record(value);
  return jsonb_build_object('ok', true, 'data', jsonb_build_object(
    'change_set_id', requested_change_set_id,
    'source_change_set_id', source_change_set_id,
    'records', sorted_json
  ));
exception when others then
  return jsonb_build_object('ok', false, 'error', kernel_read_error_envelope(sqlstate, sqlerrm));
end;
$kernel$;

-- artifact: function kernel_field_history(jsonb)
create or replace function kernel_field_history(request jsonb)
returns jsonb
language plpgsql
volatile
security invoker
set search_path from current
as $kernel$
declare
  app_id text;
  customer_id text;
  model_id text;
  record_id uuid;
  requested_field_id text;
  requested_as_of date;
  requested_limit bigint;
  requested_stages text[];
  schema_json jsonb;
  model_json jsonb;
  model_identifier text;
  version_table text;
  values_expression text;
  many_expression text;
  availability_expression text;
  version_filter text;
  query_sql text;
  history_row record;
  field_json jsonb;
  field_id text;
  requested_kind text;
  enum_value jsonb;
  policy_snapshot jsonb;
  history_required_fields jsonb;
  history_record_values jsonb;
  attribution_json jsonb;
  policy_declared boolean := false;
  history_candidates jsonb := '[]'::jsonb;
  row_fields jsonb;
  entry_value jsonb;
  entries_json jsonb := '[]'::jsonb;
begin
  perform kernel_cleanup_generated_visible_query();
  if request is null or jsonb_typeof(request) <> 'object' then
    raise exception 'contract_validation_failed: request must be a JSON object';
  end if;
  app_id := request->>'app_id';
  customer_id := request->>'customer_id';
  model_id := request->>'model_id';
  record_id := (request->>'record_id')::uuid;
  requested_field_id := request->>'field_id';
  requested_limit := least(greatest(coalesce((request->>'limit')::bigint, 100), 1), 100);
  if request ? 'as_of' and request->'as_of' <> 'null'::jsonb then requested_as_of := (request->>'as_of')::date; end if;
  select coalesce(array_agg(stage.value order by stage.ordinal), array[]::text[])
  into requested_stages
  from jsonb_array_elements_text(coalesce(request->'stages', '[]'::jsonb)) with ordinality stage(value, ordinal);
  if cardinality(requested_stages) = 0 then requested_stages := array['mainline', 'reverted']; end if;
  schema_json := kernel_read_scope_schema(app_id, customer_id);
  select model.value into model_json
  from jsonb_array_elements(schema_json->'models') model(value)
  where model.value->>'id' = model_id;
  if model_json is null then
    raise exception 'record_target_missing: model `%` is not declared in active schema', model_id;
  end if;
  if model_json->>'kind' = 'lookup' then
    perform kernel_read_assert_lookup_storage_authority(app_id, customer_id, model_id);
  end if;
  if requested_field_id is not null then
    if exists (
      select 1 from jsonb_array_elements(model_json->'fields') field(value)
      where field.value->>'id' = requested_field_id
    ) then
      requested_kind := 'declared';
    elsif exists (
      select 1 from jsonb_array_elements(coalesce(model_json->'many_relations', '[]'::jsonb)) relation(value)
      where relation.value->>'id' = requested_field_id
    ) then
      requested_kind := 'many_relation';
    elsif exists (
      select 1 from jsonb_array_elements(coalesce(schema_json->'custom_fields', '[]'::jsonb)) definition(value)
      where definition.value->>'model_id' = model_id
        and definition.value->>'field_id' = requested_field_id
    ) then
      requested_kind := 'custom';
    elsif requested_field_id = '__record_metadata'
      and model_json#>'{extensions,record_metadata}' is not null
      and model_json#>'{extensions,record_metadata}' <> 'null'::jsonb then
      requested_kind := 'metadata';
    elsif requested_field_id = '__lookup_lifecycle' and model_json->>'kind' = 'lookup' then
      requested_kind := 'lifecycle';
    else
      raise exception 'record_target_missing: field `%` is not declared on model `%`', requested_field_id, model_id;
    end if;
  end if;
  if requested_kind in ('declared', 'custom', 'many_relation') then
    history_candidates := jsonb_build_array(jsonb_build_object('id', requested_field_id, 'kind', requested_kind));
  elsif requested_field_id is null then
    -- Unqualified history covers every declared field, many relation and
    -- active custom field; record metadata and lookup lifecycle stay explicit.
    select coalesce(jsonb_agg(candidate.value order by candidate.position), '[]'::jsonb)
    into history_candidates
    from (
      select jsonb_build_object('id', field.value->>'id', 'kind', 'declared') value, field.ordinal position
      from jsonb_array_elements(coalesce(model_json->'fields', '[]'::jsonb)) with ordinality field(value, ordinal)
      union all
      select jsonb_build_object('id', relation.value->>'id', 'kind', 'many_relation'), 1000000 + relation.ordinal
      from jsonb_array_elements(coalesce(model_json->'many_relations', '[]'::jsonb)) with ordinality relation(value, ordinal)
      union all
      select jsonb_build_object('id', definition.value->>'field_id', 'kind', 'custom'), 2000000 + definition.ordinal
      from jsonb_array_elements(coalesce(schema_json->'custom_fields', '[]'::jsonb)) with ordinality definition(value, ordinal)
      where definition.value->>'model_id' = model_id
        and coalesce(definition.value->>'lifecycle', 'active') = 'active'
        and coalesce(definition.value->'archived_at', 'null'::jsonb) = 'null'::jsonb
    ) candidate;
  end if;
  policy_snapshot := kernel_policy_active_snapshot(app_id, customer_id);
  policy_declared := coalesce((policy_snapshot->>'declared')::boolean, false);
  if policy_declared then
    perform kernel_policy_request_actor(app_id, customer_id);
    if requested_kind = 'lifecycle' or exists (
      select 1 from unnest(requested_stages) requested_stage
      where requested_stage not in ('mainline', 'reverted')
    ) then
      raise exception 'unsupported_capability: policy-enabled history supports canonical mainline and reverted images only';
    end if;
    if requested_kind = 'metadata' then
      history_required_fields := jsonb_build_array('$metadata');
    elsif requested_field_id is not null then
      history_required_fields := jsonb_build_array(requested_field_id);
    else
      -- Unqualified history needs a history grant on the model; fields the
      -- actor may not read are left out rather than failing the request.
      history_required_fields := '[]'::jsonb;
    end if;
    if not kernel_policy_required_fields_allowed(
      policy_snapshot->'policy', model_id, 'history', history_required_fields
    ) then
      raise exception 'authorization_denied: no applicable authorization grant permits the requested history fields';
    end if;
    if requested_field_id is null then
      select coalesce(jsonb_agg(candidate.value order by candidate.ordinal), '[]'::jsonb)
      into history_candidates
      from jsonb_array_elements(history_candidates) with ordinality candidate(value, ordinal)
      where kernel_policy_required_fields_allowed(
        policy_snapshot->'policy', model_id, 'history', jsonb_build_array(candidate.value->>'id')
      );
    end if;
  end if;
  if model_json->>'kind'='lookup' then
    version_table:='lookup_version';
    version_filter:=format(' and v.model_id=%L',model_id);
    values_expression:='kernel_read_lookup_values($7,v.values,''[]''::jsonb)';
    many_expression := 'coalesce(v.many_relations, ''{}''::jsonb)';
    availability_expression := 'coalesce(v.availability, ''active'')';
  else
    model_identifier := kernel_read_physical_identifier(model_id);
    version_table := kernel_read_physical_identifier(model_id || '_version');
    version_filter:='';
    values_expression := kernel_read_field_values_expression('v', model_json, '[]'::jsonb);
    many_expression := '''{}''::jsonb';
    availability_expression := 'null::text';
  end if;
  perform kernel_read_assert_mainline_order(version_table, app_id, customer_id);
  query_sql := format(
    $query$
    with eligible_snapshots as (
      select v.change_set_id, v.effective_start, v.stage, cs.schema_revision_id,
        bool_or(v.tombstones_record) tombstones_record,
        bool_or(v.untombstones_record) untombstones_record,
        case when v.stage in ('mainline', 'reverted') then cs.applied_order else cs.created_order end causal_order
      from %I v
      join change_set cs on cs.id = v.change_set_id and cs.app_id = v.app_id and cs.customer_id = v.customer_id
      where v.record_id = $1 and v.app_id = $2 and v.customer_id = $3
        %s
        and v.stage = any($4)
        and ($5::date is null or v.effective_start <= $5)
        and (
          (v.stage in ('mainline', 'reverted') and cs.status = 'mainline' and cs.applied_order is not null)
          or (v.stage = 'draft' and cs.status = 'draft' and cs.applied_order is null)
          or (v.stage = 'discarded' and cs.status = 'discarded' and cs.applied_order is null)
        )
      group by v.change_set_id, v.effective_start, v.stage, cs.schema_revision_id,
        cs.applied_order, cs.created_order
    ), selected_snapshots as (
      select * from eligible_snapshots
      order by effective_start desc, tombstones_record desc, untombstones_record desc, causal_order desc
      limit $6
    )
    select v.id version_id, v.change_set_id, v.stage, v.effective_start, v.effective_end,
      selected.schema_revision_id event_schema_revision_id, event_revision.schema event_schema,
      (select revert_cs.id from change_set revert_cs
       where revert_cs.app_id = v.app_id and revert_cs.customer_id = v.customer_id
         and revert_cs.status = 'mainline' and revert_cs.applied_order is not null
         and revert_cs.source_kind = 'revert' and revert_cs.source_ref = v.change_set_id::text
       order by revert_cs.applied_order desc, revert_cs.id desc limit 1) reverted_by,
      (%s) values,
      kernel_read_custom_field_map($8, $7->>'id', v.custom_fields) custom_values,
      coalesce(v.metadata, '{}'::jsonb) metadata,
      (%s) many_relations,
      (%s) availability,
      v.tombstones_record, v.untombstones_record,
      event_cs.actor_id, event_cs.source_kind, event_cs.source_ref, event_cs.notes,
      event_cs.applied_at change_set_applied_at
    from selected_snapshots selected
    join %I v on v.change_set_id = selected.change_set_id
      and v.effective_start = selected.effective_start
      and v.stage = selected.stage
      and v.record_id = $1 and v.app_id = $2 and v.customer_id = $3
      %s
    join change_set event_cs
      on event_cs.id = v.change_set_id
     and event_cs.app_id = v.app_id
     and event_cs.customer_id = v.customer_id
    left join schema_revision event_revision
      on event_revision.id = selected.schema_revision_id
     and event_revision.app_id = v.app_id
     and event_revision.customer_id = v.customer_id
    order by selected.effective_start, selected.tombstones_record, selected.untombstones_record,
      selected.causal_order, v.tombstones_record, v.untombstones_record, v.id
    $query$,
    version_table,version_filter,values_expression,many_expression,availability_expression,
    version_table,version_filter
  );
  for history_row in execute query_sql using record_id, app_id, customer_id, requested_stages, requested_as_of, requested_limit,model_json,schema_json loop
    if history_row.event_schema is null then
      raise exception 'schema_drift: change_set|change_set `%` pins missing schema revision `%`', history_row.change_set_id, history_row.event_schema_revision_id;
    end if;
    row_fields := history_candidates;
    if policy_declared then
      history_record_values := coalesce(history_row.values, '{}'::jsonb)
        || coalesce(history_row.custom_values, '{}'::jsonb)
        || coalesce(history_row.many_relations, '{}'::jsonb);
      if not kernel_policy_record_allowed(
        policy_snapshot->'policy', model_id, 'history', history_required_fields, history_record_values
      ) then
        raise exception 'authorization_denied: a historical snapshot is not authorized by the current policy';
      end if;
      if requested_field_id is null then
        -- A field the actor may not read in this otherwise authorized
        -- snapshot is emitted as withheld, never omitted, so every snapshot
        -- boundary stays visible even when no field is readable.
        select coalesce(jsonb_agg(
          candidate.value || jsonb_build_object('withheld', not kernel_policy_record_allowed(
            policy_snapshot->'policy', model_id, 'history',
            jsonb_build_array(candidate.value->>'id'), history_record_values
          ))
          order by candidate.ordinal
        ), '[]'::jsonb)
        into row_fields
        from jsonb_array_elements(history_candidates) with ordinality candidate(value, ordinal);
      end if;
    end if;
    -- Attribution and lifecycle come from the owning change set and the
    -- physical version row; they are emitted on every entry kind.
    attribution_json := jsonb_build_object(
      'withheld', false,
      'tombstones_record', history_row.tombstones_record,
      'untombstones_record', history_row.untombstones_record,
      'source_kind', history_row.source_kind,
      'source_ref', history_row.source_ref,
      -- Under a declared policy the free-text notes and actor identity are
      -- withheld (null); source kind, source ref and time stay visible.
      'actor_id', case when policy_declared then null else history_row.actor_id end,
      'notes', case when policy_declared then null else history_row.notes end,
      'applied_at', case when history_row.change_set_applied_at is null then null else regexp_replace(to_char(history_row.change_set_applied_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'), '\.000000Z$', 'Z') end
    );
    if requested_kind = 'metadata' then
      entries_json := entries_json || jsonb_build_array(jsonb_build_object(
        'version_id', history_row.version_id, 'change_set_id', history_row.change_set_id,
        'stage', history_row.stage, 'effective_start', to_char(history_row.effective_start, 'YYYY-MM-DD'),
        'effective_end', case when history_row.effective_end is null then null else to_char(history_row.effective_end, 'YYYY-MM-DD') end,
        'field_id', requested_field_id,
        'value', jsonb_build_object('type', 'json', 'value', history_row.metadata),
        'reverted_by', history_row.reverted_by
      ) || attribution_json);
      continue;
    elsif requested_kind = 'lifecycle' then
      entries_json := entries_json || jsonb_build_array(jsonb_build_object(
        'version_id', history_row.version_id, 'change_set_id', history_row.change_set_id,
        'stage', history_row.stage, 'effective_start', to_char(history_row.effective_start, 'YYYY-MM-DD'),
        'effective_end', case when history_row.effective_end is null then null else to_char(history_row.effective_end, 'YYYY-MM-DD') end,
        'field_id', requested_field_id,
        'value', jsonb_build_object('type', 'schema_lifecycle', 'value', history_row.availability),
        'reverted_by', history_row.reverted_by
      ) || attribution_json);
      continue;
    end if;
    for field_json in
      select candidate.value from jsonb_array_elements(row_fields) with ordinality candidate(value, ordinal)
      order by candidate.ordinal
    loop
      field_id := field_json->>'id';
      enum_value := null;
      if coalesce((field_json->>'withheld')::boolean, false) then
        entries_json := entries_json || jsonb_build_array(
          jsonb_build_object(
            'version_id', history_row.version_id,
            'change_set_id', history_row.change_set_id,
            'stage', history_row.stage,
            'effective_start', to_char(history_row.effective_start, 'YYYY-MM-DD'),
            'effective_end', case when history_row.effective_end is null then null else to_char(history_row.effective_end, 'YYYY-MM-DD') end,
            'field_id', field_id,
            'value', null,
            'reverted_by', history_row.reverted_by
          ) || attribution_json || jsonb_build_object('withheld', true)
        );
        continue;
      end if;
      if field_json->>'kind' = 'many_relation' then
        entry_value := jsonb_build_object('type', 'relation_list', 'value', coalesce((
          select jsonb_agg(jsonb_build_object('type', 'record_id', 'value', target.value) order by target.ordinal)
          from jsonb_array_elements_text(coalesce(history_row.many_relations->field_id, '[]'::jsonb))
            with ordinality target(value, ordinal)
        ), '[]'::jsonb));
      else
        if field_json->>'kind' = 'custom' then
          entry_value := history_row.custom_values->field_id;
        else
          entry_value := history_row.values->field_id;
        end if;
        enum_value := kernel_read_enum_audit_value(
          schema_json, history_row.event_schema, model_id, field_id,
          entry_value, history_row.event_schema_revision_id
        );
      end if;
      entries_json := entries_json || jsonb_build_array(
        jsonb_build_object(
          'version_id', history_row.version_id,
          'change_set_id', history_row.change_set_id,
          'stage', history_row.stage,
          'effective_start', to_char(history_row.effective_start, 'YYYY-MM-DD'),
          'effective_end', case when history_row.effective_end is null then null else to_char(history_row.effective_end, 'YYYY-MM-DD') end,
          'field_id', field_id,
          'value', entry_value,
          'reverted_by', history_row.reverted_by
        ) || attribution_json || case when enum_value is null then '{}'::jsonb else jsonb_build_object('enum_value', enum_value) end
      );
    end loop;
  end loop;
  return jsonb_build_object('ok', true, 'data', entries_json);
exception when others then
  return jsonb_build_object('ok', false, 'error', kernel_read_error_envelope(sqlstate, sqlerrm));
end;
$kernel$;

-- artifact: function kernel_recent_activity(jsonb)
create or replace function kernel_recent_activity(request jsonb)
returns jsonb
language plpgsql
volatile
security invoker
set search_path from current
as $kernel$
<<read_activity>>
declare
  app_id text;
  customer_id text;
  requested_limit bigint;
  statuses text[];
  source_kinds text[];
  schema_json jsonb;
  activity_row record;
  model_json jsonb;
  model_identifier text;
  version_table text;
  model_filter text;
  version_change_set_id bigint;
  model_count bigint;
  touched_count bigint;
  query_sql text;
  entries_json jsonb := '[]'::jsonb;
begin
  perform kernel_cleanup_generated_visible_query();
  if request is null or jsonb_typeof(request) <> 'object' then
    raise exception 'contract_validation_failed: request must be a JSON object';
  end if;
  app_id := request->>'app_id';
  customer_id := request->>'customer_id';
  requested_limit := least(greatest(coalesce((request->>'limit')::bigint, 50), 1), 100);
  select coalesce(array_agg(status.value order by status.ordinal), array[]::text[])
  into statuses
  from jsonb_array_elements_text(coalesce(request->'statuses', '[]'::jsonb)) with ordinality status(value, ordinal);
  if cardinality(statuses) = 0 then statuses := array['mainline', 'draft']; end if;
  select coalesce(array_agg(source.value order by source.ordinal), array[]::text[])
  into source_kinds
  from jsonb_array_elements_text(coalesce(request->'source_kinds', '[]'::jsonb)) with ordinality source(value, ordinal);
  schema_json := kernel_read_scope_schema(app_id, customer_id);
  perform kernel_policy_reject_unsupported_capability(
    app_id, customer_id, 'recent activity'
  );
  for activity_row in
    select id, status, actor_id, source_kind, source_ref, change_type_id, notes, created_at, applied_at
    from change_set
    where change_set.app_id = read_activity.app_id
      and change_set.customer_id = read_activity.customer_id
      and status = any(statuses)
      and (cardinality(source_kinds) = 0 or source_kind = any(source_kinds))
    order by case when status = 'mainline' then applied_order else created_order end desc, id desc
    limit requested_limit
  loop
    if activity_row.source_kind = 'revert' then
      if activity_row.source_ref is null or activity_row.source_ref !~ '^-?[0-9]+$' then
        raise exception 'schema_drift: change_set.source_ref|revert change_set `%` source_ref is not a change_set id', activity_row.id;
      end if;
      version_change_set_id := activity_row.source_ref::bigint;
    else
      version_change_set_id := activity_row.id;
    end if;
    touched_count := 0;
    for model_json in select model.value from jsonb_array_elements(schema_json->'models') model(value) loop
      if model_json->>'kind'='lookup' then
        perform kernel_read_assert_lookup_storage_authority(
          app_id, customer_id, model_json->>'id'
        );
        version_table:='lookup_version'; model_filter:=format(' and model_id=%L',model_json->>'id');
      else
        model_identifier := kernel_read_physical_identifier(model_json->>'id');
        version_table := kernel_read_physical_identifier((model_json->>'id') || '_version');
        model_filter:='';
      end if;
      query_sql := format(
        'select count(distinct record_id) from %I where app_id = $1 and customer_id = $2 and change_set_id = $3%s',
        version_table,
        model_filter || case when activity_row.source_kind = 'revert' then ' and stage = ''reverted''' else '' end
      );
      execute query_sql using app_id, customer_id, version_change_set_id into model_count;
      touched_count := touched_count + model_count;
    end loop;
    entries_json := entries_json || jsonb_build_array(jsonb_build_object(
      'change_set_id', activity_row.id,
      'status', activity_row.status,
      'actor_id', activity_row.actor_id,
      'source_kind', activity_row.source_kind,
      'source_ref', activity_row.source_ref,
      'change_type_id', activity_row.change_type_id,
      'notes', activity_row.notes,
      'created_at', regexp_replace(to_char(activity_row.created_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'), '\.000000Z$', 'Z'),
      'applied_at', case when activity_row.applied_at is null then null else regexp_replace(to_char(activity_row.applied_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'), '\.000000Z$', 'Z') end,
      'touched_record_count', touched_count
    ));
  end loop;
  return jsonb_build_object('ok', true, 'data', entries_json);
exception when others then
  return jsonb_build_object('ok', false, 'error', kernel_read_error_envelope(sqlstate, sqlerrm));
end;
$kernel$;

-- artifact: function kernel_work_overlay_row(jsonb,jsonb,jsonb,jsonb)
create or replace function kernel_work_overlay_row(request jsonb, fork jsonb, row_image jsonb, schema_json jsonb)
returns jsonb language plpgsql stable security invoker set search_path from current
as $kernel$
declare entry jsonb; definition jsonb; item jsonb; values_json jsonb:=row_image->'values'; custom_json jsonb:=row_image->'custom_fields';
 entries jsonb:=coalesce(fork->'overlay','[]'::jsonb); definitions jsonb:=coalesce(schema_json->'custom_fields','[]'::jsonb);
 is_custom boolean; archived boolean; filtered jsonb; i integer; j integer;
begin
  -- The query joins each record's captured entries once. Apply that bounded
  -- array with native JSON operations, without starting SQL for each field.
  for i in 0..jsonb_array_length(entries)-1 loop
    entry:=entries->i;
    if not coalesce(entry->>'model_id'=request->>'model_id' and entry->>'record_id'=row_image->>'record_id',false) then continue; end if;
    is_custom:=false; archived:=false;
    for j in 0..jsonb_array_length(definitions)-1 loop
      definition:=definitions->j;
      if definition->>'model_id'=entry->>'model_id' and definition->>'field_id'=entry->>'field_id' then
        is_custom:=true;
        archived:=archived or coalesce(definition->>'archived_at','')<>'' or coalesce(definition->>'lifecycle','active')<>'active';
      end if;
    end loop;
    if archived then continue; end if;
    if is_custom then
      filtered:='[]';
      for j in 0..coalesce(jsonb_array_length(custom_json),0)-1 loop
        item:=custom_json->j;
        if item->>'field_id'<>entry->>'field_id' then filtered:=filtered||jsonb_build_array(item); end if;
      end loop;
      custom_json:=filtered;
      if entry->'value'<>'null'::jsonb then custom_json:=custom_json||jsonb_build_array(entry->'value'||jsonb_build_object('field_id',entry->>'field_id')); end if;
    else
      values_json:=values_json-(entry->>'field_id');
      if entry->'value'<>'null'::jsonb then values_json:=values_json||jsonb_build_object(entry->>'field_id',entry->'value'); end if;
    end if;
  end loop;
  return row_image||jsonb_build_object('values',values_json,'custom_fields',custom_json);
end;
$kernel$;

-- artifact: function kernel_work_rule_scalar(jsonb)
create or replace function kernel_work_rule_scalar(value jsonb)
returns numeric language plpgsql immutable security invoker set search_path from current
as $kernel$
begin
  if jsonb_typeof(value)='string' and value#>>'{}' ~ '^-?[0-9]+([.][0-9]+)?$' then return (value#>>'{}')::numeric; end if;
  if jsonb_typeof(value)='object' and value - array['amount','currency','period']='{}'::jsonb
    and value ?& array['amount','currency','period']
    and jsonb_typeof(value->'amount')='string' and value->>'amount' ~ '^-?[0-9]+([.][0-9]+)?$'
    and value->>'currency' ~ '^[A-Z]{3}$' and value->>'period' in ('hourly','daily','weekly','monthly','annual') then
    return (value->>'amount')::numeric;
  end if;
  raise exception 'contract_validation_failed: rule value must be a decimal or unit-bearing money';
end;
$kernel$;

-- artifact: function kernel_work_rule_boolean(jsonb)
create or replace function kernel_work_rule_boolean(value jsonb)
returns boolean language plpgsql immutable security invoker set search_path from current
as $kernel$
begin
  if jsonb_typeof(value) is distinct from 'boolean' then raise exception 'contract_validation_failed: rule condition must be boolean'; end if;
  return (value#>>'{}')::boolean;
end;
$kernel$;

-- artifact: function kernel_work_rule_op(text,jsonb)
create or replace function kernel_work_rule_op(op text, args jsonb)
returns jsonb language plpgsql immutable security invoker set search_path from current
as $kernel$
declare a jsonb := args->0; b jsonb := args->1; c jsonb := args->2; x numeric; y numeric; z numeric; n numeric; unit jsonb;
begin
  if op in ('==','!=') and jsonb_typeof(a)='boolean' and jsonb_typeof(b)='boolean' then
    return to_jsonb(case when op='==' then a=b else a<>b end);
  end if;
  x := kernel_work_rule_scalar(a); y := kernel_work_rule_scalar(b);
  if jsonb_typeof(a)='object' then unit := a-'amount'; end if;
  if op='*' then
    if jsonb_typeof(a)='object' and jsonb_typeof(b)='object' then raise exception 'contract_validation_failed: cannot multiply money by money'; end if;
    if jsonb_typeof(b)='object' then unit := b-'amount'; end if;
  elsif op='/' and jsonb_typeof(b)='object' then
    if unit is distinct from b-'amount' then raise exception 'contract_validation_failed: incompatible rule units'; end if;
    unit := null;
  elsif op<>'/' and (case when jsonb_typeof(a)='object' then a-'amount' else 'null'::jsonb end)
    is distinct from (case when jsonb_typeof(b)='object' then b-'amount' else 'null'::jsonb end) then
    raise exception 'contract_validation_failed: incompatible rule units';
  end if;
  if op in ('<','<=','>','>=','==','!=') then
    return to_jsonb(case op when '<' then x<y when '<=' then x<=y when '>' then x>y when '>=' then x>=y when '==' then x=y else x<>y end);
  end if;
  if op='clamp' then
    z := kernel_work_rule_scalar(c);
    if (case when jsonb_typeof(c)='object' then c-'amount' else null end) is distinct from unit or y>z then raise exception 'contract_validation_failed: invalid clamp bounds or units'; end if;
  end if;
  n := case op when '+' then x+y when '-' then x-y when '*' then x*y when '/' then x/y when 'min' then least(x,y) when 'max' then greatest(x,y) when 'clamp' then greatest(y,least(z,x)) else null end;
  if n is null then raise exception 'contract_validation_failed: unsupported rule operator'; end if;
  if unit is null then return to_jsonb(trim_scale(n)::text); end if;
  return unit || jsonb_build_object('amount',trim_scale(n)::text);
exception when division_by_zero or numeric_value_out_of_range then
  raise exception 'contract_validation_failed: rule arithmetic is out of range or divides by zero';
end;
$kernel$;

-- artifact: function kernel_work_rule_compile(jsonb,jsonb,jsonb,text[])
create or replace function kernel_work_rule_compile(node jsonb, model jsonb, schema_json jsonb, node_path text[])
returns text language plpgsql immutable security invoker set search_path from current
as $kernel$
declare kind text; name text; child jsonb; parts text[] := array[]::text[]; idx integer := 0; field_json jsonb; target jsonb;
begin
  if cardinality(node_path)>64 or jsonb_typeof(node) is distinct from 'object' then
    raise exception 'contract_validation_failed: invalid bounded rule expression';
  end if;
  if node ? 'op' then
    if node - array['op','args'] <> '{}'::jsonb or jsonb_typeof(node->'op') is distinct from 'string' or jsonb_typeof(node->'args') is distinct from 'array' then
      raise exception 'contract_validation_failed: invalid rule operator';
    end if;
    kind := node->>'op';
    if kind not in ('+','-','*','/','min','max','clamp','<','<=','>','>=','==','!=','if')
      or jsonb_array_length(node->'args') <> (case when kind in ('clamp','if') then 3 else 2 end) then
      raise exception 'contract_validation_failed: unsupported rule operator or arity';
    end if;
    for child in select value from jsonb_array_elements(node->'args') loop
      parts := array_append(parts,kernel_work_rule_compile(child,model,schema_json,node_path||array['args',idx::text]));
      idx := idx + 1;
    end loop;
    if kind='if' then
      return format('(case when kernel_work_rule_boolean(%s) then %s else %s end)',parts[1],parts[2],parts[3]);
    end if;
    return format('kernel_work_rule_op(%L,jsonb_build_array(%s))',kind,array_to_string(parts,','));
  end if;
  if (select count(*) from jsonb_object_keys(node))<>1 then raise exception 'contract_validation_failed: invalid rule expression'; end if;
  if node ? 'field' then
    name := node->>'field';
    select value into field_json from jsonb_array_elements((model->'fields') || coalesce((select jsonb_agg(value || jsonb_build_object('id',value->>'field_id','custom',true)) from jsonb_array_elements(coalesce(schema_json->'custom_fields','[]'::jsonb)) where value->>'model_id'=model->>'id' and coalesce(value->'archived_at','null'::jsonb)='null'::jsonb and coalesce(value->>'lifecycle','active')='active'),'[]'::jsonb)) where value->>'id'=name;
    if field_json is null or field_json->>'type' not in ('number','money_rate','bool') then
      raise exception 'contract_validation_failed: rule field must be numeric, money or boolean';
    end if;
    if field_json->>'custom'='true' then
      return format('(select entry->''value'' from jsonb_array_elements(source_row.row_value->''custom_fields'') entry where entry->>''field_id''=%L)',name);
    end if;
    return format('(source_row.row_value->''values''->%L->''value'')',name);
  elsif node ? 'parameter' then
    if jsonb_typeof(node->'parameter') is distinct from 'string' or node->>'parameter'='' then raise exception 'contract_validation_failed: invalid rule parameter'; end if;
    return format('($3->%L)',node->>'parameter');
  elsif node ? 'number' then
    if jsonb_typeof(node->'number') is distinct from 'string' or node->>'number' !~ '^-?[0-9]+([.][0-9]+)?$' then raise exception 'contract_validation_failed: invalid rule number'; end if;
    return format('($2#>%L::text[])',node_path||array['number']);
  elsif node ? 'money' then
    perform kernel_work_rule_scalar(node->'money');
    if jsonb_typeof(node->'money') is distinct from 'object' then raise exception 'contract_validation_failed: invalid rule money'; end if;
    return format('($2#>%L::text[])',node_path||array['money']);
  elsif node ? 'lookup' then
    if jsonb_typeof(node->'lookup') is distinct from 'object' or (node->'lookup') - array['relation','field'] <> '{}'::jsonb then raise exception 'contract_validation_failed: invalid rule lookup'; end if;
    select value into field_json from jsonb_array_elements(model->'fields') where value->>'id'=node#>>'{lookup,relation}' and value->>'type'='relation';
    select value into target from jsonb_array_elements(schema_json->'models') where value->>'id'=field_json->>'target_model';
    if target is null or not (exists (select 1 from jsonb_array_elements(target->'fields') where value->>'id'=node#>>'{lookup,field}' and value->>'type' in ('number','money_rate','bool')) or exists (select 1 from jsonb_array_elements(coalesce(schema_json->'custom_fields','[]'::jsonb)) where value->>'model_id'=target->>'id' and value->>'field_id'=node#>>'{lookup,field}' and value->>'type' in ('number','money_rate','bool') and coalesce(value->'archived_at','null'::jsonb)='null'::jsonb and coalesce(value->>'lifecycle','active')='active')) then raise exception 'contract_validation_failed: invalid rule lookup target'; end if;
    return format('kernel_work_rule_lookup($4,source_row.row_value,(case when source_row.row_value#>>%L::text[] is null then null::jsonb else ((select lookup_values from %I)->(source_row.row_value#>>%L::text[])) end),%L,%L,%L)',array['values',node#>>'{lookup,relation}','value','value'],'lookup_'||md5((node->'lookup')::text),array['values',node#>>'{lookup,relation}','value','value'],node#>>'{lookup,relation}',target->>'id',node#>>'{lookup,field}');
  end if;
  raise exception 'contract_validation_failed: unknown rule expression';
end;
$kernel$;

-- artifact: function kernel_work_rule_rows(jsonb,jsonb)
create or replace function kernel_work_rule_rows(request jsonb, session_state jsonb)
returns jsonb language plpgsql volatile security invoker set search_path from current
as $kernel$
declare answer jsonb;
begin
  answer := kernel_data_query_core(request,session_state,true);
  if answer->'ok' is distinct from 'true'::jsonb then
    raise exception '%: %',answer#>>'{error,code}',answer#>>'{error,message}';
  end if;
  return answer->'data';
end;
$kernel$;

-- artifact: function kernel_work_rule_lookup(jsonb,jsonb,jsonb,text,text,text)
create or replace function kernel_work_rule_lookup(request jsonb, row_image jsonb, lookup_value jsonb, relation_id text, model_id text, field_id text)
returns jsonb language plpgsql volatile security invoker set search_path from current
as $kernel$
declare target_id text;
begin
  target_id := row_image->'values'->relation_id->'value'->>'value';
  if target_id is null then raise exception 'record_target_missing: rule lookup relation is empty'; end if;
  -- The compiler extracts one value from its private, authorized lookup map.
  if lookup_value is null then raise exception 'authorization_denied: rule lookup target unavailable'; end if;
  return lookup_value;

end;
$kernel$;

-- artifact: function kernel_work_rule_evaluate(jsonb,jsonb,jsonb,text)
create or replace function kernel_work_rule_evaluate(request jsonb, session_state jsonb, rule jsonb, fork_id text)
returns jsonb language plpgsql volatile security invoker set search_path from current
as $kernel$
declare schema_json jsonb; model_json jsonb; field_json jsonb; compiled text; query_request jsonb; select_ids jsonb;
  changes jsonb; staged_overlay jsonb; evaluation_state jsonb; parameters jsonb := coalesce(rule->'parameters','{}'::jsonb); parameter jsonb; lookup_node jsonb; lookup_model text; lookup_request jsonb; lookup_ctes text := '';
begin
  schema_json := kernel_read_scope_schema(request->>'app_id',request->>'customer_id');
  if jsonb_typeof(rule) is distinct from 'object' or rule - array['id','description','model_id','field_id','where','expression','parameters','author_principal','author_kind'] <> '{}'::jsonb
    or not (rule ?& array['id','model_id','field_id','expression'])
    or jsonb_typeof(parameters) is distinct from 'object' then raise exception 'contract_validation_failed: invalid work rule'; end if;
  select value into model_json from jsonb_array_elements(schema_json->'models') where value->>'id'=rule->>'model_id';
  select value into field_json from jsonb_array_elements((model_json->'fields') || coalesce((select jsonb_agg(value || jsonb_build_object('id',value->>'field_id')) from jsonb_array_elements(coalesce(schema_json->'custom_fields','[]'::jsonb)) where value->>'model_id'=model_json->>'id' and coalesce(value->'archived_at','null'::jsonb)='null'::jsonb and coalesce(value->>'lifecycle','active')='active'),'[]'::jsonb)) where value->>'id'=rule->>'field_id';
  if field_json is null or field_json->>'type' not in ('number','money_rate','bool') then raise exception 'contract_validation_failed: invalid rule target'; end if;
  for parameter in select value from jsonb_each(parameters) loop
    if jsonb_typeof(parameter)<>'boolean' then perform kernel_work_rule_scalar(parameter); end if;
  end loop;
  if exists (
    with recursive nodes(node) as (select rule->'expression' union all
      select value from nodes cross join lateral jsonb_array_elements(coalesce(node->'args','[]'::jsonb)))
    select 1 from nodes where node ? 'parameter' and not (parameters ? (node->>'parameter'))
  ) then raise exception 'contract_validation_failed: missing rule parameter'; end if;
  compiled := kernel_work_rule_compile(rule->'expression',model_json,schema_json,array[]::text[]);
  with recursive nodes(node) as (
    select rule->'expression'
    union all
    select value from nodes cross join lateral jsonb_array_elements(coalesce(node->'args','[]'::jsonb))
  ), fields(field_id) as (
    select node->>'field' from nodes where node ? 'field'
    union select node#>>'{lookup,relation}' from nodes where node ? 'lookup'
    union select rule->>'field_id' union select '$id' union select '$version'
  ) select jsonb_agg(field_id order by field_id) into select_ids from fields;
  query_request := jsonb_build_object('app_id',request->>'app_id','customer_id',request->>'customer_id',
    'schema_version',schema_json->>'version','as_of',session_state->>'as_of',
    'model_id',rule->>'model_id','kind','list','select',select_ids,'where',coalesce(rule->'where','[]'::jsonb),
    'work',jsonb_build_object('session_id',session_state->>'id','fork_id',fork_id));
  select coalesce(jsonb_agg(case when value->>'rule_id'=rule->>'id' then value->'replaced' else value end),'[]'::jsonb) into staged_overlay
    from jsonb_array_elements(session_state->'forks'->fork_id->'overlay')
    where value->>'rule_id' is distinct from rule->>'id' or value ? 'replaced';
  evaluation_state := jsonb_set(session_state,array['forks',fork_id,'overlay'],staged_overlay);
  -- Materialized CTEs are demanded by the expression, so an unused conditional
  -- branch does not authorize or read its lookup. Each used lookup scans its
  -- target model once, rather than once per source row.
  for lookup_node in
    with recursive nodes(node) as (select rule->'expression' union all
      select value from nodes cross join lateral jsonb_array_elements(coalesce(node->'args','[]'::jsonb)))
    select distinct node->'lookup' from nodes where node ? 'lookup'
  loop
    select field->>'target_model' into lookup_model from jsonb_array_elements(model_json->'fields') field
      where field->>'id'=lookup_node->>'relation';
    lookup_request:=(query_request-array['where','order_by','limit','offset'])||jsonb_build_object(
      'model_id',lookup_model,'select',jsonb_build_array('$id',lookup_node->>'field'),'where','[]'::jsonb);
    lookup_ctes:=lookup_ctes||','||format($lookup$
      %I as materialized (
        select coalesce(jsonb_object_agg(image->>'record_id',kernel_work_value(image,%L)->'value'),'{}'::jsonb) lookup_values
        from jsonb_array_elements(kernel_work_rule_rows(%L::jsonb,$5)) image
      )$lookup$,'lookup_'||md5(lookup_node::text),lookup_node->>'field',lookup_request::text);
  end loop;
  execute format($sql$
    with images as materialized (select value image from jsonb_array_elements(kernel_work_rule_rows($4,$5)))%s
    select coalesce(jsonb_agg(jsonb_build_object('model_id',$6->>'model_id','record_id',image->>'record_id',
      'field_id',$6->>'field_id','value',jsonb_build_object('type',$7,'value',evaluated.value),'rule_id',$6->>'id')),'[]'::jsonb)
    from images cross join lateral (select %s as value from (select image as row_value) source_row) evaluated
  $sql$,lookup_ctes,compiled)
    using null::jsonb,rule->'expression',parameters,query_request,evaluation_state,rule,field_json->>'type' into changes;
  -- Stage against the original entries so the first baseline and replacements survive.
  staged_overlay := kernel_work_stage_overlay(request || jsonb_build_object('rule_id',rule->>'id'),session_state,
    session_state->'forks'->fork_id->'overlay',changes);
  -- Leaving the rule's match set removes its output and restores any displaced edit.
  with matched as materialized (
    select change->>'model_id' model_id,change->>'record_id' record_id,change->>'field_id' field_id
    from jsonb_array_elements(changes) change
  )
  select coalesce(jsonb_agg(case when entry->>'rule_id'=rule->>'id' and matched.record_id is null
    then entry->'replaced' else entry end order by ordinal),'[]'::jsonb) into staged_overlay
  from jsonb_array_elements(staged_overlay) with ordinality staged(entry,ordinal)
  left join matched on matched.model_id=entry->>'model_id' and matched.record_id=entry->>'record_id' and matched.field_id=entry->>'field_id'
  where entry->>'rule_id' is distinct from rule->>'id' or entry ? 'replaced' or matched.record_id is not null;
  return staged_overlay;
end;
$kernel$;

-- artifact: function kernel_work_helpers
create or replace function kernel_work_value(row_image jsonb,field_id text)
returns jsonb language sql immutable parallel safe as $kernel$
 select coalesce(row_image->'values'->field_id,(select value-'field_id' from jsonb_array_elements(coalesce(row_image->'custom_fields','[]')) where value->>'field_id'=field_id),'null'::jsonb)
$kernel$;

create or replace function kernel_work_same_value(a jsonb,b jsonb)
returns boolean language plpgsql immutable parallel safe as $kernel$
begin
 if a=b then return true; end if;
 if a->>'type' is distinct from b->>'type' then return false; end if;
 if a->>'type'='number' then return (a->>'value')::numeric=(b->>'value')::numeric; end if;
 if a->>'type'='money_rate' then return a#>'{value,currency}'=b#>'{value,currency}' and a#>'{value,period}'=b#>'{value,period}' and (a#>>'{value,amount}')::numeric=(b#>>'{value,amount}')::numeric; end if;
 return false;
end $kernel$;

-- Working state is owned by a trusted actor and never versions canonical data.
create or replace function kernel_work_actor(request jsonb)
returns text language plpgsql volatile security invoker set search_path from current as $kernel$
declare actor text;
begin
  perform kernel_read_scope_schema(request->>'app_id',request->>'customer_id');
  actor := kernel_policy_request_actor(request->>'app_id',request->>'customer_id');
  return actor;
end $kernel$;

-- Capture and authorize requested canonical targets once per model. This private
-- image is used only inside a work operation; read responses retain projections.
create or replace function kernel_work_canonical_map(request jsonb, session jsonb, changes jsonb)
returns jsonb language plpgsql volatile security invoker set search_path from current as $kernel$
declare schema_json jsonb; model jsonb; subject record; table_name text; fields jsonb; policy jsonb;
 result jsonb := '{}'::jsonb; batch jsonb; denied boolean; archived_fields jsonb; values_expression text; captured_grants jsonb;
begin
 schema_json:=kernel_read_scope_schema(request->>'app_id',request->>'customer_id');
 if request->>'schema_version' is distinct from schema_json->>'version' then raise exception 'schema_drift: generated operation schema version is stale'; end if;
 for subject in select value->>'model_id' model_id,jsonb_agg(value) entries from jsonb_array_elements(changes) group by 1 loop
  select value into model from jsonb_array_elements(schema_json->'models') where value->>'id'=subject.model_id;
  if model is null then raise exception 'record_target_missing: unknown model'; end if;
  if exists(select 1 from jsonb_array_elements(subject.entries) e where (e->>'record_id')::uuid::text is distinct from e->>'record_id') then raise exception 'authorization_denied: staged record is not visible'; end if;
  table_name:=kernel_draft_version_table(model);
  values_expression:=case when model->>'kind'='lookup' then format('kernel_read_lookup_values(%L::jsonb,live.values,''[]''::jsonb)',model::text) else kernel_read_field_values_expression('live',model,'[]'::jsonb) end;
  select jsonb_build_array('$id','$version')||coalesce(jsonb_agg(distinct value->>'field_id') filter(where value?'field_id'),'[]') into fields from jsonb_array_elements(subject.entries);
  policy:=kernel_policy_authorize_query(request->>'app_id',request->>'customer_id',subject.model_id,fields);
  captured_grants:=case when policy is null then null else kernel_policy_capture_grants(policy,subject.model_id,'read') end;
  if model->>'kind'='lookup' then perform kernel_read_assert_lookup_storage_authority(request->>'app_id',request->>'customer_id',subject.model_id); end if;
  perform kernel_read_assert_mainline_order(table_name,request->>'app_id',request->>'customer_id');
  select coalesce(jsonb_agg(f->>'field_id'),'[]') into archived_fields from jsonb_array_elements(coalesce(schema_json->'custom_fields','[]')) f
   where f->>'model_id'=subject.model_id and (coalesce(f->>'archived_at','')<>'' or coalesce(f->>'lifecycle','active')<>'active');
  if exists(select 1 from jsonb_array_elements_text(fields) f where f not in ('$id','$version','$externalKey')
   and (exists(select 1 from jsonb_array_elements(coalesce(model->'derived_fields','[]')) d where d->>'id'=f) or (not exists(select 1 from jsonb_array_elements(model->'fields') d where d->>'id'=f)
   and not exists(select 1 from jsonb_array_elements(coalesce(schema_json->'custom_fields','[]')) d where d->>'model_id'=subject.model_id and d->>'field_id'=f)))) then
   raise exception 'contract_validation_failed: unsupported select field';
  end if;
  execute format($query$
   with targets as materialized (
    select (entry->>'record_id')::uuid record_id,jsonb_build_array('$id','$version')||coalesce(jsonb_agg(distinct entry->>'field_id') filter(where entry?'field_id'),'[]') fields
    from jsonb_array_elements($1) entry group by 1
   ), images as materialized (
    select t.*,(%3$s) record_values,to_jsonb(live) latest,coalesce(case when not live.tombstones_record and not live.untombstones_record then to_jsonb(live) end,to_jsonb(ordinary)) image
    from targets t
    left join lateral (
     select v.* from %1$I v join change_set cs on cs.id=v.change_set_id and cs.app_id=v.app_id and cs.customer_id=v.customer_id
     where v.record_id=t.record_id and v.app_id=$2 and v.customer_id=$3 and v.stage='mainline' and cs.status='mainline' and cs.applied_order is not null
      and v.effective_start<=$4 and (v.effective_end is null or v.effective_end>=$4)%2$s
     order by v.effective_start desc,v.tombstones_record desc,v.untombstones_record desc,cs.applied_order desc,v.id desc limit 1
    ) live on true
    left join lateral (
     select v.* from %1$I v join change_set cs on cs.id=v.change_set_id and cs.app_id=v.app_id and cs.customer_id=v.customer_id
     where (live.id is null or live.tombstones_record or live.untombstones_record)
      and v.record_id=t.record_id and v.app_id=$2 and v.customer_id=$3 and v.stage='mainline' and cs.status='mainline' and cs.applied_order is not null
      and v.effective_start<=$4 and not v.tombstones_record and not v.untombstones_record%2$s
     order by (v.effective_end is null or v.effective_end>=$4) desc,v.effective_start desc,cs.applied_order desc,v.id desc limit 1
    ) ordinary on true
   ), record_images as materialized (
    select *,kernel_apply_policy_record_values(case when latest is not null and not (latest->>'tombstones_record')::boolean and not (latest->>'untombstones_record')::boolean then record_values else kernel_draft_record_values($5,image) end,image->'custom_fields',image->'metadata',image->'many_relations') policy_values from images
   )
   select coalesce(jsonb_object_agg(jsonb_build_array($5->>'id',record_id::text)::text,
    jsonb_build_object('record_id',record_id,'version_id',coalesce(latest->'id',image->'id'),'values',record_values,
     'custom_fields',kernel_read_custom_fields($8,$5->>'id',image->'custom_fields'),'policy_values',policy_values,'_archived',$7)
     ||case when latest is null or (latest->>'tombstones_record')::boolean or (latest->>'untombstones_record')::boolean then jsonb_build_object('gone','record_gone') else '{}'::jsonb end),'{}'),
    coalesce(bool_or(image is null or ($6 is not null and not kernel_policy_grants_record_allowed($6,fields,policy_values))),false)
   from record_images
  $query$,table_name,kernel_draft_model_filter(model,'v'),values_expression) into batch,denied
   using subject.entries,request->>'app_id',request->>'customer_id',(session->>'as_of')::date,model,captured_grants,archived_fields,schema_json;
  if denied then raise exception 'authorization_denied: staged record is not visible'; end if;
  result:=result||batch;
 end loop;
 return result;
end $kernel$;

create or replace function kernel_work_canonical_image(image jsonb, change jsonb)
returns jsonb language sql immutable as $kernel$
 select case when image?'gone' or image->'_archived' ? (change->>'field_id') then
   (image-array['_archived','policy_values'])||jsonb_build_object('values','{}'::jsonb,'custom_fields','[]'::jsonb)
    ||case when image?'gone' then '{}'::jsonb else jsonb_build_object('gone','field_archived') end
  else image-'_archived' end
$kernel$;

-- Private owner check for the existing query path. It does not inspect or
-- return canonical records; that query applies field/record policy afterward.
create or replace function kernel_work_state(request jsonb)
returns jsonb language plpgsql volatile security invoker set search_path from current as $kernel$
declare actor text; state jsonb;
begin
 actor:=kernel_work_actor(request);
 -- Header, fork metadata and record entries share one statement snapshot.
 select (to_jsonb(s)-'receipts')||jsonb_build_object('forks',(
  select coalesce(jsonb_object_agg(f.key,f.value||jsonb_build_object('overlay',coalesce((
   select jsonb_agg(e.value order by r.model_id,r.record_id,e.ordinality)
   from work_session_record r cross join lateral jsonb_array_elements(r.entries) with ordinality e(value,ordinality)
   where r.app_id=s.app_id and r.customer_id=s.customer_id and r.session_id=s.id and r.fork_id=f.key
  ),'[]'::jsonb))),'{}'::jsonb) from jsonb_each(s.forks) f
 )) into state from work_session s
 where s.app_id=request->>'app_id' and s.customer_id=request->>'customer_id'
  and s.id=(request->>'session_id')::uuid and s.owner_id=actor;
 if state is null then raise exception 'authorization_denied: session is unavailable'; end if;
 return state;
end $kernel$;

create or replace function kernel_work_state_targets(state jsonb)
returns jsonb language sql immutable as $kernel$
 select coalesce(jsonb_agg(entry),'[]'::jsonb) from (
  select e.value entry from jsonb_each(state->'forks') f cross join lateral jsonb_array_elements(f.value->'overlay') e
  union all
  select e.value from jsonb_each(state->'threads') t cross join lateral jsonb_array_elements(coalesce(t.value#>'{proposal,changes}','[]')) e
  union all
  select t.value->'anchor' from jsonb_each(state->'threads') t where t.value->'anchor' ?& array['model_id','record_id']
 ) targets
$kernel$;

create or replace function kernel_work_read(request jsonb)
returns jsonb language plpgsql volatile security invoker set search_path from current as $kernel$
declare state jsonb; fork record; entries jsonb; images jsonb; thread record; anchor jsonb; anchor_image jsonb;
begin
 state:=kernel_work_state(request);
 -- Authorization and freshness share one canonical capture, including proposals
 -- and anchors. Aggregate entries rather than repeatedly copying a growing array.
 images:=kernel_work_canonical_map(request,state,kernel_work_state_targets(state));
 for fork in select key,value from jsonb_each(state->'forks') loop
  with annotated as materialized (
   select entry,ordinal,kernel_work_canonical_image(images->(jsonb_build_array(entry->>'model_id',entry->>'record_id')::text),entry) canonical
   from jsonb_array_elements(fork.value->'overlay') with ordinality e(entry,ordinal)
  )
  select coalesce(jsonb_agg(entry || (case when canonical?'gone' then jsonb_build_object('gone',canonical->'gone') else '{}'::jsonb end) ||
   jsonb_build_object('stale',canonical?'gone' or canonical->'version_id' is distinct from entry->'base_version',
    'current_version',canonical->'version_id','current_value',kernel_work_value(canonical,entry->>'field_id')) order by ordinal),'[]') into entries
  from annotated;
  state:=jsonb_set(state,array['forks',fork.key,'overlay'],entries);
 end loop;
 for thread in select key,value from jsonb_each(state->'threads') loop
  if thread.value?'proposal' then
   with annotated as materialized (
    select entry,ordinal,kernel_work_canonical_image(images->(jsonb_build_array(entry->>'model_id',entry->>'record_id')::text),entry) canonical
    from jsonb_array_elements(coalesce(thread.value#>'{proposal,changes}','[]')) with ordinality e(entry,ordinal)
   )
   select coalesce(jsonb_agg(entry || (case when canonical?'gone' then jsonb_build_object('gone',canonical->'gone') else '{}'::jsonb end) order by ordinal),'[]') into entries
   from annotated;
   state:=jsonb_set(state,array['threads',thread.key,'proposal','changes'],entries);
  end if;
  anchor:=thread.value->'anchor';
  if anchor ?& array['model_id','record_id'] then
   anchor_image:=kernel_work_canonical_image(images->(jsonb_build_array(anchor->>'model_id',anchor->>'record_id')::text),anchor);
   if anchor_image?'gone' then state:=jsonb_set(state,array['threads',thread.key,'anchor'],anchor||jsonb_build_object('gone',anchor_image->'gone')); end if;
  end if;
 end loop;
 return state;
end $kernel$;

create or replace function kernel_work_stage_overlay(request jsonb, session jsonb, staged_overlay jsonb, changes jsonb)
returns jsonb language plpgsql volatile security invoker set search_path from current as $kernel$
declare change jsonb; prior jsonb; entry jsonb; canonical jsonb; baseline jsonb; replaced jsonb; result jsonb:=staged_overlay; actor text; source text; schema_json jsonb; model jsonb; field jsonb; v jsonb; policy jsonb; validation_write jsonb; issues jsonb; canonical_images jsonb; prior_entries jsonb; change_slots jsonb; changed_entries jsonb[]:=array[]::jsonb[]; changed_positions bigint[]:=array[]::bigint[]; change_key text; change_slot integer; change_position bigint:=0; write_grants jsonb:='{}'::jsonb; grant_model text; captured_grants jsonb;
begin
 actor := kernel_work_actor(request);
 select case when bool_and(actor_kind='human') then 'user' else 'agent' end into source from kernel_actor_membership m
 where m.principal_name=session_user::name and m.app_id=request->>'app_id' and m.customer_id=request->>'customer_id' and m.actor_id=actor and m.active;
 schema_json := kernel_read_scope_schema(request->>'app_id',request->>'customer_id');
 if jsonb_typeof(changes) is distinct from 'array' then raise exception 'contract_validation_failed: changes must be an array'; end if;
 -- Capture canonical targets together, including batch stages and proposals.
 if exists(select 1 from jsonb_array_elements(changes) c where jsonb_typeof(c) is distinct from 'object' or not(c ?& array['model_id','record_id','field_id','value'])) then raise exception 'contract_validation_failed: invalid staged change'; end if;
 canonical_images:=kernel_work_canonical_map(request,session,changes);
 policy:=kernel_policy_active_snapshot(request->>'app_id',request->>'customer_id')->'policy';
 if policy is not null and policy<>'null'::jsonb then
  for grant_model in select distinct c->>'model_id' from jsonb_array_elements(changes) c loop
   write_grants:=write_grants||jsonb_build_object(grant_model,kernel_policy_capture_grants(policy,grant_model,'update'));
  end loop;
 end if;
 -- Index the captured overlay once. Expanded SQL arrays hold one result slot
 -- per changed target; assemble the final JSON only after validating the batch.
 select coalesce(jsonb_object_agg(jsonb_build_array(e->>'model_id',e->>'record_id',e->>'field_id')::text,e),'{}') into prior_entries from jsonb_array_elements(staged_overlay) e;
 select coalesce(jsonb_object_agg(key,slot),'{}') into change_slots from (
  select key,row_number() over() slot from (
   select distinct jsonb_build_array(c->>'model_id',c->>'record_id',c->>'field_id')::text key from jsonb_array_elements(changes) c
  ) keys
 ) slots;
 for change in select value from jsonb_array_elements(changes) loop
  if jsonb_typeof(change) is distinct from 'object' or not(change ?& array['model_id','record_id','field_id','value']) then raise exception 'contract_validation_failed: invalid staged change'; end if;
  select value into model from jsonb_array_elements(schema_json->'models') where value->>'id'=change->>'model_id';
  select value into field from (
   select value from jsonb_array_elements(model->'fields')
   union all select value||jsonb_build_object('id',value->>'field_id','custom',true) from jsonb_array_elements(coalesce(schema_json->'custom_fields','[]')) where value->>'model_id'=change->>'model_id' and coalesce(value->>'archived_at','')='' and coalesce(value->>'lifecycle','active')='active'
  ) fields where value->>'id'=change->>'field_id';
  if field is null or field->>'readOnly'='true' or exists(select 1 from jsonb_array_elements(coalesce(model->'derived_fields','[]')) where value->>'id'=change->>'field_id') then raise exception 'contract_validation_failed: unsupported staged field'; end if;
  v := change->'value';
  validation_write:=jsonb_build_object('model_id',change->'model_id','record_key',jsonb_build_object('type','record_id','value',change->'record_id'),'effective_start',session->'as_of');
  if field->>'custom'='true' then
   if v='null'::jsonb then validation_write:=validation_write||jsonb_build_object('clear_custom_fields',jsonb_build_array(change->'field_id'));
   else validation_write:=validation_write||jsonb_build_object('custom_fields',jsonb_build_array(v||jsonb_build_object('field_id',change->'field_id'))); end if;
  else
   if v='null'::jsonb then validation_write:=validation_write||jsonb_build_object('clear_fields',jsonb_build_array(change->'field_id'));
   else validation_write:=validation_write||jsonb_build_object('values',jsonb_build_object(change->>'field_id',v)); end if;
  end if;
  issues:=kernel_apply_validation_issues(jsonb_build_object('app_id',request->'app_id','customer_id',request->'customer_id','writes',jsonb_build_array(validation_write)),schema_json);
  if jsonb_array_length(issues)>0 then raise exception using errcode='AR001',message=jsonb_build_object('ok',false,'error',jsonb_build_object('code','contract_validation_failed','message','Invalid staged value','details',issues))::text; end if;
  if v<>'null'::jsonb and field->>'type'='relation' and v#>>'{value,type}' is distinct from 'record_id' then raise exception 'contract_validation_failed: stage relations by immutable record id'; end if;
  canonical := kernel_work_canonical_image(canonical_images->(jsonb_build_array(change->>'model_id',change->>'record_id')::text),change);
  if canonical?'gone' then raise exception 'record_target_missing: staged target is gone'; end if;
  -- Apply the same write grant to the resulting image, not just the baseline.
  captured_grants:=write_grants->(change->>'model_id');
  if policy is not null and policy<>'null'::jsonb and (not kernel_policy_grants_fields_allowed(captured_grants,jsonb_build_array(change->>'field_id')) or not kernel_policy_grants_record_allowed(captured_grants,jsonb_build_array(change->>'field_id'),canonical->'policy_values') or not kernel_policy_grants_record_allowed(captured_grants,jsonb_build_array(change->>'field_id'),canonical->'policy_values'||jsonb_build_object(change->>'field_id',v))) then raise exception 'authorization_denied: staged write is not authorized'; end if;

  change_key:=jsonb_build_array(change->>'model_id',change->>'record_id',change->>'field_id')::text;
  change_slot:=(change_slots->>change_key)::integer;
  prior:=case when changed_positions[change_slot] is not null then changed_entries[change_slot] else prior_entries->change_key end;
  change_position:=change_position+1;
  changed_positions[change_slot]:=change_position;
  changed_entries[change_slot]:=null;
  baseline := case when prior is null then kernel_work_value(canonical,change->>'field_id') else prior->'baseline' end;
  replaced := prior->'replaced';
  if request->>'operation'='pull' then source:='agent'; end if;
  if change?'rule_id' and prior is not null and not(prior?'rule_id') then replaced:=prior-'stale'-'current_version'-'current_value';
  elsif source='agent' and (prior->>'author_kind' is distinct from 'agent' or (request->>'operation' is distinct from 'pull' and prior->>'author_principal' is distinct from session_user::text)) then replaced := prior-'stale'-'current_version'-'current_value'; end if;
  if (source='agent' or change?'rule_id') and replaced is not null and kernel_work_same_value(replaced->'value',v) then changed_entries[change_slot]:=replaced; continue; end if;
  if kernel_work_same_value(kernel_work_value(canonical,change->>'field_id'),v) and ((source<>'agent' and not(change?'rule_id')) or replaced is null) then continue; end if;
  entry := jsonb_build_object('model_id',change->'model_id','record_id',change->'record_id','field_id',change->'field_id','value',v,'baseline',baseline,
   'base_version',case when prior is null then canonical->'version_id' else prior->'base_version' end,'source',source,'actor_id',case when request->>'operation'='pull' then session->'threads'->(request->>'thread_id')->'proposal'->>'actor_id' else actor end,
   'author_principal',session_user::text,'author_kind',case when request->>'operation'='pull' or source='user' then 'human' else 'agent' end,
   'created_at',coalesce(prior->'created_at',to_jsonb(clock_timestamp())),'updated_at',clock_timestamp());
  if change?'rule_id' then entry:=entry||jsonb_build_object('rule_id',change->'rule_id'); end if;
  if change?'thread_id' then entry:=entry||jsonb_build_object('thread_id',change->'thread_id'); end if;
  if (source='agent' or change?'rule_id') and replaced is not null then entry:=entry||jsonb_build_object('replaced',replaced); end if;
  changed_entries[change_slot]:=entry;
 end loop;
 select coalesce(jsonb_agg(value order by position),'[]') into result from (
  select value,ordinality::bigint position from jsonb_array_elements(staged_overlay) with ordinality original(value,ordinality)
   where not(change_slots ? (jsonb_build_array(value->>'model_id',value->>'record_id',value->>'field_id')::text))
  union all
  select value,jsonb_array_length(staged_overlay)+changed_positions[ordinality::integer] from unnest(changed_entries) with ordinality changed(value,ordinality) where value is not null
 ) entries;
 return result;
end $kernel$;

create or replace function kernel_work_authorize_state(request jsonb, state jsonb)
returns void language plpgsql volatile security invoker set search_path from current as $kernel$
begin
 perform kernel_work_canonical_map(request,state,kernel_work_state_targets(state));
end $kernel$;

-- artifact: function kernel_work_session(jsonb)
create or replace function kernel_work_session(request jsonb)
returns jsonb language plpgsql volatile security invoker set search_path from current as $kernel$
declare actor text; actor_agent boolean; op text:=request->>'operation'; state jsonb; old_state jsonb; stored record; receipt jsonb; fingerprint text; work_id uuid;
 fork_id text:=coalesce(request->>'fork_id','main'); fork jsonb; staged_overlay jsonb; entry jsonb; result jsonb; thread_id text; thread jsonb; rule_id text; rule jsonb; changed jsonb; canonical jsonb;
 schema_json jsonb; writes jsonb:='[]'; write_value jsonb; subject record; apply_result jsonb; payload jsonb; guard jsonb; fork_metadata jsonb; canonical_versions jsonb; shown_proposal jsonb; canonical_images jsonb;
begin
  perform kernel_cleanup_generated_visible_query();
 if jsonb_typeof(request) is distinct from 'object' then raise exception 'contract_validation_failed: invalid work request'; end if;
 actor:=kernel_work_actor(request);
 schema_json:=kernel_read_scope_schema(request->>'app_id',request->>'customer_id');
 if request->>'schema_version' is distinct from schema_json->>'version' then raise exception 'schema_drift: generated work operation schema version is stale'; end if;
 select not bool_and(m.actor_kind='human') into actor_agent from kernel_actor_membership m where m.principal_name=session_user::name and m.app_id=request->>'app_id' and m.customer_id=request->>'customer_id' and m.actor_id=actor and m.active;
 if actor_agent and op in ('create','save','archive','unarchive','update','pin','fork_create','fork_rename','fork_choose','fork_discard','thread_resolve','pull') then raise exception 'authorization_denied: operation requires a human'; end if;
 if op='list' then
  select coalesce(jsonb_agg(to_jsonb(s)-'receipts' order by s.pinned desc,s.updated_at desc,s.id),'[]') into result from work_session s where s.app_id=request->>'app_id' and s.customer_id=request->>'customer_id' and s.owner_id=actor and s.status=coalesce(request->>'status','active');
  -- List headers only; staged values are read through get under current grants.
  select coalesce(jsonb_agg(value-'forks'-'threads'),'[]') into result from jsonb_array_elements(result);
  return jsonb_build_object('ok',true,'data',result);
 end if;
 if op='get' then return jsonb_build_object('ok',true,'data',kernel_work_read(request)); end if;
 if coalesce(btrim(request->>'request_id'),'')='' or coalesce(request->>'expected_revision','') !~ '^[0-9]+$' then raise exception 'contract_validation_failed: mutation requires request_id and expected_revision'; end if;
 guard:=kernel_http_mutation_guard(request,'kernel_work_session');
 if guard?'ok' then return guard; end if;
 work_id:=(request->>'session_id')::uuid;
 if work_id is null then raise exception 'contract_validation_failed: session_id is required'; end if;
 fingerprint:=encode(sha256(convert_to(kernel_canonical_json(request),'UTF8')),'hex');
 -- Serialize create/replay before a row exists, and later mutations with it.
 perform pg_advisory_xact_lock(hashtextextended((request->>'app_id')||':'||(request->>'customer_id')||':work:'||work_id::text,0));
 select s.* into stored from work_session s where s.app_id=request->>'app_id' and s.customer_id=request->>'customer_id' and s.id=work_id and s.owner_id=actor for update;
 if found then
  receipt:=stored.receipts->(request->>'request_id');
