  end if;
  if stored.revision<>(request->>'expected_revision')::bigint then raise exception 'revision_conflict: session changed'; end if;
  if stored.status<>'active' and op<>'unarchive' then raise exception 'revision_conflict: session is archived'; end if;
  state:=kernel_work_state(request);
  old_state:=state;
  perform kernel_work_authorize_state(request,state);
