 with desired as materialized (
  select distinct f.key fork_id,e.value->>'model_id' model_id,(e.value->>'record_id')::uuid record_id
  from jsonb_each(state->'forks') f cross join lateral jsonb_array_elements(f.value->'overlay') e
 )
 delete from work_session_record r where r.app_id=request->>'app_id' and r.customer_id=request->>'customer_id' and r.session_id=work_id
  and not exists(select 1 from desired d where d.fork_id=r.fork_id and d.model_id=r.model_id and d.record_id=r.record_id);
 with desired as materialized (
  select f.key fork_id,e.value->>'model_id' model_id,(e.value->>'record_id')::uuid record_id,jsonb_agg(e.value order by e.ordinality) entries
  from jsonb_each(state->'forks') f cross join lateral jsonb_array_elements(f.value->'overlay') with ordinality e(value,ordinality)
  group by f.key,e.value->>'model_id',(e.value->>'record_id')::uuid
 ), previous as materialized (
  select f.key fork_id,e.value->>'model_id' model_id,(e.value->>'record_id')::uuid record_id,jsonb_agg(e.value order by e.ordinality) entries
  from jsonb_each(old_state->'forks') f cross join lateral jsonb_array_elements(f.value->'overlay') with ordinality e(value,ordinality)
  group by f.key,e.value->>'model_id',(e.value->>'record_id')::uuid
 )
 insert into work_session_record(app_id,customer_id,session_id,fork_id,model_id,record_id,entries)
 select request->>'app_id',request->>'customer_id',work_id,d.fork_id,d.model_id,d.record_id,d.entries
 from (select * from desired except select * from previous) d
 on conflict on constraint work_session_record_pkey do update set entries=excluded.entries
 where work_session_record.entries is distinct from excluded.entries;
 end if;
 result:=jsonb_build_object('ok',true,'data',case when op='save' then jsonb_build_object('session',state,'change_set',apply_result->'data') else state end);
 update work_session s set receipts=s.receipts||jsonb_build_object(request->>'request_id',jsonb_strip_nulls(jsonb_build_object('fingerprint',fingerprint,'revision',state->'revision','change_set',case when op='save' then apply_result->'data' end))) where s.app_id=request->>'app_id' and s.customer_id=request->>'customer_id' and s.id=work_id;
