-- artifact: function kernel_lookup_migration_snapshot(jsonb,jsonb)
create or replace function kernel_lookup_migration_snapshot(row_json jsonb, model_json jsonb)
returns jsonb
language plpgsql
stable
security invoker
set search_path from current
as $kernel_lookup_migration$
declare
  result jsonb := case
    when jsonb_typeof(row_json->'values') = 'object' then row_json->'values'
    else '{}'::jsonb
  end;
  field_json jsonb;
  field_id text;
  field_type text;
  identifier text;
  scalar jsonb;
  amount jsonb;
  currency jsonb;
  period jsonb;
begin
  if coalesce((row_json->>'tombstones_record')::boolean, false)
    or coalesce((row_json->>'untombstones_record')::boolean, false)
  then
    return '{}'::jsonb;
  end if;

  for field_json in
    select value
    from jsonb_array_elements(coalesce(model_json->'fields', '[]'::jsonb)) item(value)
    order by item.value->>'id'
  loop
    field_id := field_json->>'id';
    field_type := field_json->>'type';
    identifier := kernel_physical_identifier(field_id);

    if field_type = 'money_rate' then
      amount := row_json->kernel_physical_identifier(field_id || '_amount');
      currency := row_json->kernel_physical_identifier(field_id || '_currency');
      period := row_json->kernel_physical_identifier(field_id || '_period');
      if amount is not null and amount <> 'null'::jsonb then
        result := result || jsonb_build_object(field_id, jsonb_build_object(
          'type', 'money_rate',
          'value', jsonb_build_object(
            'amount', amount #>> '{}',
            'currency', currency #>> '{}',
            'period', period #>> '{}'
          )
        ));
      end if;
      continue;
    end if;

    scalar := row_json->identifier;
    if scalar is null or scalar = 'null'::jsonb then
      continue;
    end if;
    if field_type in ('text', 'iso_country', 'iso_currency') then
      result := result || jsonb_build_object(
        field_id, jsonb_build_object('type', 'text', 'value', scalar)
      );
    elsif field_type = 'enum' then
      result := result || jsonb_build_object(
        field_id, jsonb_build_object('type', 'enum', 'value', scalar)
      );
    elsif field_type = 'number' then
      result := result || jsonb_build_object(
        field_id, jsonb_build_object('type', 'number', 'value', scalar #>> '{}')
      );
    elsif field_type = 'bool' then
      result := result || jsonb_build_object(
        field_id, jsonb_build_object('type', 'bool', 'value', scalar)
      );
    elsif field_type = 'date' then
      result := result || jsonb_build_object(
        field_id, jsonb_build_object('type', 'date', 'value', scalar)
      );
    elsif field_type = 'datetime' then
      result := result || jsonb_build_object(
        field_id, jsonb_build_object('type', 'datetime', 'value', scalar)
      );
    elsif field_type = 'relation' then
      result := result || jsonb_build_object(field_id, jsonb_build_object(
        'type', 'relation',
        'value', jsonb_build_object('type', 'record_id', 'value', scalar)
      ));
    elsif field_type in ('text_list', 'known_aliases') then
      result := result || jsonb_build_object(
        field_id, jsonb_build_object('type', 'text_list', 'value', scalar)
      );
    elsif field_type = 'json' then
      result := result || jsonb_build_object(
        field_id, jsonb_build_object('type', 'json', 'value', scalar)
      );
    else
      raise exception 'unsupported lookup field type `%` for `%.%`',
        field_type, model_json->>'id', field_id;
    end if;
  end loop;
  return result;
end;
$kernel_lookup_migration$;

-- artifact: function kernel_lookup_migration_block_legacy_write()
create or replace function kernel_lookup_migration_block_legacy_write()
returns trigger
language plpgsql
volatile
security invoker
set search_path from current
as $kernel_lookup_migration$
begin
  raise exception using
    errcode = '55000',
    message = 'legacy_lookup_authority_retired: writes must use the generated lookup API';
end;
$kernel_lookup_migration$;

-- artifact: function kernel_lookup_migration_mark_generic_write()
create or replace function kernel_lookup_migration_mark_generic_write()
returns trigger
language plpgsql
volatile
security invoker
set search_path from current
as $kernel_lookup_migration$
begin
  update lookup_storage_authority
  set first_generic_write_at = coalesce(first_generic_write_at, clock_timestamp())
  where app_id = new.app_id
    and customer_id = new.customer_id
    and model_id = new.model_id
    and authority = 'generic';
  return new;
end;
$kernel_lookup_migration$;

do $kernel_lookup_migration$
begin
  if not exists (
    select 1 from pg_trigger
    where tgrelid = to_regclass(format('%I.lookup_version', current_schema()))
      and tgname = 'lookup_version_mark_generic_write'
      and not tgisinternal
  ) then
    create trigger lookup_version_mark_generic_write
      after insert on lookup_version
      for each row execute function kernel_lookup_migration_mark_generic_write();
  end if;
end
$kernel_lookup_migration$;

-- artifact: function kernel_lookup_storage_authority_error(text,text,text)
create or replace function kernel_lookup_storage_authority_error(
  requested_app_id text,
  requested_customer_id text,
  requested_model_id text
)
returns jsonb
language plpgsql
volatile
security invoker
set search_path from current
as $kernel_lookup_authority$
declare
  storage_authority text;
begin
  perform set_config('kernel.app_id', requested_app_id, true);
  perform set_config('kernel.customer_id', requested_customer_id, true);
  perform pg_advisory_xact_lock_shared(hashtext(
    'postgres-schema:' || current_schema() || ':materialize-tenant:' ||
    requested_app_id || ':' || requested_customer_id || ':lookup-migration'
  ));
  select authority.authority into storage_authority
  from lookup_storage_authority authority
  where authority.app_id = requested_app_id
    and authority.customer_id = requested_customer_id
    and authority.model_id = requested_model_id;
  if storage_authority = 'typed' then
    return jsonb_build_object(
      'code', 'lookup_storage_authority_mismatch',
      'message', 'Lookup storage authority mismatch',
      'details', jsonb_build_array(jsonb_build_object(
        'path', 'model_id',
        'code', 'lookup_storage_authority_mismatch',
        'message', format(
          'generic lookup storage is not authoritative for `%s/%s/%s`',
          requested_app_id, requested_customer_id, requested_model_id
        )
      ))
    );
  end if;
  return null;
end;
$kernel_lookup_authority$;

-- artifact: function kernel_lookup_migration_model_evidence(text,text,text,jsonb)
create or replace function kernel_lookup_migration_model_evidence(
  requested_app_id text,
  requested_customer_id text,
  requested_model_id text,
  model_json jsonb
)
returns jsonb
language plpgsql
stable
security invoker
set search_path from current
as $kernel_lookup_migration$
declare
  record_table text := kernel_physical_identifier(requested_model_id || '_record');
  version_table text := kernel_physical_identifier(requested_model_id || '_version');
  source_record_count bigint;
  target_record_count bigint;
  source_version_count bigint;
  target_version_count bigint;
  source_record_hash text;
  target_record_hash text;
  source_history_hash text;
  target_history_hash text;
begin
  execute format($evidence$
    select count(*)::bigint, md5(coalesce(string_agg(canonical::text, E'\n' order by id), ''))
    from (
      select r.id, jsonb_build_object(
        'id', r.id,
        'external_key', r.external_key,
        'created_at', r.created_at
      ) canonical
      from %I r
      where r.app_id = $1 and r.customer_id = $2
    ) rows
  $evidence$, record_table)
  using requested_app_id, requested_customer_id
  into source_record_count, source_record_hash;

  select count(*)::bigint,
    md5(coalesce(string_agg(canonical::text, E'\n' order by id), ''))
  into target_record_count, target_record_hash
  from (
    select r.id, jsonb_build_object(
      'id', r.id,
      'external_key', r.external_key,
      'created_at', r.created_at
    ) canonical
    from lookup_record r
    where r.app_id = requested_app_id
      and r.customer_id = requested_customer_id
      and r.model_id = requested_model_id
  ) rows;

  execute format($evidence$
    select count(*)::bigint, md5(coalesce(string_agg(canonical::text, E'\n' order by id), ''))
    from (
      select v.id, jsonb_build_object(
        'id', v.id,
        'record_id', v.record_id,
        'stage', v.stage,
        'effective_start', v.effective_start,
        'effective_end', v.effective_end,
        'change_set_id', v.change_set_id,
        'created_at', v.created_at,
        'applied_at', v.applied_at,
        'applied_order', cs.applied_order,
        'tombstones_record', v.tombstones_record,
        'untombstones_record', v.untombstones_record,
        'availability', coalesce(to_jsonb(v)->>'availability', 'active'),
        'provenance', to_jsonb(v)->'provenance',
        'custom_fields', coalesce(to_jsonb(v)->'custom_fields', '[]'::jsonb),
        'metadata', coalesce(to_jsonb(v)->'metadata', '{}'::jsonb),
        'many_relations', coalesce(to_jsonb(v)->'many_relations', '{}'::jsonb),
        'values', kernel_lookup_migration_snapshot(to_jsonb(v), $3)
      ) canonical
      from %I v
      join change_set cs
        on cs.id = v.change_set_id
       and cs.app_id = v.app_id
       and cs.customer_id = v.customer_id
      where v.app_id = $1 and v.customer_id = $2
    ) rows
  $evidence$, version_table)
  using requested_app_id, requested_customer_id, model_json
  into source_version_count, source_history_hash;

  select count(*)::bigint,
    md5(coalesce(string_agg(canonical::text, E'\n' order by id), ''))
  into target_version_count, target_history_hash
  from (
    select v.id, jsonb_build_object(
      'id', v.id,
      'record_id', v.record_id,
      'stage', v.stage,
      'effective_start', v.effective_start,
      'effective_end', v.effective_end,
      'change_set_id', v.change_set_id,
      'created_at', v.created_at,
      'applied_at', v.applied_at,
      'applied_order', cs.applied_order,
      'tombstones_record', v.tombstones_record,
      'untombstones_record', v.untombstones_record,
      'availability', v.availability,
      'provenance', to_jsonb(v)->'provenance',
      'custom_fields', v.custom_fields,
      'metadata', v.metadata,
      'many_relations', v.many_relations,
      'values', v.values
    ) canonical
    from lookup_version v
    join change_set cs
      on cs.id = v.change_set_id
     and cs.app_id = v.app_id
     and cs.customer_id = v.customer_id
    where v.app_id = requested_app_id
      and v.customer_id = requested_customer_id
      and v.model_id = requested_model_id
  ) rows;

  return jsonb_build_object(
    'source_record_count', source_record_count,
    'target_record_count', target_record_count,
    'source_record_hash', source_record_hash,
    'target_record_hash', target_record_hash,
    'source_version_count', source_version_count,
    'target_version_count', target_version_count,
    'source_history_hash', source_history_hash,
    'target_history_hash', target_history_hash,
    'matches', source_record_count = target_record_count
      and source_version_count = target_version_count
      and source_record_hash = target_record_hash
      and source_history_hash = target_history_hash
  );
end;
$kernel_lookup_migration$;

-- artifact: function kernel_prepare_lookup_migration(jsonb)
create or replace function kernel_prepare_lookup_migration(request jsonb)
returns jsonb
language plpgsql
volatile
security invoker
set search_path from current
as $kernel_lookup_migration$
#variable_conflict use_variable
<<prepare_lookup_migration>>
declare
  app_id text := request->>'app_id';
  customer_id text := request->>'customer_id';
  schema_revision_id bigint;
  expected_schema_hash text := request->>'expected_schema_hash';
  batch_size integer := 1000;
  schema_json jsonb;
  stored_schema_hash text;
  model_json jsonb;
  model_id text;
  record_table text;
  version_table text;
  authority_row record;
  expected_columns text[];
  target_model_column text;
  column_row record;
  has_data boolean;
  phase_row record;
  row_data jsonb;
  row_count integer;
  cursor_value uuid;
  snapshot jsonb;
  evidence jsonb;
  projected_is_current boolean;
  recovery_seeds jsonb;
  recovered_first_write timestamptz;
  recovery_has_typed_history boolean;
begin
  if request is null or jsonb_typeof(request) <> 'object'
    or request - array['app_id', 'customer_id', 'schema_revision_id', 'expected_schema_hash', 'batch_size'] <> '{}'::jsonb
    or app_id is null or btrim(app_id) = ''
    or customer_id is null or btrim(customer_id) = ''
    or jsonb_typeof(request->'schema_revision_id') is distinct from 'number'
    or (request->>'schema_revision_id')::numeric <> trunc((request->>'schema_revision_id')::numeric)
    or (request->>'schema_revision_id')::numeric <= 0
    or (request->>'schema_revision_id')::numeric > 9223372036854775807
    or (
      request ? 'batch_size' and (
        jsonb_typeof(request->'batch_size') <> 'number'
        or (request->>'batch_size')::numeric <> trunc((request->>'batch_size')::numeric)
        or (request->>'batch_size')::numeric < 1
        or (request->>'batch_size')::numeric > 10000
      )
    )
    or expected_schema_hash is null
    or expected_schema_hash !~ '^[0-9a-f]{64}$'
  then
    return kernel_lookup_migration_error(
      'contract_validation_failed',
      'Lookup migration request is invalid',
      'app_id, customer_id, schema_revision_id, and expected_schema_hash are required'
    );
  end if;
  schema_revision_id := (request->>'schema_revision_id')::bigint;
  if request ? 'batch_size' then
    batch_size := (request->>'batch_size')::integer;
  end if;

  perform set_config('kernel.app_id', app_id, true);
  perform set_config('kernel.customer_id', customer_id, true);
  perform pg_advisory_xact_lock(hashtext(
    'postgres-schema:' || current_schema() || ':materialize-tenant:' || app_id || ':' || customer_id || ':lookup-migration'
  ));

  select revision.schema, revision.schema_hash
  into schema_json, stored_schema_hash
  from schema_revision revision
  where revision.id = schema_revision_id
    and revision.app_id = app_id
    and revision.customer_id = customer_id
    and revision.activated_at is not null;
  if schema_json is null then
    return kernel_lookup_migration_error(
      'stale_schema_revision', 'The supplied schema revision is not active',
      'the requested tenant schema revision is not the active head'
    );
  end if;
  if stored_schema_hash is distinct from expected_schema_hash then
    return kernel_lookup_migration_error(
      'stale_schema_hash', 'Schema hash changed',
      'the requested schema hash does not match the persisted revision'
    );
  end if;

  insert into lookup_migration_revision(
    app_id, customer_id, schema_hash, schema_revision_id, status, updated_at
  ) values (
    app_id, customer_id, expected_schema_hash, schema_revision_id, 'preparing', now()
  )
  on conflict on constraint lookup_migration_revision_pkey do update
  set schema_revision_id = excluded.schema_revision_id,
      status = case
        when lookup_migration_revision.status = 'active' then 'active'
        else 'preparing'
      end,
      updated_at = now();

  for model_json in
    select value
    from jsonb_array_elements(coalesce(schema_json->'models', '[]'::jsonb)) item(value)
    where coalesce(value->>'kind', 'entity') = 'lookup'
    order by value->>'id'
  loop
    model_id := model_json->>'id';
    record_table := kernel_physical_identifier(model_id || '_record');
    version_table := kernel_physical_identifier(model_id || '_version');
    if record_table = 'lookup_record' or version_table = 'lookup_version' then
      return kernel_lookup_migration_error(
        'legacy_table_name_collision', 'Legacy lookup table name is ambiguous',
        format('lookup model `%s` collides with the generic substrate', model_id)
      );
    end if;

    select * into authority_row
    from lookup_storage_authority authority
    where authority.app_id = app_id
      and authority.customer_id = customer_id
      and authority.model_id = model_id;
    if not found and (
      exists(
        select 1 from lookup_record generic_record
        where generic_record.app_id = app_id
          and generic_record.customer_id = customer_id
          and generic_record.model_id = model_id
      ) or exists(
        select 1 from lookup_version generic_version
        where generic_version.app_id = app_id
          and generic_version.customer_id = customer_id
          and generic_version.model_id = model_id
      )
    ) then
      -- Older native installers omitted authority when empty legacy tables
      -- existed. Recover only history fully attributed to immutable applied seeds.
      -- Hold writers while checking provenance and publishing the missing authority.
      begin
      lock table lookup_record, lookup_version, lookup_storage_authority, installed_seed, change_set in share row exclusive mode nowait;
      recovery_has_typed_history := false;
      for target_model_column in select unnest(array[record_table, version_table]) loop
        if to_regclass(format('%I.%I', current_schema(), target_model_column)) is not null then
          execute format('lock table %I in share row exclusive mode nowait', target_model_column);
          execute format('select exists(select 1 from %I where app_id=$1 and customer_id=$2)', target_model_column)
            into has_data using app_id, customer_id;
          recovery_has_typed_history := recovery_has_typed_history or has_data;
        end if;
      end loop;
      recovery_seeds := null;
      if not recovery_has_typed_history then
        select installation.seed_change_sets into recovery_seeds
        from schema_installation_revision installation
        join schema_revision revision on revision.id=installation.schema_revision_id
        where installation.app_id=app_id and installation.customer_id=customer_id
          and installation.schema_revision_id=schema_revision_id
          and installation.activated_at is not null and revision.activated_at is not null
          and revision.app_id=app_id and revision.customer_id=customer_id
          and installation.effective_artifact_hash=expected_schema_hash
          and revision.schema_hash=expected_schema_hash
        for share of installation, revision nowait;
      end if;
      recovered_first_write := null;
      if recovery_seeds is not null then
        with seed_writes as (
          select template.value as template, write.value as seed_write,
            (template.value->'seed_record_ids'->>(write.ordinality::integer-1))::uuid as record_id
          from jsonb_array_elements(recovery_seeds) template(value)
          cross join lateral jsonb_array_elements(template.value->'writes') with ordinality write(value,ordinality)
          where write.value->>'model_id'=model_id
        ), verified as (
          select seed.record_id, ledger.change_set_id, changes.applied_at
          from seed_writes seed
          join installed_seed ledger on ledger.app_id=app_id and ledger.customer_id=customer_id
            and ledger.seed_identity=seed.template->>'seed_identity'
          join change_set changes on changes.id=ledger.change_set_id
            and changes.app_id=app_id and changes.customer_id=customer_id
          where ledger.install_status='applied'
            and ledger.payload_fingerprint=kernel_admin_sha256(kernel_canonical_json(seed.template))
            and ledger.source_idempotency_key=seed.template->>'idempotency_key'
            and ledger.seed_record_ids=array(select value::uuid from jsonb_array_elements_text(seed.template->'seed_record_ids'))
            and changes.schema_revision_id=schema_revision_id
            and changes.idempotency_key=ledger.source_idempotency_key
            and changes.status='mainline' and changes.applied_order is not null and changes.applied_at is not null
        )
        select min(verified.applied_at) into recovered_first_write
        from verified
        where not exists (
          select 1 from lookup_record record
          where record.app_id=app_id and record.customer_id=customer_id and record.model_id=model_id
            and not exists(select 1 from verified seed where seed.record_id=record.id)
        ) and not exists (
          select 1 from lookup_version version
          where version.app_id=app_id and version.customer_id=customer_id and version.model_id=model_id
            and (not exists(select 1 from verified seed where seed.record_id=version.record_id and seed.change_set_id=version.change_set_id)
              or not exists(select 1 from lookup_record record where record.app_id=app_id and record.customer_id=customer_id and record.model_id=model_id and record.id=version.record_id))
        ) and exists (
          select 1 from lookup_version version where version.app_id=app_id and version.customer_id=customer_id and version.model_id=model_id
        ) and (select count(*) from lookup_version version where version.app_id=app_id and version.customer_id=customer_id and version.model_id=model_id)=(select count(*) from verified)
          and (select count(*) from lookup_record record where record.app_id=app_id and record.customer_id=customer_id and record.model_id=model_id)=(select count(distinct record_id) from verified)
          and not exists(select 1 from lookup_storage_authority authority where authority.app_id=app_id and authority.customer_id=customer_id and authority.model_id=model_id);
      end if;
      if recovered_first_write is null then
        return kernel_lookup_migration_error(
          'lookup_migration_forward_only', 'Generic lookup authority is forward-only',
          format('lookup model `%s` already contains generic data without a typed authority row', model_id)
        );
      end if;
      insert into lookup_storage_authority(
        app_id,customer_id,model_id,schema_hash,authority,legacy_record_table,legacy_version_table,activated_at,first_generic_write_at
      ) values(app_id,customer_id,model_id,expected_schema_hash,'generic','lookup_record','lookup_version',now(),recovered_first_write)
      on conflict on constraint lookup_storage_authority_pkey do nothing;
      select * into authority_row from lookup_storage_authority authority
      where authority.app_id=app_id and authority.customer_id=customer_id and authority.model_id=model_id;
      exception when lock_not_available then
        return kernel_lookup_migration_error(
          'lookup_recovery_busy', 'Lookup authority recovery is busy',
          'another database writer is active; retry normal lookup preparation after it completes'
        );
      end;

    end if;
    if found and authority_row.authority = 'generic' then
      if authority_row.schema_hash <> expected_schema_hash then
        if exists(
          select 1
          from schema_installation_revision installation
          join schema_revision revision on revision.id = installation.schema_revision_id
          where installation.schema_revision_id = schema_revision_id
            and installation.app_id = app_id
            and installation.customer_id = customer_id
            and installation.activated_at is not null
            and installation.effective_artifact_hash = expected_schema_hash
            and revision.schema_hash = expected_schema_hash
            and exists (
              select 1
              from lookup_migration_revision prior_migration
              where prior_migration.app_id = app_id
                and prior_migration.customer_id = customer_id
                and prior_migration.schema_hash = authority_row.schema_hash
                and prior_migration.status = 'active'
            )
        ) or exists(
          select 1
          from schema_revision prior_revision
          where prior_revision.app_id = app_id
            and prior_revision.customer_id = customer_id
            and prior_revision.schema_hash = authority_row.schema_hash
            and kernel_installer_default_model_kind(prior_revision.schema) - 'version'
              = schema_json - 'version'
        ) then
          update lookup_storage_authority authority
          set schema_hash = expected_schema_hash
          where authority.app_id = app_id
            and authority.customer_id = customer_id
            and authority.model_id = model_id
            and authority.authority = 'generic'
            and authority.schema_hash = authority_row.schema_hash;
        else
          return kernel_lookup_migration_error(
            'lookup_migration_forward_only', 'Generic lookup authority is forward-only',
            format('lookup model `%s` is already generic under a different schema hash', model_id)
          );
        end if;
      end if;
      -- Recover absent identities before comparing the shadow, without
      -- rewriting existing identities, versions, or projections. Identity-only
      -- loss must not replay already-migrated history through current write
      -- validation. Retained typed tables may be gone after a completed release.
      if to_regclass(format('%I.%I', current_schema(), record_table)) is not null then
        execute format(
          'insert into lookup_record(app_id, customer_id, model_id, id, external_key, created_at) '
          || 'select $1, $2, $3, record.id, record.external_key, record.created_at '
          || 'from %I record '
          || 'where record.app_id = $1 and record.customer_id = $2 '
          || 'on conflict on constraint lookup_record_pkey do nothing',
          record_table
        ) using app_id, customer_id, model_id;
      end if;
      -- Generic authority remains forward-only after its first generic write.
      if authority_row.first_generic_write_at is not null then
        continue;
      end if;
      if to_regclass(format('%I.%I', current_schema(), record_table)) is null
        or to_regclass(format('%I.%I', current_schema(), version_table)) is null
      then
        return kernel_lookup_migration_error(
          'legacy_lookup_table_missing', 'Legacy lookup storage is missing',
          format('typed tables for lookup model `%s` are not available', model_id)
        );
      end if;
      evidence := kernel_lookup_migration_model_evidence(app_id, customer_id, model_id, model_json);
      if coalesce((evidence->>'matches')::boolean, false) then
        continue;
      end if;
      update lookup_migration_phase
      set status = 'pending', cursor_id = null, completed_at = null, last_error = null
      where lookup_migration_phase.app_id = app_id
        and lookup_migration_phase.customer_id = customer_id
        and lookup_migration_phase.schema_hash = expected_schema_hash
        and lookup_migration_phase.model_id = model_id;
    end if;

    if to_regclass(format('%I.%I', current_schema(), record_table)) is null
      or to_regclass(format('%I.%I', current_schema(), version_table)) is null
    then
      return kernel_lookup_migration_error(
        'legacy_lookup_table_missing', 'Legacy lookup storage is missing',
        format('typed tables for lookup model `%s` are not available', model_id)
      );
    end if;

    insert into lookup_storage_authority(
      app_id, customer_id, model_id, schema_hash, authority,
      legacy_record_table, legacy_version_table
    ) values (
      app_id, customer_id, model_id, expected_schema_hash, 'typed',
      record_table, version_table
    )
    on conflict on constraint lookup_storage_authority_pkey do update
    set schema_hash = excluded.schema_hash,
        legacy_record_table = excluded.legacy_record_table,
        legacy_version_table = excluded.legacy_version_table
    where lookup_storage_authority.authority = 'typed';

    expected_columns := array[
      'id', 'record_id', 'app_id', 'customer_id', 'stage', 'effective_start',
      'effective_end', 'change_set_id', 'created_at', 'applied_at',
      'tombstones_record', 'untombstones_record', 'provenance', 'custom_fields',
      'metadata', 'many_relations', 'availability', 'values'
    ];
    for column_row in
      select value
      from jsonb_array_elements(coalesce(model_json->'fields', '[]'::jsonb)) item(value)
    loop
      if column_row.value->>'type' = 'money_rate' then
        expected_columns := expected_columns || array[
          kernel_physical_identifier((column_row.value->>'id') || '_amount'),
          kernel_physical_identifier((column_row.value->>'id') || '_currency'),
          kernel_physical_identifier((column_row.value->>'id') || '_period')
        ];
      else
        expected_columns := expected_columns || kernel_physical_identifier(column_row.value->>'id');
      end if;
      if column_row.value->>'type' = 'relation' then
        target_model_column := kernel_physical_identifier((column_row.value->>'id') || '_target_model');
        expected_columns := expected_columns || target_model_column;
        if exists (
          select 1 from information_schema.columns
          where table_schema = current_schema() and table_name = version_table
            and column_name = target_model_column
        ) then
          execute format(
            'select exists(select 1 from %I where app_id = $1 and customer_id = $2 and %I is not null and %I <> $3)',
            version_table, target_model_column, target_model_column
          ) using app_id, customer_id, column_row.value->>'target_model' into has_data;
          if has_data then
            return kernel_lookup_migration_error(
              'legacy_relation_target_mismatch', 'Legacy relation target cannot be represented',
              format('relation `%s.%s` contains a target-model discriminator that differs from `%s`', model_id, column_row.value->>'id', column_row.value->>'target_model')
            );
          end if;
        end if;
      end if;
    end loop;
    for column_row in
      select column_name
      from information_schema.columns
      where table_schema = current_schema()
        and table_name = version_table
        and not (column_name = any(expected_columns))
      order by ordinal_position
    loop
      execute format(
        'select exists(select 1 from %I where app_id = $1 and customer_id = $2 and %I is not null)',
        version_table, column_row.column_name
      ) using app_id, customer_id into has_data;
      if has_data then
        return kernel_lookup_migration_error(
          'unclassified_legacy_column', 'Legacy lookup data cannot be represented',
          format('column `%s.%s` contains data but is absent from the logical lookup model', version_table, column_row.column_name)
        );
      end if;
    end loop;

    insert into lookup_migration_phase(
      app_id, customer_id, schema_hash, model_id, phase
    )
    select app_id, customer_id, expected_schema_hash, model_id, phase
    from unnest(array['records', 'versions', 'projections', 'verify']) phase
    on conflict do nothing;
  end loop;

  -- Establish typed authority before reconciliation. The reconciliation may
  -- create value-free generic identities retained by typed entity history;
  -- those identities are migration input, not evidence of prior generic
  -- authority.
  perform kernel_reconcile_lookup_foreign_key_targets(app_id, customer_id);

  -- Records for every model must exist before relation-bearing versions are copied.
  for model_json in
    select value from jsonb_array_elements(coalesce(schema_json->'models', '[]'::jsonb)) item(value)
    where coalesce(value->>'kind', 'entity') = 'lookup'
    order by value->>'id'
  loop
    model_id := model_json->>'id';
    select * into authority_row from lookup_storage_authority authority
    where authority.app_id = app_id and authority.customer_id = customer_id
      and authority.model_id = model_id;
    if authority_row.authority = 'generic' and authority_row.first_generic_write_at is not null then continue; end if;
    record_table := authority_row.legacy_record_table;
    select * into phase_row from lookup_migration_phase phase
    where phase.app_id = app_id and phase.customer_id = customer_id
      and phase.schema_hash = expected_schema_hash and phase.model_id = model_id
      and phase.phase = 'records';
    if phase_row.status = 'complete' then continue; end if;
    update lookup_migration_phase set status = 'running', attempts = attempts + 1,
      started_at = coalesce(started_at, now()), last_error = null
    where lookup_migration_phase.app_id = app_id
      and lookup_migration_phase.customer_id = customer_id
      and lookup_migration_phase.schema_hash = expected_schema_hash
      and lookup_migration_phase.model_id = model_id
      and phase = 'records';
    row_count := 0;
    cursor_value := phase_row.cursor_id;
    begin
      for row_data in execute format(
        'select to_jsonb(r) from %I r where r.app_id = $1 and r.customer_id = $2 and ($3::uuid is null or r.id > $3) order by r.id limit $4',
        record_table
      ) using app_id, customer_id, cursor_value, batch_size
      loop
        insert into lookup_record(app_id, customer_id, model_id, id, external_key, created_at)
        values (
          app_id, customer_id, model_id, (row_data->>'id')::uuid,
          row_data->>'external_key', (row_data->>'created_at')::timestamptz
        )
        on conflict on constraint lookup_record_pkey do update
        set external_key = excluded.external_key, created_at = excluded.created_at;
        cursor_value := (row_data->>'id')::uuid;
        row_count := row_count + 1;
      end loop;
      update lookup_migration_phase
      set cursor_id = cursor_value,
          status = case when row_count < batch_size then 'complete' else 'running' end,
          completed_at = case when row_count < batch_size then now() else null end
      where lookup_migration_phase.app_id = app_id
        and lookup_migration_phase.customer_id = customer_id
        and lookup_migration_phase.schema_hash = expected_schema_hash
        and lookup_migration_phase.model_id = model_id and phase = 'records';
    exception when others then
      update lookup_migration_phase set status = 'failed', last_error = sqlstate || ': ' || sqlerrm
      where lookup_migration_phase.app_id = app_id
        and lookup_migration_phase.customer_id = customer_id
        and lookup_migration_phase.schema_hash = expected_schema_hash
        and lookup_migration_phase.model_id = model_id and phase = 'records';
      update lookup_migration_revision set status = 'failed', updated_at = now()
      where lookup_migration_revision.app_id = app_id
        and lookup_migration_revision.customer_id = customer_id
        and lookup_migration_revision.schema_hash = expected_schema_hash;
      return kernel_lookup_migration_error(
        'lookup_record_backfill_failed', 'Lookup record backfill failed',
        format('lookup model `%s`: %s', model_id, sqlerrm)
      );
    end;
  end loop;
  if exists(
    select 1 from lookup_migration_phase
    where lookup_migration_phase.app_id = app_id
      and lookup_migration_phase.customer_id = customer_id
      and lookup_migration_phase.schema_hash = expected_schema_hash
      and phase = 'records' and status <> 'complete'
  ) then
    return jsonb_build_object('ok', true, 'data', jsonb_build_object(
      'ready', false, 'phase', 'records', 'schema_hash', expected_schema_hash
    ));
  end if;

  for model_json in
    select value from jsonb_array_elements(coalesce(schema_json->'models', '[]'::jsonb)) item(value)
    where coalesce(value->>'kind', 'entity') = 'lookup'
    order by value->>'id'
  loop
    model_id := model_json->>'id';
    select * into authority_row from lookup_storage_authority authority
    where authority.app_id = app_id and authority.customer_id = customer_id
      and authority.model_id = model_id;
    if authority_row.authority = 'generic' and authority_row.first_generic_write_at is not null then continue; end if;
    version_table := authority_row.legacy_version_table;
    select * into phase_row from lookup_migration_phase phase
    where phase.app_id = app_id and phase.customer_id = customer_id
      and phase.schema_hash = expected_schema_hash and phase.model_id = model_id
      and phase.phase = 'versions';
    if phase_row.status = 'complete' then continue; end if;
    update lookup_migration_phase set status = 'running', attempts = attempts + 1,
      started_at = coalesce(started_at, now()), last_error = null
    where lookup_migration_phase.app_id = app_id
      and lookup_migration_phase.customer_id = customer_id
      and lookup_migration_phase.schema_hash = expected_schema_hash
      and lookup_migration_phase.model_id = model_id and phase = 'versions';
    row_count := 0;
    cursor_value := phase_row.cursor_id;
    begin
      for row_data in execute format(
        'select to_jsonb(v) from %I v where v.app_id = $1 and v.customer_id = $2 and ($3::uuid is null or v.id > $3) order by v.id limit $4',
        version_table
      ) using app_id, customer_id, cursor_value, batch_size
      loop
        snapshot := kernel_lookup_migration_snapshot(row_data, model_json);
        insert into lookup_version(
          id, app_id, customer_id, model_id, record_id, stage,
          effective_start, effective_end, change_set_id, created_at, applied_at,
          tombstones_record, untombstones_record, availability, provenance,
          custom_fields, metadata, many_relations, values
        ) values (
          (row_data->>'id')::uuid, app_id, customer_id, model_id,
          (row_data->>'record_id')::uuid, row_data->>'stage',
          (row_data->>'effective_start')::date,
          (row_data->>'effective_end')::date,
          (row_data->>'change_set_id')::bigint,
          (row_data->>'created_at')::timestamptz,
          (row_data->>'applied_at')::timestamptz,
          coalesce((row_data->>'tombstones_record')::boolean, false),
          coalesce((row_data->>'untombstones_record')::boolean, false),
          coalesce(row_data->>'availability', 'active'),
          row_data->'provenance',
          coalesce(row_data->'custom_fields', '[]'::jsonb),
          coalesce(row_data->'metadata', '{}'::jsonb),
          coalesce(row_data->'many_relations', '{}'::jsonb),
          snapshot
        )
        on conflict on constraint lookup_version_pkey do update set
          record_id = excluded.record_id,
          stage = excluded.stage,
          effective_start = excluded.effective_start,
          effective_end = excluded.effective_end,
          change_set_id = excluded.change_set_id,
          created_at = excluded.created_at,
          applied_at = excluded.applied_at,
          tombstones_record = excluded.tombstones_record,
          untombstones_record = excluded.untombstones_record,
          availability = excluded.availability,
          provenance = excluded.provenance,
          custom_fields = excluded.custom_fields,
          metadata = excluded.metadata,
          many_relations = excluded.many_relations,
          values = excluded.values;
        cursor_value := (row_data->>'id')::uuid;
        row_count := row_count + 1;
      end loop;
      update lookup_migration_phase
      set cursor_id = cursor_value,
          status = case when row_count < batch_size then 'complete' else 'running' end,
          completed_at = case when row_count < batch_size then now() else null end
      where lookup_migration_phase.app_id = app_id
        and lookup_migration_phase.customer_id = customer_id
        and lookup_migration_phase.schema_hash = expected_schema_hash
        and lookup_migration_phase.model_id = model_id and phase = 'versions';
    exception when others then
      update lookup_migration_phase set status = 'failed', last_error = sqlstate || ': ' || sqlerrm
      where lookup_migration_phase.app_id = app_id
        and lookup_migration_phase.customer_id = customer_id
        and lookup_migration_phase.schema_hash = expected_schema_hash
        and lookup_migration_phase.model_id = model_id and phase = 'versions';
      update lookup_migration_revision set status = 'failed', updated_at = now()
      where lookup_migration_revision.app_id = app_id
        and lookup_migration_revision.customer_id = customer_id
        and lookup_migration_revision.schema_hash = expected_schema_hash;
      return kernel_lookup_migration_error(
        'lookup_version_backfill_failed', 'Lookup history backfill failed',
        format('lookup model `%s`: %s', model_id, sqlerrm)
      );
    end;
  end loop;
  if exists(
    select 1 from lookup_migration_phase
    where lookup_migration_phase.app_id = app_id
      and lookup_migration_phase.customer_id = customer_id
      and lookup_migration_phase.schema_hash = expected_schema_hash
      and phase = 'versions' and status <> 'complete'
  ) then
    return jsonb_build_object('ok', true, 'data', jsonb_build_object(
      'ready', false, 'phase', 'versions', 'schema_hash', expected_schema_hash
    ));
  end if;

  for model_json in
    select value from jsonb_array_elements(coalesce(schema_json->'models', '[]'::jsonb)) item(value)
    where coalesce(value->>'kind', 'entity') = 'lookup'
    order by value->>'id'
  loop
    model_id := model_json->>'id';
    select * into authority_row from lookup_storage_authority authority
    where authority.app_id = app_id and authority.customer_id = customer_id
      and authority.model_id = model_id;
    if authority_row.authority = 'generic' and authority_row.first_generic_write_at is not null then continue; end if;
    select * into phase_row from lookup_migration_phase phase
    where phase.app_id = app_id and phase.customer_id = customer_id
      and phase.schema_hash = expected_schema_hash and phase.model_id = model_id
      and phase.phase = 'projections';
    if phase_row.status = 'complete' then continue; end if;
    update lookup_migration_phase set status = 'running', attempts = attempts + 1,
      started_at = coalesce(started_at, now()), last_error = null
    where lookup_migration_phase.app_id = app_id
      and lookup_migration_phase.customer_id = customer_id
      and lookup_migration_phase.schema_hash = expected_schema_hash
      and lookup_migration_phase.model_id = model_id and phase = 'projections';
    row_count := 0;
    cursor_value := phase_row.cursor_id;
    begin
      for row_data in
        select to_jsonb(v)
        from lookup_version v
        where v.app_id = app_id and v.customer_id = customer_id
          and v.model_id = model_id
          and (cursor_value is null or v.id > cursor_value)
        order by v.id limit batch_size
      loop
        projected_is_current := false;
        perform kernel_apply_project_lookup_version(
          (row_data->>'id')::uuid, app_id, customer_id, model_id,
          (row_data->>'record_id')::uuid, schema_json, model_json,
          row_data->'values', row_data->'many_relations', projected_is_current
        );
        cursor_value := (row_data->>'id')::uuid;
        row_count := row_count + 1;
      end loop;
      update lookup_migration_phase
      set cursor_id = cursor_value,
          status = case when row_count < batch_size then 'complete' else 'running' end,
          completed_at = case when row_count < batch_size then now() else null end
      where lookup_migration_phase.app_id = app_id
        and lookup_migration_phase.customer_id = customer_id
        and lookup_migration_phase.schema_hash = expected_schema_hash
        and lookup_migration_phase.model_id = model_id and phase = 'projections';
    exception when others then
      update lookup_migration_phase set status = 'failed', last_error = sqlstate || ': ' || sqlerrm
      where lookup_migration_phase.app_id = app_id
        and lookup_migration_phase.customer_id = customer_id
        and lookup_migration_phase.schema_hash = expected_schema_hash
        and lookup_migration_phase.model_id = model_id and phase = 'projections';
      update lookup_migration_revision set status = 'failed', updated_at = now()
      where lookup_migration_revision.app_id = app_id
        and lookup_migration_revision.customer_id = customer_id
        and lookup_migration_revision.schema_hash = expected_schema_hash;
      return kernel_lookup_migration_error(
        'lookup_projection_backfill_failed', 'Lookup projection backfill failed',
        format('lookup model `%s`: %s', model_id, sqlerrm)
      );
    end;
  end loop;
  if exists(
    select 1 from lookup_migration_phase
    where lookup_migration_phase.app_id = app_id
      and lookup_migration_phase.customer_id = customer_id
      and lookup_migration_phase.schema_hash = expected_schema_hash
      and phase = 'projections' and status <> 'complete'
  ) then
    return jsonb_build_object('ok', true, 'data', jsonb_build_object(
      'ready', false, 'phase', 'projections', 'schema_hash', expected_schema_hash
    ));
  end if;

  begin
    update lookup_alias_projection alias_projection
    set is_current = false
    where alias_projection.app_id = app_id
      and alias_projection.customer_id = customer_id
      and alias_projection.model_id in (
        select value->>'id'
        from jsonb_array_elements(coalesce(schema_json->'models', '[]'::jsonb)) item(value)
        where coalesce(value->>'kind', 'entity') = 'lookup'
      );
    update lookup_alias_projection alias_projection
    set is_current = true
    where alias_projection.app_id = app_id
      and alias_projection.customer_id = customer_id
      and (alias_projection.model_id, alias_projection.version_id) in (
        select visible.model_id, visible.id
        from (
          select distinct on (version.model_id, version.record_id)
            version.id, version.model_id, version.record_id
          from lookup_version version
          join change_set changes
            on changes.id = version.change_set_id
           and changes.app_id = version.app_id
           and changes.customer_id = version.customer_id
          where version.app_id = app_id
            and version.customer_id = customer_id
            and version.stage = 'mainline'
            and changes.status = 'mainline'
            and changes.applied_order is not null
            and version.effective_start <= current_date
            and (version.effective_end is null or version.effective_end >= current_date)
            and not version.tombstones_record
            and not version.untombstones_record
            and version.availability = 'active'
          order by version.model_id, version.record_id,
            version.effective_start desc, changes.applied_order desc, version.id desc
        ) visible
      );
  exception when unique_violation then
    update lookup_migration_revision set status = 'failed', updated_at = now()
    where lookup_migration_revision.app_id = app_id
      and lookup_migration_revision.customer_id = customer_id
      and lookup_migration_revision.schema_hash = expected_schema_hash;
    return kernel_lookup_migration_error(
      'lookup_alias_ambiguity', 'Lookup aliases are ambiguous',
      'active normalized lookup names or aliases collide within a model'
    );
  end;

  for model_json in
    select value from jsonb_array_elements(coalesce(schema_json->'models', '[]'::jsonb)) item(value)
    where coalesce(value->>'kind', 'entity') = 'lookup'
    order by value->>'id'
  loop
    model_id := model_json->>'id';
    select * into authority_row from lookup_storage_authority authority
    where authority.app_id = app_id and authority.customer_id = customer_id
      and authority.model_id = model_id;
    if authority_row.authority = 'generic' and authority_row.first_generic_write_at is not null then continue; end if;
    evidence := kernel_lookup_migration_model_evidence(app_id, customer_id, model_id, model_json);
    update lookup_migration_phase
    set status = case when (evidence->>'matches')::boolean then 'complete' else 'failed' end,
        attempts = attempts + 1,
        started_at = coalesce(started_at, now()),
        completed_at = case when (evidence->>'matches')::boolean then now() else null end,
        evidence = prepare_lookup_migration.evidence,
        last_error = case when (evidence->>'matches')::boolean then null else 'canonical source and target evidence differs' end
    where lookup_migration_phase.app_id = app_id
      and lookup_migration_phase.customer_id = customer_id
      and lookup_migration_phase.schema_hash = expected_schema_hash
      and lookup_migration_phase.model_id = model_id and phase = 'verify';
    if not (evidence->>'matches')::boolean then
      update lookup_migration_revision set status = 'failed', updated_at = now()
      where lookup_migration_revision.app_id = app_id
        and lookup_migration_revision.customer_id = customer_id
        and lookup_migration_revision.schema_hash = expected_schema_hash;
      return kernel_lookup_migration_error(
        'lookup_migration_mismatch', 'Lookup migration evidence differs',
        format('lookup model `%s` record or history count/hash differs', model_id)
      );
    end if;
  end loop;

  update lookup_migration_revision
  set status = 'ready', prepared_at = coalesce(prepared_at, now()), updated_at = now()
  where lookup_migration_revision.app_id = app_id
    and lookup_migration_revision.customer_id = customer_id
    and lookup_migration_revision.schema_hash = expected_schema_hash
    and status <> 'active';
  return jsonb_build_object('ok', true, 'data', jsonb_build_object(
    'ready', true, 'phase', 'verify', 'schema_hash', expected_schema_hash
  ));
end;
$kernel_lookup_migration$;

-- artifact: function kernel_validate_lookup_migration(jsonb)
create or replace function kernel_validate_lookup_migration(request jsonb)
returns jsonb
language plpgsql
stable
security invoker
set search_path from current
as $kernel_lookup_migration$
#variable_conflict use_variable
declare
  app_id text := request->>'app_id';
  customer_id text := request->>'customer_id';
  schema_revision_id bigint;
  expected_schema_hash text := request->>'expected_schema_hash';
  schema_json jsonb;
  stored_schema_hash text;
  model_json jsonb;
  model_id text;
  authority_row record;
  evidence jsonb;
  model_results jsonb := '[]'::jsonb;
begin
  if request is null or jsonb_typeof(request) <> 'object'
    or request - array['app_id', 'customer_id', 'schema_revision_id', 'expected_schema_hash'] <> '{}'::jsonb
    or jsonb_typeof(request->'schema_revision_id') is distinct from 'number'
    or (request->>'schema_revision_id')::numeric <> trunc((request->>'schema_revision_id')::numeric)
    or (request->>'schema_revision_id')::numeric <= 0
    or (request->>'schema_revision_id')::numeric > 9223372036854775807
  then
    return kernel_lookup_migration_error(
      'contract_validation_failed', 'Lookup migration request is invalid',
      'validation accepts only app_id, customer_id, schema_revision_id, and expected_schema_hash'
    );
  end if;
  schema_revision_id := (request->>'schema_revision_id')::bigint;
  perform set_config('kernel.app_id', app_id, true);
  perform set_config('kernel.customer_id', customer_id, true);
  select revision.schema, revision.schema_hash
  into schema_json, stored_schema_hash
  from schema_revision revision
  where revision.id = schema_revision_id
    and revision.app_id = app_id
    and revision.customer_id = customer_id
    and revision.activated_at is not null;
  if schema_json is null or stored_schema_hash is distinct from expected_schema_hash then
    return kernel_lookup_migration_error(
      'stale_schema_hash', 'Schema revision or hash changed',
      'the requested schema revision cannot be validated'
    );
  end if;
  for model_json in
    select value from jsonb_array_elements(coalesce(schema_json->'models', '[]'::jsonb)) item(value)
    where coalesce(value->>'kind', 'entity') = 'lookup'
    order by value->>'id'
  loop
    model_id := model_json->>'id';
    select * into authority_row
    from lookup_storage_authority authority
    where authority.app_id = app_id
      and authority.customer_id = customer_id
      and authority.model_id = model_id;
    if authority_row.authority = 'generic'
      and authority_row.schema_hash = expected_schema_hash
      and authority_row.first_generic_write_at is not null
    then
      model_results := model_results || jsonb_build_array(
        jsonb_build_object('model_id', model_id, 'authority', 'generic', 'matches', true)
      );
      continue;
    end if;
    evidence := kernel_lookup_migration_model_evidence(app_id, customer_id, model_id, model_json);
    model_results := model_results || jsonb_build_array(
      jsonb_build_object('model_id', model_id, 'evidence', evidence)
    );
    if not coalesce((evidence->>'matches')::boolean, false) then
      return kernel_lookup_migration_error(
        'lookup_migration_mismatch', 'Lookup migration evidence differs',
        format('lookup model `%s` record or history count/hash differs', model_id)
      );
    end if;
  end loop;
  return jsonb_build_object('ok', true, 'data', jsonb_build_object(
    'schema_hash', expected_schema_hash, 'models', model_results, 'matches', true
  ));
end;
$kernel_lookup_migration$;

-- artifact: function kernel_activate_lookup_migration(jsonb)
create or replace function kernel_activate_lookup_migration(request jsonb)
returns jsonb
language plpgsql
volatile
security invoker
set search_path from current
as $kernel_lookup_migration$
#variable_conflict use_variable
<<activate_lookup_migration>>
declare
  app_id text := request->>'app_id';
  customer_id text := request->>'customer_id';
  schema_revision_id bigint;
  expected_schema_hash text := request->>'expected_schema_hash';
  schema_json jsonb;
  stored_schema_hash text;
  migration_status text;
  model_json jsonb;
  model_id text;
  record_table text;
  version_table text;
  prepare_result jsonb;
  validate_result jsonb;
  attempts integer := 0;
begin
  if request is null or jsonb_typeof(request) <> 'object'
    or request - array['app_id', 'customer_id', 'schema_revision_id', 'expected_schema_hash'] <> '{}'::jsonb
    or jsonb_typeof(request->'schema_revision_id') is distinct from 'number'
    or (request->>'schema_revision_id')::numeric <> trunc((request->>'schema_revision_id')::numeric)
    or (request->>'schema_revision_id')::numeric <= 0
    or (request->>'schema_revision_id')::numeric > 9223372036854775807
    or expected_schema_hash is null or expected_schema_hash !~ '^[0-9a-f]{64}$'
  then
    return kernel_lookup_migration_error(
      'contract_validation_failed', 'Lookup activation request is invalid',
      'activation requires an exact schema revision and expected hash'
    );
  end if;
  schema_revision_id := (request->>'schema_revision_id')::bigint;
  perform set_config('kernel.app_id', app_id, true);
  perform set_config('kernel.customer_id', customer_id, true);
  perform pg_advisory_xact_lock(hashtext(
    'postgres-schema:' || current_schema() || ':materialize-tenant:' || app_id || ':' || customer_id || ':schema-activation'
  ));
  perform pg_advisory_xact_lock(hashtext(
    'postgres-schema:' || current_schema() || ':materialize-tenant:' || app_id || ':' || customer_id || ':lookup-migration'
  ));
  select revision.schema, revision.schema_hash
  into schema_json, stored_schema_hash
  from schema_revision revision
  where revision.id = schema_revision_id
    and revision.app_id = app_id
    and revision.customer_id = customer_id
    and revision.activated_at is not null;
  if schema_json is null or stored_schema_hash is distinct from expected_schema_hash then
    return kernel_lookup_migration_error(
      'stale_schema_hash', 'Schema revision or hash changed',
      'lookup authority was not changed'
    );
  end if;
  select status into migration_status
  from lookup_migration_revision revision
  where revision.app_id = app_id and revision.customer_id = customer_id
    and revision.schema_hash = expected_schema_hash;
  if migration_status = 'active' then
    return jsonb_build_object('ok', true, 'data', jsonb_build_object(
      'activated', true, 'idempotent', true, 'schema_hash', expected_schema_hash
    ));
  end if;
  if not exists(
    select 1
    from jsonb_array_elements(coalesce(schema_json->'models', '[]'::jsonb)) item(value)
    where coalesce(value->>'kind', 'entity') = 'lookup'
      and not exists(
        select 1 from lookup_storage_authority authority
        where authority.app_id = app_id
          and authority.customer_id = customer_id
          and authority.model_id = item.value->>'id'
          and authority.authority = 'generic'
          and authority.schema_hash = expected_schema_hash
      )
  ) then
    update lookup_migration_revision revision
    set status = 'active',
        prepared_at = coalesce(revision.prepared_at, now()),
        activated_at = coalesce(revision.activated_at, now()),
        updated_at = now()
    where revision.app_id = app_id
      and revision.customer_id = customer_id
      and revision.schema_hash = expected_schema_hash;
    return jsonb_build_object('ok', true, 'data', jsonb_build_object(
      'activated', true, 'idempotent', true, 'schema_hash', expected_schema_hash
    ));
  end if;
  if migration_status <> 'ready' then
    return kernel_lookup_migration_error(
      'lookup_migration_not_ready', 'Lookup migration is not ready',
      'prepare and validate the shadow copy before activation'
    );
  end if;

  begin
    execute 'lock table lookup_record in access exclusive mode';
    execute 'lock table lookup_version in access exclusive mode';
    execute 'lock table lookup_value_projection in access exclusive mode';
    execute 'lock table lookup_alias_projection in access exclusive mode';
    execute 'lock table lookup_relation_projection in access exclusive mode';
    for model_json in
      select value from jsonb_array_elements(coalesce(schema_json->'models', '[]'::jsonb)) item(value)
      where coalesce(value->>'kind', 'entity') = 'lookup'
      order by value->>'id'
    loop
      model_id := model_json->>'id';
      select legacy_record_table, legacy_version_table
      into record_table, version_table
      from lookup_storage_authority authority
      where authority.app_id = app_id and authority.customer_id = customer_id
        and authority.model_id = model_id and authority.authority = 'typed'
        and authority.schema_hash = expected_schema_hash;
      if record_table is null or version_table is null then
        raise exception 'typed authority for lookup model `%` is missing', model_id;
      end if;
      execute format('lock table %I in access exclusive mode', record_table);
      execute format('lock table %I in access exclusive mode', version_table);
      if not exists (
        select 1 from pg_trigger
        where tgrelid = to_regclass(format('%I.%I', current_schema(), record_table))
          and tgname = 'lookup_migration_write_block' and not tgisinternal
      ) then
        execute format(
          'create trigger lookup_migration_write_block before insert or update or delete or truncate on %I for each statement execute function kernel_lookup_migration_block_legacy_write()',
          record_table
        );
      end if;
      if not exists (
        select 1 from pg_trigger
        where tgrelid = to_regclass(format('%I.%I', current_schema(), version_table))
          and tgname = 'lookup_migration_write_block' and not tgisinternal
      ) then
        execute format(
          'create trigger lookup_migration_write_block before insert or update or delete or truncate on %I for each statement execute function kernel_lookup_migration_block_legacy_write()',
          version_table
        );
      end if;
    end loop;

    -- Reset cursors and replay under the barrier so late typed writes are included.
    update lookup_migration_phase
    set status = 'pending', cursor_id = null, completed_at = null, last_error = null
    where lookup_migration_phase.app_id = app_id
      and lookup_migration_phase.customer_id = customer_id
      and lookup_migration_phase.schema_hash = expected_schema_hash;
    update lookup_migration_revision set status = 'preparing', updated_at = now()
    where lookup_migration_revision.app_id = app_id
      and lookup_migration_revision.customer_id = customer_id
      and lookup_migration_revision.schema_hash = expected_schema_hash;
    loop
      attempts := attempts + 1;
      if attempts > 100000 then
        raise exception 'lookup migration catch-up exceeded the phase iteration bound';
      end if;
      prepare_result := kernel_prepare_lookup_migration(jsonb_build_object(
        'app_id', app_id,
        'customer_id', customer_id,
        'schema_revision_id', schema_revision_id,
        'expected_schema_hash', expected_schema_hash,
        'batch_size', 10000
      ));
      if not coalesce((prepare_result->>'ok')::boolean, false) then
        raise exception 'catch-up failed: %', prepare_result::text;
      end if;
      exit when coalesce((prepare_result#>>'{data,ready}')::boolean, false);
    end loop;
    validate_result := kernel_validate_lookup_migration(jsonb_build_object(
      'app_id', app_id,
      'customer_id', customer_id,
      'schema_revision_id', schema_revision_id,
      'expected_schema_hash', expected_schema_hash
    ));
    if not coalesce((validate_result->>'ok')::boolean, false) then
      raise exception 'final validation failed: %', validate_result::text;
    end if;

    update lookup_storage_authority
    set authority = 'generic', activated_at = now(), schema_hash = expected_schema_hash
    where lookup_storage_authority.app_id = app_id
      and lookup_storage_authority.customer_id = customer_id
      and lookup_storage_authority.schema_hash = expected_schema_hash
      and authority = 'typed';
    update lookup_migration_revision
    set status = 'active', activated_at = now(), updated_at = now()
    where lookup_migration_revision.app_id = app_id
      and lookup_migration_revision.customer_id = customer_id
      and lookup_migration_revision.schema_hash = expected_schema_hash;
  exception when others then
    return kernel_lookup_migration_error(
      'lookup_migration_activation_failed', 'Lookup authority activation failed',
      'typed authority remains active: ' || sqlerrm
    );
  end;
  return jsonb_build_object('ok', true, 'data', jsonb_build_object(
    'activated', true, 'idempotent', false, 'schema_hash', expected_schema_hash,
    'catch_up_iterations', attempts
  ));
end;
$kernel_lookup_migration$;

-- artifact: function kernel_lookup_migration_status(jsonb)
create or replace function kernel_lookup_migration_status(request jsonb)
returns jsonb
language plpgsql
stable
security invoker
set search_path from current
as $kernel_lookup_migration$
#variable_conflict use_variable
declare
  app_id text := request->>'app_id';
  customer_id text := request->>'customer_id';
  requested_schema_hash text := request->>'schema_hash';
  revision_json jsonb;
  phase_json jsonb;
  authority_json jsonb;
begin
  if request is null or jsonb_typeof(request) <> 'object'
    or request - array['app_id', 'customer_id', 'schema_hash'] <> '{}'::jsonb
  then
    return kernel_lookup_migration_error(
      'contract_validation_failed', 'Lookup migration status request is invalid',
      'status accepts only app_id, customer_id, and schema_hash'
    );
  end if;
  perform set_config('kernel.app_id', app_id, true);
  perform set_config('kernel.customer_id', customer_id, true);
  select to_jsonb(revision) into revision_json
  from lookup_migration_revision revision
  where revision.app_id = app_id and revision.customer_id = customer_id
    and revision.schema_hash = requested_schema_hash;
  select coalesce(jsonb_agg(to_jsonb(phase) order by phase.model_id, phase.phase), '[]'::jsonb)
  into phase_json
  from lookup_migration_phase phase
  where phase.app_id = app_id and phase.customer_id = customer_id
    and phase.schema_hash = requested_schema_hash;
  select coalesce(jsonb_agg(to_jsonb(authority) order by authority.model_id), '[]'::jsonb)
  into authority_json
  from lookup_storage_authority authority
  where authority.app_id = app_id and authority.customer_id = customer_id;
  return jsonb_build_object('ok', true, 'data', jsonb_build_object(
    'revision', revision_json, 'phases', phase_json, 'authorities', authority_json
  ));
end;
$kernel_lookup_migration$;

-- artifact: function kernel_apply_seed_defaults(jsonb)
create table if not exists installed_seed (
  app_id text not null,
  customer_id text not null,
  seed_identity text not null,
  seed_record_ids uuid[] not null,
  payload_fingerprint text not null,
  source_idempotency_key text not null,
  install_status text not null,
  change_set_id bigint,
  result jsonb not null,
  installed_at timestamptz not null default now(),
  constraint installed_seed_pkey primary key (app_id, customer_id, seed_identity),
  constraint installed_seed_identity_check check (seed_identity ~ '^[0-9a-f]{64}$'),
  constraint installed_seed_payload_fingerprint_check check (payload_fingerprint ~ '^[0-9a-f]{64}$'),
  constraint installed_seed_status_check check (install_status in ('applied', 'skipped_existing')),
  constraint installed_seed_result_check check (jsonb_typeof(result) = 'object')
);

alter table installed_seed enable row level security;
alter table installed_seed force row level security;

do $kernel_seed_policy$
begin
  if exists (
    select 1 from pg_policies
    where schemaname = current_schema()
      and tablename = 'installed_seed'
      and policyname = 'kernel_tenant_isolation'
  ) then
    alter policy kernel_tenant_isolation on installed_seed
      using (
        app_id = current_setting('kernel.app_id', true)
        and customer_id = current_setting('kernel.customer_id', true)
        and kernel_principal_scope_authorized('any', app_id, customer_id, null)
      )
      with check (
        app_id = current_setting('kernel.app_id', true)
        and customer_id = current_setting('kernel.customer_id', true)
        and kernel_principal_scope_authorized('any', app_id, customer_id, null)
      );
  else
    create policy kernel_tenant_isolation on installed_seed
      for all
      using (
        app_id = current_setting('kernel.app_id', true)
        and customer_id = current_setting('kernel.customer_id', true)
        and kernel_principal_scope_authorized('any', app_id, customer_id, null)
      )
      with check (
        app_id = current_setting('kernel.app_id', true)
        and customer_id = current_setting('kernel.customer_id', true)
        and kernel_principal_scope_authorized('any', app_id, customer_id, null)
      );
  end if;
end
$kernel_seed_policy$;

create or replace function kernel_apply_seed_defaults(request jsonb)
returns jsonb
language plpgsql
volatile
parallel unsafe
security invoker
set search_path from current
as $kernel$
<<seed_defaults>>
declare
  requested_app_id text := request->>'app_id';
  requested_customer_id text := request->>'customer_id';
  schema_revision_id jsonb := coalesce(request->'schema_revision_id', 'null'::jsonb);
  templates jsonb := request->'change_sets';
  template jsonb;
  template_index integer := 0;
  current_seed_identity text;
  seed_record_ids jsonb;
  seed_record_id uuid;
  payload_fingerprint text;
  active_schema jsonb;
  model jsonb;
  current_model_id text;
  model_is_lookup boolean;
  record_table_name text;
  write jsonb;
  write_index integer;
  record_key jsonb;
  record_key_type text;
  record_key_value text;
  subject_exists boolean;
  reserved_count integer;
  apply_request jsonb;
  apply_result jsonb;
  installed_result jsonb;
  recovering_skip boolean;
  had_prior_change_history boolean;
  allocation_collision boolean;
  scoped_subject_exists boolean;
  allocated_record_id uuid;
  seed_result jsonb;
  applied_results jsonb := '[]'::jsonb;
  seed_results jsonb := '[]'::jsonb;
  applied_count integer := 0;
  skipped_count integer := 0;
  failure jsonb;
  failure_state text; failure_message text; failure_constraint text; failure_table text;
begin
  perform kernel_cleanup_generated_visible_query();
  if jsonb_typeof(request) is distinct from 'object' then
    return kernel_admin_validation_error(jsonb_build_array(jsonb_build_object(
      'path', 'request', 'code', 'invalid_type', 'message', 'request must be a JSON object'
    )));
  end if;
  if request - array['app_id', 'customer_id', 'schema_revision_id', 'change_sets']::text[] <> '{}'::jsonb then
    return kernel_admin_validation_error(jsonb_build_array(jsonb_build_object(
      'path', 'request', 'code', 'unknown_field', 'message', 'seed request contains an unknown field'
    )));
  end if;
  if coalesce(btrim(requested_app_id), '') = '' or coalesce(btrim(requested_customer_id), '') = '' then
    return kernel_admin_validation_error(jsonb_build_array(jsonb_build_object(
      'path', 'scope', 'code', 'required', 'message', 'app_id and customer_id are required'
    )));
  end if;
  if jsonb_typeof(templates) is distinct from 'array' then
    return kernel_admin_validation_error(jsonb_build_array(jsonb_build_object(
      'path', 'change_sets', 'code', 'invalid_type', 'message', 'change_sets must be an array'
    )));
  end if;
  if not kernel_principal_scope_authorized(
    'schema_admin', requested_app_id, requested_customer_id, null
  ) then
    return kernel_authorize_scope(
      'schema_admin', requested_app_id, requested_customer_id, null
    );
  end if;

  perform set_config('kernel.app_id', requested_app_id, true);
  perform set_config('kernel.customer_id', requested_customer_id, true);

  select sr.schema
  into active_schema
  from schema_revision sr
  where sr.app_id = requested_app_id
    and sr.customer_id = requested_customer_id
    and (
      (schema_revision_id <> 'null'::jsonb and sr.id = (schema_revision_id #>> '{}')::bigint)
      or (schema_revision_id = 'null'::jsonb and sr.activated_at is not null)
    )
  order by sr.activated_at desc nulls last, sr.id desc
  limit 1;
  if active_schema is null then
    return kernel_admin_validation_error(jsonb_build_array(jsonb_build_object(
      'path', 'schema_revision_id', 'code', 'unknown_schema_revision',
      'message', 'schema revision does not exist in the requested tenant scope'
    )));
  end if;

  -- Validate the complete compiler-owned batch before the first seed can reserve a subject.
  for template in select value from jsonb_array_elements(templates)
  loop
    if jsonb_typeof(template) is distinct from 'object'
      or template - array[
        'seed_identity', 'seed_record_ids', 'actor_id', 'source_kind', 'idempotency_key',
        'change_type_id', 'notes', 'writes'
      ]::text[] <> '{}'::jsonb
    then
      return kernel_admin_validation_error(jsonb_build_array(jsonb_build_object(
        'path', format('change_sets[%s]', template_index),
        'code', 'invalid_seed_template',
        'message', 'seed templates must contain only compiler-owned change-set fields'
      )));
    end if;
    current_seed_identity := template->>'seed_identity';
    seed_record_ids := template->'seed_record_ids';
    if current_seed_identity is null or current_seed_identity !~ '^[0-9a-f]{64}$' then
      return kernel_admin_validation_error(jsonb_build_array(jsonb_build_object(
        'path', format('change_sets[%s].seed_identity', template_index),
        'code', 'invalid_seed_identity', 'message', 'seed identity must be compiler-derived SHA-256 hex'
      )));
    end if;
    if jsonb_typeof(seed_record_ids) is distinct from 'array'
      or jsonb_typeof(template->'writes') is distinct from 'array'
      or jsonb_array_length(seed_record_ids) <> jsonb_array_length(template->'writes')
      or jsonb_array_length(seed_record_ids) = 0
    then
      return kernel_admin_validation_error(jsonb_build_array(jsonb_build_object(
        'path', format('change_sets[%s].seed_record_ids', template_index),
        'code', 'invalid_seed_record_ids', 'message', 'seed record ids must align one-to-one with writes'
      )));
    end if;
    begin
      perform (value #>> '{}')::uuid from jsonb_array_elements(seed_record_ids);
    exception when invalid_text_representation then
      return kernel_admin_validation_error(jsonb_build_array(jsonb_build_object(
        'path', format('change_sets[%s].seed_record_ids', template_index),
        'code', 'invalid_seed_record_id', 'message', 'seed record ids must be UUIDs'
      )));
    end;
    write_index := 0;
    for write in select value from jsonb_array_elements(template->'writes')
    loop
      current_model_id := write->>'model_id';
      select value into model
      from jsonb_array_elements(coalesce(active_schema->'models', '[]'::jsonb)) entry(value)
      where value->>'id' = current_model_id;
      if model is null then
        return kernel_admin_validation_error(jsonb_build_array(jsonb_build_object(
          'path', format('change_sets[%s].writes[%s].model_id', template_index, write_index),
          'code', 'unknown_seed_model', 'message', 'seed write model is not present in the selected schema revision'
        )));
      end if;
      write_index := write_index + 1;
    end loop;
    template_index := template_index + 1;
  end loop;

  -- Freeze pre-batch history under the normal activation/write boundary. A
  -- recovered template must not disqualify later templates in this transaction.
  perform kernel_installer_lock_tenant(requested_app_id, requested_customer_id);
  select exists(select 1 from change_set cs where cs.app_id=requested_app_id
    and cs.customer_id=requested_customer_id) into had_prior_change_history;
  template_index := 0;
  begin
  for template in select value from jsonb_array_elements(templates)
  loop
    current_seed_identity := template->>'seed_identity';
    seed_record_ids := template->'seed_record_ids';

    perform pg_advisory_xact_lock(hashtextextended(
      'kernel:seed:' || requested_app_id || ':' || requested_customer_id || ':' || current_seed_identity, 0
    ));
    payload_fingerprint := kernel_admin_sha256(kernel_canonical_json(template));
    select ledger.result, (ledger.install_status='skipped_existing'
      and ledger.change_set_id is null
      and ledger.payload_fingerprint=seed_defaults.payload_fingerprint
      and ledger.source_idempotency_key=template->>'idempotency_key'
      and ledger.seed_record_ids=array(select value::uuid from jsonb_array_elements_text(seed_defaults.seed_record_ids))
      and not had_prior_change_history
      and exists(select 1 from schema_installation_revision installation
        where installation.app_id=requested_app_id and installation.customer_id=requested_customer_id
          and installation.activated_at=ledger.installed_at
          and installation.activation_kind in ('app_base','tenant_overlay')
          and installation.seed_change_sets @> jsonb_build_array(template)
          and not exists(select 1 from schema_revision earlier
            where earlier.app_id=requested_app_id and earlier.customer_id=requested_customer_id
              and earlier.id < installation.schema_revision_id)))
    into installed_result, recovering_skip
    from installed_seed ledger
    where ledger.app_id = requested_app_id
      and ledger.customer_id = requested_customer_id
      and ledger.seed_identity = current_seed_identity;
    if found and not recovering_skip then
      seed_results := seed_results || jsonb_build_array(
        installed_result || jsonb_build_object('status', 'already_installed')
      );
      skipped_count := skipped_count + 1;
      template_index := template_index + 1;
      continue;
    end if;

    payload_fingerprint := kernel_admin_sha256(kernel_canonical_json(template));
    subject_exists := false;
    write_index := 0;
    for write in select value from jsonb_array_elements(template->'writes')
    loop
      current_model_id := write->>'model_id';
      select value into model
      from jsonb_array_elements(coalesce(active_schema->'models', '[]'::jsonb)) entry(value)
      where value->>'id' = current_model_id;
      model_is_lookup := model->>'kind' = 'lookup';
      record_table_name := kernel_apply_identifier(current_model_id || '_record');
      seed_record_id := (seed_record_ids->>write_index)::uuid;
      record_key := write->'record_key';
      record_key_type := record_key->>'type';
      record_key_value := record_key->>'value';

      if model_is_lookup then
        select exists(
          select 1 from lookup_record record
          where record.app_id = requested_app_id
            and record.customer_id = requested_customer_id
            and record.model_id = current_model_id
            and (
              record.id = seed_record_id
              or (record_key_type = 'external_key' and record.external_key = record_key_value)
            )
        ) into subject_exists;
      else
        execute format(
          'select exists(select 1 from %I where app_id=$1 and customer_id=$2 and (id=$3 or ($4=''external_key'' and external_key=$5)))',
          record_table_name
        ) using requested_app_id, requested_customer_id, seed_record_id, record_key_type, record_key_value
          into subject_exists;
      end if;
      exit when subject_exists;
      write_index := write_index + 1;
    end loop;

    if subject_exists and recovering_skip then
      seed_results := seed_results || jsonb_build_array(installed_result || jsonb_build_object('status','already_installed'));
      skipped_count := skipped_count + 1;
      template_index := template_index + 1;
      continue;
    end if;
    if subject_exists then
      seed_result := jsonb_build_object(
        'seed_identity', current_seed_identity,
        'seed_record_ids', seed_record_ids,
        'status', 'skipped_existing',
        'change_set', null
      );
      insert into installed_seed (
        app_id, customer_id, seed_identity, seed_record_ids, payload_fingerprint,
        source_idempotency_key, install_status, change_set_id, result
      ) values (
        requested_app_id, requested_customer_id, current_seed_identity,
        array(select (value #>> '{}')::uuid from jsonb_array_elements(seed_record_ids)),
        payload_fingerprint, template->>'idempotency_key', 'skipped_existing', null, seed_result
      );
      seed_results := seed_results || jsonb_build_array(seed_result);
      skipped_count := skipped_count + 1;
      template_index := template_index + 1;
      continue;
    end if;

    begin
      allocation_collision := false;
      write_index := 0;
      for write in select value from jsonb_array_elements(template->'writes')
      loop
        record_key := write->'record_key';
        if jsonb_typeof(coalesce(record_key, 'null'::jsonb)) = 'object' then
          current_model_id := write->>'model_id';
          select value into model
          from jsonb_array_elements(active_schema->'models') entry(value)
          where value->>'id' = current_model_id;
          model_is_lookup := model->>'kind' = 'lookup';
          record_table_name := kernel_apply_identifier(current_model_id || '_record');
          seed_record_id := (seed_record_ids->>write_index)::uuid;
          record_key_type := record_key->>'type';
          record_key_value := record_key->>'value';
          if model_is_lookup then
            insert into lookup_record (app_id, customer_id, model_id, id, external_key)
            values (
              requested_app_id, requested_customer_id, current_model_id, seed_record_id,
              case when record_key_type = 'external_key' then record_key_value else null end
            )
            on conflict do nothing;
          else
            execute format(
              'insert into %I (id,app_id,customer_id,external_key) values ($1,$2,$3,$4) on conflict do nothing',
              record_table_name
            ) using seed_record_id, requested_app_id, requested_customer_id,
              case when record_key_type = 'external_key' then record_key_value else null end;
          end if;
          get diagnostics reserved_count = row_count;
          if reserved_count <> 1 then
            -- A global primary-key collision can be invisible under tenant RLS.
            -- A scoped external key still wins: never replace customer defaults.
            if model_is_lookup then
              select exists(select 1 from lookup_record where app_id=requested_app_id
                and customer_id=requested_customer_id and model_id=current_model_id
                and (id=seed_record_id or external_key=record_key_value)) into scoped_subject_exists;
            else
              execute format('select exists(select 1 from %I where app_id=$1 and customer_id=$2 and (id=$3 or external_key=$4))', record_table_name)
                using requested_app_id, requested_customer_id, seed_record_id, record_key_value into scoped_subject_exists;
            end if;
            if scoped_subject_exists then
              raise exception using errcode = 'P0002', message = 'seed subject was created concurrently';
            end if;
            if record_key_type <> 'external_key' then
              failure := kernel_admin_validation_error(jsonb_build_array(jsonb_build_object(
                'path', 'change_sets', 'code', 'seed_record_id_collision',
                'message', 'Explicit record-id seed conflicts with an existing global record identity')));
              raise exception using errcode = 'P0001', message = 'kernel seed defaults failed';
            end if;
            allocation_collision := true;
            allocated_record_id := substr(kernel_admin_sha256(kernel_canonical_json(jsonb_build_array(
              'kernel:scoped-seed-record:v1', requested_app_id, requested_customer_id, current_model_id, seed_record_id
            ))), 1, 32)::uuid;
            if model_is_lookup then
              insert into lookup_record(app_id,customer_id,model_id,id,external_key)
                values(requested_app_id,requested_customer_id,current_model_id,allocated_record_id,record_key_value)
                on conflict do nothing;
            else
              execute format('insert into %I(id,app_id,customer_id,external_key) values($1,$2,$3,$4) on conflict do nothing', record_table_name)
                using allocated_record_id,requested_app_id,requested_customer_id,record_key_value;
            end if;
            get diagnostics reserved_count = row_count;
            if reserved_count <> 1 then
              failure := kernel_admin_validation_error(jsonb_build_array(jsonb_build_object(
                'path', 'change_sets', 'code', 'seed_allocation_conflict',
                'message', 'Scoped seed allocation conflicted; retry after inspecting the selected subject')));
              raise exception using errcode = 'P0001', message = 'kernel seed defaults failed';
            end if;
            seed_record_ids := jsonb_set(seed_record_ids, array[write_index::text], to_jsonb(allocated_record_id));
          end if;
        end if;
        write_index := write_index + 1;
      end loop;

      if recovering_skip and not allocation_collision then
        raise exception using errcode='P0003', message='historical skip has no proven allocation conflict';
      end if;
      apply_request := jsonb_build_object(
        'app_id', requested_app_id,
        'customer_id', requested_customer_id,
        'schema_revision_id', schema_revision_id,
        'actor_id', template->'actor_id',
        'source_kind', template->'source_kind',
        'idempotency_key', template->'idempotency_key',
        'change_type_id', coalesce(template->'change_type_id', 'null'::jsonb),
        'notes', coalesce(template->'notes', 'null'::jsonb),
        'mode', 'mainline',
        'writes', template->'writes'
      );
      begin
        apply_result := jsonb_build_object('ok',true,'data',
          kernel_apply_execute_internal(apply_request,false,null,null,true));
      exception
        when serialization_failure then raise;
        when others then
          -- Preserve the public apply error envelope while keeping seed authority private.
          get stacked diagnostics failure_state=returned_sqlstate,failure_message=message_text,
            failure_constraint=constraint_name,failure_table=table_name;
          apply_result := jsonb_build_object('ok',false,'error',kernel_apply_error_envelope_v2(
            failure_state,failure_message,failure_constraint,failure_table,apply_request));
      end;
      if coalesce((apply_result->>'ok')::boolean, false) is not true then
        failure := apply_result;
        raise exception using errcode = 'P0001', message = 'kernel seed defaults failed';
      end if;
      seed_result := jsonb_build_object(
        'seed_identity', current_seed_identity,
        'seed_record_ids', seed_record_ids,
        'status', 'applied',
        'change_set', apply_result->'data'
      );
      insert into installed_seed (
        app_id, customer_id, seed_identity, seed_record_ids, payload_fingerprint,
        source_idempotency_key, install_status, change_set_id, result
      ) values (
        requested_app_id, requested_customer_id, current_seed_identity,
        array(select (value #>> '{}')::uuid from jsonb_array_elements(seed_record_ids)),
        payload_fingerprint, template->>'idempotency_key', 'applied',
        (apply_result->'data'->>'id')::bigint, seed_result
      ) on conflict (app_id,customer_id,seed_identity) do update set
        seed_record_ids=excluded.seed_record_ids, install_status=excluded.install_status,
        change_set_id=excluded.change_set_id, result=excluded.result;
      applied_results := applied_results || jsonb_build_array(apply_result->'data');
      seed_results := seed_results || jsonb_build_array(seed_result);
      applied_count := applied_count + 1;
    exception
      when sqlstate 'P0001' then
        raise;
      when sqlstate 'P0003' then
        seed_results := seed_results || jsonb_build_array(installed_result || jsonb_build_object('status','already_installed'));
        skipped_count := skipped_count + 1;
      when sqlstate 'P0002' then
        seed_record_ids := template->'seed_record_ids';
        seed_result := jsonb_build_object(
          'seed_identity', current_seed_identity,
          'seed_record_ids', seed_record_ids,
          'status', 'skipped_existing',
          'change_set', null
        );
        insert into installed_seed (
          app_id, customer_id, seed_identity, seed_record_ids, payload_fingerprint,
          source_idempotency_key, install_status, change_set_id, result
        ) values (
          requested_app_id, requested_customer_id, current_seed_identity,
          array(select (value #>> '{}')::uuid from jsonb_array_elements(seed_record_ids)),
          payload_fingerprint, template->>'idempotency_key', 'skipped_existing', null, seed_result
        ) on conflict (app_id,customer_id,seed_identity) do nothing;
        seed_results := seed_results || jsonb_build_array(seed_result);
        skipped_count := skipped_count + 1;
    end;
    template_index := template_index + 1;
  end loop;
  exception when sqlstate 'P0001' then
    return failure;
  end;

  return jsonb_build_object('ok', true, 'data', jsonb_build_object(
    'change_sets', applied_results,
    'seeds', seed_results,
    'applied_count', applied_count,
    'skipped_count', skipped_count
  ));
end;
$kernel$;

-- artifact: function kernel_tenant_schema_strip_option(jsonb)
create or replace function kernel_tenant_schema_strip_option(option_value jsonb)
returns jsonb
language sql
immutable
parallel safe
security invoker
set search_path from current
as $kernel$
  select jsonb_strip_nulls(jsonb_build_object(
    'id', option_value->>'id',
    'label', option_value->>'label',
    'aliases', coalesce(option_value->'aliases', '[]'::jsonb),
    'origin', coalesce(option_value->>'origin', 'app'),
    'management', coalesce(option_value->>'management', 'fixed'),
    'lifecycle', coalesce(option_value->>'lifecycle', 'active')
  ))
$kernel$;

-- artifact: function kernel_tenant_schema_strip_field(jsonb)
create or replace function kernel_tenant_schema_strip_field(field_value jsonb)
returns jsonb
language sql
immutable
parallel safe
security invoker
set search_path from current
as $kernel$
  select jsonb_build_object(
    'id', field_value->>'id',
    'label', field_value->>'label',
    'type', field_value->>'type',
    'required', coalesce((field_value->>'required')::boolean, false),
    'is_unique', coalesce((field_value->>'is_unique')::boolean, false),
    'target_model', case
      when field_value ? 'target_model' and field_value->'target_model' <> 'null'::jsonb
        then to_jsonb(field_value->>'target_model')
      else 'null'::jsonb
    end,
    'option_set', coalesce((
      select jsonb_agg(kernel_tenant_schema_strip_option(option_item.value) order by option_item.ordinality)
      from jsonb_array_elements(coalesce(field_value->'option_set', '[]'::jsonb))
        with ordinality as option_item(value, ordinality)
    ), '[]'::jsonb),
    'origin', coalesce(field_value->>'origin', 'app'),
    'management', coalesce(field_value->>'management', 'fixed'),
    'lifecycle', coalesce(field_value->>'lifecycle', 'active')
  )
$kernel$;

-- artifact: function kernel_tenant_schema_strip_many_relation(jsonb)
create or replace function kernel_tenant_schema_strip_many_relation(relation_value jsonb)
returns jsonb
language sql
immutable
parallel safe
security invoker
set search_path from current
as $kernel$
  select jsonb_build_object(
    'id', relation_value->>'id',
    'label', relation_value->>'label',
    'target_model', relation_value->>'target_model',
    'origin', coalesce(relation_value->>'origin', 'app'),
    'management', coalesce(relation_value->>'management', 'fixed'),
    'lifecycle', coalesce(relation_value->>'lifecycle', 'active')
  )
$kernel$;

-- artifact: function kernel_tenant_schema_strip_model(jsonb)
create or replace function kernel_tenant_schema_strip_model(model_value jsonb)
returns jsonb
language sql
immutable
parallel safe
security invoker
set search_path from current
as $kernel$
  select jsonb_build_object(
    'id', model_value->>'id',
    'kind', model_value->>'kind',
    'label', model_value->>'label',
    'display_field_id', case
      when model_value ? 'display_field_id' and model_value->'display_field_id' <> 'null'::jsonb
        then model_value->'display_field_id'
      else 'null'::jsonb
    end,
    'origin', coalesce(model_value->>'origin', 'app'),
    'management', coalesce(model_value->>'management', 'fixed'),
    'lifecycle', coalesce(model_value->>'lifecycle', 'active'),
    'extensions', coalesce(model_value->'extensions', '{}'::jsonb),
    'fields', coalesce((
      select jsonb_agg(kernel_tenant_schema_strip_field(field_item.value) order by field_item.ordinality)
      from jsonb_array_elements(coalesce(model_value->'fields', '[]'::jsonb))
        with ordinality as field_item(value, ordinality)
    ), '[]'::jsonb),
    'many_relations', coalesce((
      select jsonb_agg(kernel_tenant_schema_strip_many_relation(relation_item.value) order by relation_item.ordinality)
      from jsonb_array_elements(coalesce(model_value->'many_relations', '[]'::jsonb))
        with ordinality as relation_item(value, ordinality)
    ), '[]'::jsonb)
  )
$kernel$;

-- artifact: function kernel_tenant_schema_strip_custom_field(jsonb)
create or replace function kernel_tenant_schema_strip_custom_field(field_value jsonb)
returns jsonb
language sql
immutable
parallel safe
security invoker
set search_path from current
as $kernel$
  select jsonb_strip_nulls(jsonb_build_object(
    'id', field_value->>'id',
    'model_id', field_value->>'model_id',
    'field_id', field_value->>'field_id',
    'label', field_value->>'label',
    'type', field_value->>'type',
    'target_model_id', case
      when field_value ? 'target_model_id' and field_value->'target_model_id' <> 'null'::jsonb
        then to_jsonb(field_value->>'target_model_id')
      else 'null'::jsonb
    end,
    'option_set', coalesce((
      select jsonb_agg(kernel_tenant_schema_strip_option(option_item.value) order by option_item.ordinality)
      from jsonb_array_elements(coalesce(field_value->'option_set', '[]'::jsonb))
        with ordinality as option_item(value, ordinality)
    ), '[]'::jsonb),
    'expression', field_value->'expression',
    'origin', coalesce(field_value->>'origin', 'app'),
    'management', coalesce(field_value->>'management', 'fixed'),
    'lifecycle', coalesce(field_value->>'lifecycle', 'active'),
    'archived_at', case
      when coalesce(field_value->>'lifecycle', 'active') = 'retired'
        then field_value->'archived_at'
      else null
    end
  ))
$kernel$;

-- artifact: function kernel_tenant_schema_catalog(jsonb,jsonb)
create or replace function kernel_tenant_schema_catalog(effective_schema jsonb, customer_overlay jsonb)
returns jsonb
language plpgsql
immutable
parallel safe
security invoker
set search_path from current
as $kernel$
declare
  tenant_state jsonb := coalesce(customer_overlay->'tenant_schema', '{}'::jsonb);
  catalog_models jsonb := '[]'::jsonb;
  catalog_custom_fields jsonb := '[]'::jsonb;
  model_value jsonb;
  field_value jsonb;
  relation_value jsonb;
  option_value jsonb;
  custom_value jsonb;
  decorated_fields jsonb;
  decorated_relations jsonb;
  decorated_options jsonb;
  decorated_model jsonb;
begin
  for model_value in
    select value from jsonb_array_elements(coalesce(effective_schema->'models', '[]'::jsonb))
  loop
    select value into decorated_model
    from jsonb_array_elements(coalesce(tenant_state->'models', '[]'::jsonb))
    where value->>'id' = model_value->>'id';
    if found then
      catalog_models := catalog_models || jsonb_build_array(decorated_model);
      continue;
    end if;

    decorated_fields := '[]'::jsonb;
    for field_value in select value from jsonb_array_elements(coalesce(model_value->'fields', '[]'::jsonb))
    loop
      decorated_options := '[]'::jsonb;
      for option_value in select value from jsonb_array_elements(coalesce(field_value->'option_set', '[]'::jsonb))
      loop
        decorated_options := decorated_options || jsonb_build_array(
          jsonb_build_object('origin', 'app', 'management', 'fixed', 'lifecycle', 'active') || option_value
        );
      end loop;
      decorated_fields := decorated_fields || jsonb_build_array(
        jsonb_build_object('origin', 'app', 'management', 'fixed', 'lifecycle', 'active')
          || field_value
          || jsonb_build_object('option_set', decorated_options)
      );
    end loop;
    decorated_relations := '[]'::jsonb;
    for relation_value in select value from jsonb_array_elements(coalesce(model_value->'many_relations', '[]'::jsonb))
    loop
      decorated_relations := decorated_relations || jsonb_build_array(
        jsonb_build_object('origin', 'app', 'management', 'fixed', 'lifecycle', 'active') || relation_value
      );
    end loop;
    decorated_model := model_value
      || jsonb_build_object(
        'origin', 'app',
        'management', coalesce(model_value->>'management', 'fixed'),
        'lifecycle', coalesce(model_value->>'lifecycle', 'active'),
        'display_field_id', model_value->>'display_field_id',
        'extensions', coalesce(model_value->'extensions', '{}'::jsonb),
        'fields', decorated_fields,
        'many_relations', decorated_relations
      );
    catalog_models := catalog_models || jsonb_build_array(decorated_model);
  end loop;

  for custom_value in
    select value from jsonb_array_elements(coalesce(effective_schema->'custom_fields', '[]'::jsonb))
  loop
    select value into field_value
    from jsonb_array_elements(coalesce(tenant_state->'custom_fields', '[]'::jsonb))
    where value->>'id' = custom_value->>'id';
    if found then
      catalog_custom_fields := catalog_custom_fields || jsonb_build_array(field_value);
    else
      decorated_options := '[]'::jsonb;
      for option_value in select value from jsonb_array_elements(coalesce(custom_value->'option_set', '[]'::jsonb))
      loop
        decorated_options := decorated_options || jsonb_build_array(
          jsonb_build_object('origin', 'app', 'management', 'fixed', 'lifecycle', 'active') || option_value
        );
      end loop;
      catalog_custom_fields := catalog_custom_fields || jsonb_build_array(
        jsonb_build_object(
            'origin', 'app',
            'management', coalesce(custom_value->>'management', 'fixed'),
            'lifecycle', coalesce(
              custom_value->>'lifecycle',
              case when coalesce(custom_value->>'archived_at', '') = '' then 'active' else 'retired' end
            )
          )
          || custom_value
          || jsonb_build_object('option_set', decorated_options)
      );
    end if;
  end loop;
  return jsonb_build_object('models', catalog_models, 'custom_fields', catalog_custom_fields);
end;
$kernel$;

-- artifact: function kernel_tenant_schema_validate_catalog(jsonb)
create or replace function kernel_tenant_schema_validate_catalog(catalog jsonb)
returns jsonb
language plpgsql
immutable
parallel safe
security invoker
set search_path from current
as $kernel$
declare
  issues jsonb := '[]'::jsonb;
  model_value jsonb;
  field_value jsonb;
  option_value jsonb;
  custom_value jsonb;
  relation_value jsonb;
  display_field jsonb;
  target_model jsonb;
  seen_keys jsonb;
  match_key text;
  prior_id text;
  alias_value jsonb;
  model_index integer;
  field_index integer;
  option_index integer;
  relation_index integer;
  alias_index integer;
  allowed_field_types text[] := array[
    'text', 'number', 'bool', 'date', 'datetime', 'relation', 'text_list',
    'known_aliases', 'json', 'enum', 'iso_country', 'iso_currency', 'money_rate'
  ];
  allowed_custom_types text[] := array[
    'text', 'number', 'bool', 'date', 'datetime', 'relation', 'text_list', 'enum', 'money_rate'
  ];
begin
  if jsonb_typeof(catalog) is distinct from 'object'
    or jsonb_typeof(catalog->'models') is distinct from 'array'
    or jsonb_typeof(catalog->'custom_fields') is distinct from 'array'
  then
    return jsonb_build_array(jsonb_build_object(
      'path', 'catalog', 'code', 'invalid_catalog', 'message', 'tenant schema catalog must contain model and custom-field arrays'
    ));
  end if;
  if exists (
    select 1 from jsonb_array_elements(catalog->'models')
    group by value->>'id' having count(*) > 1
  ) then
    issues := issues || jsonb_build_array(jsonb_build_object(
      'path', 'models', 'code', 'duplicate_model_id', 'message', 'model ids must be unique'
    ));
  end if;

  for model_value, model_index in
    select value, (ordinality - 1)::integer
    from jsonb_array_elements(catalog->'models') with ordinality
  loop
    if kernel_admin_normalize_identifier(model_value->>'id') is distinct from model_value->>'id' then
      issues := issues || jsonb_build_array(jsonb_build_object(
        'path', format('models[%s].id', model_index), 'code', 'invalid_identifier',
        'message', 'model id must already be a normalized kernel identifier'
      ));
    end if;
    if coalesce(btrim(model_value->>'label'), '') = '' then
      issues := issues || jsonb_build_array(jsonb_build_object(
        'path', format('models[%s].label', model_index), 'code', 'empty_value', 'message', 'model label must not be empty'
      ));
    end if;
    if model_value->>'origin' not in ('app', 'tenant')
      or model_value->>'management' not in ('fixed', 'tenant_managed')
      or model_value->>'lifecycle' not in ('active', 'retired')
    then
      issues := issues || jsonb_build_array(jsonb_build_object(
        'path', format('models[%s]', model_index), 'code', 'invalid_schema_metadata',
        'message', 'model origin, management, and lifecycle metadata are invalid'
      ));
    end if;
    if model_value->>'origin' = 'tenant'
      and (model_value->>'kind' <> 'lookup' or model_value->>'management' <> 'tenant_managed')
    then
      issues := issues || jsonb_build_array(jsonb_build_object(
        'path', format('models[%s]', model_index), 'code', 'invalid_tenant_model',
        'message', 'tenant-created models must be tenant-managed lookup models'
      ));
    end if;
    if jsonb_typeof(coalesce(model_value->'extensions', '{}'::jsonb)) is distinct from 'object'
      or jsonb_typeof(coalesce(model_value #> '{extensions,typed_custom_fields}', 'false'::jsonb)) is distinct from 'boolean'
    then
      issues := issues || jsonb_build_array(jsonb_build_object(
        'path', format('models[%s].extensions', model_index), 'code', 'invalid_entity_extensions',
        'message', 'model extensions must use the compiled typed_custom_fields and record_metadata contract'
      ));
    end if;
    if model_value->>'kind' = 'lookup'
      and model_value #> '{extensions,record_metadata}' is not null
      and model_value #> '{extensions,record_metadata}' <> 'null'::jsonb
    then
      issues := issues || jsonb_build_array(jsonb_build_object(
        'path', format('models[%s].extensions', model_index), 'code', 'lookup_extensions_forbidden',
        'message', 'lookup models cannot declare record metadata'
      ));
    end if;
    if model_value #> '{extensions,record_metadata}' is not null
      and model_value #> '{extensions,record_metadata}' <> 'null'::jsonb
      and (
        jsonb_typeof(model_value #> '{extensions,record_metadata}') <> 'object'
        or coalesce((model_value #>> '{extensions,record_metadata,max_bytes}')::numeric, 0) <= 0
        or coalesce((model_value #>> '{extensions,record_metadata,max_bytes}')::numeric, 65537) > 65536
        or coalesce((model_value #>> '{extensions,record_metadata,max_depth}')::numeric, 0) <= 0
        or coalesce((model_value #>> '{extensions,record_metadata,max_depth}')::numeric, 17) > 16
        or coalesce((model_value #>> '{extensions,record_metadata,max_keys}')::numeric, 0) <= 0
        or coalesce((model_value #>> '{extensions,record_metadata,max_keys}')::numeric, 257) > 256
        or coalesce((model_value #>> '{extensions,record_metadata,max_key_bytes}')::numeric, 0) <= 0
        or coalesce((model_value #>> '{extensions,record_metadata,max_key_bytes}')::numeric, 257) > 256
        or coalesce((model_value #>> '{extensions,record_metadata,max_scalar_bytes}')::numeric, 0) <= 0
        or coalesce((model_value #>> '{extensions,record_metadata,max_scalar_bytes}')::numeric, 16385) > 16384
        or coalesce((model_value #>> '{extensions,record_metadata,max_array_items}')::numeric, 0) <= 0
        or coalesce((model_value #>> '{extensions,record_metadata,max_array_items}')::numeric, 257) > 256
      )
    then
      issues := issues || jsonb_build_array(jsonb_build_object(
        'path', format('models[%s].extensions.record_metadata', model_index), 'code', 'invalid_metadata_limits',
        'message', 'record metadata limits must be within compiled byte, depth, and key bounds'
      ));
    end if;
    if jsonb_typeof(model_value->'fields') is distinct from 'array' then
      issues := issues || jsonb_build_array(jsonb_build_object(
        'path', format('models[%s].fields', model_index), 'code', 'invalid_fields', 'message', 'model fields must be an array'
      ));
      continue;
    end if;
    if exists (
      select 1 from jsonb_array_elements(model_value->'fields')
      group by value->>'id' having count(*) > 1
    ) then
      issues := issues || jsonb_build_array(jsonb_build_object(
        'path', format('models[%s].fields', model_index), 'code', 'duplicate_field_id', 'message', 'field ids must be unique within a model'
      ));
    end if;
    if exists (
      select identity
      from (
        select value->>'id' as identity from jsonb_array_elements(model_value->'fields')
        union all
        select value->>'id' from jsonb_array_elements(
          case when jsonb_typeof(model_value->'many_relations') = 'array'
            then model_value->'many_relations' else '[]'::jsonb end
        )
      ) as identities
      group by identity having count(*) > 1
    ) then
      issues := issues || jsonb_build_array(jsonb_build_object(
        'path', format('models[%s].many_relations', model_index), 'code', 'many_relation_id_collision',
        'message', 'many-relation ids must be unique and cannot collide with field ids'
      ));
    end if;

    for field_value, field_index in
      select value, (ordinality - 1)::integer
      from jsonb_array_elements(model_value->'fields') with ordinality
    loop
      if kernel_admin_normalize_identifier(field_value->>'id') is distinct from field_value->>'id' then
        issues := issues || jsonb_build_array(jsonb_build_object(
          'path', format('models[%s].fields[%s].id', model_index, field_index), 'code', 'invalid_identifier',
          'message', 'field id must already be a normalized kernel identifier'
        ));
      end if;
      if coalesce(btrim(field_value->>'label'), '') = '' or not (field_value->>'type' = any(allowed_field_types)) then
        issues := issues || jsonb_build_array(jsonb_build_object(
          'path', format('models[%s].fields[%s]', model_index, field_index), 'code', 'invalid_field',
          'message', 'field label and a supported type are required'
        ));
      end if;
      if field_value->>'origin' not in ('app', 'tenant')
        or field_value->>'management' not in ('fixed', 'tenant_managed')
        or field_value->>'lifecycle' not in ('active', 'retired')
      then
        issues := issues || jsonb_build_array(jsonb_build_object(
          'path', format('models[%s].fields[%s]', model_index, field_index), 'code', 'invalid_schema_metadata',
          'message', 'field origin, management, and lifecycle metadata are invalid'
        ));
      end if;
      if field_value->>'type' = 'relation' then
        select value into target_model from jsonb_array_elements(catalog->'models')
        where value->>'id' = field_value->>'target_model';
        if not found then
          issues := issues || jsonb_build_array(jsonb_build_object(
            'path', format('models[%s].fields[%s].target_model', model_index, field_index),
            'code', 'unknown_relation_target', 'message', 'relation target model does not exist'
          ));
        end if;
      elsif coalesce(field_value->>'target_model', '') <> '' then
        issues := issues || jsonb_build_array(jsonb_build_object(
          'path', format('models[%s].fields[%s].target_model', model_index, field_index),
          'code', 'unexpected_relation_target', 'message', 'only relation fields may declare target_model'
        ));
      end if;
      if field_value->>'type' = 'enum' then
        if jsonb_typeof(field_value->'option_set') is distinct from 'array' then
          issues := issues || jsonb_build_array(jsonb_build_object(
            'path', format('models[%s].fields[%s].option_set', model_index, field_index),
            'code', 'invalid_enum_options', 'message', 'enum option_set must be an array'
          ));
          continue;
        end if;
        seen_keys := '{}'::jsonb;
        for option_value, option_index in
          select value, (ordinality - 1)::integer
          from jsonb_array_elements(field_value->'option_set') with ordinality
        loop
          if kernel_admin_normalize_identifier(option_value->>'id') is distinct from option_value->>'id'
            or coalesce(btrim(option_value->>'label'), '') = ''
            or option_value->>'lifecycle' not in ('active', 'retired')
          then
            issues := issues || jsonb_build_array(jsonb_build_object(
              'path', format('models[%s].fields[%s].option_set[%s]', model_index, field_index, option_index),
              'code', 'invalid_enum_option', 'message', 'enum option identity, label, or lifecycle is invalid'
            ));
            continue;
          end if;
          if option_value->>'lifecycle' = 'active' then
            for match_key in
              select kernel_admin_enum_match_key(raw_value)
              from (
                select option_value->>'label' as raw_value
                union all
                select alias #>> '{}' from jsonb_array_elements(coalesce(option_value->'aliases', '[]'::jsonb)) as aliases(alias)
              ) as names
            loop
              if coalesce(match_key, '') = '' then
                issues := issues || jsonb_build_array(jsonb_build_object(
                  'path', format('models[%s].fields[%s].option_set[%s]', model_index, field_index, option_index),
                  'code', 'invalid_enum_alias', 'message', 'enum labels and aliases must normalize to a non-empty match key'
                ));
              else
                prior_id := seen_keys->>match_key;
                if prior_id is not null and prior_id <> option_value->>'id' then
                  issues := issues || jsonb_build_array(jsonb_build_object(
                    'path', format('models[%s].fields[%s].option_set[%s]', model_index, field_index, option_index),
                    'code', 'enum_alias_collision', 'message', format('normalized enum label or alias collides with option `%s`', prior_id)
                  ));
                else
                  seen_keys := seen_keys || jsonb_build_object(match_key, option_value->>'id');
                end if;
              end if;
            end loop;
          end if;
        end loop;
        if exists (
          select 1 from jsonb_array_elements(field_value->'option_set')
          group by value->>'id' having count(*) > 1
        ) then
          issues := issues || jsonb_build_array(jsonb_build_object(
            'path', format('models[%s].fields[%s].option_set', model_index, field_index),
            'code', 'duplicate_enum_option_id', 'message', 'enum option ids remain reserved after retirement'
          ));
        end if;
      elsif jsonb_array_length(coalesce(field_value->'option_set', '[]'::jsonb)) > 0 then
        issues := issues || jsonb_build_array(jsonb_build_object(
          'path', format('models[%s].fields[%s].option_set', model_index, field_index),
          'code', 'unexpected_enum_options', 'message', 'only enum fields may declare option_set values'
        ));
      end if;
    end loop;

    if jsonb_typeof(coalesce(model_value->'many_relations', '[]'::jsonb)) is distinct from 'array' then
      issues := issues || jsonb_build_array(jsonb_build_object(
        'path', format('models[%s].many_relations', model_index), 'code', 'invalid_many_relations',
        'message', 'model many_relations must be an array'
      ));
    else
      for relation_value, relation_index in
        select value, (ordinality - 1)::integer
        from jsonb_array_elements(coalesce(model_value->'many_relations', '[]'::jsonb)) with ordinality
      loop
        if kernel_admin_normalize_identifier(relation_value->>'id') is distinct from relation_value->>'id'
          or coalesce(btrim(relation_value->>'label'), '') = ''
          or coalesce(btrim(relation_value->>'target_model'), '') = ''
          or relation_value->>'origin' not in ('app', 'tenant')
          or relation_value->>'management' not in ('fixed', 'tenant_managed')
          or relation_value->>'lifecycle' not in ('active', 'retired')
        then
          issues := issues || jsonb_build_array(jsonb_build_object(
            'path', format('models[%s].many_relations[%s]', model_index, relation_index),
            'code', 'invalid_many_relation',
            'message', 'many relation identity, label, target, or schema metadata is invalid'
          ));
        end if;
        if not exists (
          select 1 from jsonb_array_elements(catalog->'models')
          where value->>'id' = relation_value->>'target_model'
        ) then
          issues := issues || jsonb_build_array(jsonb_build_object(
            'path', format('models[%s].many_relations[%s].target_model', model_index, relation_index),
            'code', 'unknown_many_relation_target', 'message', 'many-relation target model does not exist'
          ));
        end if;
      end loop;
    end if;

    if model_value->>'kind' = 'lookup' and model_value->>'lifecycle' = 'active' then
      select value into display_field from jsonb_array_elements(model_value->'fields')
      where value->>'id' = model_value->>'display_field_id'
        and value->>'type' = 'text'
        and coalesce((value->>'required')::boolean, false)
        and value->>'lifecycle' = 'active';
      if not found then
        issues := issues || jsonb_build_array(jsonb_build_object(
          'path', format('models[%s].display_field_id', model_index), 'code', 'invalid_display_field',
          'message', 'active lookup display_field_id must reference an active required text field'
        ));
      end if;
    end if;
  end loop;

  if exists (
    select 1 from jsonb_array_elements(catalog->'custom_fields')
    group by value->>'id' having count(*) > 1
  ) or exists (
    select 1 from jsonb_array_elements(catalog->'custom_fields')
    group by value->>'model_id', value->>'field_id' having count(*) > 1
  ) then
    issues := issues || jsonb_build_array(jsonb_build_object(
      'path', 'custom_fields', 'code', 'duplicate_custom_field',
      'message', 'custom-field definition ids and model/field identities must be unique'
    ));
  end if;
  for custom_value, field_index in
    select value, (ordinality - 1)::integer
    from jsonb_array_elements(catalog->'custom_fields') with ordinality
  loop
    select value into model_value from jsonb_array_elements(catalog->'models')
    where value->>'id' = custom_value->>'model_id';
    if not found then
      issues := issues || jsonb_build_array(jsonb_build_object(
        'path', format('custom_fields[%s].model_id', field_index), 'code', 'unknown_model',
        'message', 'custom field owner model does not exist'
      ));
    elsif not coalesce((model_value #>> '{extensions,typed_custom_fields}')::boolean, false)
      -- App-authored derived fields store nothing and need no tenant opt-in.
      and not (coalesce(custom_value->'expression', 'null'::jsonb) <> 'null'::jsonb and custom_value->>'origin' = 'app')
    then
      issues := issues || jsonb_build_array(jsonb_build_object(
        'path', format('custom_fields[%s].model_id', field_index), 'code', 'custom_fields_not_enabled',
        'message', 'app-owned model has not opted into tenant custom fields'
      ));
    end if;
    if coalesce(custom_value->'expression', 'null'::jsonb) <> 'null'::jsonb and custom_value->>'lifecycle' = 'active' then
      issues := issues || kernel_derived_issues(
        kernel_derived_environment(catalog, custom_value->>'model_id'),
        custom_value->>'field_id', custom_value->'expression', custom_value->>'type',
        format('custom_fields[%s]', field_index)
      );
    end if;
    if kernel_admin_normalize_identifier(custom_value->>'id') is distinct from custom_value->>'id'
      or kernel_admin_normalize_identifier(custom_value->>'field_id') is distinct from custom_value->>'field_id'
      or coalesce(btrim(custom_value->>'label'), '') = ''
      or not (custom_value->>'type' = any(allowed_custom_types))
      or custom_value->>'origin' not in ('app', 'tenant')
      or custom_value->>'management' not in ('fixed', 'tenant_managed')
      or custom_value->>'lifecycle' not in ('active', 'retired')
    then
      issues := issues || jsonb_build_array(jsonb_build_object(
        'path', format('custom_fields[%s]', field_index), 'code', 'invalid_custom_field',
        'message', 'custom-field identity, type, label, or schema metadata is invalid'
      ));
    end if;
    if custom_value ? 'archived_at' and custom_value->'archived_at' <> 'null'::jsonb
      and custom_value->>'lifecycle' <> 'retired'
    then
      issues := issues || jsonb_build_array(jsonb_build_object(
        'path', format('custom_fields[%s].archived_at', field_index), 'code', 'archived_lifecycle_conflict',
        'message', 'deprecated archived_at input is accepted only when lifecycle is retired'
      ));
    end if;
    if custom_value->>'lifecycle' = 'retired'
      and (not (custom_value ? 'archived_at') or custom_value->'archived_at' = 'null'::jsonb)
    then
      issues := issues || jsonb_build_array(jsonb_build_object(
        'path', format('custom_fields[%s].archived_at', field_index), 'code', 'custom_field_lifecycle_mismatch',
        'message', 'retired custom fields must retain archived_at'
      ));
    end if;
    if custom_value->>'type' = 'relation' then
      if not exists (
        select 1 from jsonb_array_elements(catalog->'models')
        where value->>'id' = custom_value->>'target_model_id'
      ) then
        issues := issues || jsonb_build_array(jsonb_build_object(
          'path', format('custom_fields[%s].target_model_id', field_index), 'code', 'unknown_relation_target',
          'message', 'custom relation target model does not exist'
        ));
      end if;
    elsif coalesce(custom_value->>'target_model_id', '') <> '' then
      issues := issues || jsonb_build_array(jsonb_build_object(
        'path', format('custom_fields[%s].target_model_id', field_index), 'code', 'unexpected_relation_target',
        'message', 'only relation custom fields may declare target_model_id'
      ));
    end if;
    if custom_value->>'type' = 'enum' then
      if jsonb_typeof(custom_value->'option_set') is distinct from 'array' then
        issues := issues || jsonb_build_array(jsonb_build_object(
          'path', format('custom_fields[%s].option_set', field_index),
          'code', 'invalid_enum_options', 'message', 'custom enum option_set must be an array'
        ));
        continue;
      end if;
      if exists (
        select 1 from jsonb_array_elements(custom_value->'option_set')
        group by value->>'id' having count(*) > 1
      ) then
        issues := issues || jsonb_build_array(jsonb_build_object(
          'path', format('custom_fields[%s].option_set', field_index),
          'code', 'duplicate_enum_option_id', 'message', 'enum option ids remain reserved after retirement'
        ));
      end if;
      seen_keys := '{}'::jsonb;
      for option_value, option_index in
        select value, (ordinality - 1)::integer
        from jsonb_array_elements(custom_value->'option_set') with ordinality
      loop
        if kernel_admin_normalize_identifier(option_value->>'id') is distinct from option_value->>'id'
          or coalesce(btrim(option_value->>'label'), '') = ''
          or option_value->>'lifecycle' not in ('active', 'retired')
        then
          issues := issues || jsonb_build_array(jsonb_build_object(
            'path', format('custom_fields[%s].option_set[%s]', field_index, option_index),
            'code', 'invalid_enum_option', 'message', 'enum option identity, label, or lifecycle is invalid'
          ));
          continue;
        end if;
        if option_value->>'lifecycle' = 'active' then
          for match_key in
            select kernel_admin_enum_match_key(raw_value)
            from (
              select option_value->>'label' as raw_value
              union all
              select alias #>> '{}' from jsonb_array_elements(coalesce(option_value->'aliases', '[]'::jsonb)) as aliases(alias)
            ) as names
          loop
            prior_id := seen_keys->>match_key;
            if coalesce(match_key, '') = '' then
              issues := issues || jsonb_build_array(jsonb_build_object(
                'path', format('custom_fields[%s].option_set[%s]', field_index, option_index),
                'code', 'invalid_enum_alias', 'message', 'enum labels and aliases must normalize to a non-empty match key'
              ));
            elsif prior_id is not null and prior_id <> option_value->>'id' then
              issues := issues || jsonb_build_array(jsonb_build_object(
                'path', format('custom_fields[%s].option_set[%s]', field_index, option_index),
                'code', 'enum_alias_collision', 'message', format('normalized enum label or alias collides with option `%s`', prior_id)
              ));
            else
              seen_keys := seen_keys || jsonb_build_object(match_key, option_value->>'id');
            end if;
          end loop;
        end if;
      end loop;
    elsif jsonb_array_length(coalesce(custom_value->'option_set', '[]'::jsonb)) > 0 then
      issues := issues || jsonb_build_array(jsonb_build_object(
        'path', format('custom_fields[%s].option_set', field_index),
        'code', 'unexpected_enum_options', 'message', 'only enum custom fields may declare option_set values'
      ));
    end if;
  end loop;
  return issues;
end;
$kernel$;

-- artifact: function kernel_tenant_schema_scalar_issues(jsonb,text)
create or replace function kernel_tenant_schema_scalar_issues(
  input_value jsonb,
  path text default 'operations'
)
returns jsonb
language plpgsql
immutable
parallel safe
security invoker
set search_path from current
as $kernel$
declare
  entry record;
  item jsonb;
  ordinal integer := 0;
  child_path text;
  issues jsonb := '[]'::jsonb;
begin
  if jsonb_typeof(input_value) = 'object' then
    for entry in
      select object_entry.key, object_entry.value
      from jsonb_each(input_value) as object_entry(key, value)
      order by object_entry.key
    loop
      child_path := path || '.' || entry.key;
      if entry.key in ('required', 'is_unique', 'typed_custom_fields')
        and entry.value <> 'null'::jsonb
        and jsonb_typeof(entry.value) <> 'boolean'
      then
        issues := issues || jsonb_build_array(jsonb_build_object(
          'path', child_path,
          'code', 'invalid_boolean',
          'message', entry.key || ' must be a JSON boolean'
        ));
      elsif entry.key in (
        'max_bytes', 'max_depth', 'max_keys', 'max_key_bytes',
        'max_scalar_bytes', 'max_array_items'
      ) and entry.value <> 'null'::jsonb
        and jsonb_typeof(entry.value) <> 'number'
      then
        issues := issues || jsonb_build_array(jsonb_build_object(
          'path', child_path,
          'code', 'invalid_number',
          'message', entry.key || ' must be a JSON number'
        ));
      end if;
      issues := issues || kernel_tenant_schema_scalar_issues(entry.value, child_path);
    end loop;
  elsif jsonb_typeof(input_value) = 'array' then
    for item in
      select array_item.value
      from jsonb_array_elements(input_value) as array_item(value)
    loop
      issues := issues || kernel_tenant_schema_scalar_issues(
        item,
        path || '[' || ordinal || ']'
      );
      ordinal := ordinal + 1;
    end loop;
  end if;
  return issues;
end;
$kernel$;

-- artifact: function kernel_tenant_schema_apply_operations(jsonb,jsonb,text,text,text)
create or replace function kernel_tenant_schema_apply_operations(
  initial_catalog jsonb,
  operations jsonb,
  actor_id text,
  mutation_at text,
  identity_seed text
)
returns jsonb
language plpgsql
volatile
parallel unsafe
security invoker
set search_path from current
as $kernel$
declare
  catalog jsonb := initial_catalog;
  models jsonb := initial_catalog->'models';
  custom_fields jsonb := initial_catalog->'custom_fields';
  changes jsonb := '[]'::jsonb;
  operation jsonb;
  operation_index integer;
  operation_type text;
  model_id text;
  field_id text;
  option_id text;
  from_option_id text;
  to_option_id text;
  alias_text text;
  target_kind text;
  model_index integer;
  field_index integer;
  relation_index integer;
  custom_index integer;
  option_index integer;
  from_option_index integer;
  to_option_index integer;
  current_model jsonb;
  current_field jsonb;
  current_relation jsonb;
  current_option jsonb;
  target_option jsonb;
  current_custom jsonb;
  next_value jsonb;
  next_fields jsonb;
  next_relations jsonb;
  next_options jsonb;
  supplied jsonb;
  issues jsonb;
  path_value text;
  allowed_operation_keys text[];
begin
  for operation, operation_index in
    select value, (ordinality - 1)::integer
    from jsonb_array_elements(operations) with ordinality
  loop
    if jsonb_typeof(operation) is distinct from 'object' then
      return kernel_admin_validation_error(jsonb_build_array(jsonb_build_object(
        'path', format('operations[%s]', operation_index), 'code', 'invalid_operation', 'message', 'operation must be a JSON object'
      )));
    end if;
    operation_type := operation->>'type';

    allowed_operation_keys := case operation_type
      when 'create_model' then array['type', 'model']
      when 'update_model' then array['type', 'model_id', 'label', 'management', 'extensions']
      when 'retire_model' then array['type', 'model_id']
      when 'restore_model' then array['type', 'model_id']
      when 'create_field' then array['type', 'model_id', 'field']
      when 'update_field' then array['type', 'model_id', 'field_id', 'label', 'required', 'is_unique', 'management']
      when 'retire_field' then array['type', 'model_id', 'field_id']
      when 'restore_field' then array['type', 'model_id', 'field_id']
      when 'create_many_relation' then array['type', 'model_id', 'relation']
      when 'update_many_relation' then array['type', 'model_id', 'relation_id', 'label', 'management']
      when 'retire_many_relation' then array['type', 'model_id', 'relation_id']
      when 'restore_many_relation' then array['type', 'model_id', 'relation_id']
      when 'create_enum_option' then array['type', 'model_id', 'field_id', 'option']
      when 'update_enum_option' then array['type', 'model_id', 'field_id', 'option_id', 'label', 'aliases', 'management']
      when 'retire_enum_option' then array['type', 'model_id', 'field_id', 'option_id']
      when 'restore_enum_option' then array['type', 'model_id', 'field_id', 'option_id']
      when 'transfer_enum_alias' then array['type', 'model_id', 'field_id', 'alias', 'from_option_id', 'to_option_id']
      when 'create_custom_field' then array['type', 'definition']
      when 'update_custom_field' then array['type', 'definition_id', 'label', 'management']
      when 'retire_custom_field' then array['type', 'definition_id']
      when 'restore_custom_field' then array['type', 'definition_id']
      else null
    end;
    if allowed_operation_keys is null then
      return kernel_admin_validation_error(jsonb_build_array(jsonb_build_object(
        'path', format('operations[%s].type', operation_index), 'code', 'unknown_tenant_schema_operation',
        'message', format('unsupported tenant schema operation `%s`', coalesce(operation_type, ''))
      )));
    end if;
    path_value := null;
    select supplied_key into path_value
    from jsonb_object_keys(operation) as supplied_key
    where not (supplied_key = any(allowed_operation_keys))
    order by supplied_key
    limit 1;
    if path_value is not null then
      return kernel_admin_validation_error(jsonb_build_array(jsonb_build_object(
        'path', format('operations[%s].%s', operation_index, path_value), 'code', 'unknown_field',
        'message', 'operation contains a field outside its typed contract'
      )));
    end if;

    if operation_type = 'create_model' then
      supplied := operation->'model';
      if jsonb_typeof(supplied) is distinct from 'object' then
        return kernel_admin_validation_error(jsonb_build_array(jsonb_build_object(
          'path', format('operations[%s].model', operation_index), 'code', 'invalid_model', 'message', 'model must be an object'
        )));
      end if;
      path_value := null;
      select supplied_key into path_value
      from jsonb_object_keys(supplied) as supplied_key
      where supplied_key not in ('kind', 'label', 'display_field_id', 'fields', 'many_relations')
      order by supplied_key
      limit 1;
      if path_value is not null then
        return kernel_admin_validation_error(jsonb_build_array(jsonb_build_object(
          'path', format('operations[%s].model.%s', operation_index, path_value), 'code', 'unknown_field',
          'message', 'model contains a server-owned or unknown field'
        )));
      end if;
      if jsonb_typeof(supplied->'kind') is distinct from 'string'
        or jsonb_typeof(supplied->'label') is distinct from 'string'
        or coalesce(btrim(supplied->>'label'), '') = ''
        or (supplied ? 'display_field_id' and supplied->'display_field_id' <> 'null'::jsonb
          and jsonb_typeof(supplied->'display_field_id') is distinct from 'string')
        or jsonb_typeof(supplied->'fields') is distinct from 'array'
        or (supplied ? 'many_relations' and jsonb_typeof(supplied->'many_relations') is distinct from 'array')
      then
        return kernel_admin_validation_error(jsonb_build_array(jsonb_build_object(
          'path', format('operations[%s].model', operation_index), 'code', 'invalid_model',
          'message', 'model kind, label, display_field_id, fields, or many_relations has an invalid type'
        )));
      end if;
      model_id := 'lookup_' || substr(
        kernel_admin_sha256(identity_seed || ':' || operation_index::text),
        1,
        24
      );
      if supplied->>'kind' <> 'lookup' then
        return kernel_admin_validation_error(jsonb_build_array(jsonb_build_object(
          'path', format('operations[%s].model.kind', operation_index), 'code', 'runtime_entity_model_forbidden',
          'message', 'only lookup models may be created at runtime'
        )));
      end if;
      if exists (select 1 from jsonb_array_elements(models) where value->>'id' = model_id) then
        return kernel_admin_validation_error(jsonb_build_array(jsonb_build_object(
          'path', format('operations[%s].model', operation_index), 'code', 'generated_model_id_collision',
          'message', 'generated model identity is already reserved'
        )));
      end if;
      next_fields := '[]'::jsonb;
      for current_field in select value from jsonb_array_elements(coalesce(supplied->'fields', '[]'::jsonb))
      loop
        next_options := '[]'::jsonb;
        for current_option in select value from jsonb_array_elements(coalesce(current_field->'option_set', '[]'::jsonb))
        loop
          next_options := next_options || jsonb_build_array(
            current_option || jsonb_build_object('origin', 'tenant', 'management', 'tenant_managed', 'lifecycle', 'active')
          );
        end loop;
        next_fields := next_fields || jsonb_build_array(
          current_field
            || jsonb_build_object(
              'required', coalesce((current_field->>'required')::boolean, false),
              'is_unique', coalesce((current_field->>'is_unique')::boolean, false),
              'target_model', coalesce(current_field->'target_model', 'null'::jsonb),
              'origin', 'tenant', 'management', 'tenant_managed', 'lifecycle', 'active',
              'option_set', next_options
            )
        );
      end loop;
      next_relations := '[]'::jsonb;
      for current_relation in select value from jsonb_array_elements(coalesce(supplied->'many_relations', '[]'::jsonb))
      loop
        next_relations := next_relations || jsonb_build_array(
          current_relation || jsonb_build_object(
            'origin', 'tenant', 'management', 'tenant_managed', 'lifecycle', 'active'
          )
        );
      end loop;
      next_value := jsonb_build_object(
        'id', model_id,
        'kind', 'lookup',
        'label', supplied->>'label',
        'display_field_id', coalesce(supplied->'display_field_id', 'null'::jsonb),
        'origin', 'tenant',
        'management', 'tenant_managed',
        'lifecycle', 'active',
        'extensions', '{}'::jsonb,
        'fields', next_fields,
        'many_relations', next_relations
      );
      models := models || jsonb_build_array(next_value);
      changes := changes || jsonb_build_array(jsonb_build_object(
        'operation', operation_type, 'path', 'models.' || model_id, 'before', 'null'::jsonb, 'after', next_value,
        'actor_id', actor_id, 'reason', null, 'changed_at', mutation_at
      ));

    elsif operation_type in ('update_model', 'retire_model', 'restore_model') then
      model_id := operation->>'model_id';
      select value, (ordinality - 1)::integer into current_model, model_index
      from jsonb_array_elements(models) with ordinality where value->>'id' = model_id;
      if not found or current_model->>'kind' <> 'lookup' then
        return kernel_admin_validation_error(jsonb_build_array(jsonb_build_object(
          'path', format('operations[%s].model_id', operation_index), 'code', 'unknown_lookup_model',
          'message', 'lookup model does not exist'
        )));
      end if;
      if current_model->>'management' <> 'tenant_managed' then
        return kernel_admin_error('schema_management_forbidden', 'Schema definition is fixed', jsonb_build_array(jsonb_build_object(
          'path', format('operations[%s].model_id', operation_index), 'code', 'fixed_definition',
          'message', 'app-owned fixed model cannot be changed by a tenant'
        )));
      end if;
      next_value := current_model;
      if operation_type = 'update_model' then
        supplied := operation - 'type' - 'model_id';
        if jsonb_typeof(supplied) is distinct from 'object' or exists (
          select 1 from jsonb_object_keys(supplied) as supplied_key(key_value)
          where key_value not in ('label', 'management', 'extensions')
        ) then
          return kernel_admin_validation_error(jsonb_build_array(jsonb_build_object(
            'path', format('operations[%s].changes', operation_index), 'code', 'immutable_model_property',
            'message', 'lookup model update contains an unsupported or immutable property'
          )));
        end if;
        if supplied ? 'management' and supplied->>'management' <> 'tenant_managed' then
          return kernel_admin_validation_error(jsonb_build_array(jsonb_build_object(
            'path', format('operations[%s].management', operation_index), 'code', 'invalid_management_transition',
            'message', 'tenant-managed definitions cannot be converted into fixed definitions'
          )));
        end if;
        if supplied ? 'extensions' and supplied->'extensions' is distinct from current_model->'extensions' then
          return kernel_admin_validation_error(jsonb_build_array(jsonb_build_object(
            'path', format('operations[%s].extensions', operation_index), 'code', 'immutable_entity_extensions',
            'message', 'tenant schema mutations cannot change app-owned extension capabilities'
          )));
        end if;
        if supplied ? 'label' then next_value := jsonb_set(next_value, '{label}', supplied->'label'); end if;
      elsif operation_type = 'retire_model' then
        if current_model->>'lifecycle' <> 'active' then
          return kernel_admin_validation_error(jsonb_build_array(jsonb_build_object(
            'path', format('operations[%s].model_id', operation_index), 'code', 'invalid_lifecycle_transition', 'message', 'only an active model can be retired'
          )));
        end if;
        next_value := next_value || jsonb_build_object('lifecycle', 'retired', 'retired_at', mutation_at);
      else
        if current_model->>'lifecycle' <> 'retired' then
          return kernel_admin_validation_error(jsonb_build_array(jsonb_build_object(
            'path', format('operations[%s].model_id', operation_index), 'code', 'invalid_lifecycle_transition', 'message', 'only a retired model can be restored'
          )));
        end if;
        next_value := (next_value - 'retired_at') || jsonb_build_object('lifecycle', 'active');
      end if;
      models := jsonb_set(models, array[model_index::text], next_value);
      changes := changes || jsonb_build_array(jsonb_build_object(
        'operation', operation_type, 'path', 'models.' || model_id, 'before', current_model, 'after', next_value,
        'actor_id', actor_id, 'changed_at', mutation_at
      ));

    elsif operation_type in ('create_field', 'update_field', 'retire_field', 'restore_field') then
      model_id := operation->>'model_id';
      select value, (ordinality - 1)::integer into current_model, model_index
      from jsonb_array_elements(models) with ordinality where value->>'id' = model_id;
      if not found or current_model->>'kind' <> 'lookup' or current_model->>'lifecycle' <> 'active' then
        return kernel_admin_validation_error(jsonb_build_array(jsonb_build_object(
          'path', format('operations[%s].model_id', operation_index), 'code', 'unknown_active_lookup_model',
          'message', 'an active lookup model is required'
        )));
      end if;
      next_fields := current_model->'fields';
      if operation_type = 'create_field' then
        if current_model->>'management' <> 'tenant_managed' then
          return kernel_admin_error('schema_management_forbidden', 'Schema definition is fixed', jsonb_build_array(jsonb_build_object(
            'path', format('operations[%s].model_id', operation_index), 'code', 'fixed_definition',
            'message', 'fixed lookup model does not accept tenant-created fields'
          )));
        end if;
        supplied := operation->'field';
        field_id := supplied->>'id';
        if jsonb_typeof(supplied) is distinct from 'object' then
          return kernel_admin_validation_error(jsonb_build_array(jsonb_build_object(
            'path', format('operations[%s].field', operation_index), 'code', 'invalid_field', 'message', 'field must be an object'
          )));
        end if;
        if exists (select 1 from jsonb_array_elements(next_fields) where value->>'id' = field_id) then
          return kernel_admin_validation_error(jsonb_build_array(jsonb_build_object(
            'path', format('operations[%s].field.id', operation_index), 'code', 'field_id_reserved',
            'message', 'field id already exists or remains reserved after retirement'
          )));
        end if;
        next_options := '[]'::jsonb;
        for current_option in select value from jsonb_array_elements(coalesce(supplied->'option_set', '[]'::jsonb))
        loop
          next_options := next_options || jsonb_build_array(
            current_option || jsonb_build_object('origin', 'tenant', 'management', 'tenant_managed', 'lifecycle', 'active')
          );
        end loop;
        next_value := supplied || jsonb_build_object(
          'required', coalesce((supplied->>'required')::boolean, false),
          'is_unique', coalesce((supplied->>'is_unique')::boolean, false),
          'target_model', coalesce(supplied->'target_model', 'null'::jsonb),
          'option_set', next_options,
          'origin', 'tenant', 'management', 'tenant_managed', 'lifecycle', 'active'
        );
        next_fields := next_fields || jsonb_build_array(next_value);
        current_field := null;
      else
        field_id := operation->>'field_id';
        select value, (ordinality - 1)::integer into current_field, field_index
        from jsonb_array_elements(next_fields) with ordinality where value->>'id' = field_id;
        if not found then
          return kernel_admin_validation_error(jsonb_build_array(jsonb_build_object(
            'path', format('operations[%s].field_id', operation_index), 'code', 'unknown_lookup_field', 'message', 'lookup field does not exist'
          )));
        end if;
        if current_field->>'management' <> 'tenant_managed' then
          return kernel_admin_error('schema_management_forbidden', 'Schema definition is fixed', jsonb_build_array(jsonb_build_object(
            'path', format('operations[%s].field_id', operation_index), 'code', 'fixed_definition', 'message', 'lookup field is not tenant-manageable'
          )));
        end if;
        next_value := current_field;
        if operation_type = 'update_field' then
          supplied := operation - 'type' - 'model_id' - 'field_id';
          if jsonb_typeof(supplied) is distinct from 'object' then
            return kernel_admin_validation_error(jsonb_build_array(jsonb_build_object(
              'path', format('operations[%s].changes', operation_index), 'code', 'invalid_field_update', 'message', 'field changes must be an object'
            )));
          end if;
          if supplied ? 'type' and supplied->>'type' is distinct from current_field->>'type' then
            return kernel_admin_validation_error(jsonb_build_array(jsonb_build_object(
              'path', format('operations[%s].changes.type', operation_index), 'code', 'immutable_field_type', 'message', 'field type is immutable'
            )));
          end if;
          if supplied ? 'target_model' and supplied->'target_model' is distinct from current_field->'target_model' then
            return kernel_admin_validation_error(jsonb_build_array(jsonb_build_object(
              'path', format('operations[%s].changes.target_model', operation_index), 'code', 'immutable_relation_target', 'message', 'relation target is immutable'
            )));
          end if;
          if exists (
            select 1 from jsonb_object_keys(supplied) as supplied_key(key_value)
            where key_value not in ('label', 'required', 'is_unique', 'management', 'type', 'target_model')
          ) then
            return kernel_admin_validation_error(jsonb_build_array(jsonb_build_object(
              'path', format('operations[%s].changes', operation_index), 'code', 'immutable_field_property',
              'message', 'field update contains an unsupported or immutable property'
            )));
          end if;
          if supplied ? 'management' and supplied->>'management' <> 'tenant_managed' then
            return kernel_admin_validation_error(jsonb_build_array(jsonb_build_object(
              'path', format('operations[%s].management', operation_index), 'code', 'invalid_management_transition',
              'message', 'tenant-managed definitions cannot be converted into fixed definitions'
            )));
          end if;
          if supplied ? 'label' then next_value := jsonb_set(next_value, '{label}', supplied->'label'); end if;
          if supplied ? 'required' then next_value := jsonb_set(next_value, '{required}', supplied->'required'); end if;
          if supplied ? 'is_unique' then next_value := jsonb_set(next_value, '{is_unique}', supplied->'is_unique'); end if;
        elsif operation_type = 'retire_field' then
