    end if;
    if prepared.ready_at is null then
      return kernel_installer_error('schema_revision_not_ready', 'Schema revision is not ready', 'targets.' || customer_id, 'readiness_required', 'every continuation target must pass readiness validation');
    end if;
    select sr.id, sir.activation_kind, sir.release_id,
           sir.base_artifact_hash, sir.effective_artifact_hash
    into active
    from schema_revision sr
    left join schema_installation_revision sir on sir.schema_revision_id = sr.id
    where sr.app_id = installer_app_base_continuation.app_id
      and sr.customer_id = installer_app_base_continuation.customer_id
      and sr.activated_at is not null
    for update of sr;
    if active.id is not null then
      if active.id is distinct from schema_revision_id
        or active.activation_kind is distinct from 'app_base'
        or active.release_id is distinct from release_id
        or active.base_artifact_hash is distinct from base_artifact_hash
        or active.effective_artifact_hash is distinct from effective_artifact_hash
      then
        return kernel_installer_error('schema_activation_conflict', 'Schema activation conflict', 'targets.' || customer_id, 'target_has_different_active_revision', 'continuation cannot replace an active revision or tenant overlay');
      end if;
    elsif expected_hash is not null then
      return kernel_installer_error('schema_activation_conflict', 'Schema activation conflict', 'targets.' || customer_id, 'expected_hash_mismatch', 'the target no longer has the active revision recorded at preparation');
    end if;
  end loop;

  begin
    for target in
      select value from jsonb_array_elements(targets) as item(value)
      order by value->>'customer_id'
    loop
      schema_revision_id := (target->>'schema_revision_id')::bigint;
      customer_id := target->>'customer_id';
      effective_artifact_hash := target->>'effective_artifact_hash';
      perform set_config('kernel.app_id', app_id, true);
      perform set_config('kernel.customer_id', customer_id, true);
      select sr.activated_at, sr.base_schema->>'version' as base_schema_version
      into prepared
      from schema_revision sr
      where sr.id = installer_app_base_continuation.schema_revision_id
        and sr.app_id = installer_app_base_continuation.app_id
        and sr.customer_id = installer_app_base_continuation.customer_id
      for update;
      insert into schema_activation_head (app_id, customer_id, base_schema_version)
      values (
        installer_app_base_continuation.app_id,
        installer_app_base_continuation.customer_id,
        coalesce(prepared.base_schema_version, installer_app_base_continuation.release_id)
      )
      on conflict on constraint schema_activation_head_pkey do update
        set base_schema_version = excluded.base_schema_version, advanced_at = now();
      if prepared.activated_at is null then
        all_idempotent := false;
        update schema_revision as revision
        set activated_at = now()
        where revision.id = installer_app_base_continuation.schema_revision_id
          and revision.app_id = installer_app_base_continuation.app_id
          and revision.customer_id = installer_app_base_continuation.customer_id;
        update schema_installation_revision as installation
        set activated_at = now()
        where installation.schema_revision_id = installer_app_base_continuation.schema_revision_id
          and installation.app_id = installer_app_base_continuation.app_id
          and installation.customer_id = installer_app_base_continuation.customer_id;
        insert into lookup_storage_authority(
          app_id, customer_id, model_id, schema_hash, authority,
          legacy_record_table, legacy_version_table, activated_at
        )
        select sr.app_id, sr.customer_id, model.value->>'id', sr.schema_hash,
               'generic', 'lookup_record', 'lookup_version', now()
        from schema_revision sr
        cross join lateral jsonb_array_elements(sr.schema->'models') model(value)
        where sr.id = installer_app_base_continuation.schema_revision_id
          and model.value->>'kind' = 'lookup'
          and not kernel_lookup_has_typed_history(sr.app_id, sr.customer_id, model.value->>'id')
        on conflict on constraint lookup_storage_authority_pkey do nothing;
        perform kernel_reconcile_lookup_foreign_key_targets(
          installer_app_base_continuation.app_id,
          installer_app_base_continuation.customer_id
        );
        select sir.seed_change_sets into target_seed_change_sets
        from schema_installation_revision sir
        where sir.schema_revision_id = installer_app_base_continuation.schema_revision_id;
        if jsonb_array_length(target_seed_change_sets) > 0 then
          seed_result := kernel_apply_seed_defaults(jsonb_build_object(
            'app_id', app_id, 'customer_id', customer_id,
            'schema_revision_id', schema_revision_id,
            'change_sets', target_seed_change_sets
          ));
          if coalesce((seed_result->>'ok')::boolean, false) is not true then
            raise exception using errcode = 'P0001', message = 'kernel seed activation failed';
          end if;
        end if;
      end if;
      activated_targets := activated_targets || jsonb_build_array(jsonb_build_object(
        'customer_id', customer_id,
        'schema_revision_id', schema_revision_id,
        'effective_artifact_hash', effective_artifact_hash
      ));
    end loop;
  exception when others then
    if seed_result is not null
      and coalesce((seed_result->>'ok')::boolean, false) is not true
    then
      return seed_result;
    end if;
    return kernel_installer_error('database_error', 'Database operation failed', 'activation', 'continuation_failed', 'app-base continuation was rolled back for every selected target');
  end;

  return jsonb_build_object('ok', true, 'data', jsonb_build_object(
    'activation_kind', 'app_base', 'app_id', app_id, 'release_id', release_id,
    'base_artifact_hash', base_artifact_hash, 'targets', activated_targets,
    'state', 'active', 'idempotent', all_idempotent
  ));
end;
$kernel$;

-- artifact: function kernel_sync_schema_constraint_identities(bigint)
create or replace function kernel_sync_schema_constraint_identities(requested_revision_id bigint)
returns void
language plpgsql
volatile
security invoker
set search_path from current
as $kernel$
declare
  revision_row record;
  expected_catalog jsonb;
  actual_catalog jsonb;
begin
  select id, app_id, customer_id, base_schema->>'version' as base_version
  into strict revision_row from schema_revision where id = requested_revision_id for update;
  select catalog into expected_catalog from schema_constraint_identity_source as source
  where source.app_id = revision_row.app_id
    and source.schema_version = revision_row.base_version;
  if found then
    insert into schema_constraint_identity (schema_revision_id, app_id, customer_id, catalog)
    values (revision_row.id, revision_row.app_id, revision_row.customer_id, expected_catalog)
    on conflict do nothing;
  end if;
  select catalog into actual_catalog from schema_constraint_identity
  where schema_revision_id = revision_row.id;
  if actual_catalog is distinct from expected_catalog then
    raise exception using errcode = 'P0001', message = 'schema constraint catalog drift';
  end if;
end;
$kernel$;

-- artifact: function kernel_constraint_identity_drift(jsonb)
create or replace function kernel_constraint_identity_drift(expected_schema jsonb)
returns jsonb
language plpgsql
stable
security invoker
set search_path from current
as $kernel$
declare
  expected_catalog jsonb;
  actual_catalog jsonb;
  identity_value jsonb;
  active_row record;
begin
  select source.catalog into expected_catalog
  from schema_constraint_identity_source as source
  where source.app_id = expected_schema->>'app_id'
    and source.schema_version = expected_schema->>'version';
  select revision.id, revision.base_schema->>'version' as base_version into active_row
  from schema_revision as revision
  where revision.app_id = expected_schema->>'app_id'
    and revision.customer_id = expected_schema->>'customer_id'
    and revision.activated_at is not null;
  if found and active_row.base_version = expected_schema->>'version' then
    select snapshot.catalog into actual_catalog from schema_constraint_identity as snapshot
    where snapshot.schema_revision_id = active_row.id
      and snapshot.app_id = expected_schema->>'app_id'
      and snapshot.customer_id = expected_schema->>'customer_id';
    if actual_catalog is distinct from expected_catalog then
      return kernel_installer_schema_drift('schema_constraint_identity', 'constraint identities differ from the checked catalog');
    end if;
  end if;
  -- Legacy revisions have no catalog; they retain generic database errors.
  -- New generated releases persist even an empty catalog, so empty is not absent.
  for identity_value in select value from jsonb_array_elements(coalesce(expected_catalog, '[]'::jsonb)) loop
    -- Interval rules have no CHECK; their generated enforcement needs the
    -- model version table to carry every referenced field column.
    if identity_value->>'kind' = 'non_overlapping_intervals' then
      if exists (
        select 1 from jsonb_array_elements_text(identity_value->'field_ids') as item(field_id)
        where not exists (
          select 1 from pg_attribute as attribute
          join pg_class as relation on relation.oid = attribute.attrelid
          join pg_namespace as namespace on namespace.oid = relation.relnamespace
          where namespace.nspname = current_schema()
            and relation.relname = kernel_physical_identifier(kernel_physical_identifier(identity_value->>'model_id') || '_version')
            and attribute.attname = kernel_physical_identifier(item.field_id)
            and attribute.attnum > 0 and not attribute.attisdropped
        )
      ) then
        return kernel_installer_schema_drift('schema_constraint_identity', 'declared interval rule references a missing version column');
      end if;
      continue;
    end if;
    if not exists (
      select 1 from pg_constraint as constraint_value
      join pg_class as relation on relation.oid = constraint_value.conrelid
      join pg_namespace as namespace on namespace.oid = relation.relnamespace
      where namespace.nspname = current_schema()
        and relation.relname = identity_value->>'table_name'
        and constraint_value.conname = identity_value->>'constraint_name'
        and constraint_value.contype = 'c' and constraint_value.convalidated
    ) then
      return kernel_installer_schema_drift('schema_constraint_identity', 'declared CHECK identity is missing or invalid');
    end if;
  end loop;
  return null;
end;
$kernel$;

-- artifact: function kernel_constraint_interval_rules(text,text,bigint)
create or replace function kernel_constraint_interval_rules(
  app_id text,
  customer_id text,
  schema_revision_id bigint
)
returns jsonb
language sql
stable
security invoker
set search_path from current
as $kernel$
  select jsonb_build_object(
    'schema', revision.schema,
    'rules', coalesce((
      select jsonb_agg(entry.value order by entry.value->>'model_id', entry.value->>'constraint_id')
      from schema_constraint_identity as snapshot
      cross join lateral jsonb_array_elements(snapshot.catalog) as entry(value)
      where snapshot.schema_revision_id = revision.id
        and snapshot.app_id = revision.app_id
        and snapshot.customer_id = revision.customer_id
        and entry.value->>'kind' = 'non_overlapping_intervals'
    ), '[]'::jsonb)
  )
  from schema_revision as revision
  where revision.app_id = $1
    and revision.customer_id = $2
    and (($3 is null and revision.activated_at is not null) or revision.id = $3)
$kernel$;

-- artifact: function kernel_constraint_interval_isolation_error(text,text,bigint,text[])
create or replace function kernel_constraint_interval_isolation_error(
  app_id text,
  customer_id text,
  schema_revision_id bigint,
  model_ids text[]
)
returns jsonb
language plpgsql
stable
security invoker
set search_path from current
as $kernel$
begin
  if current_setting('transaction_isolation') = 'read committed' or not exists (
    select 1
    from jsonb_array_elements(
      coalesce(kernel_constraint_interval_rules(app_id, customer_id, schema_revision_id)->'rules', '[]'::jsonb)
    ) as rule(value)
    where model_ids is null or rule.value->>'model_id' = any(model_ids)
  ) then
    return null;
  end if;
  return jsonb_build_object(
    'code', 'contract_validation_failed',
    'message', 'Contract validation failed',
    'details', jsonb_build_array(jsonb_build_object(
      'path', 'transaction',
      'code', 'interval_rule_requires_read_committed',
      'message', 'interval rules require a READ COMMITTED transaction'
    ))
  );
end;
$kernel$;

-- artifact: function kernel_constraint_interval_lock(text,text,bigint,text[])
create or replace function kernel_constraint_interval_lock(
  app_id text,
  customer_id text,
  schema_revision_id bigint,
  model_ids text[]
)
returns void
language plpgsql
volatile
security invoker
set search_path from current
as $kernel$
declare
  locked_model_id text;
begin
  for locked_model_id in
    select distinct rule.value->>'model_id'
    from jsonb_array_elements(
      coalesce(kernel_constraint_interval_rules(app_id, customer_id, schema_revision_id)->'rules', '[]'::jsonb)
    ) as rule(value)
    where rule.value->>'model_id' = any(model_ids)
    order by 1
  loop
    -- The lock serializes writers, but only READ COMMITTED re-reads committed
    -- rows after waiting; an older snapshot could miss a concurrent overlap.
    if current_setting('transaction_isolation') <> 'read committed' then
      raise exception using errcode = 'P0001', message = 'kernel_apply:' || jsonb_build_object(
        'code', 'contract_validation_failed',
        'message', 'Contract validation failed',
        'details', jsonb_build_array(jsonb_build_object(
          'path', 'transaction',
          'code', 'interval_rule_requires_read_committed',
          'message', 'writes to a model with an interval rule require a READ COMMITTED transaction'
        ))
      )::text;
    end if;
    perform pg_advisory_xact_lock(hashtextextended(
      'interval-exclusion' || E'\x1f' || app_id || E'\x1f' || customer_id || E'\x1f' || locked_model_id, 0
    ));
  end loop;
end;
$kernel$;

-- artifact: function kernel_constraint_interval_violation(text,text,bigint,jsonb)
create or replace function kernel_constraint_interval_violation(
  app_id text,
  customer_id text,
  schema_revision_id bigint,
  record_scope jsonb
)
returns jsonb
language plpgsql
volatile
security invoker
set search_path from current
as $kernel$
declare
  loaded jsonb;
  rule jsonb;
  model jsonb;
  subject jsonb;
  scoped uuid[];
  subject_predicate text;
  start_column text;
  end_column text;
  overlap_pair jsonb;
  model_label text;
  start_label text;
  end_label text;
  subject_label text;
  message text;
begin
  loaded := kernel_constraint_interval_rules(app_id, customer_id, schema_revision_id);
  for rule in
    select value from jsonb_array_elements(coalesce(loaded->'rules', '[]'::jsonb)) as item(value)
    order by value->>'model_id', value->>'constraint_id'
  loop
    scoped := null;
    if record_scope is not null then
      select array_agg(distinct item.value::uuid) into scoped
      from jsonb_array_elements_text(coalesce(record_scope->(rule->>'model_id'), '[]'::jsonb)) as item(value);
      if scoped is null then continue; end if;
    end if;
    select value into model from jsonb_array_elements(loaded->'schema'->'models') as item(value)
    where value->>'id' = rule->>'model_id';
    if model is null then
      return jsonb_build_object('code', 'schema_drift', 'message', 'Schema drift detected',
        'details', jsonb_build_array(jsonb_build_object('path', 'constraint', 'code', 'schema_drift',
          'message', rule->>'constraint_id')));
    end if;
    start_column := quote_ident(kernel_physical_identifier(rule->>'start_field_id'));
    end_column := quote_ident(kernel_physical_identifier(rule->>'end_field_id'));
    for subject in select value from jsonb_array_elements(rule->'subject_field_ids') as item(value) loop
      select string_agg(format('a.%1$s = b.%1$s', quote_ident(kernel_physical_identifier(item.value))), ' and ' order by item.ordinal)
      into subject_predicate
      from jsonb_array_elements_text(subject) with ordinality as item(value, ordinal);
      overlap_pair := null;
      execute format(
        'with live as (
           select v.* from %1$s v join change_set cs
             on cs.id = v.change_set_id and cs.app_id = v.app_id and cs.customer_id = v.customer_id
           where v.app_id = $1 and v.customer_id = $2 and v.stage = ''mainline'' and v.effective_end is null
             and not v.tombstones_record and not v.untombstones_record
             and cs.status = ''mainline'' and cs.applied_order is not null
         )
         select jsonb_build_object(
           ''other_record_id'', b.record_id,
           ''start'', a.%2$s, ''end'', a.%3$s, ''other_start'', b.%2$s, ''other_end'', b.%3$s
         )
         from live a join live b on b.record_id <> a.record_id and %4$s
           and greatest(a.%2$s, b.%2$s) <= least(coalesce(a.%3$s, ''infinity''::date), coalesce(b.%3$s, ''infinity''::date))
         where $3::uuid[] is null or a.record_id = any($3)
         order by a.record_id, b.record_id
         limit 1',
        quote_ident(kernel_physical_identifier(kernel_physical_identifier(rule->>'model_id') || '_version')),
        start_column, end_column, subject_predicate
      ) using app_id, customer_id, scoped into overlap_pair;
      if overlap_pair is null then continue; end if;

      model_label := coalesce(model->>'label', rule->>'model_id');
      select coalesce(max(value->>'label') filter (where value->>'id' = rule->>'start_field_id'), rule->>'start_field_id'),
             coalesce(max(value->>'label') filter (where value->>'id' = rule->>'end_field_id'), rule->>'end_field_id')
      into start_label, end_label
      from jsonb_array_elements(model->'fields') as item(value);
      select string_agg(coalesce(field.value->>'label', item.value), ' and ' order by item.ordinal)
      into subject_label
      from jsonb_array_elements_text(subject) with ordinality as item(value, ordinal)
      left join lateral (
        select value from jsonb_array_elements(model->'fields') as candidate(value)
        where candidate.value->>'id' = item.value
      ) as field on true;
      message := format(
        '%s: %s (%s %s, %s %s) overlaps another %s with the same %s (%s %s, %s %s)',
        coalesce(rule->>'label', rule->>'constraint_id'),
        model_label, start_label, overlap_pair->>'start', end_label, coalesce(overlap_pair->>'end', 'none'),
        model_label, subject_label,
        start_label, overlap_pair->>'other_start', end_label, coalesce(overlap_pair->>'other_end', 'none')
      );
      return jsonb_build_object(
        'code', 'constraint_violation',
        'message', message,
        'details', jsonb_build_array(
          jsonb_build_object('path', 'interval', 'code', 'constraint_violation', 'message', message),
          jsonb_build_object('path', 'model', 'code', 'constraint_violation', 'message', rule->>'model_id'),
          jsonb_build_object('path', 'constraint', 'code', 'constraint_violation', 'message', rule->>'constraint_id')
        ) || coalesce((
          select jsonb_agg(jsonb_build_object('path', 'field', 'code', 'constraint_violation', 'message', item.value) order by item.ordinal)
          from jsonb_array_elements_text(rule->'field_ids') with ordinality as item(value, ordinal)
        ), '[]'::jsonb) || jsonb_build_array(
          jsonb_build_object('path', 'record', 'code', 'constraint_violation', 'message', overlap_pair->>'other_record_id')
        )
      );
    end loop;
  end loop;
  return null;
end;
$kernel$;

-- artifact: function kernel_install_runtime_privileges()
create or replace function kernel_install_runtime_privileges()
returns void
language plpgsql
volatile
parallel unsafe
security invoker
set search_path from current
as $kernel$
declare
  schema_name text := current_schema();
  role_name text;
  role_row record;
  execution_role text := kernel_installer_capability_role('execution_owner');
  runtime_role text := kernel_installer_capability_role('runtime');
  schema_admin_role text := kernel_installer_capability_role('schema_admin');
  query_role text := kernel_installer_capability_role('query');
  function_row record;
  entrypoint text;
  qualified_function text;
begin
  perform pg_advisory_xact_lock(hashtextextended(
    current_database() || ':' || schema_name || ':kernel_generated_runtime_roles', 0
  ));
  foreach role_name in array array[
    execution_role, runtime_role, schema_admin_role, query_role
  ] loop
    if to_regrole(role_name) is null then
      execute format(
        'create role %I nologin nosuperuser nocreatedb nocreaterole noinherit noreplication nobypassrls',
        role_name
      );
    end if;
    select rolcanlogin, rolsuper, rolcreatedb, rolcreaterole, rolreplication, rolbypassrls

    into role_row
    from pg_roles
    where rolname = role_name;
    if role_row.rolcanlogin or role_row.rolsuper or role_row.rolcreatedb
      or role_row.rolcreaterole or role_row.rolreplication or role_row.rolbypassrls
    then
      raise exception using
        errcode = '42501',
        message = format('%s has unsafe role attributes', role_name);
    end if;
  end loop;

  if current_user <> execution_role
    and not pg_has_role(current_user, execution_role, 'SET')
  then
    execute format('grant %I to %I', execution_role, current_user);
  end if;

  alter table work_session enable row level security;
  alter table work_session force row level security;
  alter table work_session_record enable row level security;
  alter table work_session_record force row level security;
  drop policy if exists kernel_work_owner on work_session;
  create policy kernel_work_owner on work_session using (
    app_id=current_setting('kernel.app_id',true) and customer_id=current_setting('kernel.customer_id',true)
    and owner_id=nullif(current_setting('kernel.actor_id',true),'')
    and kernel_principal_scope_authorized('runtime',app_id,customer_id,null)
  ) with check (
    app_id=current_setting('kernel.app_id',true) and customer_id=current_setting('kernel.customer_id',true)
    and owner_id=nullif(current_setting('kernel.actor_id',true),'')
    and kernel_principal_scope_authorized('runtime',app_id,customer_id,null)
  );
  drop policy if exists kernel_work_owner on work_session_record;
  create policy kernel_work_owner on work_session_record using (
    exists(select 1 from work_session s where s.app_id=work_session_record.app_id and s.customer_id=work_session_record.customer_id and s.id=session_id)
  ) with check (
    exists(select 1 from work_session s where s.app_id=work_session_record.app_id and s.customer_id=work_session_record.customer_id and s.id=session_id)
  );
  execute format('grant usage, create on schema %I to %I', schema_name, execution_role);
  -- Database CONNECT is database-wide provisioning state. Login principals
  -- need it at connection startup; NOLOGIN capabilities do not. A tenant-schema
  -- installer must not rewrite the database ACL as independent schemas install.
  execute format('grant usage on schema %I to %I, %I', schema_name, runtime_role, schema_admin_role);
  execute format('revoke create on schema %I from %I, %I', schema_name, runtime_role, schema_admin_role);
  execute format('revoke insert, update, delete, truncate, references, trigger on all tables in schema %I from public', schema_name);
  execute format('revoke all privileges on all tables in schema %I from %I, %I, %I', schema_name, execution_role, runtime_role, schema_admin_role);
  execute format('revoke all privileges on all sequences in schema %I from public, %I, %I, %I', schema_name, execution_role, runtime_role, schema_admin_role);
  execute format('grant select, insert, update, delete, references, trigger on all tables in schema %I to %I', schema_name, execution_role);
  execute format('grant usage, select, update on all sequences in schema %I to %I', schema_name, execution_role);
  execute format('revoke execute on all functions in schema %I from public, %I, %I', schema_name, runtime_role, schema_admin_role);

  for function_row in
    select procedure.oid, procedure.proname,
           pg_get_function_identity_arguments(procedure.oid) as identity_arguments
    from pg_proc as procedure
    join pg_namespace as namespace on namespace.oid = procedure.pronamespace
    where namespace.nspname = schema_name
      and procedure.prokind = 'f'
      and procedure.proname like 'kernel\_%' escape '\'
    order by procedure.proname, procedure.oid
  loop
    qualified_function := format(
      '%I.%I(%s)', schema_name, function_row.proname, function_row.identity_arguments
    );
    execute format('alter function %s owner to %I', qualified_function, execution_role);
    execute format('alter function %s security invoker', qualified_function);
    execute format(
      'alter function %s set search_path to %I, pg_catalog, pg_temp',
      qualified_function, schema_name
    );
    execute format('grant execute on function %s to %I', qualified_function, execution_role);
  end loop;

  foreach entrypoint in array array[
    'kernel_admit_http_request(jsonb)',
    'kernel_admit_http_operation(jsonb)',
    'kernel_finish_http_request(jsonb)',
    'kernel_apply_change_set(jsonb)',
    'kernel_apply_change_set_in_transaction(jsonb)',
    'kernel_validate_materialized_schema_revision(jsonb)',
    'kernel_validate_change_set_dry_run(jsonb)',
    'kernel_validate_change_sets_dry_run(jsonb)',
    'kernel_list_draft_change_sets(jsonb)',
    'kernel_read_draft_change_set(jsonb)',
    'kernel_update_draft_notes(jsonb)',
    'kernel_discard_draft_change_set(jsonb)',
    'kernel_approve_draft_change_set(jsonb)',
    'kernel_revert_change_set(jsonb)',
    'kernel_read_active_schema_revision(jsonb)',
    'kernel_read_runtime_release_observability(jsonb)',
    'kernel_read_actor_binding(jsonb)',
    'kernel_read_visible_records(jsonb)',
    'kernel_read_visible_record(jsonb)',
    'kernel_read_visible_records_by_text_fields(jsonb)',
    'kernel_read_visible_record_for_update(jsonb)',
    'kernel_read_visible_records_by_model(jsonb)',
    'kernel_data_query(jsonb)',
    'kernel_work_session(jsonb)',
    'kernel_query_visible_sql(jsonb)',
    'kernel_prepare_visible_query(jsonb)',
    'kernel_change_set_diff(jsonb)',
    'kernel_field_history(jsonb)',
    'kernel_recent_activity(jsonb)',
    'kernel_lookup_list(jsonb)',
    'kernel_lookup_resolve_batch(jsonb)',
    'kernel_lookup_hydrate(jsonb)',
    'kernel_lookup_reference_count(jsonb)',
    'kernel_lookup_set_availability(jsonb)',
    'kernel_lookup_transfer_alias(jsonb)',
    'kernel_record_agent_run(jsonb)',
    'kernel_update_agent_run_status(jsonb)',
    'kernel_schema_revision_is_active_with_materialized_tables(jsonb)'
  ] loop
    if to_regprocedure(format('%I.%s', schema_name, entrypoint)) is null then
      raise exception using
        errcode = '42883',
        message = format('required runtime entrypoint %s is missing', entrypoint);
    end if;
    execute format('alter function %I.%s security definer', schema_name, entrypoint);
    execute format('grant execute on function %I.%s to %I', schema_name, entrypoint, runtime_role);
  end loop;

  if to_regprocedure(format('%I.kernel_cleanup_visible_query()', schema_name)) is null then
    raise exception using
      errcode = '42883',
      message = 'required runtime entrypoint kernel_cleanup_visible_query() is missing';
  end if;
  execute format(
    'alter function %I.kernel_cleanup_visible_query() security invoker',
    schema_name
  );
  execute format(
    'grant execute on function %I.kernel_cleanup_visible_query() to %I',
    schema_name, runtime_role
  );

  foreach entrypoint in array array[
    'kernel_dry_run_tenant_schema_revision(jsonb)',
    'kernel_commit_tenant_schema_revision(jsonb)',
    'kernel_apply_seed_defaults(jsonb)',
    'kernel_bind_actor_membership(jsonb)'
  ] loop
    if to_regprocedure(format('%I.%s', schema_name, entrypoint)) is null then
      raise exception using
        errcode = '42883',
        message = format('required schema-admin entrypoint %s is missing', entrypoint);
    end if;
    execute format('alter function %I.%s security definer', schema_name, entrypoint);
    execute format('grant execute on function %I.%s to %I', schema_name, entrypoint, schema_admin_role);
  end loop;

  if to_regprocedure(format('%I.kernel_policy_raw_table_access_allowed(name,text,text)', schema_name)) is null then
    raise exception using
      errcode = '42883',
      message = 'required runtime policy helper kernel_policy_raw_table_access_allowed is missing';
  end if;
  execute format(
    'alter function %I.kernel_policy_raw_table_access_allowed(name,text,text) security definer',
    schema_name
  );
  execute format(
    'grant execute on function %I.kernel_policy_raw_table_access_allowed(name,text,text) to %I',
    schema_name, runtime_role
  );

  if to_regrole(query_role) is not null then
    execute format(
      'grant execute on function %I.kernel_policy_raw_table_access_allowed(name,text,text) to %I',
      schema_name, query_role
    );
    execute format('grant %I to %I', query_role, runtime_role);
    execute format('grant usage on schema %I to %I', schema_name, query_role);
    execute format('revoke create on schema %I from %I', schema_name, query_role);
    execute format('revoke all privileges on all tables in schema %I from %I', schema_name, query_role);
    execute format('revoke all privileges on all sequences in schema %I from %I', schema_name, query_role);
    execute format(
      'alter function %I.kernel_validate_visible_query(jsonb) set search_path to pg_temp, %I, pg_catalog',
      schema_name, schema_name
    );
    execute format(
      'alter function %I.kernel_validate_visible_query(text) set search_path to pg_temp, %I, pg_catalog',
      schema_name, schema_name
    );
    execute format('grant execute on function %I.kernel_validate_visible_query(jsonb) to %I', schema_name, query_role);
    execute format('grant execute on function %I.kernel_validate_visible_query(text) to %I', schema_name, query_role);
    execute format(
      'alter function %I.kernel_principal_scope_authorized(text,text,text,text) security definer',
      schema_name
    );
    execute format(
      'grant execute on function %I.kernel_principal_scope_authorized(text,text,text,text) to %I',
      schema_name, query_role
    );
  end if;
end;
$kernel$;

-- artifact: function kernel_admit_http_request(jsonb)
create or replace function kernel_admit_http_request(request jsonb)
returns jsonb language plpgsql volatile parallel unsafe security invoker set search_path from current
as $kernel$
declare app text:=request->>'app_id'; customer text:=request->>'customer_id'; actor text:=request->>'actor_id'; role_name text:=request->>'role'; generation text:=request->>'fence_generation'; descriptor jsonb:=request->'http_request'; nonce text:=descriptor->>'jti'; identity_value jsonb; existing_identity jsonb;
begin
  if coalesce(descriptor->>'expiresAt','') !~ '^[1-9][0-9]*$' or (descriptor->>'expiresAt')::numeric<=floor(extract(epoch from clock_timestamp())) then
    return kernel_installer_error('authorization_denied','Verified request has expired','request','http_request_expired','a current signed request expiry is required');
  end if;
  if coalesce(btrim(nonce),'')='' or coalesce(descriptor->>'method','') not in ('POST','PUT','PATCH','DELETE')
    or descriptor->>'payloadSha256' is null or descriptor->>'payloadSha256' !~ '^[A-Za-z0-9_-]{43}$'
    or descriptor->>'bodySha256' is null or descriptor->>'bodySha256' !~ '^[A-Za-z0-9_-]{43}$'
    or coalesce(btrim(descriptor->>'issuer'),'')='' or coalesce(btrim(descriptor->>'audience'),'')='' or coalesce(btrim(descriptor->>'target'),'')=''
    or generation is null or generation !~ '^[1-9][0-9]*$' then
    return kernel_installer_error('authorization_denied','Protected request is unavailable','request','http_request_required','a verified mutation request and normalized payload identity are required');
  end if;
  if not exists(select 1 from kernel_principal_scope s where s.principal_name=session_user::name and s.active and s.capability='runtime' and s.app_id=app and s.customer_id=customer and (s.actor_id is null or s.actor_id=actor) and pg_has_role(session_user,pg_catalog.to_regrole(kernel_installer_capability_role('runtime')),'MEMBER')) then
    return kernel_installer_error('authorization_denied','Runtime scope is not authorized','request','scope_mismatch','the runtime principal is outside this request scope');
  end if;
  perform 1 from kernel_actor_membership m where m.principal_name=session_user::name and m.app_id=app and m.customer_id=customer and m.actor_id=actor and m.role=role_name and m.active and m.fence_generation>0 and m.fence_generation::text=generation for share of m;
  if not found then return kernel_installer_error('authorization_denied','Actor binding is not current','request','binding_mismatch','a current actor binding is required'); end if;
  -- Actor validation may wait on a revocation transaction. Never admit an expired request after that wait.
  if (descriptor->>'expiresAt')::numeric<=floor(extract(epoch from clock_timestamp())) then
    return kernel_installer_error('authorization_denied','Verified request has expired','request','http_request_expired','a current signed request expiry is required');
  end if;
  -- The fixed definer admission owns expiry-only cleanup; runtime cannot invoke this helper directly.
  perform kernel_prune_expired_http_requests(app,customer);
  if (descriptor->>'expiresAt')::numeric<=floor(extract(epoch from clock_timestamp())) then
    return kernel_installer_error('authorization_denied','Verified request has expired','request','http_request_expired','a current signed request expiry is required');
  end if;
  identity_value:=jsonb_build_object('actorId',actor,'role',role_name,'fenceGeneration',generation,'request',descriptor);
  insert into kernel_http_request_admission(principal_name,app_id,customer_id,jti,identity,expires_at)
  values(session_user::name,app,customer,nonce,identity_value,(descriptor->>'expiresAt')::bigint) on conflict do nothing;
  select a.identity into existing_identity from kernel_http_request_admission a where a.principal_name=session_user::name and a.app_id=app and a.customer_id=customer and a.jti=nonce;
  if existing_identity is distinct from identity_value then return kernel_installer_error('authorization_denied','Request identity does not match','request','http_request_identity_conflict','a nonce cannot be reused for changed identity or payload'); end if;
  return jsonb_build_object('ok',true,'data',null);
end;
$kernel$;

-- artifact: function kernel_admit_http_operation(jsonb)
create or replace function kernel_admit_http_operation(request jsonb)
returns jsonb language plpgsql volatile parallel unsafe security invoker set search_path from current
as $kernel$
declare admission jsonb; app text:=request->>'app_id'; customer text:=request->>'customer_id'; nonce text:=request->'http_request'->>'jti'; sequence_value bigint; operation_value text:=request->>'operation'; fingerprint_value text; existing record;
begin
  admission:=kernel_admit_http_request(request);
  if admission->'ok'<>'true'::jsonb then return admission; end if;
  if coalesce(request->>'sequence','') !~ '^[1-9][0-9]*$' or coalesce(jsonb_typeof(request->'payload'),'')<>'object' then return kernel_installer_error('authorization_denied','Operation identity is unavailable','request','http_operation_required','an ordered operation identity is required'); end if;
  sequence_value:=(request->>'sequence')::bigint;
  fingerprint_value:=encode(sha256(convert_to(kernel_canonical_json(request->'payload'),'UTF8')),'hex');
  select o.operation,o.fingerprint into existing from kernel_http_operation_admission o where o.principal_name=session_user::name and o.app_id=app and o.customer_id=customer and o.jti=nonce and o.sequence=sequence_value;
  if not found then
    if sequence_value<>coalesce((select max(o.sequence) from kernel_http_operation_admission o where o.principal_name=session_user::name and o.app_id=app and o.customer_id=customer and o.jti=nonce),0)+1 then return kernel_installer_error('authorization_denied','Operation order does not match','request','http_operation_order_conflict','new operations must be admitted in contiguous order'); end if;
    if exists(select 1 from kernel_http_request_consumption c where c.principal_name=session_user::name and c.app_id=app and c.customer_id=customer and c.jti=nonce) then return kernel_installer_error('authorization_denied','Request nonce was consumed','request','http_request_replayed','a consumed nonce cannot acquire new operations'); end if;
    insert into kernel_http_operation_admission(principal_name,app_id,customer_id,jti,sequence,operation,fingerprint) values(session_user::name,app,customer,nonce,sequence_value,operation_value,fingerprint_value) on conflict do nothing;
    select o.operation,o.fingerprint into existing from kernel_http_operation_admission o where o.principal_name=session_user::name and o.app_id=app and o.customer_id=customer and o.jti=nonce and o.sequence=sequence_value;
  end if;
  if existing.operation is distinct from operation_value or existing.fingerprint is distinct from fingerprint_value then return kernel_installer_error('authorization_denied','Operation identity does not match','request','http_operation_conflict','the ordered request operation cannot change'); end if;
  return jsonb_build_object('ok',true,'data',null);
end;
$kernel$;

-- artifact: function kernel_http_mutation_guard(jsonb,text)
create or replace function kernel_http_mutation_guard(request jsonb, operation_value text)
returns jsonb language plpgsql volatile parallel unsafe security invoker set search_path from current
as $kernel$
declare app text:=request->>'app_id'; customer text:=request->>'customer_id'; nonce text:=nullif(current_setting('kernel.http_jti',true),''); descriptor jsonb; identity_value jsonb; generation text:=nullif(current_setting('kernel.actor_fence_generation',true),''); role_name text:=nullif(current_setting('kernel.actor_role',true),''); actor text:=nullif(current_setting('kernel.actor_id',true),''); sequence_value bigint; consumed record; replay_id bigint; fingerprint_value text;
begin
  if not exists(select 1 from kernel_principal_scope s where s.principal_name=session_user::name and s.capability='runtime' and s.app_id=app and s.customer_id=customer and s.actor_binding_required) then return jsonb_build_object('required',false); end if;
  if nonce is null or nullif(current_setting('kernel.http_descriptor',true),'') is null or nullif(current_setting('kernel.http_sequence',true),'') is null then return kernel_installer_error('authorization_denied','Protected request is unavailable','request','http_request_required','a verified request nonce is required for mutations'); end if;
  if not kernel_principal_scope_authorized('runtime',app,customer,null) then return kernel_authorize_scope('runtime',app,customer,null); end if;
  -- Bind authorized scope before inspecting canonical receipts under their RLS.
  perform set_config('kernel.app_id',app,true); perform set_config('kernel.customer_id',customer,true);
  descriptor:=current_setting('kernel.http_descriptor',true)::jsonb;
  if coalesce(descriptor->>'expiresAt','') !~ '^[1-9][0-9]*$' or (descriptor->>'expiresAt')::numeric<=floor(extract(epoch from clock_timestamp())) then
    return kernel_installer_error('authorization_denied','Verified request has expired','request','http_request_expired','a current signed request expiry is required');
  end if;
  identity_value:=jsonb_build_object('actorId',actor,'role',role_name,'fenceGeneration',generation,'request',descriptor);
  if not exists(select 1 from kernel_http_request_admission a where a.principal_name=session_user::name and a.app_id=app and a.customer_id=customer and a.jti=nonce and a.identity=identity_value) then return kernel_installer_error('authorization_denied','Request admission does not match','request','http_request_identity_conflict','the request must match its durable admission'); end if;
  select c.* into consumed from kernel_http_request_consumption c where c.principal_name=session_user::name and c.app_id=app and c.customer_id=customer and c.jti=nonce;
  -- Only the private execution marker allows nested calls from a fixed mutation body.
  if found and consumed.executing_xid=pg_current_xact_id() and consumed.executing then return jsonb_build_object('required',false); end if;
  sequence_value:=current_setting('kernel.http_sequence',true)::bigint;
  fingerprint_value:=encode(sha256(convert_to(kernel_canonical_json(request),'UTF8')),'hex');
  if not exists(select 1 from kernel_http_operation_admission o where o.principal_name=session_user::name and o.app_id=app and o.customer_id=customer and o.jti=nonce and o.sequence=sequence_value and o.operation=operation_value and o.fingerprint=fingerprint_value) then return kernel_installer_error('authorization_denied','Operation admission does not match','request','http_operation_conflict','the operation must match its ordered durable admission'); end if;
  insert into kernel_http_request_consumption(principal_name,app_id,customer_id,jti,owner_xid) values(session_user::name,app,customer,nonce,pg_current_xact_id()) on conflict do nothing;
  select c.* into consumed from kernel_http_request_consumption c where c.principal_name=session_user::name and c.app_id=app and c.customer_id=customer and c.jti=nonce for update;
  if not found or (descriptor->>'expiresAt')::numeric<=floor(extract(epoch from clock_timestamp())) then return kernel_installer_error('authorization_denied','Verified request has expired','request','http_request_expired','expired requests cannot execute after waiting for another transaction'); end if;
  if consumed.owner_xid<>pg_current_xact_id() then
    select r.change_set_id into replay_id from kernel_http_operation_receipt r where r.principal_name=session_user::name and r.app_id=app and r.customer_id=customer and r.jti=nonce and r.sequence=sequence_value;
    if operation_value='kernel_work_session' then
      if not exists(select 1 from work_session s where s.app_id=app and s.customer_id=customer and s.id=(request->>'session_id')::uuid and s.owner_id=actor and s.receipts->(request->>'request_id')->>'fingerprint'=fingerprint_value) then
        return kernel_installer_error('authorization_denied','Request nonce was consumed','request','http_request_replayed','this mutation has no exact durable replay receipt');
      end if;
    elsif replay_id is null or operation_value not in ('kernel_apply_change_set','kernel_apply_change_set_in_transaction','kernel_lookup_set_availability') or not exists(select 1 from change_set c where c.id=replay_id and c.app_id=app and c.customer_id=customer and c.idempotency_key=request->>'idempotency_key') then return kernel_installer_error('authorization_denied','Request nonce was consumed','request','http_request_replayed','this mutation has no exact durable replay receipt'); end if;
  end if;
  update kernel_http_request_consumption set executing=true,executing_xid=pg_current_xact_id() where principal_name=session_user::name and app_id=app and customer_id=customer and jti=nonce;
  return jsonb_build_object('required',true,'sequence',sequence_value,'fresh',consumed.owner_xid=pg_current_xact_id(),'operation',operation_value);
end;
$kernel$;

-- artifact: function kernel_http_mutation_record(jsonb,jsonb,jsonb)
create or replace function kernel_http_mutation_record(request jsonb, guard jsonb, result jsonb)
returns void language plpgsql volatile parallel unsafe security invoker set search_path from current
as $kernel$
declare app text:=request->>'app_id'; customer text:=request->>'customer_id'; nonce text:=current_setting('kernel.http_jti',true); receipt_id bigint;
begin
  update kernel_http_request_consumption set executing=false,executing_xid=null where principal_name=session_user::name and app_id=app and customer_id=customer and jti=nonce;
  if (guard->>'fresh')::boolean then
    if guard->>'operation' in ('kernel_apply_change_set','kernel_apply_change_set_in_transaction','kernel_lookup_set_availability') and result->'ok'='true'::jsonb and coalesce(btrim(request->>'idempotency_key'),'')<>'' then receipt_id:=(result->'data'->>'id')::bigint; end if;
    insert into kernel_http_operation_receipt(principal_name,app_id,customer_id,jti,sequence,change_set_id) values(session_user::name,app,customer,nonce,(guard->>'sequence')::bigint,receipt_id) on conflict do nothing;
  end if;
end;
$kernel$;

-- artifact: function kernel_finish_http_request(jsonb)
create or replace function kernel_finish_http_request(request jsonb)
returns jsonb language plpgsql volatile parallel unsafe security invoker set search_path from current
as $kernel$
declare app text:=request->>'app_id'; customer text:=request->>'customer_id'; nonce text:=current_setting('kernel.http_jti',true); count_value bigint:=(request->>'operation_count')::bigint; consumed record;
begin
  if coalesce((current_setting('kernel.http_descriptor',true)::jsonb)->>'expiresAt','') !~ '^[1-9][0-9]*$' or ((current_setting('kernel.http_descriptor',true)::jsonb)->>'expiresAt')::numeric<=floor(extract(epoch from clock_timestamp())) then return kernel_installer_error('authorization_denied','Verified request has expired','request','http_request_expired','expired requests cannot commit'); end if;
  select c.* into consumed from kernel_http_request_consumption c where c.principal_name=session_user::name and c.app_id=app and c.customer_id=customer and c.jti=nonce for update;
  if not found then return jsonb_build_object('ok',true,'data',null); end if;
  if count_value<=0 or count_value is distinct from (select max(o.sequence) from kernel_http_operation_admission o where o.principal_name=session_user::name and o.app_id=app and o.customer_id=customer and o.jti=nonce) then return kernel_installer_error('authorization_denied','Request operations do not match','request','http_operation_count_conflict','the complete admitted operation sequence is required'); end if;
  if consumed.owner_xid=pg_current_xact_id() then
    if count_value is distinct from (select count(*) from kernel_http_operation_receipt r where r.principal_name=session_user::name and r.app_id=app and r.customer_id=customer and r.jti=nonce) then return kernel_installer_error('authorization_denied','Request operations are incomplete','request','http_operation_count_conflict','every operation must complete before commit'); end if;
    update kernel_http_request_consumption set operation_count=count_value where principal_name=session_user::name and app_id=app and customer_id=customer and jti=nonce;
  elsif consumed.operation_count is distinct from count_value then return kernel_installer_error('authorization_denied','Request operations do not match','request','http_operation_count_conflict','all admitted operations must be replayed in their original order'); end if;
  return jsonb_build_object('ok',true,'data',null);
end;
$kernel$;

-- artifact: function kernel_prune_expired_http_requests()
create or replace function kernel_prune_expired_http_requests()
returns bigint language plpgsql volatile parallel unsafe security invoker set search_path from current
as $kernel$
declare candidate record; removed bigint:=0;
begin
  -- Private execution-owner maintenance only. Unknown legacy expiry is retained.
  for candidate in select a.principal_name,a.app_id,a.customer_id,a.jti from kernel_http_request_admission a where a.expires_at<=floor(extract(epoch from clock_timestamp())) loop
    begin
      -- Match business lock ordering; a busy transaction is skipped, never raced.
      perform 1 from kernel_http_request_consumption c where c.principal_name=candidate.principal_name and c.app_id=candidate.app_id and c.customer_id=candidate.customer_id and c.jti=candidate.jti for update nowait;
      perform 1 from kernel_http_request_admission a where a.principal_name=candidate.principal_name and a.app_id=candidate.app_id and a.customer_id=candidate.customer_id and a.jti=candidate.jti and a.expires_at<=floor(extract(epoch from clock_timestamp())) for update nowait;
      if not found then continue; end if;
      delete from kernel_http_operation_receipt r where r.principal_name=candidate.principal_name and r.app_id=candidate.app_id and r.customer_id=candidate.customer_id and r.jti=candidate.jti;
      delete from kernel_http_request_consumption c where c.principal_name=candidate.principal_name and c.app_id=candidate.app_id and c.customer_id=candidate.customer_id and c.jti=candidate.jti;
      delete from kernel_http_operation_admission o where o.principal_name=candidate.principal_name and o.app_id=candidate.app_id and o.customer_id=candidate.customer_id and o.jti=candidate.jti;
      delete from kernel_http_request_admission a where a.principal_name=candidate.principal_name and a.app_id=candidate.app_id and a.customer_id=candidate.customer_id and a.jti=candidate.jti;
      removed:=removed+1;
    exception when lock_not_available then null;
    end;
  end loop;
  return removed;
end;
$kernel$;

-- artifact: function kernel_prune_expired_http_requests(text,text)
create or replace function kernel_prune_expired_http_requests(scoped_app text, scoped_customer text)
returns bigint language plpgsql volatile parallel unsafe security invoker set search_path from current
as $kernel$
declare candidate record; removed bigint:=0;
begin
  -- Called only by validated fixed admission. Session login identity remains authoritative under SECURITY DEFINER.
  -- Unknown legacy expiry is retained; other principals/apps/customers are never inspected.
  for candidate in select a.principal_name,a.app_id,a.customer_id,a.jti from kernel_http_request_admission a where a.principal_name=session_user::name and a.app_id=scoped_app and a.customer_id=scoped_customer and a.expires_at<=floor(extract(epoch from clock_timestamp())) loop
    begin
      -- Match business lock ordering; a busy transaction is skipped, never raced.
      perform 1 from kernel_http_request_consumption c where c.principal_name=candidate.principal_name and c.app_id=candidate.app_id and c.customer_id=candidate.customer_id and c.jti=candidate.jti for update nowait;
      perform 1 from kernel_http_request_admission a where a.principal_name=candidate.principal_name and a.app_id=candidate.app_id and a.customer_id=candidate.customer_id and a.jti=candidate.jti and a.expires_at<=floor(extract(epoch from clock_timestamp())) for update nowait;
      if not found then continue; end if;
      delete from kernel_http_operation_receipt r where r.principal_name=candidate.principal_name and r.app_id=candidate.app_id and r.customer_id=candidate.customer_id and r.jti=candidate.jti;
      delete from kernel_http_request_consumption c where c.principal_name=candidate.principal_name and c.app_id=candidate.app_id and c.customer_id=candidate.customer_id and c.jti=candidate.jti;
      delete from kernel_http_operation_admission o where o.principal_name=candidate.principal_name and o.app_id=candidate.app_id and o.customer_id=candidate.customer_id and o.jti=candidate.jti;
      delete from kernel_http_request_admission a where a.principal_name=candidate.principal_name and a.app_id=candidate.app_id and a.customer_id=candidate.customer_id and a.jti=candidate.jti;
      removed:=removed+1;
    exception when lock_not_available then null;
    end;
  end loop;
  return removed;
end;
$kernel$;

-- artifact: function kernel_materialization_preflight.hc.hc
do $kernel$
declare
