:"department","is_import_default":true,"touches":[],"required":[]},{"id":"location_update","label":"Location update","target_model":"location","is_import_default":true,"touches":[],"required":[]},{"id":"level_update","label":"Level update","target_model":"level","is_import_default":true,"touches":[],"required":[]},{"id":"business_unit_update","label":"Business unit update","target_model":"business_unit","is_import_default":true,"touches":[],"required":[]},{"id":"job_family_update","label":"Job family update","target_model":"job_family","is_import_default":true,"touches":[],"required":[]},{"id":"pnl_category_update","label":"P&L category update","target_model":"pnl_category","is_import_default":true,"touches":[],"required":[]},{"id":"employee_update","label":"Employee update","target_model":"employee","is_import_default":true,"touches":[],"required":[]},{"id":"position_update","label":"Position update","target_model":"position","is_import_default":true,"touches":[],"required":[]},{"id":"position_status_change","label":"Position status change","target_model":"position","touches":["position_status","start_date","end_date"],"required":[]},{"id":"position_budget_change","label":"Position budget change","target_model":"position","touches":["base_salary","target_bonus","target_commission","annual_equity_value","benefits_actual","taxes_actual","pnl_category"],"required":[]},{"id":"position_structure_change","label":"Position structure change","target_model":"position","touches":["department","location","business_unit","job_family","level"],"required":[]},{"id":"org_assignment_change","label":"Org assignment change","target_model":"org_assignment","is_import_default":true,"touches":["employee","position","reports_to_employee","reports_to_position","start_date","end_date"],"required":[]}]}'::jsonb;
  candidate record;
  still_declared boolean;
begin
  perform set_config('kernel.schema_catalog_read', 'on', true);

  for candidate in
    select relation.relname as table_name, constraint_value.conname as object_name
    from pg_constraint as constraint_value
    join pg_class as relation on relation.oid = constraint_value.conrelid
    join pg_namespace as namespace on namespace.oid = relation.relnamespace
    where namespace.nspname = current_schema()
      and relation.relname like '%\_version' escape '\'
      and constraint_value.contype = 'c'
      and constraint_value.conname like '%\_required\_check' escape '\'
  loop
    select exists (
      select 1
      from (
        select proposed_schema as schema_json
        union all
        select schema
        from schema_revision
        where activated_at is not null
          and not (
            app_id = proposed_schema->>'app_id'
            and customer_id = proposed_schema->>'customer_id'
          )
      ) as declared_schema
      cross join lateral jsonb_array_elements(coalesce(declared_schema.schema_json->'models', '[]'::jsonb)) as model(value)
      cross join lateral jsonb_array_elements(coalesce(model.value->'fields', '[]'::jsonb)) as field(value)
      cross join lateral unnest(
        case when field.value->>'type' = 'money_rate'
          then array[
            field.value->>'id' || '_amount',
            field.value->>'id' || '_currency',
            field.value->>'id' || '_period'
          ]
          else array[field.value->>'id']
        end
      ) as physical_column(name)
      where coalesce((field.value->>'required')::boolean, false)
        and kernel_physical_identifier(model.value->>'id' || '_version') = candidate.table_name
        and kernel_physical_identifier(
          candidate.table_name || '_' || kernel_physical_identifier(physical_column.name) || '_required_check'
        ) = candidate.object_name
    ) into still_declared;
    if not still_declared then
      execute format(
        'alter table %I.%I drop constraint %I',
        current_schema(), candidate.table_name, candidate.object_name
      );
    end if;
  end loop;

  for candidate in
    select index_relation.relname as object_name
    from pg_class as index_relation
    join pg_namespace as namespace on namespace.oid = index_relation.relnamespace
    where namespace.nspname = current_schema()
      and index_relation.relkind = 'i'
      and index_relation.relname like '%\_live\_unique\_idx' escape '\'
  loop
    select exists (
      select 1
      from (
        select proposed_schema as schema_json
        union all
        select schema
        from schema_revision
        where activated_at is not null
          and not (
            app_id = proposed_schema->>'app_id'
            and customer_id = proposed_schema->>'customer_id'
          )
      ) as declared_schema
      cross join lateral jsonb_array_elements(coalesce(declared_schema.schema_json->'models', '[]'::jsonb)) as model(value)
      cross join lateral jsonb_array_elements(coalesce(model.value->'fields', '[]'::jsonb)) as field(value)
      where coalesce((field.value->>'is_unique')::boolean, false)
        and kernel_physical_identifier(
          kernel_physical_identifier(model.value->>'id' || '_version') || '_' ||
          kernel_physical_identifier(field.value->>'id') || '_live_unique_idx'
        ) = candidate.object_name
    ) into still_declared;
    if not still_declared then
      execute format('drop index %I.%I', current_schema(), candidate.object_name);
    end if;
  end loop;
end
$kernel$;

