-- artifact: policy agent_run.kernel_tenant_isolation
alter table "agent_run" enable row level security;
alter table "agent_run" force row level security;
do $kernel$
declare
  unexpected_policy record;
begin
  for unexpected_policy in
    select policyname
    from pg_policies
    where schemaname = current_schema()
      and tablename = 'agent_run'
      and policyname not in ('kernel_tenant_isolation')
    order by policyname
  loop
    execute format('drop policy %I on %I', unexpected_policy.policyname, 'agent_run');
  end loop;

  if exists (select 1 from pg_policies where schemaname = current_schema() and tablename = 'agent_run' and policyname = 'kernel_tenant_isolation') then
    execute 'alter policy kernel_tenant_isolation on "agent_run" using ((app_id = current_setting(''kernel.app_id'', true) and customer_id = current_setting(''kernel.customer_id'', true)) and kernel_principal_scope_authorized(''any'', app_id, customer_id, null)) with check ((app_id = current_setting(''kernel.app_id'', true) and customer_id = current_setting(''kernel.customer_id'', true)) and kernel_principal_scope_authorized(''any'', app_id, customer_id, null))';
  else
    execute 'create policy kernel_tenant_isolation on "agent_run" for all using ((app_id = current_setting(''kernel.app_id'', true) and customer_id = current_setting(''kernel.customer_id'', true)) and kernel_principal_scope_authorized(''any'', app_id, customer_id, null)) with check ((app_id = current_setting(''kernel.app_id'', true) and customer_id = current_setting(''kernel.customer_id'', true)) and kernel_principal_scope_authorized(''any'', app_id, customer_id, null))';
  end if;
end
$kernel$;

